INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36407, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の意味や内容を説明し、理解させること。", "primary_collocate": null, "pronunciation": "かいしゃく", "ipa": "kaiɕaku", "syllable_count": 4, "sentences": [{"text": "先生が、むずかしい古文を現代語に解釈してくれた。", "target_word": "解釈", "complexity_tier": "T4", "furigana": "先生[せんせい]が、むずかしい古文[こぶん]を現代語[げんだいご]に解釈[かいしゃく]してくれた。", "sentence_source": "generated"}, {"text": "ガイドは、絵の意味を子どもにも分かるように解釈した。", "target_word": "解釈", "complexity_tier": "T4", "furigana": "ガイドは、絵[え]の意味[いみ]を子[こ]どもにも分[わ]かるように解釈[かいしゃく]した。", "sentence_source": "generated"}, {"text": "授業で、先生が詩の意味を丁寧に解釈した。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で、先生[せんせい]が詩[し]の意味[いみ]を丁寧[ていねい]に解釈[かいしゃく]した。", "sentence_source": "generated"}, {"text": "弁護士が契約書の内容を解釈してくれたので、よく分かった。", "target_word": "解釈", "complexity_tier": "T4", "furigana": "弁護士[べんごし]が契約書[けいやくしょ]の内容[ないよう]を解釈[かいしゃく]してくれたので、よく分[わ]かった。", "sentence_source": "generated"}, {"text": "先生が解釈してくれた法律の条文を読んで、意味を理解した。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "先生[せんせい]が解釈[かいしゃく]してくれた法律[ほうりつ]の条文[じょうぶん]を読[よ]んで、意味[いみ]を理解[りかい]した。", "sentence_source": "generated"}, {"text": "彼の解釈のおかげで、難しい文章の意味がよく分かった。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "彼[かれ]の解釈[かいしゃく]のおかげで、難[むずか]しい文章[ぶんしょう]の意味[いみ]がよく分[わ]かった。", "sentence_source": "generated"}, {"text": "博物館の人が展示の意味を解釈して、見学の人に伝えた。", "target_word": "解釈", "complexity_tier": "T4", "furigana": "博物館[はくぶつかん]の人[ひと]が展示[てんじ]の意味[いみ]を解釈[かいしゃく]して、見学[けんがく]の人[ひと]に伝[つた]えた。", "sentence_source": "generated"}, {"text": "この本は、昔の物語を現代の言葉で解釈している。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "この本[ほん]は、昔[むかし]の物語[ものがたり]を現代[げんだい]の言葉[ことば]で解釈[かいしゃく]している。", "sentence_source": "generated"}, {"text": "母は古い手紙の内容を解釈して、私に読んで聞かせた。", "target_word": "解釈", "complexity_tier": "T4", "furigana": "母[はは]は古[ふる]い手紙[てがみ]の内容[ないよう]を解釈[かいしゃく]して、私[わたし]に読[よ]んで聞[き]かせた。", "sentence_source": "generated"}, {"text": "先生の解釈を聞いて、やっと歌詞の意味がつかめた。", "target_word": "解釈", "complexity_tier": "T3", "furigana": "先生[せんせい]の解釈[かいしゃく]を聞[き]いて、やっと歌詞[かし]の意味[いみ]がつかめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解釈", "label": "基本形"}, {"form": "解釈する", "label": "辞書形(する動詞)"}, {"form": "解釈した", "label": "過去形"}, {"form": "解釈して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "難しい文章や物事の意味・内容を、相手に分かるように説明し理解させる行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36407, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解釈", "is_correct": true, "explanation": "「現代語に解釈してくれた」は、古文の意味を現代の言葉で説明する意味になり、文に合う。"}, {"text": "撮影", "is_correct": false, "explanation": "「現代語に撮影してくれた」は、写真や映像を撮る意味になり、文が成り立たない。"}, {"text": "採点", "is_correct": false, "explanation": "「現代語に採点してくれた」は点数をつける意味で、古文を現代語にする文脈と合わない。"}, {"text": "保管", "is_correct": false, "explanation": "「現代語に保管してくれた」は物を預かる意味になり、言葉の説明とは関係がない。"}], "explanations": {"解釈": "「現代語に解釈してくれた」は、古文の意味を現代の言葉で説明する意味になり、文に合う。", "撮影": "「現代語に撮影してくれた」は、写真や映像を撮る意味になり、文が成り立たない。", "採点": "「現代語に採点してくれた」は点数をつける意味で、古文を現代語にする文脈と合わない。", "保管": "「現代語に保管してくれた」は物を預かる意味になり、言葉の説明とは関係がない。"}, "sentence_index": 0, "correct_answer": "解釈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母がシャツを解釈して、紺色に染めた。", "explanation": "ここは〈染める〉の意味。解釈は意味や内容を説明することで、布を色で染める作業とは違う。"}, {"text": "母がケーキを解釈して、六つに切ってくれた。", "explanation": "ここは〈切る〉の意味。解釈は意味を受け取ることで、物を切る動作には使わない。"}, {"text": "部屋の窓を解釈してくれた。", "explanation": "ここは〈磨く〉の意味。解釈は意味を考えることで、窓を磨く作業には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36407, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解釈", "is_correct": true, "explanation": "「展示の意味を解釈して、伝えた」は、意味を説明して見学者に伝える意味になり、文に合う。"}, {"text": "返却", "is_correct": false, "explanation": "「展示の意味を返却して」は、物を戻す意味になり、意味の説明とは合わない。"}, {"text": "修繕", "is_correct": false, "explanation": "「展示の意味を修繕して」は、壊れた物を直す意味になり、文が成り立たない。"}, {"text": "配達", "is_correct": false, "explanation": "「展示の意味を配達して」は、物を届ける意味になり、説明の文脈と合わない。"}], "explanations": {"解釈": "「展示の意味を解釈して、伝えた」は、意味を説明して見学者に伝える意味になり、文に合う。", "返却": "「展示の意味を返却して」は、物を戻す意味になり、意味の説明とは合わない。", "修繕": "「展示の意味を修繕して」は、壊れた物を直す意味になり、文が成り立たない。", "配達": "「展示の意味を配達して」は、物を届ける意味になり、説明の文脈と合わない。"}, "sentence_index": 6, "correct_answer": "解釈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は魚を解釈して、冷凍庫に入れた。", "explanation": "ここは〈冷凍する〉の意味。解釈は意味を説明することで、食品を凍らせる作業とは違う。"}, {"text": "犬を毎朝、解釈させた。", "explanation": "ここは〈散歩させる〉の意味。解釈は意味を考えることで、犬を歩かせる行為には使わない。"}, {"text": "お皿を解釈して、棚にしまった。", "explanation": "ここは〈洗う〉の意味。解釈は物事の意味を受け取ることで、食器を洗う動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36407, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生が、難しい論文が平易な言葉に解釈してくれた。", "corrected_sentence": "先生が、難しい論文を平易な言葉に解釈してくれた。", "error_description": "「解釈する」は解釈される対象を「を」で示す。「が」は誤りで、正しくは「論文を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36407, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女が解釈ったので、やっと歌詞の意味がつかめた。", "corrected_sentence": "彼女が解釈したので、やっと歌詞の意味がつかめた。", "error_description": "「解釈する」の過去形は「解釈した」。「解釈った」は五段動詞の活用で、する動詞には使えないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36408, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "進展を主語として、『あった』（存在）を示す『が』。"}, {"text": "に", "is_correct": false, "explanation": "場所を示す『に』は『あった』の場所にならず、『進展にあった』は不自然。"}, {"text": "と", "is_correct": false, "explanation": "『と』は相手や引用を表し、『進展とあった』は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "『を』は他動詞の目的語を示し、『あった』は目的語を取らないので『進展をあった』は誤り。"}], "correct_answer": "が", "explanations": {"が": "進展を主語として、『あった』（存在）を示す『が』。", "に": "場所を示す『に』は『あった』の場所にならず、『進展にあった』は不自然。", "と": "『と』は相手や引用を表し、『進展とあった』は成り立たない。", "を": "『を』は他動詞の目的語を示し、『あった』は目的語を取らないので『進展をあった』は誤り。"}, "error_tags": {"に": "場所（存在の場所を示すが、進展には付かない）", "と": "相手・引用（進展の対象にならない）", "を": "目的語（『ある』は目的語を取らない）"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停滞", "is_correct": true, "explanation": "進展の対義語。前へ進まず止まっている状態で、『計画がなかなか進展せず』と対応する。"}, {"text": "延長", "is_correct": false, "explanation": "期間や長さを伸ばす意味で、進展の対義語ではない。"}, {"text": "整理", "is_correct": false, "explanation": "散らかったものを片付ける意味で、対義語ではない。"}, {"text": "検討", "is_correct": false, "explanation": "よく考え調べる意味で、対義語ではない。"}], "correct_answer": "停滞", "explanations": {"停滞": "進展の対義語。前へ進まず止まっている状態で、『計画がなかなか進展せず』と対応する。", "延長": "期間や長さを伸ばす意味で、進展の対義語ではない。", "整理": "散らかったものを片付ける意味で、対義語ではない。", "検討": "よく考え調べる意味で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36408, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "進展を主語として、『あり』（存在）を示す『が』。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は『進展へあり』と合わず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す『から』は『進展からあり』と合わず、存在を表せない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐもので、『進展のあり』は述語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "進展を主語として、『あり』（存在）を示す『が』。", "へ": "方向を示す『へ』は『進展へあり』と合わず、文が成り立たない。", "から": "起点を示す『から』は『進展からあり』と合わず、存在を表せない。", "の": "『の』は名詞をつなぐもので、『進展のあり』は述語として成り立たない。"}, "error_tags": {"へ": "方向（進展の存在を示せない）", "から": "起点（存在の表現に合わない）", "の": "連体修飾（述語にならない）"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停滞", "is_correct": true, "explanation": "進展の対義語。前へ進まず止まる意味で、『話し合いに進展がない』と対応する。"}, {"text": "協議", "is_correct": false, "explanation": "話し合って決める意味で、対義語ではない。"}, {"text": "収納", "is_correct": false, "explanation": "物をしまう意味で、対義語ではない。"}, {"text": "演説", "is_correct": false, "explanation": "人前で話す意味で、対義語ではない。"}], "correct_answer": "停滞", "explanations": {"停滞": "進展の対義語。前へ進まず止まる意味で、『話し合いに進展がない』と対応する。", "協議": "話し合って決める意味で、対義語ではない。", "収納": "物をしまう意味で、対義語ではない。", "演説": "人前で話す意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36408, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事が前に進んで、もっと大きくなったり、よくなったりすること。", "primary_collocate": null, "pronunciation": "しんてん", "ipa": "ɕiɲteɴ", "syllable_count": 4, "sentences": [{"text": "交渉は少しずつ進展し、合意に近づいている。", "target_word": "進展", "complexity_tier": "T3", "furigana": "交渉[こうしょう]は少[すこ]しずつ進展[しんてん]し、合意[ごうい]に近[ちか]づいている。", "sentence_source": "generated"}, {"text": "二国間の話し合いに大きな進展があった。", "target_word": "進展", "complexity_tier": "T3", "furigana": "二国間[にこくかん]の話[はな]し合[あ]いに大[おお]きな進展[しんてん]があった。", "sentence_source": "generated"}, {"text": "治療の進展で、多くの患者が元気になった。", "target_word": "進展", "complexity_tier": "T3", "furigana": "治療[ちりょう]の進展[しんてん]で、多[おお]くの患者[かんじゃ]が元気[げんき]になった。", "sentence_source": "generated"}, {"text": "計画がなかなか進展せず、みんな不安になっていた。", "target_word": "進展", "complexity_tier": "T3", "furigana": "計画[けいかく]がなかなか進展[しんてん]せず、みんな不安[ふあん]になっていた。", "sentence_source": "generated"}, {"text": "調査に進展が見られないまま、一か月が過ぎた。", "target_word": "進展", "complexity_tier": "T3", "furigana": "調査[ちょうさ]に進展[しんてん]が見[み]られないまま、一[いっ]か月[げつ]が過[す]ぎた。", "sentence_source": "generated"}, {"text": "二人の関係は、旅行をきっかけに大きく進展した。", "target_word": "進展", "complexity_tier": "T3", "furigana": "二人[ふたり]の関係[かんけい]は、旅行[りょこう]をきっかけに大[おお]きく進展[しんてん]した。", "sentence_source": "generated"}, {"text": "技術の進展により、生活はずっと便利になった。", "target_word": "進展", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]の進展[しんてん]により、生活[せいかつ]はずっと便利[べんり]になった。", "sentence_source": "generated"}, {"text": "事件の捜査に進展があり、犯人の手がかりが見つかった。", "target_word": "進展", "complexity_tier": "T3", "furigana": "事件[じけん]の捜査[そうさ]に進展[しんてん]があり、犯人[はんにん]の手[て]がかりが見[み]つかった。", "sentence_source": "generated"}, {"text": "新しい薬の開発が進展して、来年には使えそうだ。", "target_word": "進展", "complexity_tier": "T3", "furigana": "新[あたら]しい薬[くすり]の開発[かいはつ]が進展[しんてん]して、来年[らいねん]には使[つか]えそうだ。", "sentence_source": "generated"}, {"text": "話し合いに進展がないので、会議は短く終わった。", "target_word": "進展", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いに進展[しんてん]がないので、会議[かいぎ]は短[みじか]く終[お]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "進展する", "label": "動詞 基本形"}, {"form": "進展した", "label": "過去形"}, {"form": "進展して", "label": "て形"}, {"form": "進展しない", "label": "否定形"}, {"form": "進展せず", "label": "否定連用形"}], "register": "plain (常体)", "sense_fingerprint": "交渉・捜査・計画・関係などが前向きに進み、よい方向や大きな規模へ発展すること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5fbc95f-0ae8-454f-a614-42c57107f7b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36408, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "進展", "is_correct": true, "explanation": "交渉が少しずつ前へ進み、合意に近づくという文に合う。"}, {"text": "停止", "is_correct": false, "explanation": "停止は止まる意味で、少しずつ進みながら合意に近づく文と矛盾する。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集まりを終わらせる意味で、交渉が合意へ近づく流れに合わない。"}, {"text": "撤回", "is_correct": false, "explanation": "撤回は取り下げる意味で、交渉が前へ進む文脈では使えない。"}], "explanations": {"進展": "交渉が少しずつ前へ進み、合意に近づくという文に合う。", "停止": "停止は止まる意味で、少しずつ進みながら合意に近づく文と矛盾する。", "解散": "解散は集まりを終わらせる意味で、交渉が合意へ近づく流れに合わない。", "撤回": "撤回は取り下げる意味で、交渉が前へ進む文脈では使えない。"}, "sentence_index": 0, "correct_answer": "進展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹はピアノの腕が毎日着実に進展している。", "explanation": "ここは〈進歩〉の意味。進展は物事の状況が前へ動くことで、人の腕前の上達には使わないので合わない。"}, {"text": "車が坂道を進展して、頂上へ向かった。", "explanation": "ここは〈進行〉の意味。車が前へ動くことは進行と言い、進展は物事の状況に使うので合わない。"}, {"text": "選手が試合の途中で進展して、ベンチへ下がった。", "explanation": "ここは〈交代〉の意味。選手を入れ替える場合は交代と言い、進展は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36408, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "進展", "is_correct": true, "explanation": "技術が前へ進むことで生活が便利になる、という文脈に合う。"}, {"text": "紛失", "is_correct": false, "explanation": "紛失は失くすことで、技術の紛失が便利さの理由になるという文は成り立たない。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まることで、技術の停電によって便利になるのは不自然。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は水分がなくなる意味で、技術の乾燥が生活を便利にする理由にはならない。"}], "explanations": {"進展": "技術が前へ進むことで生活が便利になる、という文脈に合う。", "紛失": "紛失は失くすことで、技術の紛失が便利さの理由になるという文は成り立たない。", "停電": "停電は電気が止まることで、技術の停電によって便利になるのは不自然。", "乾燥": "乾燥は水分がなくなる意味で、技術の乾燥が生活を便利にする理由にはならない。"}, "sentence_index": 6, "correct_answer": "進展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "軍は夜明けに街から進展して、郊外へ退いた。", "explanation": "ここは〈撤退〉の意味。進展は前へ進むことで、退いて離れる意味では使えないので合わない。"}, {"text": "電車が駅に向かって進展している。", "explanation": "ここは〈進行〉の意味。電車が前へ動くことは進行と言い、進展は物事の状況が新しい段階へ移る意味なので合わない。"}, {"text": "彼は予定を進展させて、会議の日を変えた。", "explanation": "ここは〈変更〉の意味。予定を改める場合は変更を使い、進展は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36408, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議では、少しずつ進展を見られた。", "corrected_sentence": "会議では、少しずつ進展が見られた。", "error_description": "『見られる』は受身で、主語には『が』を付ける。誤りは『進展を見られた』で、正しくは『進展が見られた』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36408, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "調査が進展させず、一か月が過ぎた。", "corrected_sentence": "調査が進展せず、一か月が過ぎた。", "error_description": "『進展させ』は他動詞で、誰かが物事を進めるという意味になる。主語『調査が』の文では誤り。正しくは自動詞の『進展せず』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36409, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『けんかに進展』で、進展の変化先を示す『に』。"}, {"text": "を", "is_correct": false, "explanation": "『を』は他動詞の目的語で、進展は自動詞なので『けんかを進展して』は誤り。"}, {"text": "と", "is_correct": false, "explanation": "『と』は相手や引用を示し、『けんかと進展して』は変化先を表せない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐもので、『けんかの進展してしまいました』は文にならない。"}], "correct_answer": "に", "explanations": {"に": "『けんかに進展』で、進展の変化先を示す『に』。", "を": "『を』は他動詞の目的語で、進展は自動詞なので『けんかを進展して』は誤り。", "と": "『と』は相手や引用を示し、『けんかと進展して』は変化先を表せない。", "の": "『の』は名詞をつなぐもので、『けんかの進展してしまいました』は文にならない。"}, "error_tags": {"を": "目的語（自動詞の進展には付かない）", "と": "相手・引用（変化先を示せない）", "の": "連体修飾（述語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36409, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『病気に進展』で、進展の変化先を示す『に』。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示し、『病気で進展する』は変化先を表せない。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すが、進展は自動詞なので『病気を進展する』は不自然。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示し、『病気より進展する』は変化先を表せない。"}], "correct_answer": "に", "explanations": {"に": "『病気に進展』で、進展の変化先を示す『に』。", "で": "『で』は手段や場所を示し、『病気で進展する』は変化先を表せない。", "を": "『を』は目的語を示すが、進展は自動詞なので『病気を進展する』は不自然。", "より": "『より』は比較を示し、『病気より進展する』は変化先を表せない。"}, "error_tags": {"で": "手段・場所（変化先を示せない）", "より": "比較（変化先を示せない）", "を": "目的語（自動詞の進展には付かない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36409, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事が進行して、新しい段階や状態に移ること。", "primary_collocate": null, "pronunciation": "しんてん", "ipa": "ɕiɲteɴ", "syllable_count": 4, "sentences": [{"text": "事態は思わぬ方向に進展しました。", "target_word": "進展", "complexity_tier": "T3", "furigana": "事態[じたい]は思[おも]わぬ方向[ほうこう]に進展[しんてん]しました。", "sentence_source": "generated"}, {"text": "小さな口論が、大きなけんかに進展してしまいました。", "target_word": "進展", "complexity_tier": "T3", "furigana": "小[ちい]さな口論[こうろん]が、大[おお]きなけんかに進展[しんてん]してしまいました。", "sentence_source": "generated"}, {"text": "風邪が肺炎に進展することもあるので、注意してください。", "target_word": "進展", "complexity_tier": "T3", "furigana": "風邪[かぜ]が肺炎[はいえん]に進展[しんてん]することもあるので、注意[ちゅうい]してください。", "sentence_source": "generated"}, {"text": "話は急に進展して、来月には結婚することになりました。", "target_word": "進展", "complexity_tier": "T3", "furigana": "話[はなし]は急[きゅう]に進展[しんてん]して、来月[らいげつ]には結婚[けっこん]することになりました。", "sentence_source": "generated"}, {"text": "研究は基礎の段階から、実用の段階へ進展しました。", "target_word": "進展", "complexity_tier": "T3", "furigana": "研究[けんきゅう]は基礎[きそ]の段階[だんかい]から、実用[じつよう]の段階[だんかい]へ進展[しんてん]しました。", "sentence_source": "generated"}, {"text": "友情が恋愛に進展するとは、思っていませんでした。", "target_word": "進展", "complexity_tier": "T3", "furigana": "友情[ゆうじょう]が恋愛[れんあい]に進展[しんてん]するとは、思[おも]っていませんでした。", "sentence_source": "generated"}, {"text": "工事は計画どおり、次の段階に進展しています。", "target_word": "進展", "complexity_tier": "T3", "furigana": "工事[こうじ]は計画[けいかく]どおり、次[つぎ]の段階[だんかい]に進展[しんてん]しています。", "sentence_source": "generated"}, {"text": "軽い症状が重い病気に進展する前に、病院へ行きましょう。", "target_word": "進展", "complexity_tier": "T3", "furigana": "軽[かる]い症状[しょうじょう]が重[おも]い病気[びょうき]に進展[しんてん]する前[まえ]に、病院[びょういん]へ行[い]きましょう。", "sentence_source": "generated"}, {"text": "事態がさらに進展して、裁判になってしまいました。", "target_word": "進展", "complexity_tier": "T3", "furigana": "事態[じたい]がさらに進展[しんてん]して、裁判[さいばん]になってしまいました。", "sentence_source": "generated"}, {"text": "状況が新しい局面に進展したため、計画を見直しました。", "target_word": "進展", "complexity_tier": "T3", "furigana": "状況[じょうきょう]が新[あたら]しい局面[きょくめん]に進展[しんてん]したため、計画[けいかく]を見直[みなお]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "進展する", "label": "動詞 基本形"}, {"form": "進展した", "label": "過去形"}, {"form": "進展して", "label": "て形"}, {"form": "進展しない", "label": "否定形"}, {"form": "進展せず", "label": "否定連用形"}], "register": "polite (丁寧体)", "sense_fingerprint": "状況・関係・問題などが進み、前とは別の新しい段階や状態（よい悪いは問わない）に移ること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5fbc95f-0ae8-454f-a614-42c57107f7b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36409, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "進展", "is_correct": true, "explanation": "事態が方向を変えて新しい段階に移る、という文に合う。"}, {"text": "撤去", "is_correct": false, "explanation": "撤去は取り除く意味で、事態が方向を変える文には合わない。"}, {"text": "辞退", "is_correct": false, "explanation": "辞退は断る意味で、事態を主語にした文には使えない。"}, {"text": "停車", "is_correct": false, "explanation": "停車は車などが止まる意味で、事態には使えない。"}], "explanations": {"進展": "事態が方向を変えて新しい段階に移る、という文に合う。", "撤去": "撤去は取り除く意味で、事態が方向を変える文には合わない。", "辞退": "辞退は断る意味で、事態を主語にした文には使えない。", "停車": "停車は車などが止まる意味で、事態には使えない。"}, "sentence_index": 0, "correct_answer": "進展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "車が坂道を進展して、頂上へ向かいました。", "explanation": "ここは〈進行〉の意味。車が前へ動くことは進行と言い、進展は新しい段階への移りに使うので合わない。"}, {"text": "工事は大雨で進展しました。", "explanation": "ここは〈中断〉の意味。大雨で作業を途中で止める場合は中断を使うので、進展は合わない。"}, {"text": "選手が試合の途中で進展し、ベンチへ下がりました。", "explanation": "ここは〈交代〉の意味。選手を入れ替える場合は交代と言い、進展は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36409, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "進展", "is_correct": true, "explanation": "工事が計画どおりに次の段階へ移る、という文に合う。"}, {"text": "解析", "is_correct": false, "explanation": "解析は細かく分けて調べる意味で、次の段階に進むという文とは合わない。"}, {"text": "開放", "is_correct": false, "explanation": "開放は開いて自由にする意味で、段階が移る文には合わない。"}, {"text": "輸入", "is_correct": false, "explanation": "輸入は外国から取り入れる意味で、工事の段階には使えない。"}], "explanations": {"進展": "工事が計画どおりに次の段階へ移る、という文に合う。", "解析": "解析は細かく分けて調べる意味で、次の段階に進むという文とは合わない。", "開放": "開放は開いて自由にする意味で、段階が移る文には合わない。", "輸入": "輸入は外国から取り入れる意味で、工事の段階には使えない。"}, "sentence_index": 6, "correct_answer": "進展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部隊は夜明けに陣地から進展し、後方へ退いた。", "explanation": "ここは〈撤退〉の意味。進展は前へ進むことで、退いて離れる意味では使えないので合わない。"}, {"text": "雨は夜まで進展した。", "explanation": "ここは〈継続〉の意味。同じ状態が途切れず続く場合は継続を使い、進展は新しい段階へ移る意味なので合わない。"}, {"text": "彼は荷物を進展させて、棚の上へ置いた。", "explanation": "ここは〈移す〉の意味。物を別の場所へ動かす場合は移すを使い、進展は状況の段階には使うが物には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36409, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "相手との話が急に進展させて、会う日が決まりました。", "corrected_sentence": "相手との話が急に進展して、会う日が決まりました。", "error_description": "『進展させて』は他動詞で、誰かが話を進める意味になる。主語『話が』の文では誤り。正しくは自動詞の『進展して』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36409, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "話し合いは進展させて、結論が出た。", "corrected_sentence": "話し合いは進展して、結論が出た。", "error_description": "『進展させて』は他動詞で、誰かが進めるという意味になる。主語『話し合いは』の文では誤り。正しくは自動詞の『進展して』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
