INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36410, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「協働が苦手」の「が」は苦手な対象を示し、文が通る。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すので、苦手の対象は表せない。"}, {"text": "に", "is_correct": false, "explanation": "「協働に苦手」では対象を示せず、文の意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「協働で苦手」では手段の意味になり、文の意味が合わない。"}], "correct_answer": "が", "explanations": {"が": "「協働が苦手」の「が」は苦手な対象を示し、文が通る。", "と": "並列や相手を示すので、苦手の対象は表せない。", "に": "「協働に苦手」では対象を示せず、文の意味が通らない。", "で": "「協働で苦手」では手段の意味になり、文の意味が合わない。"}, "error_tags": {"と": "並列・相手", "に": "相手・場所", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36410, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たくさんの人が一緒に仕事をすること。", "primary_collocate": null, "pronunciation": "きょうどう", "ipa": "kʲoːdoː", "syllable_count": 4, "sentences": [{"text": "町の人々の協働で、公園がきれいになりました。", "target_word": "協働", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]の協働[きょうどう]で、公園[こうえん]がきれいになりました。", "sentence_source": "generated"}, {"text": "この仕事は一人では無理なので、みんなで協働して進めます。", "target_word": "協働して", "complexity_tier": "T3", "furigana": "この仕事[しごと]は一人[ひとり]では無理[むり]なので、みんなで協働[きょうどう]して進[すす]めます。", "sentence_source": "generated"}, {"text": "協働のおかげで、予定より早く工事が終わった。", "target_word": "協働", "complexity_tier": "T3", "furigana": "協働[きょうどう]のおかげで、予定[よてい]より早[はや]く工事[こうじ]が終[お]わった。", "sentence_source": "generated"}, {"text": "学生と地域の人が協働し、夏祭りを開いた。", "target_word": "協働し", "complexity_tier": "T3", "furigana": "学生[がくせい]と地域[ちいき]の人[ひと]が協働[きょうどう]し、夏祭[なつまつ]りを開[ひら]いた。", "sentence_source": "generated"}, {"text": "協働には、お互いを信じる気持ちが大切だ。", "target_word": "協働", "complexity_tier": "T3", "furigana": "協働[きょうどう]には、お互[たが]いを信[しん]じる気持[きも]ちが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "大勢の協働によって、大きな絵が完成した。", "target_word": "協働", "complexity_tier": "T3", "furigana": "大勢[おおぜい]の協働[きょうどう]によって、大[おお]きな絵[え]が完成[かんせい]した。", "sentence_source": "generated"}, {"text": "新しい校舎は、先生と保護者の協働から生まれた。", "target_word": "協働", "complexity_tier": "T3", "furigana": "新[あたら]しい校舎[こうしゃ]は、先生[せんせい]と保護者[ほごしゃ]の協働[きょうどう]から生[う]まれた。", "sentence_source": "generated"}, {"text": "協働が苦手な人でも、役割があれば参加しやすい。", "target_word": "協働", "complexity_tier": "T3", "furigana": "協働[きょうどう]が苦手[にがて]な人[ひと]でも、役割[やくわり]があれば参加[さんか]しやすい。", "sentence_source": "generated"}, {"text": "私たちは毎週集まって、協働で畑の世話をしている。", "target_word": "協働", "complexity_tier": "T3", "furigana": "私[わたし]たちは毎週[まいしゅう]集[あつ]まって、協働[きょうどう]で畑[はたけ]の世話[せわ]をしている。", "sentence_source": "generated"}, {"text": "協働の経験を通して、彼は仲間の大切さを知った。", "target_word": "協働", "complexity_tier": "T3", "furigana": "協働[きょうどう]の経験[けいけん]を通[とお]して、彼[かれ]は仲間[なかま]の大切[たいせつ]さを知[し]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "協働", "label": "基本形"}, {"form": "協働する", "label": "サ変動詞"}, {"form": "協働して", "label": "て形"}, {"form": "協働し", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "大勢の人が力を合わせて一緒に作業や仕事をすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36410, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "協働", "is_correct": true, "explanation": "名詞。「協働で」は皆が一緒に作業した手段を表し、文の意味が通る。"}, {"text": "反省", "is_correct": false, "explanation": "「反省で公園がきれいになった」は作業を表さず、文が通らない。"}, {"text": "誤解", "is_correct": false, "explanation": "誤解では公園を掃除できず、文の内容と合わない。"}, {"text": "迷惑", "is_correct": false, "explanation": "迷惑では公園がきれいにならず、文の意味が合わない。"}], "explanations": {"協働": "名詞。「協働で」は皆が一緒に作業した手段を表し、文の意味が通る。", "反省": "「反省で公園がきれいになった」は作業を表さず、文が通らない。", "誤解": "誤解では公園を掃除できず、文の内容と合わない。", "迷惑": "迷惑では公園がきれいにならず、文の意味が合わない。"}, "sentence_index": 0, "correct_answer": "協働"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一人で協働した。", "explanation": "ここは〈個人作業〉の意味。協働は複数の人が一緒に仕事をすることなので、ひとりで進める作業には合わない。"}, {"text": "寝る時間を協働した。", "explanation": "ここは〈決める〉の意味。協働は一緒に仕事をする意味なので、時間を決める場面には合わない。"}, {"text": "ゴミの量を協働した。", "explanation": "ここは〈量る〉の意味。協働は一緒に仕事をする意味なので、量を測る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36410, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "協働", "is_correct": true, "explanation": "名詞。先生と保護者が協力して作ったことを示し、「協働から生まれた」が通る。"}, {"text": "停電", "is_correct": false, "explanation": "停電から校舎が生まれるとは言えず、文の意味が合わない。"}, {"text": "注射", "is_correct": false, "explanation": "注射から校舎が生まれることはなく、文の意味が通らない。"}, {"text": "手術", "is_correct": false, "explanation": "手術から校舎が生まれることはなく、文の意味が通らない。"}], "explanations": {"協働": "名詞。先生と保護者が協力して作ったことを示し、「協働から生まれた」が通る。", "停電": "停電から校舎が生まれるとは言えず、文の意味が合わない。", "注射": "注射から校舎が生まれることはなく、文の意味が通らない。", "手術": "手術から校舎が生まれることはなく、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "協働"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達の意見を協働した。", "explanation": "ここは〈無視する〉の意味。協働は力を合わせる意味で、意見を退ける場面には合わない。"}, {"text": "彼は仕事の報告を協働した。", "explanation": "ここは〈報告する〉の意味。協働は力を合わせる意味なので、情報を伝える場面には合わない。"}, {"text": "二つの案の値段を協働した。", "explanation": "ここは〈値切る〉の意味。協働は力を合わせる意味なので、値段を下げる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36410, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の子どもたちは、協働しで川を掃除した。", "corrected_sentence": "町の子どもたちは、協働して川を掃除した。", "error_description": "「協働して」が濁って「協働しで」になっている。て形は「して」で、「しで」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36410, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域の人々を協働して、新しい店を作った。", "corrected_sentence": "地域の人々と協働して、新しい店を作った。", "error_description": "「協働して」には「と」で相手を示す。「人々を」の「を」は誤りで、「人々と」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36411, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「大学の協働」の「の」は協働の主体を示す修飾で、文の意味が通る。"}, {"text": "を", "is_correct": false, "explanation": "「大学を協働」では目的語にならず、文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、協働の主体を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すので、協働の主体を表せない。"}], "correct_answer": "の", "explanations": {"の": "「大学の協働」の「の」は協働の主体を示す修飾で、文の意味が通る。", "を": "「大学を協働」では目的語にならず、文の意味が通らない。", "へ": "方向を示すので、協働の主体を表せない。", "より": "比較を示すので、協働の主体を表せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36411, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「地域が」の「が」は主語を示し、協働する主体として文が通る。"}, {"text": "に", "is_correct": false, "explanation": "「地域に協働し」では主体を示せず、文の意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「地域の協働し」は動詞につながらず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「地域から協働し」では起点の意味になり、文の意味が合わない。"}], "correct_answer": "が", "explanations": {"が": "「地域が」の「が」は主語を示し、協働する主体として文が通る。", "に": "「地域に協働し」では主体を示せず、文の意味が通らない。", "の": "「地域の協働し」は動詞につながらず、文が成り立たない。", "から": "「地域から協働し」では起点の意味になり、文の意味が合わない。"}, "error_tags": {"に": "相手・場所", "の": "所有・修飾", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36411, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の人や組織が、同じ目標に向かって共に働くこと。", "primary_collocate": null, "pronunciation": "きょうどう", "ipa": "kʲoːdoː", "syllable_count": 4, "sentences": [{"text": "市と企業が協働して、環境を守る計画を作った。", "target_word": "協働して", "complexity_tier": "T3", "furigana": "市[し]と企業[きぎょう]が協働[きょうどう]して、環境[かんきょう]を守[まも]る計画[けいかく]を作[つく]った。", "sentence_source": "generated"}, {"text": "病院と大学の協働により、新しい治療法が生まれた。", "target_word": "協働", "complexity_tier": "T3", "furigana": "病院[びょういん]と大学[だいがく]の協働[きょうどう]により、新[あたら]しい治療法[ちりょうほう]が生[う]まれた。", "sentence_source": "generated"}, {"text": "協働を進めるには、目標を共有することが欠かせない。", "target_word": "協働", "complexity_tier": "T3", "furigana": "協働[きょうどう]を進[すす]めるには、目標[もくひょう]を共有[きょうゆう]することが欠[か]かせない。", "sentence_source": "generated"}, {"text": "二つの会社は協働で、新しいアプリを開発した。", "target_word": "協働", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]は協働[きょうどう]で、新[あたら]しいアプリを開発[かいはつ]した。", "sentence_source": "generated"}, {"text": "NPOと行政の協働が、被災地の復興を支えている。", "target_word": "協働", "complexity_tier": "T3", "furigana": "NPOと行政[ぎょうせい]の協働[きょうどう]が、被災地[ひさいち]の復興[ふっこう]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "国どうしの協働なしに、地球温暖化は止められない。", "target_word": "協働", "complexity_tier": "T3", "furigana": "国[くに]どうしの協働[きょうどう]なしに、地球温暖化[ちきゅうおんだんか]は止[と]められない。", "sentence_source": "generated"}, {"text": "協働の成果として、川の水質が改善した。", "target_word": "協働", "complexity_tier": "T3", "furigana": "協働[きょうどう]の成果[せいか]として、川[かわ]の水質[すいしつ]が改善[かいぜん]した。", "sentence_source": "generated"}, {"text": "学校と地域が協働し、子どもの安全を見守っている。", "target_word": "協働し", "complexity_tier": "T3", "furigana": "学校[がっこう]と地域[ちいき]が協働[きょうどう]し、子[こ]どもの安全[あんぜん]を見守[みまも]っている。", "sentence_source": "generated"}, {"text": "異なる分野の専門家が協働することで、新しい発想が生まれる。", "target_word": "協働する", "complexity_tier": "T3", "furigana": "異[こと]なる分野[ぶんや]の専門家[せんもんか]が協働[きょうどう]することで、新[あたら]しい発想[はっそう]が生[う]まれる。", "sentence_source": "generated"}, {"text": "両団体は協働に関する約束を交わし、来月から調査を始める。", "target_word": "協働", "complexity_tier": "T3", "furigana": "両団体[りょうだんたい]は協働[きょうどう]に関[かん]する約束[やくそく]を交[か]わし、来月[らいげつ]から調査[ちょうさ]を始[はじ]める。", "sentence_source": "generated"}], "morphological_forms": [{"form": "協働", "label": "基本形"}, {"form": "協働する", "label": "サ変動詞"}, {"form": "協働して", "label": "て形"}, {"form": "協働し", "label": "連用形"}], "register": "formal", "sense_fingerprint": "複数の人や組織が同じ目標のために対等に協力して働くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36411, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "協働して", "is_correct": true, "explanation": "て形。「市と企業が協働して」で、一緒に計画を作ったという意味が通る。"}, {"text": "漂白して", "is_correct": false, "explanation": "「漂白して」では環境を守る計画とつながらず、文の意味が通らない。"}, {"text": "誤解して", "is_correct": false, "explanation": "「誤解して計画を作った」となり、環境を守る計画の内容と合わない。"}, {"text": "迷惑して", "is_correct": false, "explanation": "「迷惑して計画を作った」となり、計画を作った動機と合わない。"}], "explanations": {"協働して": "て形。「市と企業が協働して」で、一緒に計画を作ったという意味が通る。", "漂白して": "「漂白して」では環境を守る計画とつながらず、文の意味が通らない。", "誤解して": "「誤解して計画を作った」となり、環境を守る計画の内容と合わない。", "迷惑して": "「迷惑して計画を作った」となり、計画を作った動機と合わない。"}, "sentence_index": 0, "correct_answer": "協働して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの会社は、同じ市場で、ライバル関係を協働した。", "explanation": "ここは〈対立する〉の意味。協働は力を合わせる意味なので、ライバルとして争う場面には合わない。"}, {"text": "新しい計画の期限を協働した。", "explanation": "ここは〈延期する〉の意味。協働は一緒に力を合わせる意味なので、期限を先送りする場面には合わない。"}, {"text": "ライバル社が市場を協働した。", "explanation": "ここは〈独占する〉の意味。協働は皆で力を合わせる意味で、ひとり占めする場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36411, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "協働", "is_correct": true, "explanation": "名詞。「協働の成果」は協力の結果を表し、文の意味が通る。"}, {"text": "事故", "is_correct": false, "explanation": "「事故の成果」では成果の意味にならず、文が通らない。"}, {"text": "寝坊", "is_correct": false, "explanation": "「寝坊の成果」は意味が通らず、文が成り立たない。"}, {"text": "停電", "is_correct": false, "explanation": "「停電の成果」は意味が通らず、水質の改善とつながらない。"}], "explanations": {"協働": "名詞。「協働の成果」は協力の結果を表し、文の意味が通る。", "事故": "「事故の成果」では成果の意味にならず、文が通らない。", "寝坊": "「寝坊の成果」は意味が通らず、文が成り立たない。", "停電": "「停電の成果」は意味が通らず、水質の改善とつながらない。"}, "sentence_index": 6, "correct_answer": "協働"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "両団体は会議の出席者の数を協働した。", "explanation": "ここは〈数える〉の意味。協働は力を合わせる意味なので、人数を数える場面には合わない。"}, {"text": "両団体は天気を協働した。", "explanation": "ここは〈予報する〉の意味。協働は力を合わせる意味なので、天気を読む場面には合わない。"}, {"text": "両団体は会社の株価を協働で、自分の財布に入れた。", "explanation": "ここは〈盗む〉の意味。協働は力を合わせる意味なので、他人の物を奪う場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36411, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市民は行政と協働を、道路を直した。", "corrected_sentence": "市民は行政と協働して、道路を直した。", "error_description": "「協働して」の「して」が「を」になっている。協働する形には「して」が必要で、「協働を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36411, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大学は企業を協働して、新しい教材を作った。", "corrected_sentence": "大学は企業と協働して、新しい教材を作った。", "error_description": "「協働して」には「と」で相手を示す。「企業を」の「を」は誤りで、「企業と」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
