INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36412, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "仕事や活動を実際に行う場所のことです。", "primary_collocate": null, "pronunciation": "げんば", "ipa": "geɴba", "syllable_count": 3, "sentences": [{"text": "工事の現場では、全員がヘルメットをかぶらなければならない。", "target_word": "現場", "complexity_tier": "T3", "furigana": "工事[こうじ]の現場[げんば]では、全員[ぜんいん]がヘルメットをかぶらなければならない。", "sentence_source": "generated"}, {"text": "新人のころは、現場で先輩から多くのことを学びました。", "target_word": "現場", "complexity_tier": "T3", "furigana": "新人[しんじん]のころは、現場[げんば]で先輩[せんぱい]から多[おお]くのことを学[まな]びました。", "sentence_source": "generated"}, {"text": "新しい機械の使い方は、現場で実際に動かしながら覚えるのが一番だ。", "target_word": "現場", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]の使[つか]い方[かた]は、現場[げんば]で実際[じっさい]に動[うご]かしながら覚[おぼ]えるのが一番[いちばん]だ。", "sentence_source": "generated"}, {"text": "現場の意見を聞かずに決めたので、社員から不満が出た。", "target_word": "現場", "complexity_tier": "T3", "furigana": "現場[げんば]の意見[いけん]を聞[き]かずに決[き]めたので、社員[しゃいん]から不満[ふまん]が出[で]た。", "sentence_source": "generated"}, {"text": "社長は毎週、工場の現場を見て回っています。", "target_word": "現場", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は毎週[まいしゅう]、工場[こうじょう]の現場[げんば]を見[み]て回[まわ]っています。", "sentence_source": "generated"}, {"text": "机の上で考えるだけでなく、現場に行って確かめることが大切だ。", "target_word": "現場", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]で考[かんが]えるだけでなく、現場[げんば]に行[い]って確[たし]かめることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "現場で働く人たちのおかげで、このビルは予定どおりに完成した。", "target_word": "現場", "complexity_tier": "T3", "furigana": "現場[げんば]で働[はたら]く人[ひと]たちのおかげで、このビルは予定[よてい]どおりに完成[かんせい]した。", "sentence_source": "generated"}, {"text": "この技術は研究室で作られたあと、すぐに現場で使われるようになった。", "target_word": "現場", "complexity_tier": "T3", "furigana": "この技術[ぎじゅつ]は研究室[けんきゅうしつ]で作[つく]られたあと、すぐに現場[げんば]で使[つか]われるようになった。", "sentence_source": "generated"}, {"text": "現場の作業員が足りなくて、工事が遅れている。", "target_word": "現場", "complexity_tier": "T3", "furigana": "現場[げんば]の作業員[さぎょういん]が足[た]りなくて、工事[こうじ]が遅[おく]れている。", "sentence_source": "generated"}, {"text": "彼は営業から現場の仕事に変わって、毎日外で働いています。", "target_word": "現場", "complexity_tier": "T3", "furigana": "彼[かれ]は営業[えいぎょう]から現場[げんば]の仕事[しごと]に変[か]わって、毎日[まいにち]外[そと]で働[はたら]いています。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "工事・仕事・作業が実際に行われている場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36412, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寝室", "is_correct": false, "explanation": "「工事の寝室」は意味が通らず、空欄には入らない。"}, {"text": "現場", "is_correct": true, "explanation": "「工事の現場」は作業が実際に行われる場所を表し、文の意味に合う。"}, {"text": "教室", "is_correct": false, "explanation": "「工事の教室」は成り立たず、空欄には入らない。"}, {"text": "音楽", "is_correct": false, "explanation": "「工事の音楽」は意味が通らず、場所を表す語でもないので入らない。"}], "explanations": {"寝室": "「工事の寝室」は意味が通らず、空欄には入らない。", "現場": "「工事の現場」は作業が実際に行われる場所を表し、文の意味に合う。", "教室": "「工事の教室」は成り立たず、空欄には入らない。", "音楽": "「工事の音楽」は意味が通らず、場所を表す語でもないので入らない。"}, "sentence_index": 0, "correct_answer": "現場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "理想と現場の値段に悩んだ。", "explanation": "ここは〈価格〉の意味。〈現場〉は場所を表すので、理想との値段の差を表すことはできない。"}, {"text": "町で不思議な現場が起きた。", "explanation": "ここは〈現象〉の意味。〈現場〉は仕事などが行われる場所で、出来事が「起きる」ものではない。"}, {"text": "長年の現場を実現した。", "explanation": "ここは〈夢〉の意味。〈現場〉は場所を表す語で、「実現する」対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36412, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教科書", "is_correct": false, "explanation": "「教科書で働く人たち」は意味が通らず、空欄には入らない。"}, {"text": "現場", "is_correct": true, "explanation": "「現場で働く人たち」は作業の現場で働く人を表し、文の意味に合う。"}, {"text": "段ボール", "is_correct": false, "explanation": "「段ボールで働く人たち」は成り立たず、空欄には入らない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖で働く人たち」は意味が通らず、空欄には入らない。"}], "explanations": {"教科書": "「教科書で働く人たち」は意味が通らず、空欄には入らない。", "現場": "「現場で働く人たち」は作業の現場で働く人を表し、文の意味に合う。", "段ボール": "「段ボールで働く人たち」は成り立たず、空欄には入らない。", "砂糖": "「砂糖で働く人たち」は意味が通らず、空欄には入らない。"}, "sentence_index": 6, "correct_answer": "現場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大きな現場を果たした。", "explanation": "ここは〈責任〉の意味。「果たす」対象は役割や務めで、〈現場〉は場所なので合わない。"}, {"text": "遅れた現場は、天気の悪さだった。", "explanation": "ここは〈理由〉の意味。〈現場〉は場所を表すので、遅れた原因という意味にはならない。"}, {"text": "この現場の結論は次の会議で決まる。", "explanation": "ここは〈結論〉の意味。〈現場〉は場所を表すので、会議で決まる結論の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36412, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新人は現場に仕事を覚える。", "corrected_sentence": "新人は現場で仕事を覚える。", "error_description": "動作が行われる場所は「で」で示す（現場で仕事を覚える）。「に」は到着点などを示すので「現場に仕事を覚える」は不自然で、誤り。誤りは「現場」に直接つく助詞「に」の部分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36412, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社長は休日も現場を食べて回っている。", "corrected_sentence": "社長は休日も現場を見て回っている。", "error_description": "「現場を見て回る」が正しい。「食べて回る」は〈現場〉と結びつく動詞として不自然で、誤り。誤りは「現場」に続く動詞の部分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36414, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「増える」の主語を示す〈が〉で、「摩擦が増えた」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「増える」は目的語を取らないので、「摩擦を増えた」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「摩擦に増えた」は変化の結果を表す形にならず、文が続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表さず、「摩擦へ増えた」は意味をなさない。"}], "correct_answer": "が", "explanations": {"が": "「増える」の主語を示す〈が〉で、「摩擦が増えた」が自然。", "を": "「増える」は目的語を取らないので、「摩擦を増えた」は不自然。", "に": "「摩擦に増えた」は変化の結果を表す形にならず、文が続かない。", "へ": "方向を表さず、「摩擦へ増えた」は意味をなさない。"}, "error_tags": {"を": "対象", "に": "変化の結果", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36414, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「摩擦」が主語となり、「親の悩みになっている」に続く。"}, {"text": "の", "is_correct": false, "explanation": "「兄弟の摩擦の、親の悩み」と続き、主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「兄弟の摩擦と、親の悩み」と並べる形になり、文の主語を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「摩擦を」は目的語になり、「なっている」の主語を示せない。文として不自然。"}], "correct_answer": "が", "explanations": {"が": "「摩擦」が主語となり、「親の悩みになっている」に続く。", "の": "「兄弟の摩擦の、親の悩み」と続き、主語にならない。", "と": "「兄弟の摩擦と、親の悩み」と並べる形になり、文の主語を示せない。", "を": "「摩擦を」は目的語になり、「なっている」の主語を示せない。文として不自然。"}, "error_tags": {"の": "所有", "と": "並列", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36414, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物と物がこすれ合うことからできた、人の間のいざこざ。", "primary_collocate": null, "pronunciation": "まさつ", "ipa": "masatsɯ", "syllable_count": 3, "sentences": [{"text": "兄と弟の間に、小さな摩擦が生まれた。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]の間[あいだ]に、小[ちい]さな摩擦[まさつ]が生[う]まれた。", "sentence_source": "generated"}, {"text": "引っ越してから、近所の人との摩擦が増えた。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]してから、近所[きんじょ]の人[ひと]との摩擦[まさつ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "話し方が強すぎて、友達との摩擦ができた。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "話[はな]し方[かた]が強[つよ]すぎて、友達[ともだち]との摩擦[まさつ]ができた。", "sentence_source": "generated"}, {"text": "家族の間の摩擦をなくすために、よく話し合った。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "家族[かぞく]の間[あいだ]の摩擦[まさつ]をなくすために、よく話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "彼女は職場での摩擦を避けて、あまり意見を言わない。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は職場[しょくば]での摩擦[まさつ]を避[さ]けて、あまり意見[いけん]を言[い]わない。", "sentence_source": "generated"}, {"text": "同じ部屋で暮らすと、どうしても摩擦が起きやすい。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "同[おな]じ部屋[へや]で暮[く]らすと、どうしても摩擦[まさつ]が起[お]きやすい。", "sentence_source": "generated"}, {"text": "隣の家との摩擦は、あいさつ一つで少なくなった。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]との摩擦[まさつ]は、あいさつ一[ひと]つで少[すく]なくなった。", "sentence_source": "generated"}, {"text": "兄弟の摩擦が、親の悩みになっている。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]の摩擦[まさつ]が、親[おや]の悩[なや]みになっている。", "sentence_source": "generated"}, {"text": "小さな誤解から、二人の間に摩擦が生じた。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "小[ちい]さな誤解[ごかい]から、二人[ふたり]の間[あいだ]に摩擦[まさつ]が生[しょう]じた。", "sentence_source": "generated"}, {"text": "摩擦を恐れていては、本当の友達はできない。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "摩擦[まさつ]を恐[おそ]れていては、本当[ほんとう]の友達[ともだち]はできない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "摩擦", "label": "基本形"}, {"form": "摩擦が", "label": "が格"}], "register": "neutral", "sense_fingerprint": "身近な人どうしの間に生じる小さないざこざ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36414, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摩擦", "is_correct": true, "explanation": "人どうしのいざこざを指し、「小さな摩擦が生まれた」として自然に成り立つ。"}, {"text": "紙", "is_correct": false, "explanation": "物で、人間関係のいざこざを表せず、「小さな紙が生まれた」は意味が通らない。"}, {"text": "切手", "is_correct": false, "explanation": "物で、兄と弟のあいだの問題を指せない。"}, {"text": "絵の具", "is_correct": false, "explanation": "物で、「小さな絵の具が生まれた」は不自然になる。"}], "explanations": {"摩擦": "人どうしのいざこざを指し、「小さな摩擦が生まれた」として自然に成り立つ。", "紙": "物で、人間関係のいざこざを表せず、「小さな紙が生まれた」は意味が通らない。", "切手": "物で、兄と弟のあいだの問題を指せない。", "絵の具": "物で、「小さな絵の具が生まれた」は不自然になる。"}, "sentence_index": 0, "correct_answer": "摩擦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先輩への摩擦を忘れず、丁寧に接した。", "explanation": "ここは〈尊敬〉の意味。相手を敬う気持ちを指す語で、衝突や対立を表す摩擦は合わない。"}, {"text": "友達の摩擦で、悩みが解決した。", "explanation": "ここは〈助言〉の意味。悩みを解決するのは助言で、対立を表す摩擦では場面に合わない。"}, {"text": "彼女の明るい摩擦で、場の空気が和らいだ。", "explanation": "ここは〈笑顔〉の意味。場を和ませるのは笑顔で、対立を表す摩擦は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36414, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摩擦", "is_correct": true, "explanation": "隣の家との人間関係のいざこざを指し、「少なくなった」と合う。"}, {"text": "豆", "is_correct": false, "explanation": "物で、「隣の家との豆」は成り立たない。"}, {"text": "缶", "is_correct": false, "explanation": "物で、人間関係の問題を指せない。"}, {"text": "靴下", "is_correct": false, "explanation": "物で、「隣の家との靴下」は不自然になる。"}], "explanations": {"摩擦": "隣の家との人間関係のいざこざを指し、「少なくなった」と合う。", "豆": "物で、「隣の家との豆」は成り立たない。", "缶": "物で、人間関係の問題を指せない。", "靴下": "物で、「隣の家との靴下」は不自然になる。"}, "sentence_index": 6, "correct_answer": "摩擦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その映画に深く摩擦した。", "explanation": "ここは〈感動〉の意味。心が強く動かされる体験で、人どうしのいざこざを表す摩擦とは合わない。"}, {"text": "彼は部下の摩擦を得ていた。", "explanation": "ここは〈信頼〉の意味。相手に任せられる状態を指す語で、いざこざを表す摩擦とは合わない。"}, {"text": "家族の摩擦を分かち合った。", "explanation": "ここは〈喜び〉の意味。よろこびを共に味わう語で、人の間のいざこざを表す摩擦とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36414, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週、家族の間に小さな摩擦を生まれた。", "corrected_sentence": "先週、家族の間に小さな摩擦が生まれた。", "error_description": "「生まれる」は「が」で主語を示す自動詞。「摩擦を」と書くと他動詞の目的語になり、誤りになる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36414, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同じ寮で暮らすと、どうしても摩擦を起きやすい。", "corrected_sentence": "同じ寮で暮らすと、どうしても摩擦が起きやすい。", "error_description": "「起きる」は自動詞なので、主語を「が」で示す。「摩擦を起きやすい」は「を」が目的語を表すため誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36415, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「起きた」の主語を示す〈が〉で、「摩擦が起きた」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「起きる」は目的語を取らないので、「摩擦を起きた」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "場所や時点を示す「に」では、「摩擦に起きた」は文が続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、「摩擦へ起きた」は意味をなさない。"}], "correct_answer": "が", "explanations": {"が": "「起きた」の主語を示す〈が〉で、「摩擦が起きた」が自然。", "を": "「起きる」は目的語を取らないので、「摩擦を起きた」は不自然。", "に": "場所や時点を示す「に」では、「摩擦に起きた」は文が続かない。", "へ": "方向を表すため、「摩擦へ起きた」は意味をなさない。"}, "error_tags": {"を": "対象", "に": "場所・時点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36415, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「減らそう」の対象を示す〈を〉で、「摩擦を減らそうとしている」が自然。"}, {"text": "と", "is_correct": false, "explanation": "「摩擦と減らそう」は対象にならず、並べる意味にもならない。"}, {"text": "の", "is_correct": false, "explanation": "「摩擦の減らそう」は所有の形で、減らす対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "「摩擦から減らそう」は起点の意味になり、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「減らそう」の対象を示す〈を〉で、「摩擦を減らそうとしている」が自然。", "と": "「摩擦と減らそう」は対象にならず、並べる意味にもならない。", "の": "「摩擦の減らそう」は所有の形で、減らす対象にならない。", "から": "「摩擦から減らそう」は起点の意味になり、対象を示せない。"}, "error_tags": {"と": "並列", "の": "所有", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36415, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "異なる意見や立場を持つ者同士がぶつかり合うことで生じる、対立や問題。", "primary_collocate": null, "pronunciation": "まさつ", "ipa": "masatsɯ", "syllable_count": 3, "sentences": [{"text": "二つの国の間で、貿易をめぐる摩擦が続いている。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]の間[あいだ]で、貿易[ぼうえき]をめぐる摩擦[まさつ]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "新しい方針をめぐって、会社の中で摩擦が起きた。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "新[あたら]しい方針[ほうしん]をめぐって、会社[かいしゃ]の中[なか]で摩擦[まさつ]が起[お]きた。", "sentence_source": "generated"}, {"text": "環境の問題で、住民と工場の間に摩擦が生じた。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "環境[かんきょう]の問題[もんだい]で、住民[じゅうみん]と工場[こうじょう]の間[あいだ]に摩擦[まさつ]が生[しょう]じた。", "sentence_source": "generated"}, {"text": "古い考えと新しい考えの摩擦は、どの時代にもある。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "古[ふる]い考[かんが]えと新[あたら]しい考[かんが]えの摩擦[まさつ]は、どの時代[じだい]にもある。", "sentence_source": "generated"}, {"text": "文化のちがいから、外国人と地域の人の摩擦が起こることがある。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "文化[ぶんか]のちがいから、外国人[がいこくじん]と地域[ちいき]の人[ひと]の摩擦[まさつ]が起[お]こることがある。", "sentence_source": "generated"}, {"text": "部長と社長の意見がちがい、摩擦が深まった。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "部長[ぶちょう]と社長[しゃちょう]の意見[いけん]がちがい、摩擦[まさつ]が深[ふか]まった。", "sentence_source": "generated"}, {"text": "世代ごとの価値観のちがいが、家庭内の摩擦を生む。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "世代[せだい]ごとの価値観[かちかん]のちがいが、家庭内[かていない]の摩擦[まさつ]を生[う]む。", "sentence_source": "generated"}, {"text": "政府は、近隣の国との摩擦を減らそうとしている。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "政府[せいふ]は、近隣[きんりん]の国[くに]との摩擦[まさつ]を減[へ]らそうとしている。", "sentence_source": "generated"}, {"text": "立場がちがえば、意見がぶつかって摩擦になるのは当然だ。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "立場[たちば]がちがえば、意見[いけん]がぶつかって摩擦[まさつ]になるのは当然[とうぜん]だ。", "sentence_source": "generated"}, {"text": "経済をめぐる摩擦が、会議で大きな問題になった。", "target_word": "摩擦", "complexity_tier": "T3", "furigana": "経済[けいざい]をめぐる摩擦[まさつ]が、会議[かいぎ]で大[おお]きな問題[もんだい]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "摩擦", "label": "基本形"}, {"form": "摩擦が", "label": "が格"}], "register": "formal", "sense_fingerprint": "意見・立場の違いによる組織や国どうしの対立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: ちがえ (Zipf 1.73)']::text[], '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36415, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摩擦", "is_correct": true, "explanation": "国どうしの対立を指し、「摩擦が続いている」と合う。"}, {"text": "豆腐", "is_correct": false, "explanation": "食べ物で、貿易をめぐる対立を表せない。"}, {"text": "電球", "is_correct": false, "explanation": "物で、「貿易をめぐる電球が続いている」は成り立たない。"}, {"text": "自転車", "is_correct": false, "explanation": "物で、国どうしの対立を指せない。"}], "explanations": {"摩擦": "国どうしの対立を指し、「摩擦が続いている」と合う。", "豆腐": "食べ物で、貿易をめぐる対立を表せない。", "電球": "物で、「貿易をめぐる電球が続いている」は成り立たない。", "自転車": "物で、国どうしの対立を指せない。"}, "sentence_index": 0, "correct_answer": "摩擦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "両国は摩擦して災害に対応した。", "explanation": "ここは〈協力〉の意味。互いに助け合って事に当たる行為を指す語で、対立を表す摩擦とは合わない。"}, {"text": "会議の説明を聞いて、摩擦した。", "explanation": "ここは〈納得〉の意味。説明を受け入れて理解した状態で、対立を表す摩擦とは合わない。"}, {"text": "彼女の摩擦は、大きな成果を生んだ。", "explanation": "ここは〈努力〉の意味。力を注いで成果を生むのは努力で、対立を表す摩擦では意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36415, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摩擦", "is_correct": true, "explanation": "家庭内の人どうしの対立を指し、「摩擦を生む」と合う。"}, {"text": "花瓶", "is_correct": false, "explanation": "物で、家庭内の対立を生むとは言えない。"}, {"text": "座布団", "is_correct": false, "explanation": "物で、「座布団を生む」は成り立たない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "物で、対立の意味にならない。"}], "explanations": {"摩擦": "家庭内の人どうしの対立を指し、「摩擦を生む」と合う。", "花瓶": "物で、家庭内の対立を生むとは言えない。", "座布団": "物で、「座布団を生む」は成り立たない。", "歯ブラシ": "物で、対立の意味にならない。"}, "sentence_index": 6, "correct_answer": "摩擦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "両国は、摩擦を重ねて互いの文化を学んだ。", "explanation": "ここは〈交流〉の意味。互いに行き来して親しむ行為で、対立を指す摩擦は合わない。"}, {"text": "二つの会社は、摩擦を進めて共同開発を始めた。", "explanation": "ここは〈交渉〉の意味。条件を話し合って進める行為で、対立を表す摩擦を進めるとは言わない。"}, {"text": "事故の摩擦で、車の前部が大きくへこんだ。", "explanation": "ここは〈衝突〉の意味。物が強くぶつかって壊れる場面は衝突で、摩擦では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36415, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "両国の間で、関税をめぐる摩擦を続いている。", "corrected_sentence": "両国の間で、関税をめぐる摩擦が続いている。", "error_description": "「続く」は自動詞なので主語を「が」で示す。「摩擦を」と書くと他動詞の目的語になり、誤りになる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36415, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "文化のちがいから、外国人と地域の人の摩擦を起きることがある。", "corrected_sentence": "文化のちがいから、外国人と地域の人の摩擦が起きることがある。", "error_description": "「起きる」は自動詞なので、主語を「が」で示す。「摩擦を」と書くと目的語になり、誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36416, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "生み出す対象を表す助詞です。"}, {"text": "に", "is_correct": false, "explanation": "「新商品に生み出す」は成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、ここでは不自然です。"}, {"text": "と", "is_correct": false, "explanation": "「新商品と生み出す」は意味が通りません。"}], "correct_answer": "を", "explanations": {"を": "生み出す対象を表す助詞です。", "に": "「新商品に生み出す」は成り立ちません。", "へ": "方向の助詞で、ここでは不自然です。", "と": "「新商品と生み出す」は意味が通りません。"}, "error_tags": {"に": "対象の誤用", "へ": "方向", "と": "共同・引用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "器を新しくつくることの反対で、あるものをなくします。"}, {"text": "作る", "is_correct": false, "explanation": "近い意味で、反対ではありません。"}, {"text": "描く", "is_correct": false, "explanation": "つくる側の行為で、反対ではありません。"}, {"text": "組み立てる", "is_correct": false, "explanation": "つくる側の行為で、反対ではありません。"}], "correct_answer": "壊す", "explanations": {"壊す": "器を新しくつくることの反対で、あるものをなくします。", "作る": "近い意味で、反対ではありません。", "描く": "つくる側の行為で、反対ではありません。", "組み立てる": "つくる側の行為で、反対ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36416, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "生み出す対象を表す助詞です。"}, {"text": "に", "is_correct": false, "explanation": "「遊びに生み出せる」は成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、ここでは不自然です。"}, {"text": "と", "is_correct": false, "explanation": "「遊びと生み出せる」は意味が通りません。"}], "correct_answer": "を", "explanations": {"を": "生み出す対象を表す助詞です。", "に": "「遊びに生み出せる」は成り立ちません。", "へ": "方向の助詞で、ここでは不自然です。", "と": "「遊びと生み出せる」は意味が通りません。"}, "error_tags": {"に": "対象の誤用", "へ": "方向", "と": "共同・引用"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消し去る", "is_correct": true, "explanation": "新しく生み出すことの反対で、あるものをなくします。"}, {"text": "築く", "is_correct": false, "explanation": "つくり上げる意味で、反対ではありません。"}, {"text": "編み出す", "is_correct": false, "explanation": "新しく考え出す意味で、近い語です。"}, {"text": "育てる", "is_correct": false, "explanation": "反対の関係ではありません。"}], "correct_answer": "消し去る", "explanations": {"消し去る": "新しく生み出すことの反対で、あるものをなくします。", "築く": "つくり上げる意味で、反対ではありません。", "編み出す": "新しく考え出す意味で、近い語です。", "育てる": "反対の関係ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36416, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "新しいものをつくる。", "primary_collocate": null, "pronunciation": "うみだす", "ipa": "ɯmidasɯ", "syllable_count": 4, "sentences": [{"text": "彼は曲を生み出す。", "target_word": "生み出す", "complexity_tier": "T1", "furigana": "彼[かれ]は曲[きょく]を生[う]み出[だ]す。", "sentence_source": "generated"}, {"text": "工場は新商品を生み出します。", "target_word": "生み出します", "complexity_tier": "T2", "furigana": "工場[こうじょう]は新商品[しんしょうひん]を生[う]み出[だ]します。", "sentence_source": "generated"}, {"text": "彼女は美しい絵を生み出しました。", "target_word": "生み出しました", "complexity_tier": "T2", "furigana": "彼女[かのじょ]は美[うつく]しい絵[え]を生[う]み出[だ]しました。", "sentence_source": "generated"}, {"text": "職人が長い時間をかけて、器を生み出している。", "target_word": "生み出して", "complexity_tier": "T3", "furigana": "職人[しょくにん]が長[なが]い時間[じかん]をかけて、器[うつわ]を生[う]み出[だ]している。", "sentence_source": "generated"}, {"text": "新しい味を生み出すために、毎日試している。", "target_word": "生み出す", "complexity_tier": "T3", "furigana": "新[あたら]しい味[あじ]を生[う]み出[だ]すために、毎日[まいにち]試[ため]している。", "sentence_source": "generated"}, {"text": "この会社は、世界で初めての機械を生み出した。", "target_word": "生み出した", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、世界[せかい]で初[はじ]めての機械[きかい]を生[う]み出[だ]した。", "sentence_source": "generated"}, {"text": "多くの名曲がこの小さな町から生み出された。", "target_word": "生み出された", "complexity_tier": "T4", "furigana": "多[おお]くの名曲[めいきょく]がこの小[ちい]さな町[まち]から生[う]み出[だ]された。", "sentence_source": "generated"}, {"text": "自分の手で新しい遊びを生み出せる。", "target_word": "生み出せる", "complexity_tier": "T3", "furigana": "自分[じぶん]の手[て]で新[あたら]しい遊[あそ]びを生[う]み出[だ]せる。", "sentence_source": "generated"}, {"text": "材料が足りなければ、新しい料理は生み出せない。", "target_word": "生み出せない", "complexity_tier": "T4", "furigana": "材料[ざいりょう]が足[た]りなければ、新[あたら]しい料理[りょうり]は生[う]み出[だ]せない。", "sentence_source": "generated"}, {"text": "新しい物を生み出す人は、いつも楽しそうだ。", "target_word": "生み出す", "complexity_tier": "T4", "furigana": "新[あたら]しい物[もの]を生[う]み出[だ]す人[ひと]は、いつも楽[たの]しそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生み出した", "label": "活用"}, {"form": "生み出さない", "label": "活用"}, {"form": "生み出せる", "label": "活用"}, {"form": "生み出される", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 新しいものをつくり出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36416, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生み出す", "is_correct": true, "explanation": "見出し語「うみだす」そのものです。"}, {"text": "売り出す", "is_correct": false, "explanation": "「うりだす」で、み→りの一拍だけが違います。"}, {"text": "打ち出す", "is_correct": false, "explanation": "「うちだす」で、み→ちの一拍だけが違います。"}, {"text": "浮き出す", "is_correct": false, "explanation": "「うきだす」で、み→きの一拍だけが違います。"}, {"text": "踏み出す", "is_correct": false, "explanation": "「ふみだす」で、う→ふの一拍だけが違います。"}], "explanations": {"生み出す": "見出し語「うみだす」そのものです。", "売り出す": "「うりだす」で、み→りの一拍だけが違います。", "打ち出す": "「うちだす」で、み→ちの一拍だけが違います。", "浮き出す": "「うきだす」で、み→きの一拍だけが違います。", "踏み出す": "「ふみだす」で、う→ふの一拍だけが違います。"}, "sentence_index": null, "correct_answer": "生み出す"}, "level_3": {"options": [{"text": "生み出す", "is_correct": true, "explanation": "曲という新しいものをつくる意味に合います。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが、曲を洗うでは意味が合わない。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが、曲を食べるでは意味が合わない。"}, {"text": "閉める", "is_correct": false, "explanation": "形は合うが、曲を閉めるでは意味が合わない。"}], "explanations": {"生み出す": "曲という新しいものをつくる意味に合います。", "洗う": "形は合うが、曲を洗うでは意味が合わない。", "食べる": "形は合うが、曲を食べるでは意味が合わない。", "閉める": "形は合うが、曲を閉めるでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "生み出す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、公園で犬を生み出している。", "explanation": "散歩させる意味では使えません。「生み出す」は新しいものをつくる意味です。"}, {"text": "重い荷物を二階まで生み出した。", "explanation": "運ぶ意味はなく、荷物を運ぶ場面には使えません。"}, {"text": "手紙を生み出して、内容を読んだ。", "explanation": "開ける意味では使えず、手紙の封を開く動作と合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36416, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生み出す", "is_correct": true, "explanation": "見出し語「うみだす」そのものです。"}, {"text": "汲み出す", "is_correct": false, "explanation": "「くみだす」で、う→くの一拍だけが違います。"}, {"text": "積み出す", "is_correct": false, "explanation": "「つみだす」で、う→つの一拍だけが違います。"}, {"text": "読み出す", "is_correct": false, "explanation": "「よみだす」で、う→よの一拍だけが違います。"}, {"text": "請け出す", "is_correct": false, "explanation": "「うけだす」で、み→けの一拍だけが違います。"}], "explanations": {"生み出す": "見出し語「うみだす」そのものです。", "汲み出す": "「くみだす」で、う→くの一拍だけが違います。", "積み出す": "「つみだす」で、う→つの一拍だけが違います。", "読み出す": "「よみだす」で、う→よの一拍だけが違います。", "請け出す": "「うけだす」で、み→けの一拍だけが違います。"}, "sentence_index": null, "correct_answer": "生み出す"}, "level_3": {"options": [{"text": "生み出された", "is_correct": true, "explanation": "名曲が町で新しくつくられたという意味に合います。"}, {"text": "食べられた", "is_correct": false, "explanation": "形は合うが、名曲が食べられたでは意味が合わない。"}, {"text": "閉められた", "is_correct": false, "explanation": "形は合うが、名曲が町から閉められたでは意味が合わない。"}, {"text": "洗われた", "is_correct": false, "explanation": "形は合うが、名曲が町から洗われたでは意味が合わない。"}], "explanations": {"生み出された": "名曲が町で新しくつくられたという意味に合います。", "食べられた": "形は合うが、名曲が食べられたでは意味が合わない。", "閉められた": "形は合うが、名曲が町から閉められたでは意味が合わない。", "洗われた": "形は合うが、名曲が町から洗われたでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "生み出された"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓を生み出して、風を入れた。", "explanation": "「生み出す」に開ける意味はなく、窓を開ける場面には使えません。"}, {"text": "バスを生み出すために駅へ走った。", "explanation": "バスに乗る意味では使えません。「生み出す」は新しくつくる意味です。"}, {"text": "古い服を生み出して、箱にしまった。", "explanation": "たたむ意味では使えず、服をたたむ場面と合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_val