INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36416, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は、世界で初めての機械に生み出した。", "corrected_sentence": "この会社は、世界で初めての機械を生み出した。", "error_description": "「生み出す」の対象には助詞「を」を使い、「に」は誤りです。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生み出します", "is_correct": true, "explanation": "文末で丁寧に言い切る形です。"}, {"text": "生み出せば", "is_correct": false, "explanation": "仮定形は文末で言い切れません。"}, {"text": "生み出して", "is_correct": false, "explanation": "て形では文が終わりません。"}, {"text": "生み出さず", "is_correct": false, "explanation": "「ず」の形で文を言い切ることはできません。"}], "correct_form": "生み出します", "base_form": "生み出す", "form_label": "丁寧形(ます形)", "sentence_index": 1, "explanations": {"生み出します": "文末で丁寧に言い切る形です。", "生み出せば": "仮定形は文末で言い切れません。", "生み出して": "て形では文が終わりません。", "生み出さず": "「ず」の形で文を言い切ることはできません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36416, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "職人の手によって、美しい器が生み出した。", "corrected_sentence": "職人の手によって、美しい器が生み出された。", "error_description": "器が主語なので、受身形「生み出された」にします。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生み出せる", "is_correct": true, "explanation": "「できる」の意味を表す可能形で、文末に合います。"}, {"text": "生み出して", "is_correct": false, "explanation": "て形では文が終わりません。"}, {"text": "生み出さず", "is_correct": false, "explanation": "「ず」の形で文を言い切ることはできません。"}, {"text": "生み出せば", "is_correct": false, "explanation": "仮定形は文末で言い切れません。"}], "correct_form": "生み出せる", "base_form": "生み出す", "form_label": "可能形", "sentence_index": 7, "explanations": {"生み出せる": "「できる」の意味を表す可能形で、文末に合います。", "生み出して": "て形では文が終わりません。", "生み出さず": "「ず」の形で文を言い切ることはできません。", "生み出せば": "仮定形は文末で言い切れません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36417, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "生み出す対象を表す助詞です。"}, {"text": "に", "is_correct": false, "explanation": "「価値に生み出す」は成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、ここでは不自然です。"}, {"text": "と", "is_correct": false, "explanation": "「価値と生み出す」は意味が通りません。"}], "correct_answer": "を", "explanations": {"を": "生み出す対象を表す助詞です。", "に": "「価値に生み出す」は成り立ちません。", "へ": "方向を表すので、ここでは不自然です。", "と": "「価値と生み出す」は意味が通りません。"}, "error_tags": {"に": "対象の誤用", "へ": "方向", "と": "共同・引用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "壊す", "is_correct": true, "explanation": "新しく生み出すことの反対で、あるものをなくします。"}, {"text": "作る", "is_correct": false, "explanation": "近い意味で、反対ではありません。"}, {"text": "考える", "is_correct": false, "explanation": "反対ではなく、生み出す前段階の行為です。"}, {"text": "見せる", "is_correct": false, "explanation": "反対の関係はありません。"}], "correct_answer": "壊す", "explanations": {"壊す": "新しく生み出すことの反対で、あるものをなくします。", "作る": "近い意味で、反対ではありません。", "考える": "反対ではなく、生み出す前段階の行為です。", "見せる": "反対の関係はありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36417, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "生み出した主体を表す助詞です。"}, {"text": "に", "is_correct": false, "explanation": "「彼女に生み出した物語」は主体を表せません。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、主体になりません。"}, {"text": "で", "is_correct": false, "explanation": "「彼女で生み出した」は不自然です。"}], "correct_answer": "が", "explanations": {"が": "生み出した主体を表す助詞です。", "に": "「彼女に生み出した物語」は主体を表せません。", "へ": "方向の助詞で、主体になりません。", "で": "「彼女で生み出した」は不自然です。"}, "error_tags": {"に": "主体の誤用", "へ": "方向", "で": "手段・場所"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "滅ぼす", "is_correct": true, "explanation": "生み出すの反対で、あるものをなくします。"}, {"text": "築く", "is_correct": false, "explanation": "つくり上げる意味で、反対ではありません。"}, {"text": "育てる", "is_correct": false, "explanation": "反対の関係ではありません。"}, {"text": "描く", "is_correct": false, "explanation": "反対の関係ではありません。"}], "correct_answer": "滅ぼす", "explanations": {"滅ぼす": "生み出すの反対で、あるものをなくします。", "築く": "つくり上げる意味で、反対ではありません。", "育てる": "反対の関係ではありません。", "描く": "反対の関係ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36417, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "考えや物事を、今までなかった形にして外に出す。", "primary_collocate": null, "pronunciation": "うみだす", "ipa": "ɯmidasɯ", "syllable_count": 4, "sentences": [{"text": "さらに、こうした緑の拠点が生み出す波及効果は計り知れない。", "target_word": "生み出す", "complexity_tier": "T6", "furigana": "さらに、こうした緑[みどり]の拠点[きょてん]が生[う]み出[だ]す波及[はきゅう]効果[こうか]は計[はか]り知[し]れない。", "sentence_source": "mined"}, {"text": "新しい考えが価値を生み出します。", "target_word": "生み出します", "complexity_tier": "T2", "furigana": "新[あたら]しい考[かんが]えが価値[かち]を生[う]み出[だ]します。", "sentence_source": "generated"}, {"text": "彼は古い技術から方法を生み出した。", "target_word": "生み出した", "complexity_tier": "T3", "furigana": "彼[かれ]は古[ふる]い技術[ぎじゅつ]から方法[ほうほう]を生[う]み出[だ]した。", "sentence_source": "generated"}, {"text": "笑いを生み出す。", "target_word": "生み出す", "complexity_tier": "T1", "furigana": "笑[わら]いを生[う]み出[だ]す。", "sentence_source": "generated"}, {"text": "話し合って案を生み出している。", "target_word": "生み出して", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]って案[あん]を生[う]み出[だ]している。", "sentence_source": "generated"}, {"text": "この制度によって多くの雇用が生み出された。", "target_word": "生み出された", "complexity_tier": "T4", "furigana": "この制度[せいど]によって多[おお]くの雇用[こよう]が生[う]み出[だ]された。", "sentence_source": "generated"}, {"text": "発想を変えれば、新しい価値を生み出せる。", "target_word": "生み出せる", "complexity_tier": "T4", "furigana": "発想[はっそう]を変[か]えれば、新[あたら]しい価値[かち]を生[う]み出[だ]せる。", "sentence_source": "generated"}, {"text": "彼女が生み出した物語は、世界中の子どもたちに愛されている。", "target_word": "生み出した", "complexity_tier": "T5", "furigana": "彼女[かのじょ]が生[う]み出[だ]した物語[ものがたり]は、世界中[せかいじゅう]の子[こ]どもたちに愛[あい]されている。", "sentence_source": "generated"}, {"text": "新しいアイデアを生み出して、会社を大きくした。", "target_word": "生み出して", "complexity_tier": "T3", "furigana": "新[あたら]しいアイデアを生[う]み出[だ]して、会社[かいしゃ]を大[おお]きくした。", "sentence_source": "generated"}, {"text": "自由な時間は、新しい発想を生み出す土壌になる。", "target_word": "生み出す", "complexity_tier": "T4", "furigana": "自由[じゆう]な時間[じかん]は、新[あたら]しい発想[はっそう]を生[う]み出[だ]す土壌[どじょう]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生み出した", "label": "活用"}, {"form": "生み出さない", "label": "活用"}, {"form": "生み出せる", "label": "活用"}, {"form": "生み出される", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 考えや結果を新しく外に生じさせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36417, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生み出す", "is_correct": true, "explanation": "見出し語「うみだす」そのものです。"}, {"text": "売り出す", "is_correct": false, "explanation": "「うりだす」で、み→りの一拍だけが違います。"}, {"text": "打ち出す", "is_correct": false, "explanation": "「うちだす」で、み→ちの一拍だけが違います。"}, {"text": "浮き出す", "is_correct": false, "explanation": "「うきだす」で、み→きの一拍だけが違います。"}, {"text": "踏み出す", "is_correct": false, "explanation": "「ふみだす」で、う→ふの一拍だけが違います。"}], "explanations": {"生み出す": "見出し語「うみだす」そのものです。", "売り出す": "「うりだす」で、み→りの一拍だけが違います。", "打ち出す": "「うちだす」で、み→ちの一拍だけが違います。", "浮き出す": "「うきだす」で、み→きの一拍だけが違います。", "踏み出す": "「ふみだす」で、う→ふの一拍だけが違います。"}, "sentence_index": null, "correct_answer": "生み出す"}, "level_3": {"options": [{"text": "生み出す", "is_correct": true, "explanation": "拠点が波及効果を新しく生じさせるという意味に合います。"}, {"text": "壊す", "is_correct": false, "explanation": "形は合うが、波及効果を壊すでは意味が合わない。"}, {"text": "眺める", "is_correct": false, "explanation": "形は合うが、拠点が効果を眺めるでは意味が合わない。"}, {"text": "忘れる", "is_correct": false, "explanation": "形は合うが、拠点が効果を忘れるでは意味が合わない。"}], "explanations": {"生み出す": "拠点が波及効果を新しく生じさせるという意味に合います。", "壊す": "形は合うが、波及効果を壊すでは意味が合わない。", "眺める": "形は合うが、拠点が効果を眺めるでは意味が合わない。", "忘れる": "形は合うが、拠点が効果を忘れるでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "生み出す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車を生み出して学校へ行った。", "explanation": "「生み出す」は新しく形にして出す意味で、乗り物に乗る意味では使えません。"}, {"text": "ご飯を生み出して、お腹がいっぱいだ。", "explanation": "「生み出す」に食べる意味はなく、ご飯を食べる場面には使えません。"}, {"text": "駅で友達を生み出して、一緒に帰った。", "explanation": "「生み出す」は人と会う・待つ意味では使えず、友達を新しくつくり出す意味にもなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36417, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生み出す", "is_correct": true, "explanation": "見出し語「うみだす」そのものです。"}, {"text": "汲み出す", "is_correct": false, "explanation": "「くみだす」で、う→くの一拍だけが違います。"}, {"text": "積み出す", "is_correct": false, "explanation": "「つみだす」で、う→つの一拍だけが違います。"}, {"text": "読み出す", "is_correct": false, "explanation": "「よみだす」で、う→よの一拍だけが違います。"}, {"text": "請け出す", "is_correct": false, "explanation": "「うけだす」で、み→けの一拍だけが違います。"}], "explanations": {"生み出す": "見出し語「うみだす」そのものです。", "汲み出す": "「くみだす」で、う→くの一拍だけが違います。", "積み出す": "「つみだす」で、う→つの一拍だけが違います。", "読み出す": "「よみだす」で、う→よの一拍だけが違います。", "請け出す": "「うけだす」で、み→けの一拍だけが違います。"}, "sentence_index": null, "correct_answer": "生み出す"}, "level_3": {"options": [{"text": "生み出せる", "is_correct": true, "explanation": "発想を変えれば新しい価値をつくり出せるという意味に合います。"}, {"text": "洗える", "is_correct": false, "explanation": "形は合うが、価値を洗えるでは意味が合わない。"}, {"text": "飲める", "is_correct": false, "explanation": "形は合うが、価値を飲めるでは意味が合わない。"}, {"text": "踏める", "is_correct": false, "explanation": "形は合うが、価値を踏めるでは意味が合わない。"}], "explanations": {"生み出せる": "発想を変えれば新しい価値をつくり出せるという意味に合います。", "洗える": "形は合うが、価値を洗えるでは意味が合わない。", "飲める": "形は合うが、価値を飲めるでは意味が合わない。", "踏める": "形は合うが、価値を踏めるでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "生み出せる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は財布を道に生み出してしまった。", "explanation": "「生み出す」に落とす意味はなく、財布を落とす場面には使えません。"}, {"text": "先生の話を生み出して、よく分かった。", "explanation": "話を聞く意味では使えません。「生み出す」は新しく出す意味です。"}, {"text": "友達に傘を生み出した。", "explanation": "貸す・渡す意味には使えず、傘を新しくつくる意味にもなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_va