INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36417, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいアイデアに生み出して、会社を大きくした。", "corrected_sentence": "新しいアイデアを生み出して、会社を大きくした。", "error_description": "「生み出す」の対象を表す助詞は「を」で、「に」は誤りです。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生み出します", "is_correct": true, "explanation": "文末で丁寧に言い切る形で、空欄に合います。"}, {"text": "生み出せば", "is_correct": false, "explanation": "仮定形は文末で言い切れません。"}, {"text": "生み出して", "is_correct": false, "explanation": "て形では文が終わりません。"}, {"text": "生み出さず", "is_correct": false, "explanation": "「ず」の形で文を言い切ることはできません。"}], "correct_form": "生み出します", "base_form": "生み出す", "form_label": "丁寧形(ます形)", "sentence_index": 1, "explanations": {"生み出します": "文末で丁寧に言い切る形で、空欄に合います。", "生み出せば": "仮定形は文末で言い切れません。", "生み出して": "て形では文が終わりません。", "生み出さず": "「ず」の形で文を言い切ることはできません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36417, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この制度によって多くの雇用が生み出した。", "corrected_sentence": "この制度によって多くの雇用が生み出された。", "error_description": "雇用が主語なので、受身形「生み出された」にします。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生み出した", "is_correct": true, "explanation": "名詞「物語」を修飾する過去の連体形です。"}, {"text": "生み出して", "is_correct": false, "explanation": "て形は名詞を修飾できません。"}, {"text": "生み出せば", "is_correct": false, "explanation": "仮定形は名詞を修飾できません。"}, {"text": "生み出そう", "is_correct": false, "explanation": "意志形は名詞を修飾できません。"}], "correct_form": "生み出した", "base_form": "生み出す", "form_label": "過去形(連体)", "sentence_index": 7, "explanations": {"生み出した": "名詞「物語」を修飾する過去の連体形です。", "生み出して": "て形は名詞を修飾できません。", "生み出せば": "仮定形は名詞を修飾できません。", "生み出そう": "意志形は名詞を修飾できません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36418, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜になった」で、ある状態に変わったことを表すので自然。"}, {"text": "から", "is_correct": false, "explanation": "「〜からなった」は起点や材料を表し、「なった」の前には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる相手を表し、「なった」とは続かない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ語で、「なった」の前には立てない。"}], "correct_answer": "に", "explanations": {"に": "「〜になった」で、ある状態に変わったことを表すので自然。", "から": "「〜からなった」は起点や材料を表し、「なった」の前には合わない。", "より": "「より」は比べる相手を表し、「なった」とは続かない。", "の": "「の」は名詞をつなぐ語で、「なった」の前には立てない。"}, "error_tags": {"から": "source/starting point", "より": "comparison", "の": "possessive/modifier"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36418, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「する」の目的語として、動作の対象を表すので自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すので、「して」の目的語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すので、「する」の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「して」とは続かない。"}], "correct_answer": "を", "explanations": {"を": "「する」の目的語として、動作の対象を表すので自然。", "が": "「が」は主語を表すので、「して」の目的語にはならない。", "で": "「で」は手段や場所を表すので、「する」の目的語にはならない。", "へ": "「へ」は方向を表すので、「して」とは続かない。"}, "error_tags": {"が": "subject", "で": "means/location", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36418, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人と人が意見を出し合いながら、話し合うこと。", "primary_collocate": null, "pronunciation": "でぃすかっしょん", "ipa": "disɯkaɕːoɴ", "syllable_count": 6, "sentences": [{"text": "授業の最後に、クラスでディスカッションをした。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の最後[さいご]に、クラスでディスカッションをした。", "sentence_source": "generated"}, {"text": "意見が分かれたので、長いディスカッションになった。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "意見[いけん]が分[わ]かれたので、長[なが]いディスカッションになった。", "sentence_source": "generated"}, {"text": "彼はディスカッションで、自分の考えをはっきり話した。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "彼[かれ]はディスカッションで、自分[じぶん]の考[かんが]えをはっきり話[はな]した。", "sentence_source": "generated"}, {"text": "グループでディスカッションをして、旅行の行き先を決めた。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "グループでディスカッションをして、旅行[りょこう]の行[い]き先[さき]を決[き]めた。", "sentence_source": "generated"}, {"text": "ディスカッションの時間が短くて、全員は話せなかった。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "ディスカッションの時間[じかん]が短[みじか]くて、全員[ぜんいん]は話[はな]せなかった。", "sentence_source": "generated"}, {"text": "先生は、ディスカッションの前に、テーマを黒板に書いた。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ディスカッションの前[まえ]に、テーマを黒板[こくばん]に書[か]いた。", "sentence_source": "generated"}, {"text": "人の話を聞かないと、いいディスカッションはできない。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "人[ひと]の話[はなし]を聞[き]かないと、いいディスカッションはできない。", "sentence_source": "generated"}, {"text": "夕食のあと、家族でディスカッションをして、引っ越しが決まった。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "夕食[ゆうしょく]のあと、家族[かぞく]でディスカッションをして、引[ひ]っ越[こ]しが決[き]まった。", "sentence_source": "generated"}, {"text": "ディスカッションが盛り上がって、休み時間になっても終わらなかった。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "ディスカッションが盛[も]り上[あ]がって、休[やす]み時間[じかん]になっても終[お]わらなかった。", "sentence_source": "generated"}, {"text": "留学生と日本人が、環境問題についてディスカッションをした。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]と日本人[にほんじん]が、環境[かんきょう]問題[もんだい]についてディスカッションをした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ディスカッション", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人どうしが意見を出し合って話し合うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36418, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ディスカッション", "is_correct": true, "explanation": "クラスで行う話し合いの活動で、「クラスで＿をした」に自然に入る。"}, {"text": "体温", "is_correct": false, "explanation": "体温はからだの温度で、クラスで行う活動の名前にはならない。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まることで、クラスで行う活動ではない。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は寝すごすことで、クラスで行う活動にはならない。"}], "explanations": {"ディスカッション": "クラスで行う話し合いの活動で、「クラスで＿をした」に自然に入る。", "体温": "体温はからだの温度で、クラスで行う活動の名前にはならない。", "停電": "停電は電気が止まることで、クラスで行う活動ではない。", "寝坊": "寝坊は寝すごすことで、クラスで行う活動にはならない。"}, "sentence_index": 0, "correct_answer": "ディスカッション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パソコンにディスカッションを入れて、データを読み込んだ。", "explanation": "ここは〈ディスク〉（記録媒体）の意味。話し合いの意味のディスカッションは、パソコンに入れる物ではない。"}, {"text": "この店で会員カードを見せると、ディスカッションが受けられる。", "explanation": "ここは〈ディスカウント〉（値引き）の意味。値段を下げる話ではないので合わない。"}, {"text": "店の入口に、新しいディスカッションを置いた。", "explanation": "ここは〈ディスプレイ〉（展示や飾りの品）の意味。店に置いて飾るものはディスプレイと言い、話し合いのディスカッションは置けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36418, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ディスカッション", "is_correct": true, "explanation": "話し合いの活動で、「いいディスカッションはできない」に入ると意味が通るので自然。"}, {"text": "筆箱", "is_correct": false, "explanation": "筆箱は文房具で、「いい筆箱はできない」は意味が通らない。"}, {"text": "大根", "is_correct": false, "explanation": "大根は野菜で、「大根はできない」は意味が通らない。"}, {"text": "感電", "is_correct": false, "explanation": "感電は電気が体に流れる出来事で、「感電はできない」は成り立たない。"}], "explanations": {"ディスカッション": "話し合いの活動で、「いいディスカッションはできない」に入ると意味が通るので自然。", "筆箱": "筆箱は文房具で、「いい筆箱はできない」は意味が通らない。", "大根": "大根は野菜で、「大根はできない」は意味が通らない。", "感電": "感電は電気が体に流れる出来事で、「感電はできない」は成り立たない。"}, "sentence_index": 6, "correct_answer": "ディスカッション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の前に、ディスカッションを配った。", "explanation": "ここは〈資料〉の意味。配れるのは紙の資料で、話し合いは配るものではないので合わない。"}, {"text": "運動会で、ディスカッションを遠くまで投げた。", "explanation": "ここは〈ディスカス〉（円盤投げの円盤）の意味。話し合いの意味のディスカッションは投げられない。"}, {"text": "汗をかいたので、ディスカッションを浴びた。", "explanation": "ここは〈シャワー〉の意味。ディスカッションは話し合いで、体に浴びるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36418, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放課後、クラスでディスカッションを食べた。", "corrected_sentence": "放課後、クラスでディスカッションをした。", "error_description": "「ディスカッション」は「する」と組み合わせる。「食べた」は誤りで、「した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36418, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週、ディスカッションにクラスの意見をまとめる予定だ。", "corrected_sentence": "来週、ディスカッションでクラスの意見をまとめる予定だ。", "error_description": "「ディスカッション」は手段を表すので「で」を使う。「に」は誤りで、「で」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36419, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「〜を通じて」の形で、きっかけや手段を表すので自然。"}, {"text": "が", "is_correct": false, "explanation": "「〜が通じて」は成り立たず、主語の形は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「〜で通じて」は成り立たない。「〜を通じて」の形で使う。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ語で、「通じて」の前には立てない。"}], "correct_answer": "を", "explanations": {"を": "「〜を通じて」の形で、きっかけや手段を表すので自然。", "が": "「〜が通じて」は成り立たず、主語の形は合わない。", "で": "「〜で通じて」は成り立たない。「〜を通じて」の形で使う。", "の": "「の」は名詞をつなぐ語で、「通じて」の前には立てない。"}, "error_tags": {"が": "subject", "で": "means/location", "の": "possessive/modifier"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36419, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「重ねた」の目的語として、動作の対象を「を」で示すので自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「重ねた」の目的語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「重ねた」の目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる基準を表すので、「重ねた」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「重ねた」の目的語として、動作の対象を「を」で示すので自然。", "へ": "「へ」は方向を表すので、「重ねた」の目的語にはならない。", "から": "「から」は起点を表すので、「重ねた」の目的語にはならない。", "より": "「より」は比べる基準を表すので、「重ねた」の目的語にはならない。"}, "error_tags": {"へ": "direction", "から": "source/starting point", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36419, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あるテーマについて、複数の人が自分の意見や考えを述べ合い、理解を深めたり解決策を探ったりすること。", "primary_collocate": null, "pronunciation": "でぃすかっしょん", "ipa": "disɯkaɕːoɴ", "syllable_count": 6, "sentences": [{"text": "会議では、新しい制度についてディスカッションが行われた。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、新[あたら]しい制度[せいど]についてディスカッションが行[おこな]われた。", "sentence_source": "generated"}, {"text": "ディスカッションを通じて、問題の原因がはっきりしてきた。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "ディスカッションを通[つう]じて、問題[もんだい]の原因[げんいん]がはっきりしてきた。", "sentence_source": "generated"}, {"text": "このゼミでは、毎週一つのテーマでディスカッションをする。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "このゼミでは、毎週[まいしゅう]一[ひと]つのテーマでディスカッションをする。", "sentence_source": "generated"}, {"text": "ディスカッションのおかげで、自分とちがう考え方を知った。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "ディスカッションのおかげで、自分[じぶん]とちがう考[かんが]え方[かた]を知[し]った。", "sentence_source": "generated"}, {"text": "解決策は見つからなかったが、ディスカッションで課題は整理できた。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "解決策[かいけつさく]は見[み]つからなかったが、ディスカッションで課題[かだい]は整理[せいり]できた。", "sentence_source": "generated"}, {"text": "参加者が自由に意見を述べるディスカッションの場を設けた。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]が自由[じゆう]に意見[いけん]を述[の]べるディスカッションの場[ば]を設[もう]けた。", "sentence_source": "generated"}, {"text": "ディスカッションの司会は、全員が話せるように気を配る。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "ディスカッションの司会[しかい]は、全員[ぜんいん]が話[はな]せるように気[き]を配[くば]る。", "sentence_source": "generated"}, {"text": "賛成と反対の両方の立場からディスカッションを重ねた。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "賛成[さんせい]と反対[はんたい]の両方[りょうほう]の立場[たちば]からディスカッションを重[かさ]ねた。", "sentence_source": "generated"}, {"text": "事前に資料を読んでおくと、ディスカッションが深まる。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "事前[じぜん]に資料[しりょう]を読[よ]んでおくと、ディスカッションが深[ふか]まる。", "sentence_source": "generated"}, {"text": "専門家を呼んで、地域の防災についてディスカッションを開いた。", "target_word": "ディスカッション", "complexity_tier": "T3", "furigana": "専門家[せんもんか]を呼[よ]んで、地域[ちいき]の防災[ぼうさい]についてディスカッションを開[ひら]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ディスカッション", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "テーマについて複数の人が意見を述べ合い、理解を深めたり解決策を探ったりすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36419, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ディスカッション", "is_correct": true, "explanation": "制度について話し合う活動で、「行われた」と自然につながる。"}, {"text": "雨季", "is_correct": false, "explanation": "雨季は季節で、制度について行われるものではない。"}, {"text": "大根", "is_correct": false, "explanation": "大根は野菜で、「行われた」とつながる活動ではない。"}, {"text": "駅員", "is_correct": false, "explanation": "駅員は職業で、「行われた」の主語にはならない。"}], "explanations": {"ディスカッション": "制度について話し合う活動で、「行われた」と自然につながる。", "雨季": "雨季は季節で、制度について行われるものではない。", "大根": "大根は野菜で、「行われた」とつながる活動ではない。", "駅員": "駅員は職業で、「行われた」の主語にはならない。"}, "sentence_index": 0, "correct_answer": "ディスカッション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店のディスカッションを変えて、客を増やした。", "explanation": "ここは〈ディスプレイ〉（商品の陳列）の意味。話し合いの意味のディスカッションは、店の陳列には使わない。"}, {"text": "人と並んで歩くときは、ディスカッションを保つようにしている。", "explanation": "ここは〈ディスタンス〉（間隔）の意味。話し合いのディスカッションは間隔を表さないので合わない。"}, {"text": "夜はディスカッションを食べる予定だ。", "explanation": "ここは〈ディナー〉（夕食）の意味。ディナーは食べるものだが、ディスカッションは話し合いで食べ物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36419, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ディスカッション", "is_correct": true, "explanation": "話し合いの活動で、「＿の司会」と言えるので自然。"}, {"text": "感電", "is_correct": false, "explanation": "感電は電気が体に流れる出来事で、「感電の司会」は意味が通らない。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は寝すごすことで、「寝坊の司会」は意味が通らない。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まることで、「停電の司会」は意味が通らない。"}], "explanations": {"ディスカッション": "話し合いの活動で、「＿の司会」と言えるので自然。", "感電": "感電は電気が体に流れる出来事で、「感電の司会」は意味が通らない。", "寝坊": "寝坊は寝すごすことで、「寝坊の司会」は意味が通らない。", "停電": "停電は電気が止まることで、「停電の司会」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "ディスカッション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末は友達とディスカッションで踊った。", "explanation": "ここは〈ディスコ〉（踊る場所）の意味。ディスカッションは話し合いで、踊る場所にはならない。"}, {"text": "船のディスカッションで海を眺めた。", "explanation": "ここは〈デッキ〉（甲板）の意味。ディスカッションは場所ではないので合わない。"}, {"text": "会社のディスカッションが古くなったので、買い替えた。", "explanation": "ここは〈デスクトップ〉（パソコンの一種）の意味。ディスカッションは話し合いで、物として古くならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36419, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週、班ごとにディスカッションで開いた。", "corrected_sentence": "先週、班ごとにディスカッションを開いた。", "error_description": "「開く」の目的語には「を」を使う。「ディスカッションで」は誤りで、「ディスカッションを」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36419, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週は、班ごとにディスカッションを重ねた予定だ。", "corrected_sentence": "来週は、班ごとにディスカッションを重ねる予定だ。", "error_description": "「予定」の前には動詞の辞書形を置く。「重ねた」は過去形で、未来の予定と合わない。「重ねる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36420, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『枠組みの中』で、名詞をつなぐ『の』。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示し、『枠組みを中で』は文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や相手を示し、『枠組みに中で』は不自然。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示し、『枠組みと中で』は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "『枠組みの中』で、名詞をつなぐ『の』。", "を": "『を』は目的語を示し、『枠組みを中で』は文として成り立たない。", "に": "『に』は位置や相手を示し、『枠組みに中で』は不自然。", "と": "『と』は並列や相手を示し、『枠組みと中で』は成り立たない。"}, "error_tags": {"を": "目的語（名詞をつなぐ位置に合わない）", "に": "位置・相手（名詞の連結に合わない）", "と": "並列・相手（名詞の連結に合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36420, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『枠組みを学ぶ』で、学ぶの対象を示す『を』。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示し、『枠組みが学ぶ』は主語と動詞が合わず誤り。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示し、『枠組みへ学ぶ』は学ぶの対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示し、『枠組みより学ぶ』は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『枠組みを学ぶ』で、学ぶの対象を示す『を』。", "が": "『が』は主語を示し、『枠組みが学ぶ』は主語と動詞が合わず誤り。", "へ": "『へ』は方向を示し、『枠組みへ学ぶ』は学ぶの対象にならない。", "より": "『より』は比較を示し、『枠組みより学ぶ』は成り立たない。"}, "error_tags": {"が": "主語（学ぶの対象を示せない）", "へ": "方向（学ぶの対象に合わない）", "より": "比較（学ぶの対象に合わない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36420, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを作るときの、形やしくみの土台のこと。", "primary_collocate": null, "pronunciation": "わくぐみ", "ipa": "wakɯɡɯmi", "syllable_count": 4, "sentences": [{"text": "新しい計画の枠組みが、ようやく決まりました。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "新[あたら]しい計画[けいかく]の枠組[わくぐ]みが、ようやく決[き]まりました。", "sentence_source": "generated"}, {"text": "この法律は、国際的な枠組みの中で作られた。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "この法律[ほうりつ]は、国際的[こくさいてき]な枠組[わくぐ]みの中[なか]で作[つく]られた。", "sentence_source": "generated"}, {"text": "まず全体の枠組みを考えてから、細かい内容を決めましょう。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "まず全体[ぜんたい]の枠組[わくぐ]みを考[かんが]えてから、細[こま]かい内容[ないよう]を決[き]めましょう。", "sentence_source": "generated"}, {"text": "家の枠組みができたので、次は壁を作ります。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "家[いえ]の枠組[わくぐ]みができたので、次[つぎ]は壁[かべ]を作[つく]ります。", "sentence_source": "generated"}, {"text": "研究の枠組みが弱いと、結果を信じにくい。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "研究[けんきゅう]の枠組[わくぐ]みが弱[よわ]いと、結果[けっか]を信[しん]じにくい。", "sentence_source": "generated"}, {"text": "彼は既存の枠組みにとらわれない考え方をする。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "彼[かれ]は既存[きそん]の枠組[わくぐ]みにとらわれない考[かんが]え方[かた]をする。", "sentence_source": "generated"}, {"text": "会議では、協力の枠組みについて話し合った。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、協力[きょうりょく]の枠組[わくぐ]みについて話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "この授業では、作文の枠組みを学びます。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "この授業[じゅぎょう]では、作文[さくぶん]の枠組[わくぐ]みを学[まな]びます。", "sentence_source": "generated"}, {"text": "枠組みさえ決まれば、あとの作業は早く進む。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "枠組[わくぐ]みさえ決[き]まれば、あとの作業[さぎょう]は早[はや]く進[すす]む。", "sentence_source": "generated"}, {"text": "新しい枠組みを作るには、時間と話し合いが必要だ。", "target_word": "枠組み", "complexity_tier": "T3", "furigana": "新[あたら]しい枠組[わくぐ]みを作[つく]るには、時間[じかん]と話[はな]し合[あ]いが必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "枠組み", "label": "基本形"}, {"form": "枠組", "label": "送り仮名を省いた形"}, {"form": "枠組みの", "label": "名詞+の"}], "register": "neutral", "sense_fingerprint": "物事を作る際の骨組みとなる、形やしくみの土台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5fbc95f-0ae8-454f-a614-42c57107f7b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36420, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "枠組み", "is_correct": true, "explanation": "計画の土台や仕組みを表し、『計画の枠組みが決まる』と合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様の意味で、『計画の天気が決まる』とは言えない。"}, {"text": "好み", "is_correct": false, "explanation": "好みは気に入る傾向の意味で、『計画の好みが決まる』は成り立たない。"}, {"text": "疲れ", "is_correct": false, "explanation": "疲れは体の状態の意味で、『計画の疲れが決まる』は成り立たない。"}], "explanations": {"枠組み": "計画の土台や仕組みを表し、『計画の枠組みが決まる』と合う。", "天気": "天気は空模様の意味で、『計画の天気が決まる』とは言えない。", "好み": "好みは気に入る傾向の意味で、『計画の好みが決まる』は成り立たない。", "疲れ": "疲れは体の状態の意味で、『計画の疲れが決まる』は成り立たない。"}, "sentence_index": 0, "correct_answer": "枠組み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理の枠組みには、塩を少し加えます。", "explanation": "ここは〈材料〉の意味。枠組みは仕組みや土台の意味で、食材や調味料は指さないので合わない。"}, {"text": "この布の枠組みは、細かい花の模様だ。", "explanation": "ここは〈模様〉の意味。布の柄は模様と言い、枠組みは土台や仕組みの意味なので合わない。"}, {"text": "夜空の枠組みに、星がきれいに光っている。", "explanation": "ここは〈景色〉の意味。空の見え方は景色と言い、枠組みは使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36420, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "枠組み", "is_correct": true, "explanation": "協力の仕組みや土台を表し、『協力の枠組みについて話し合う』と合う。"}, {"text": "味", "is_correct": false, "explanation": "味は食べ物の感じの意味で、『協力の味について話し合う』は成り立たない。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は寝すぎる意味で、『協力の寝坊について話し合う』は合わない。"}, {"text": "湯気", "is_correct": false, "explanation": "湯気は蒸気の意味で、『協力の湯気について話し合う』は成り立たない。"}], "explanations": {"枠組み": "協力の仕組みや土台を表し、『協力の枠組みについて話し合う』と合う。", "味": "味は食べ物の感じの意味で、『協力の味について話し合う』は成り立たない。", "寝坊": "寝坊は寝すぎる意味で、『協力の寝坊について話し合う』は合わない。", "湯気": "湯気は蒸気の意味で、『協力の湯気について話し合う』は成り立たない。"}, "sentence_index": 6, "correct_answer": "枠組み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は背が低いが、枠組みが太くて力が強い。", "explanation": "ここは〈骨格〉の意味。人の体の骨組みは骨格と言い、枠組みでは言わないので合わない。"}, {"text": "卵の枠組みが割れて、中身が出た。", "explanation": "ここは〈殻〉の意味。卵の外側の硬い部分は殻と言い、枠組みでは言わないので合わない。"}, {"text": "明日の天気は、枠組みが晴れだそうだ。", "explanation": "ここは〈予報〉の意味。天気の見通しは予報と言い、枠組みでは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36420, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "計画の枠組みが、来週までに決めます。", "corrected_sentence": "計画の枠組みを、来週までに決めます。", "error_description": "『決める』は他動詞で、目的語には『を』を付ける。『枠組みが』は誤りで、正しくは『枠組みを』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36420, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週の会議で、新しい枠組みに話し合います。", "corrected_sentence": "来週の会議で、新しい枠組みについて話し合います。", "error_description": "『話し合う』は『について』で話題を示す。『枠組みに』は誤りで、正しくは『枠組みについて』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36422, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「概念がない」の「が」は存在の主語を示す。「まだ〜がない」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「概念をない」は目的語になり、「ない」と結べない。"}, {"text": "から", "is_correct": false, "explanation": "「概念から」は起点を示す。「ない」とは結べない。"}, {"text": "と", "is_correct": false, "explanation": "「概念とない」は並列や相手を示し、「ない」と結べない。"}], "correct_answer": "が", "explanations": {"が": "「概念がない」の「が」は存在の主語を示す。「まだ〜がない」と続く。", "を": "「概念をない」は目的語になり、「ない」と結べない。", "から": "「概念から」は起点を示す。「ない」とは結べない。", "と": "「概念とない」は並列や相手を示し、「ない」と結べない。"}, "error_tags": {"を": "目的語", "から": "起点", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
