INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36422, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることについて、まとめて考えたもの。", "primary_collocate": null, "pronunciation": "がいねん", "ipa": "ɡaineɴ", "syllable_count": 4, "sentences": [{"text": "「平和」という概念を、絵で表してみよう。", "target_word": "概念", "complexity_tier": "T3", "furigana": "「平和[へいわ]」という概念[がいねん]を、絵[え]で表[あらわ]してみよう。", "sentence_source": "generated"}, {"text": "小さな子には、まだ時間の概念がない。", "target_word": "概念", "complexity_tier": "T3", "furigana": "小[ちい]さな子[こ]には、まだ時間[じかん]の概念[がいねん]がない。", "sentence_source": "generated"}, {"text": "先生は、「円」の概念を図で説明した。", "target_word": "概念", "complexity_tier": "T3", "furigana": "先生[せんせい]は、「円[えん]」の概念[がいねん]を図[ず]で説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この本は、むずかしい概念をやさしく説明している。", "target_word": "概念", "complexity_tier": "T3", "furigana": "この本[ほん]は、むずかしい概念[がいねん]をやさしく説明[せつめい]している。", "sentence_source": "generated"}, {"text": "外国語には、日本語では一言で表せない概念がある。", "target_word": "概念", "complexity_tier": "T3", "furigana": "外国語[がいこくご]には、日本語[にほんご]では一言[ひとこと]で表[あらわ]せない概念[がいねん]がある。", "sentence_source": "generated"}, {"text": "「友情」の概念は、人によって少しずつ違う。", "target_word": "概念", "complexity_tier": "T3", "furigana": "「友情[ゆうじょう]」の概念[がいねん]は、人[ひと]によって少[すこ]しずつ違[ちが]う。", "sentence_source": "generated"}, {"text": "概念がわかれば、問題はずっと解きやすくなる。", "target_word": "概念", "complexity_tier": "T3", "furigana": "概念[がいねん]がわかれば、問題[もんだい]はずっと解[と]きやすくなる。", "sentence_source": "generated"}, {"text": "彼の話は概念ばかりで、例がなくてわかりにくい。", "target_word": "概念", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は概念[がいねん]ばかりで、例[れい]がなくてわかりにくい。", "sentence_source": "generated"}, {"text": "「リサイクル」の概念は、今ではだれでも知っている。", "target_word": "概念", "complexity_tier": "T3", "furigana": "「リサイクル」の概念[がいねん]は、今[いま]ではだれでも知[し]っている。", "sentence_source": "generated"}, {"text": "授業でまず「速さ」の概念を学んだ。", "target_word": "概念", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]でまず「速[はや]さ」の概念[がいねん]を学[まな]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "概念的", "label": "adjectival (-teki)"}, {"form": "概念を", "label": "object-marked form"}], "register": "neutral", "sense_fingerprint": "あることについて全体をまとめて考えた内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32b69eeb-98c8-40d8-b5f5-d42b8a81ba55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36422, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概念", "is_correct": true, "explanation": "「という概念」は平和という一般的な考えのまとまりを指し、絵で表す対象として自然。"}, {"text": "延期", "is_correct": false, "explanation": "予定を延ばす意味。「平和」という言葉と結びつかず、絵で表す文には合わない。"}, {"text": "採用", "is_correct": false, "explanation": "採り入れる意味。「平和という〜」で言い表す対象にはならない。"}, {"text": "申請", "is_correct": false, "explanation": "許可を求める手続きの意味。「平和という申請」は絵で表す対象にならない。"}], "explanations": {"概念": "「という概念」は平和という一般的な考えのまとまりを指し、絵で表す対象として自然。", "延期": "予定を延ばす意味。「平和」という言葉と結びつかず、絵で表す文には合わない。", "採用": "採り入れる意味。「平和という〜」で言い表す対象にはならない。", "申請": "許可を求める手続きの意味。「平和という申請」は絵で表す対象にならない。"}, "sentence_index": 0, "correct_answer": "概念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画は、悲しい概念をうまく表している。", "explanation": "ここは〈感情〉（心の動き）の意味。概念はことばでまとめた考えなので、心の動きそのものを表す文には合わない。"}, {"text": "なぜ遅れたのか、その概念をやさしく説明した。", "explanation": "ここは〈理由〉（原因となる事情）の意味。概念は一般的な考えのまとまりなので、遅れた事情を指す文には合わない。"}, {"text": "パンの作り方を、概念で教えた。", "explanation": "ここは〈方法〉（やり方）の意味。概念は考えのまとまりなので、手順や作り方を示す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36422, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概念", "is_correct": true, "explanation": "「概念がわかれば」の主語。考え方を理解すれば問題が解けるという文で、空所に入る。"}, {"text": "混雑", "is_correct": false, "explanation": "人や物が込み合う意味。理解の対象として成り立たない。"}, {"text": "出版", "is_correct": false, "explanation": "書籍を世に出す意味。理解できるかどうかの文には合わない。"}, {"text": "寄付", "is_correct": false, "explanation": "金品を贈る意味。理解との関係が成り立たない。"}], "explanations": {"概念": "「概念がわかれば」の主語。考え方を理解すれば問題が解けるという文で、空所に入る。", "混雑": "人や物が込み合う意味。理解の対象として成り立たない。", "出版": "書籍を世に出す意味。理解できるかどうかの文には合わない。", "寄付": "金品を贈る意味。理解との関係が成り立たない。"}, "sentence_index": 6, "correct_answer": "概念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の概念は、やさしくて明るい。", "explanation": "ここは〈人柄〉（その人の性格）の意味。概念は一般的な考えのまとまりなので、人の性格を言う文には合わない。"}, {"text": "パンの概念を三つ用意した。", "explanation": "ここは〈材料〉（原料）の意味。概念は考えのまとまりなので、用意して使う物には合わない。"}, {"text": "このスープは、深い概念がある。", "explanation": "ここは〈味〉（味わい）の意味。概念は思考の産物なので、味の深さを表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36422, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は時間の概念をわかるのに苦労した。", "corrected_sentence": "彼は時間の概念がわかるのに苦労した。", "error_description": "「わかる」は対象を「が」で示す。「概念をわかる」の「を」は誤りで、「概念がわかる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36422, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人は「円」の概念に図で説明した。", "corrected_sentence": "友人は「円」の概念を図で説明した。", "error_description": "「説明する」は対象を「を」で示す。「概念に説明した」の「に」は誤りで、「概念を説明した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
