INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36423, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「概念が変わり」の「が」は主語を示す。概念が変わったという文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「概念を変わり」では目的語になり、変わる主体にならない。"}, {"text": "か", "is_correct": false, "explanation": "「概念か」は選択を示す。「変わり」とは続かない。"}, {"text": "と", "is_correct": false, "explanation": "「概念と変わり」は相手や並列を示し、主語の形にならない。"}], "correct_answer": "が", "explanations": {"が": "「概念が変わり」の「が」は主語を示す。概念が変わったという文に合う。", "を": "「概念を変わり」では目的語になり、変わる主体にならない。", "か": "「概念か」は選択を示す。「変わり」とは続かない。", "と": "「概念と変わり」は相手や並列を示し、主語の形にならない。"}, "error_tags": {"を": "目的語", "か": "選択", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36423, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の本質をとらえるために、思考によってつくり出された、一般的な意味をもつまとまり。", "primary_collocate": null, "pronunciation": "がいねん", "ipa": "ɡaineɴ", "syllable_count": 4, "sentences": [{"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "概念", "complexity_tier": "T5", "furigana": "かかる感覚的[かんかくてき]知見[ちけん]の蓄積[ちくせき]は、単一[たんいつ]品種[ひんしゅ]を基準[きじゅん]とした旧来[きゅうらい]の分類[ぶんるい]体系[たいけい]を相対化[そうたいか]し、微細[びさい]な区画[くかく]ごとの個性[こせい]を階層的[かいそうてき]に位置[いち]づけるアペラシオンの概念[がいねん]を、より厳密[げんみつ]かつ動的[どうてき]なヒエラルキーへと昇華[しょうか]させ、ワインの価値[かち]評価[ひょうか]基準[きじゅん]そのものを哲学的[てつがくてき]かつ実践的[じっせんてき]に再定義[さいていぎ]しているのである。", "sentence_source": "mined"}, {"text": "「自由」という概念は、国や時代によって受け取り方が違う。", "target_word": "概念", "complexity_tier": "T4", "furigana": "「自由[じゆう]」という概念[がいねん]は、国[くに]や時代[じだい]によって受[う]け取[と]り方[かた]が違[ちが]う。", "sentence_source": "generated"}, {"text": "子どもに時間の概念を教えるのは難しい。", "target_word": "概念", "complexity_tier": "T3", "furigana": "子[こ]どもに時間[じかん]の概念[がいねん]を教[おし]えるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼の提案は、従来の概念を大きく変えるものだった。", "target_word": "概念", "complexity_tier": "T4", "furigana": "彼[かれ]の提案[ていあん]は、従来[じゅうらい]の概念[がいねん]を大[おお]きく変[か]えるものだった。", "sentence_source": "generated"}, {"text": "哲学の授業で、「正義」の概念について議論した。", "target_word": "概念", "complexity_tier": "T4", "furigana": "哲学[てつがく]の授業[じゅぎょう]で、「正義[せいぎ]」の概念[がいねん]について議論[ぎろん]した。", "sentence_source": "generated"}, {"text": "数の概念が生まれたのは、ものを数える必要があったからだ。", "target_word": "概念", "complexity_tier": "T4", "furigana": "数[かず]の概念[がいねん]が生[う]まれたのは、ものを数[かぞ]える必要[ひつよう]があったからだ。", "sentence_source": "generated"}, {"text": "この言葉は日本語にはない概念を表している。", "target_word": "概念", "complexity_tier": "T3", "furigana": "この言葉[ことば]は日本語[にほんご]にはない概念[がいねん]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "「豊かさ」の概念が変わり、物より時間を大切にする人が増えた。", "target_word": "概念", "complexity_tier": "T4", "furigana": "「豊[ゆた]かさ」の概念[がいねん]が変[か]わり、物[もの]より時間[じかん]を大切[たいせつ]にする人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "新しい概念を理解するには、具体的な例が助けになる。", "target_word": "概念", "complexity_tier": "T4", "furigana": "新[あたら]しい概念[がいねん]を理解[りかい]するには、具体的[ぐたいてき]な例[れい]が助[たす]けになる。", "sentence_source": "generated"}, {"text": "「家族」の概念は、一つの形だけでは説明できない。", "target_word": "概念", "complexity_tier": "T4", "furigana": "「家族[かぞく]」の概念[がいねん]は、一[ひと]つの形[かたち]だけでは説明[せつめい]できない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "概念的", "label": "adjectival (-teki)"}, {"form": "概念を", "label": "object-marked form"}], "register": "formal", "sense_fingerprint": "物事の本質をとらえるために思考でつくった一般的な考えのまとまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: アペラシオン (Zipf 1.01)']::text[], '32b69eeb-98c8-40d8-b5f5-d42b8a81ba55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36423, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概念", "is_correct": true, "explanation": "「アペラシオンの概念」は個別の区画を位置づける考え方を指し、昇華させる対象として自然。"}, {"text": "延期", "is_correct": false, "explanation": "予定を延ばす意味。思考の枠組みを昇華させる文とは合わない。"}, {"text": "採用", "is_correct": false, "explanation": "採り入れる意味。ここで述べる考え方の変化には意味がつながらない。"}, {"text": "混雑", "is_correct": false, "explanation": "人や物が込み合う意味。抽象的な考え方を扱う文には合わない。"}], "explanations": {"概念": "「アペラシオンの概念」は個別の区画を位置づける考え方を指し、昇華させる対象として自然。", "延期": "予定を延ばす意味。思考の枠組みを昇華させる文とは合わない。", "採用": "採り入れる意味。ここで述べる考え方の変化には意味がつながらない。", "混雑": "人や物が込み合う意味。抽象的な考え方を扱う文には合わない。"}, "sentence_index": 0, "correct_answer": "概念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は、舌で感じる概念が鋭く、香りがよく残る。", "explanation": "ここは〈感覚〉（感じ取る働き）の意味。概念は思考でまとめた一般的な考えなので、舌で感じる鋭さには合わない。"}, {"text": "初対面の概念で、彼を判断してはいけない。", "explanation": "ここは〈印象〉（最初に受けた感じ）の意味。概念は一般的な考えのまとまりなので、個人に受けた印象の話には合わない。"}, {"text": "その商品の概念は、三千円だった。", "explanation": "ここは〈値段〉（代金）の意味。概念は思考でまとめた考えなので、金額を示す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36423, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概念", "is_correct": true, "explanation": "「概念を表している」の目的語。言葉が表す考え方のまとまりを指し、空所に入る。"}, {"text": "演奏", "is_correct": false, "explanation": "音楽を奏でる意味。言葉が表すものとしては成り立たない。"}, {"text": "寄付", "is_correct": false, "explanation": "金品を贈る意味。言葉が表す対象とは合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "掃除する意味。言葉が表すものとして入らない。"}], "explanations": {"概念": "「概念を表している」の目的語。言葉が表す考え方のまとまりを指し、空所に入る。", "演奏": "音楽を奏でる意味。言葉が表すものとしては成り立たない。", "寄付": "金品を贈る意味。言葉が表す対象とは合わない。", "清掃": "掃除する意味。言葉が表すものとして入らない。"}, "sentence_index": 6, "correct_answer": "概念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "まず泳ぎの概念を練習して、プールで実際に泳いだ。", "explanation": "ここは〈技術〉（体で覚えた能力）の意味。概念は思考でまとめた考えなので、体で練習する動作の話には合わない。"}, {"text": "料理の概念を一つずつ撮ってから、作り始めた。", "explanation": "ここは〈写真〉（写し取った像）の意味。概念は思考でまとめた考えなので、撮影する文には合わない。"}, {"text": "その映画を見て、概念をすぐ友人に送った。", "explanation": "ここは〈感想〉（心に受けた感じ）の意味。概念は一般的な考えのまとまりなので、見て感じたことを伝える文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36423, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもに時間の概念が教える授業だった。", "corrected_sentence": "子どもに時間の概念を教える授業だった。", "error_description": "「教える」は目的語を「を」で示す。「概念が教える」の「が」は誤りで、「概念を教える」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36423, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達は、「正義」の概念に議論を始めた。", "corrected_sentence": "友達は、「正義」の概念について議論を始めた。", "error_description": "「議論する」は話題を「について」で示す。「概念に議論を始めた」の「に」は誤りで、「概念について」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
