INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36424, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『薬品を扱う』で、扱う対象を示す『を』。"}, {"text": "に", "is_correct": false, "explanation": "『に』は位置や相手を示し、『薬品に扱う』は扱う対象を表せない。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示し、『薬品が扱う』は主語と動詞が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示し、『薬品へ扱う』は扱う対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "『薬品を扱う』で、扱う対象を示す『を』。", "に": "『に』は位置や相手を示し、『薬品に扱う』は扱う対象を表せない。", "が": "『が』は主語を示し、『薬品が扱う』は主語と動詞が合わない。", "へ": "『へ』は方向を示し、『薬品へ扱う』は扱う対象を表せない。"}, "error_tags": {"に": "位置・相手（扱う対象を示せない）", "が": "主語（扱う対象にならない）", "へ": "方向（扱う対象にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36424, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを自分の手で持ったり、使ったりするようにすること。", "primary_collocate": null, "pronunciation": "あつかう", "ipa": "atsɯkaɯ", "syllable_count": 4, "sentences": [{"text": "包丁を扱うときは、手を切らないように気をつけてください。", "target_word": "扱う", "complexity_tier": "T3", "furigana": "包丁[ほうちょう]を扱[あつか]うときは、手[て]を切[き]らないように気[き]をつけてください。", "sentence_source": "generated"}, {"text": "この箱にはガラスが入っているので、丁寧に扱ってください。", "target_word": "扱って", "complexity_tier": "T3", "furigana": "この箱[はこ]にはガラスが入[はい]っているので、丁寧[ていねい]に扱[あつか]ってください。", "sentence_source": "generated"}, {"text": "祖父は古い道具を大切に扱っている。", "target_word": "扱って", "complexity_tier": "T3", "furigana": "祖父[そふ]は古[ふる]い道具[どうぐ]を大切[たいせつ]に扱[あつか]っている。", "sentence_source": "generated"}, {"text": "子どもが刃物を扱うときは、大人がそばで見ていたほうがいい。", "target_word": "扱う", "complexity_tier": "T3", "furigana": "子[こ]どもが刃物[はもの]を扱[あつか]うときは、大人[おとな]がそばで見[み]ていたほうがいい。", "sentence_source": "generated"}, {"text": "重い荷物を扱う仕事なので、腕の力が強くなった。", "target_word": "扱う", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を扱[あつか]う仕事[しごと]なので、腕[うで]の力[ちから]が強[つよ]くなった。", "sentence_source": "generated"}, {"text": "壊れやすい皿なので、乱暴に扱ったらすぐ割れてしまう。", "target_word": "扱った", "complexity_tier": "T3", "furigana": "壊[こわ]れやすい皿[さら]なので、乱暴[らんぼう]に扱[あつか]ったらすぐ割[わ]れてしまう。", "sentence_source": "generated"}, {"text": "彼はカメラを上手に扱って、きれいな写真を撮った。", "target_word": "扱って", "complexity_tier": "T3", "furigana": "彼[かれ]はカメラを上手[じょうず]に扱[あつか]って、きれいな写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "薬品を扱う実験では、必ず手袋をつけます。", "target_word": "扱う", "complexity_tier": "T3", "furigana": "薬品[やくひん]を扱[あつか]う実験[じっけん]では、必[かなら]ず手袋[てぶくろ]をつけます。", "sentence_source": "generated"}, {"text": "この楽器は高いので、そっと扱わなければならない。", "target_word": "扱わ", "complexity_tier": "T3", "furigana": "この楽器[がっき]は高[たか]いので、そっと扱[あつか]わなければならない。", "sentence_source": "generated"}, {"text": "初めて工具を扱う人には、使い方を先に教えます。", "target_word": "扱う", "complexity_tier": "T3", "furigana": "初[はじ]めて工具[こうぐ]を扱[あつか]う人[ひと]には、使[つか]い方[かた]を先[さき]に教[おし]えます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "扱う", "label": "辞書形"}, {"form": "扱い", "label": "連用形"}, {"form": "扱わ", "label": "未然形"}, {"form": "扱って", "label": "て形"}, {"form": "扱った", "label": "た形"}, {"form": "扱える", "label": "可能形"}, {"form": "扱われる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "道具や品物を手に持って使う、手で取り扱う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5fbc95f-0ae8-454f-a614-42c57107f7b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36424, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扱う", "is_correct": true, "explanation": "包丁を手に持って使うという意味で、『包丁を扱うときは』と合う。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは寝る意味で、『包丁を眠るときは』は成り立たない。"}, {"text": "祈る", "is_correct": false, "explanation": "祈るは願う意味で、『包丁を祈るときは』は成り立たない。"}, {"text": "笑う", "is_correct": false, "explanation": "笑うは喜んで声を出す意味で、『包丁を笑うときは』は成り立たない。"}], "explanations": {"扱う": "包丁を手に持って使うという意味で、『包丁を扱うときは』と合う。", "眠る": "眠るは寝る意味で、『包丁を眠るときは』は成り立たない。", "祈る": "祈るは願う意味で、『包丁を祈るときは』は成り立たない。", "笑う": "笑うは喜んで声を出す意味で、『包丁を笑うときは』は成り立たない。"}, "sentence_index": 0, "correct_answer": "扱う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は風邪を扱って、学校を休んだ。", "explanation": "ここは〈ひく〉の意味。病気にかかる場合は風邪をひくと言い、扱うは合わない。"}, {"text": "その夢を扱うと、大きな成功が手に入る。", "explanation": "ここは〈追う〉の意味。夢は手に持つものではないので、扱うは合わない。"}, {"text": "彼は約束を扱って、すぐに守った。", "explanation": "ここは〈守る〉の意味。約束は守るもので、扱うは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36424, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扱って", "is_correct": true, "explanation": "カメラを手に持って使うという意味で、『カメラを上手に扱って』と合う。"}, {"text": "蹴って", "is_correct": false, "explanation": "蹴るは足で打つ意味で、『カメラを上手に蹴って』は成り立たない。"}, {"text": "噛んで", "is_correct": false, "explanation": "噛むは歯で力を入れる意味で、『カメラを上手に噛んで』は不自然。"}, {"text": "泣いて", "is_correct": false, "explanation": "泣くは涙を流す意味で、『カメラを上手に泣いて』は成り立たない。"}], "explanations": {"扱って": "カメラを手に持って使うという意味で、『カメラを上手に扱って』と合う。", "蹴って": "蹴るは足で打つ意味で、『カメラを上手に蹴って』は成り立たない。", "噛んで": "噛むは歯で力を入れる意味で、『カメラを上手に噛んで』は不自然。", "泣いて": "泣くは涙を流す意味で、『カメラを上手に泣いて』は成り立たない。"}, "sentence_index": 6, "correct_answer": "扱って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は昼寝を扱って、すぐに起きた。", "explanation": "ここは〈する〉の意味。昼寝は『する』ものなので、扱うは合わない。"}, {"text": "彼は連休を扱って、旅行に出かけた。", "explanation": "ここは〈取る〉の意味。休みを取る場合は取るを使い、扱うは合わない。"}, {"text": "彼は卒業を扱って、春に大学へ行った。", "explanation": "ここは〈迎える〉の意味。卒業は迎えるもので、扱うでは表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36424, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工具に扱うときは、手袋を使いましょう。", "corrected_sentence": "工具を扱うときは、手袋を使いましょう。", "error_description": "『扱う』は『を』を取る他動詞。『工具に』は誤りで、正しくは『工具を』。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "扱って", "is_correct": true, "explanation": "て形で、『丁寧に扱ってください』の依頼に合う。"}, {"text": "扱った", "is_correct": false, "explanation": "た形（過去）で、『扱ってください』の依頼の形と合わない。"}, {"text": "扱える", "is_correct": false, "explanation": "可能形で、『丁寧に扱えてください』は依頼文として成り立たない。"}, {"text": "扱われ", "is_correct": false, "explanation": "受身の連用形で、主語が『扱う人』ではなくなり、文が成り立たない。"}], "correct_form": "扱って", "base_form": "扱う", "form_label": "て形", "sentence_index": 1, "explanations": {"扱って": "て形で、『丁寧に扱ってください』の依頼に合う。", "扱った": "た形（過去）で、『扱ってください』の依頼の形と合わない。", "扱える": "可能形で、『丁寧に扱えてください』は依頼文として成り立たない。", "扱われ": "受身の連用形で、主語が『扱う人』ではなくなり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36424, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洗剤に扱うときは、必ず手袋をつけましょう。", "corrected_sentence": "洗剤を扱うときは、必ず手袋をつけましょう。", "error_description": "『扱う』は『を』を取る他動詞。『洗剤に』は誤りで、正しくは『洗剤を』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "扱う", "is_correct": true, "explanation": "辞書形で、『薬品を扱う実験』と名詞を修飾できる。"}, {"text": "扱って", "is_correct": false, "explanation": "て形で、名詞を修飾できず『薬品を扱って実験では』は成り立たない。"}, {"text": "扱わ", "is_correct": false, "explanation": "未然形で、そのままでは名詞を修飾できず文が成り立たない。"}, {"text": "扱われ", "is_correct": false, "explanation": "受身の連用形で、主語が『薬品』になり文が成り立たない。"}], "correct_form": "扱う", "base_form": "扱う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"扱う": "辞書形で、『薬品を扱う実験』と名詞を修飾できる。", "扱って": "て形で、名詞を修飾できず『薬品を扱って実験では』は成り立たない。", "扱わ": "未然形で、そのままでは名詞を修飾できず文が成り立たない。", "扱われ": "受身の連用形で、主語が『薬品』になり文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36425, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「扱う」に続けて名詞化する「の」。「扱うのが得意だ」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「扱うを得意だ」となり、「得意」の前に目的語を置く形として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「扱うに得意だ」となり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「扱うで得意だ」となり、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「扱う」に続けて名詞化する「の」。「扱うのが得意だ」と続く。", "を": "「扱うを得意だ」となり、「得意」の前に目的語を置く形として成り立たない。", "に": "「扱うに得意だ」となり、文が成り立たない。", "で": "「扱うで得意だ」となり、文が成り立たない。"}, "error_tags": {"を": "object", "に": "target", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
