INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36425, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事を自分の思い通りに動かしたり、操作したりすること。また、ある方法で物事を進めること。", "primary_collocate": null, "pronunciation": "あつかう", "ipa": "atsɯkaɯ", "syllable_count": 4, "sentences": [{"text": "新しい機械を自由に扱えるようになるまで、三か月かかった。", "target_word": "扱え", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]を自由[じゆう]に扱[あつか]えるようになるまで、三[さん]か月[げつ]かかった。", "sentence_source": "generated"}, {"text": "彼は気難しい客をうまく扱うのが得意だ。", "target_word": "扱う", "complexity_tier": "T3", "furigana": "彼[かれ]は気難[きむずか]しい客[きゃく]をうまく扱[あつか]うのが得意[とくい]だ。", "sentence_source": "generated"}, {"text": "この事件は、慎重に扱わなければならない。", "target_word": "扱わ", "complexity_tier": "T3", "furigana": "この事件[じけん]は、慎重[しんちょう]に扱[あつか]わなければならない。", "sentence_source": "generated"}, {"text": "会社はこの問題を内部の秘密として扱った。", "target_word": "扱った", "complexity_tier": "T3", "furigana": "会社[かいしゃ]はこの問題[もんだい]を内部[ないぶ]の秘密[ひみつ]として扱[あつか]った。", "sentence_source": "generated"}, {"text": "新しい道具を扱う仕事を任される会社で働きたい。", "target_word": "扱う", "complexity_tier": "T3", "furigana": "新[あたら]しい道具[どうぐ]を扱[あつか]う仕事[しごと]を任[まか]される会社[かいしゃ]で働[はたら]きたい。", "sentence_source": "generated"}, {"text": "この会議では、予算の問題を最初に扱います。", "target_word": "扱い", "complexity_tier": "T3", "furigana": "この会議[かいぎ]では、予算[よさん]の問題[もんだい]を最初[さいしょ]に扱[あつか]います。", "sentence_source": "generated"}, {"text": "犬をうまく扱える人は、訓練士に向いている。", "target_word": "扱える", "complexity_tier": "T3", "furigana": "犬[いぬ]をうまく扱[あつか]える人[ひと]は、訓練士[くんれんし]に向[む]いている。", "sentence_source": "generated"}, {"text": "先生は生徒の意見を公平に扱ってくれた。", "target_word": "扱って", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の意見[いけん]を公平[こうへい]に扱[あつか]ってくれた。", "sentence_source": "generated"}, {"text": "複雑な機械を扱うには、資格が必要だ。", "target_word": "扱う", "complexity_tier": "T3", "furigana": "複雑[ふくざつ]な機械[きかい]を扱[あつか]うには、資格[しかく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "大きな金額を扱う仕事は、責任が重い。", "target_word": "扱う", "complexity_tier": "T3", "furigana": "大[おお]きな金額[きんがく]を扱[あつか]う仕事[しごと]は、責任[せきにん]が重[おも]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "扱う", "label": "辞書形"}, {"form": "扱い", "label": "連用形"}, {"form": "扱わ", "label": "未然形"}, {"form": "扱って", "label": "て形"}, {"form": "扱った", "label": "た形"}, {"form": "扱える", "label": "可能形"}, {"form": "扱われる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "機械・人・物事を思い通りに操作する、またはある方法で処理する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5fbc95f-0ae8-454f-a614-42c57107f7b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36425, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扱え", "is_correct": true, "explanation": "可能形の語幹。「扱えるようになる」で「扱えるようになるまで」と続く。"}, {"text": "扱う", "is_correct": false, "explanation": "辞書形では「扱うるようになる」となり、後ろの「るようになる」と続かない。"}, {"text": "扱わ", "is_correct": false, "explanation": "未然形では「扱わるようになる」となり、文が成り立たない。"}, {"text": "扱った", "is_correct": false, "explanation": "た形では「扱ったるようになる」となり、後ろの「るようになる」と続かない。"}], "explanations": {"扱え": "可能形の語幹。「扱えるようになる」で「扱えるようになるまで」と続く。", "扱う": "辞書形では「扱うるようになる」となり、後ろの「るようになる」と続かない。", "扱わ": "未然形では「扱わるようになる」となり、文が成り立たない。", "扱った": "た形では「扱ったるようになる」となり、後ろの「るようになる」と続かない。"}, "sentence_index": 0, "correct_answer": "扱え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パーティーで、ケーキを扱ってみんなに配った。", "explanation": "ここは〈分配・譲渡〉の意味。扱うは物事を操作・処理する意味なので、食べ物を人に渡す行為とは合わない。"}, {"text": "夕立が来たので、傘を扱って家に帰った。", "explanation": "ここは〈さす〉の意味。扱うは道具を操作する意味で、雨をよける行為には使わない。"}, {"text": "鍋のスープを扱って、味を見た。", "explanation": "ここは〈かき混ぜる〉の意味。扱うは物事を思い通りに操作・処理する意味で、スープを混ぜる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36425, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扱える", "is_correct": true, "explanation": "可能形。「犬をうまく扱える人」と、能力を表す形として正しい。"}, {"text": "扱わ", "is_correct": false, "explanation": "未然形では「犬をうまく扱わ人は」となり、文が成り立たない。"}, {"text": "扱い", "is_correct": false, "explanation": "連用形では「犬をうまく扱い人は」となり、名詞修飾にならない。"}, {"text": "扱って", "is_correct": false, "explanation": "て形では「犬をうまく扱って人は」となり、名詞修飾にならない。"}], "explanations": {"扱える": "可能形。「犬をうまく扱える人」と、能力を表す形として正しい。", "扱わ": "未然形では「犬をうまく扱わ人は」となり、文が成り立たない。", "扱い": "連用形では「犬をうまく扱い人は」となり、名詞修飾にならない。", "扱って": "て形では「犬をうまく扱って人は」となり、名詞修飾にならない。"}, "sentence_index": 6, "correct_answer": "扱える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は満面の笑顔を扱った。", "explanation": "ここは〈浮かべる〉の意味。扱うは物事を操作・処理する意味で、表情を顔に出す動作には使わない。"}, {"text": "彼は緊張をほぐそうと、ゆっくり息を扱った。", "explanation": "ここは〈吸う〉の意味。扱うは物事を操作・処理する意味で、息を体に取り込む動作には使わない。"}, {"text": "会議の結論を聞き、彼は深いため息を扱った。", "explanation": "ここは〈つく〉の意味（ため息をつく）。扱うは物事を操作・処理する意味で、息を吐く動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36425, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い道具を丁寧に扱いた。", "corrected_sentence": "古い道具を丁寧に扱った。", "error_description": "過去形の誤り。「扱う」の過去形は「扱った」で、「扱いた」は誤った形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "扱う", "is_correct": true, "explanation": "辞書形。「うまく扱うのが得意」と名詞を修飾する形として正しい。"}, {"text": "扱い", "is_correct": false, "explanation": "連用形では「扱いのが得意」となり、文が成り立たない。"}, {"text": "扱え", "is_correct": false, "explanation": "可能形の語幹では「扱えのが得意」となり、文が成り立たない。"}, {"text": "扱わ", "is_correct": false, "explanation": "未然形では「扱わのが得意」となり、文が成り立たない。"}], "correct_form": "扱う", "base_form": "扱う", "form_label": "辞書形", "sentence_index": 1, "explanations": {"扱う": "辞書形。「うまく扱うのが得意」と名詞を修飾する形として正しい。", "扱い": "連用形では「扱いのが得意」となり、文が成り立たない。", "扱え": "可能形の語幹では「扱えのが得意」となり、文が成り立たない。", "扱わ": "未然形では「扱わのが得意」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36425, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い犬をうまく扱えようになった。", "corrected_sentence": "古い犬をうまく扱えるようになった。", "error_description": "可能形の誤り。「扱えるようになった」の「る」が抜けて「扱えようになった」となっている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "扱って", "is_correct": true, "explanation": "て形。「扱ってくれた」と続き、正しい。"}, {"text": "扱い", "is_correct": false, "explanation": "連用形では「扱いてくれた」となり、文が成り立たない。"}, {"text": "扱う", "is_correct": false, "explanation": "辞書形では「扱うてくれた」となり、文が成り立たない。"}, {"text": "扱った", "is_correct": false, "explanation": "た形では「扱ったくれた」となり、文が成り立たない。"}], "correct_form": "扱って", "base_form": "扱う", "form_label": "て形", "sentence_index": 7, "explanations": {"扱って": "て形。「扱ってくれた」と続き、正しい。", "扱い": "連用形では「扱いてくれた」となり、文が成り立たない。", "扱う": "辞書形では「扱うてくれた」となり、文が成り立たない。", "扱った": "た形では「扱ったくれた」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36426, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「投資を」は「した」の目的語を示し、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「投資がした」となり、目的語を示せず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「投資からした」となり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「投資へした」となり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「投資を」は「した」の目的語を示し、正しい。", "が": "「投資がした」となり、目的語を示せず文が成り立たない。", "から": "「投資からした」となり、文が成り立たない。", "へ": "「投資へした」となり、文が成り立たない。"}, "error_tags": {"が": "subject", "から": "source", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
