INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36426, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金を使って、あとでもっとお金をもらえるようにすること。", "primary_collocate": null, "pronunciation": "とうし", "ipa": "toːɕi", "syllable_count": 3, "sentences": [{"text": "将来のために、少しずつ投資を始めた。", "target_word": "投資", "complexity_tier": "T3", "furigana": "将来[しょうらい]のために、少[すこ]しずつ投資[とうし]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼は新しい会社に大きな投資をした。", "target_word": "投資", "complexity_tier": "T3", "furigana": "彼[かれ]は新[あたら]しい会社[かいしゃ]に大[おお]きな投資[とうし]をした。", "sentence_source": "generated"}, {"text": "教育への投資は、社会を豊かにする。", "target_word": "投資", "complexity_tier": "T3", "furigana": "教育[きょういく]への投資[とうし]は、社会[しゃかい]を豊[ゆた]かにする。", "sentence_source": "generated"}, {"text": "投資には危険もあるので、よく調べてから決めましょう。", "target_word": "投資", "complexity_tier": "T3", "furigana": "投資[とうし]には危険[きけん]もあるので、よく調[しら]べてから決[き]めましょう。", "sentence_source": "generated"}, {"text": "株に投資して、お金が二倍になった人もいる。", "target_word": "投資", "complexity_tier": "T3", "furigana": "株[かぶ]に投資[とうし]して、お金[かね]が二倍[にばい]になった人[ひと]もいる。", "sentence_source": "generated"}, {"text": "父は不動産への投資で失敗した。", "target_word": "投資", "complexity_tier": "T3", "furigana": "父[ちち]は不動産[ふどうさん]への投資[とうし]で失敗[しっぱい]した。", "sentence_source": "generated"}, {"text": "工場の機械を新しくするのは、会社にとって大切な投資だ。", "target_word": "投資", "complexity_tier": "T3", "furigana": "工場[こうじょう]の機械[きかい]を新[あたら]しくするのは、会社[かいしゃ]にとって大切[たいせつ]な投資[とうし]だ。", "sentence_source": "generated"}, {"text": "投資した金額が戻らず、彼はとても困っている。", "target_word": "投資", "complexity_tier": "T3", "furigana": "投資[とうし]した金額[きんがく]が戻[もど]らず、彼[かれ]はとても困[こま]っている。", "sentence_source": "generated"}, {"text": "若いうちから投資について学ぶのは、いいことだと思う。", "target_word": "投資", "complexity_tier": "T3", "furigana": "若[わか]いうちから投資[とうし]について学[まな]ぶのは、いいことだと思[おも]う。", "sentence_source": "generated"}, {"text": "外国の企業から多額の投資を受けて、町が発展した。", "target_word": "投資", "complexity_tier": "T3", "furigana": "外国[がいこく]の企業[きぎょう]から多額[たがく]の投資[とうし]を受[う]けて、町[まち]が発展[はってん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "投資", "label": "基本形"}, {"form": "投資する", "label": "する動詞の辞書形"}, {"form": "投資し", "label": "連用形"}, {"form": "投資して", "label": "て形"}, {"form": "投資した", "label": "た形"}, {"form": "投資しない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "利益を得るために、お金を出して事業や株などに使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5fbc95f-0ae8-454f-a614-42c57107f7b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36426, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投資", "is_correct": true, "explanation": "名詞。「投資を始めた」と続き、正しい。"}, {"text": "投資し", "is_correct": false, "explanation": "連用形では「投資しを始めた」となり、文が成り立たない。"}, {"text": "投資する", "is_correct": false, "explanation": "辞書形では「投資するを始めた」となり、文が成り立たない。"}, {"text": "投資しない", "is_correct": false, "explanation": "ない形では「投資しないを始めた」となり、文が成り立たない。"}], "explanations": {"投資": "名詞。「投資を始めた」と続き、正しい。", "投資し": "連用形では「投資しを始めた」となり、文が成り立たない。", "投資する": "辞書形では「投資するを始めた」となり、文が成り立たない。", "投資しない": "ない形では「投資しないを始めた」となり、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "投資"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎晩、ほうきを投資して、床を掃いた。", "explanation": "ここは〈使う〉の意味。投資は利益を見込んで金銭を出すことで、道具を使って掃除する行為には使わない。"}, {"text": "ドアを投資して、部屋に入った。", "explanation": "ここは〈開ける〉の意味。投資は利益を見込んで金銭を出すことで、ドアを押し開ける動作には使わない。"}, {"text": "電気代に投資して、家計を節約した。", "explanation": "ここは〈支払い〉の意味。投資は将来の利益を見込んで金銭を出すことで、すでにかかる電気代を払う行為とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36426, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投資", "is_correct": true, "explanation": "名詞。「大切な投資だ」と続き、正しい。"}, {"text": "投資する", "is_correct": false, "explanation": "辞書形では「大切な投資するだ」となり、名詞修飾にならない。"}, {"text": "投資した", "is_correct": false, "explanation": "た形では「大切な投資しただ」となり、文が成り立たない。"}, {"text": "投資して", "is_correct": false, "explanation": "て形では「大切な投資してだ」となり、文が成り立たない。"}], "explanations": {"投資": "名詞。「大切な投資だ」と続き、正しい。", "投資する": "辞書形では「大切な投資するだ」となり、名詞修飾にならない。", "投資した": "た形では「大切な投資しただ」となり、文が成り立たない。", "投資して": "て形では「大切な投資してだ」となり、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "投資"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雑誌に詩を投資した。", "explanation": "ここは〈投稿〉の意味。投資は金銭を出すことで、作品を送る行為には合わない。"}, {"text": "古い服を投資して、捨てた。", "explanation": "ここは〈寄付〉の意味。投資は利益を得るための行為で、物を譲る文脈には合わない。"}, {"text": "友達に感謝を投資して、手紙を書いた。", "explanation": "ここは〈謝意を示す〉の意味。投資は利益を見込んで金銭を出すことで、気持ちを伝える行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36426, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は新しい工場に投資がした。", "corrected_sentence": "彼は新しい工場に投資をした。", "error_description": "格助詞の誤り。「投資する」の目的語は「を」で示すため、「投資が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36426, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は外国の銀行から大きな投資が受けた。", "corrected_sentence": "町は外国の銀行から大きな投資を受けた。", "error_description": "格助詞の誤り。「投資を受ける」の目的語は「を」で示すため、「投資が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36429, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "節約", "is_correct": true, "explanation": "浪費の対義語。資源を大切に使う意味で、むだに消費する浪費と対になる。"}, {"text": "努力", "is_correct": false, "explanation": "目標に向かって力を尽くすこと。資源の使い方の対義語ではない。"}, {"text": "会話", "is_correct": false, "explanation": "人と話すこと。資源の使い方とは関係がない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のこと。浪費とは対義の関係にない。"}], "correct_answer": "節約", "explanations": {"節約": "浪費の対義語。資源を大切に使う意味で、むだに消費する浪費と対になる。", "努力": "目標に向かって力を尽くすこと。資源の使い方の対義語ではない。", "会話": "人と話すこと。資源の使い方とは関係がない。", "天気": "空模様のこと。浪費とは対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36429, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「浪費を続ければ」の「を」は、続ける動作の目的語を示し、正しい。"}, {"text": "に", "is_correct": false, "explanation": "「浪費に続ければ」となり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「浪費と続ければ」となり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「浪費へ続ければ」となり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「浪費を続ければ」の「を」は、続ける動作の目的語を示し、正しい。", "に": "「浪費に続ければ」となり、文が成り立たない。", "と": "「浪費と続ければ」となり、文が成り立たない。", "へ": "「浪費へ続ければ」となり、文が成り立たない。"}, "error_tags": {"に": "target", "と": "with", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "節約", "is_correct": true, "explanation": "浪費の対義語。資源を大切に使う意味で、むだに消費する浪費と対になる。"}, {"text": "記録", "is_correct": false, "explanation": "物事を書き残すこと。資源の使い方の対義語ではない。"}, {"text": "散歩", "is_correct": false, "explanation": "気ままに歩くこと。資源の使い方とは関係がない。"}, {"text": "相談", "is_correct": false, "explanation": "話し合って助言を求めること。浪費とは対義の関係にない。"}], "correct_answer": "節約", "explanations": {"節約": "浪費の対義語。資源を大切に使う意味で、むだに消費する浪費と対になる。", "記録": "物事を書き残すこと。資源の使い方の対義語ではない。", "散歩": "気ままに歩くこと。資源の使い方とは関係がない。", "相談": "話し合って助言を求めること。浪費とは対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36429, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "必要なものや役に立つものに対して、むだに使ったり、無駄に消費すること", "primary_collocate": null, "pronunciation": "ろうひ", "ipa": "ɾoːçi", "syllable_count": 3, "sentences": [{"text": "水の浪費をなくすために、シャワーの時間を短くした。", "target_word": "浪費", "complexity_tier": "T3", "furigana": "水[みず]の浪費[ろうひ]をなくすために、シャワーの時間[じかん]を短[みじか]くした。", "sentence_source": "generated"}, {"text": "食べ物を捨てるのは、大切な資源の浪費だ。", "target_word": "浪費", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]を捨[す]てるのは、大切[たいせつ]な資源[しげん]の浪費[ろうひ]だ。", "sentence_source": "generated"}, {"text": "使わない部屋の電気をつけておくのは、電力の浪費になる。", "target_word": "浪費", "complexity_tier": "T3", "furigana": "使[つか]わない部屋[へや]の電気[でんき]をつけておくのは、電力[でんりょく]の浪費[ろうひ]になる。", "sentence_source": "generated"}, {"text": "紙の浪費を防ぐため、会議の資料は画面で見ることにした。", "target_word": "浪費", "complexity_tier": "T3", "furigana": "紙[かみ]の浪費[ろうひ]を防[ふせ]ぐため、会議[かいぎ]の資料[しりょう]は画面[がめん]で見[み]ることにした。", "sentence_source": "generated"}, {"text": "この工場では、材料の浪費が問題になっている。", "target_word": "浪費", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、材料[ざいりょう]の浪費[ろうひ]が問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "才能を遊びに使ってばかりいるのは、才能の浪費だ。", "target_word": "浪費", "complexity_tier": "T3", "furigana": "才能[さいのう]を遊[あそ]びに使[つか]ってばかりいるのは、才能[さいのう]の浪費[ろうひ]だ。", "sentence_source": "generated"}, {"text": "食べ残しは、農家の努力の浪費でもある。", "target_word": "浪費", "complexity_tier": "T3", "furigana": "食[た]べ残[のこ]しは、農家[のうか]の努力[どりょく]の浪費[ろうひ]でもある。", "sentence_source": "generated"}, {"text": "石油の浪費を続ければ、将来の世代が困る。", "target_word": "浪費", "complexity_tier": "T3", "furigana": "石油[せきゆ]の浪費[ろうひ]を続[つづ]ければ、将来[しょうらい]の世代[せだい]が困[こま]る。", "sentence_source": "generated"}, {"text": "燃料の浪費を減らすため、急な発進をやめた。", "target_word": "浪費", "complexity_tier": "T3", "furigana": "燃料[ねんりょう]の浪費[ろうひ]を減[へ]らすため、急[きゅう]な発進[はっしん]をやめた。", "sentence_source": "generated"}, {"text": "エアコンをつけたまま出かけるのは、エネルギーの浪費だ。", "target_word": "浪費", "complexity_tier": "T3", "furigana": "エアコンをつけたまま出[で]かけるのは、エネルギーの浪費[ろうひ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪費", "label": "基本形"}, {"form": "浪費する", "label": "する動詞の辞書形"}, {"form": "浪費し", "label": "連用形"}, {"form": "浪費して", "label": "て形"}, {"form": "浪費した", "label": "た形"}, {"form": "浪費される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "水・電気・資源・才能など役に立つものをむだに消費すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5fbc95f-0ae8-454f-a614-42c57107f7b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36429, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪費", "is_correct": true, "explanation": "名詞。「水の浪費をなくす」と続き、正しい。"}, {"text": "浪費する", "is_correct": false, "explanation": "辞書形では「水の浪費するをなくす」となり、文が成り立たない。"}, {"text": "浪費した", "is_correct": false, "explanation": "た形では「水の浪費したをなくす」となり、文が成り立たない。"}, {"text": "浪費して", "is_correct": false, "explanation": "て形では「水の浪費してをなくす」となり、文が成り立たない。"}], "explanations": {"浪費": "名詞。「水の浪費をなくす」と続き、正しい。", "浪費する": "辞書形では「水の浪費するをなくす」となり、文が成り立たない。", "浪費した": "た形では「水の浪費したをなくす」となり、文が成り立たない。", "浪費して": "て形では「水の浪費してをなくす」となり、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "浪費"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食後、テーブルを布で浪費した。", "explanation": "ここは〈拭く〉の意味。浪費はむだに消費することで、汚れを布でぬぐう動作には使わない。"}, {"text": "遠足の日、山道でリュックを浪費して、水を飲んだ。", "explanation": "ここは〈下ろす〉の意味。浪費はむだに消費することで、荷物を下ろす動作には使わない。"}, {"text": "朝の散歩で、川沿いを浪費した。", "explanation": "ここは〈歩く〉の意味。浪費はむだに消費することで、道を進む動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36429, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪費", "is_correct": true, "explanation": "名詞。「努力の浪費でもある」と続き、正しい。"}, {"text": "浪費し", "is_correct": false, "explanation": "連用形では「努力の浪費しでもある」となり、名詞の後に続かず文が成り立たない。"}, {"text": "浪費しない", "is_correct": false, "explanation": "否定形では「努力の浪費しないでもある」となり、文が成り立たない。"}, {"text": "浪費される", "is_correct": false, "explanation": "受身形では「努力の浪費されでもある」となり、文が成り立たない。"}], "explanations": {"浪費": "名詞。「努力の浪費でもある」と続き、正しい。", "浪費し": "連用形では「努力の浪費しでもある」となり、名詞の後に続かず文が成り立たない。", "浪費しない": "否定形では「努力の浪費しないでもある」となり、文が成り立たない。", "浪費される": "受身形では「努力の浪費されでもある」となり、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "浪費"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドアを浪費して、中の人を呼んだ。", "explanation": "ここは〈たたく〉の意味。浪費はむだに消費することで、ドアを打つ動作には使わない。"}, {"text": "湯気の立つ鍋を浪費して、皿に取り分けた。", "explanation": "ここは〈取り分ける〉の意味。浪費はむだに消費することで、料理を皿に分ける動作には使わない。"}, {"text": "泣いている赤ちゃんを浪費した。", "explanation": "ここは〈抱きしめる〉の意味。浪費はむだに使う意味で、人を抱いてなだめる行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36429, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "資源の浪費が防ぐため、リサイクルを始めた。", "corrected_sentence": "資源の浪費を防ぐため、リサイクルを始めた。", "error_description": "格助詞の誤り。「防ぐ」の目的語は「を」で示すため、「浪費が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36429, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電力の浪費に防ぐ工夫をした。", "corrected_sentence": "電力の浪費を防ぐ工夫をした。", "error_description": "格助詞の誤り。「防ぐ」の目的語は「を」で示すため、「浪費に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36430, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪費", "is_correct": true, "explanation": "「浪費」はお金や物をむだに使うことで、節約と反対の意味で対になる。"}, {"text": "貯蓄", "is_correct": false, "explanation": "「貯蓄」はお金をためる行為で、むだに使わないという点は近いが、節約の対義語ではない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は外を歩く楽しみで、物やお金の使い方とは関係がない。"}, {"text": "読書", "is_correct": false, "explanation": "「読書」は本を読む行為で、節約の対義語ではない。"}], "correct_answer": "浪費", "explanations": {"浪費": "「浪費」はお金や物をむだに使うことで、節約と反対の意味で対になる。", "貯蓄": "「貯蓄」はお金をためる行為で、むだに使わないという点は近いが、節約の対義語ではない。", "散歩": "「散歩」は外を歩く楽しみで、物やお金の使い方とは関係がない。", "読書": "「読書」は本を読む行為で、節約の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36430, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「節約と言っても」の「と」。引用の形で、ここでは節約という言葉を取り上げている。"}, {"text": "に", "is_correct": false, "explanation": "「節約に言う」は成り立たず、「に」は言う相手や場所を示すので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「節約で言う」は成り立たず、「で」は手段や場所を示すので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「節約へ言う」は文が通らない。"}], "correct_answer": "と", "explanations": {"と": "「節約と言っても」の「と」。引用の形で、ここでは節約という言葉を取り上げている。", "に": "「節約に言う」は成り立たず、「に」は言う相手や場所を示すので合わない。", "で": "「節約で言う」は成り立たず、「で」は手段や場所を示すので合わない。", "へ": "「へ」は方向を示すので、「節約へ言う」は文が通らない。"}, "error_tags": {"に": "target", "で": "means", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪費", "is_correct": true, "explanation": "時間をむだに費やすことで、時間を節約する反対の意味になる。"}, {"text": "余暇", "is_correct": false, "explanation": "「余暇」は仕事以外の自由な時間を指すが、節約の対義語ではない。"}, {"text": "通勤", "is_correct": false, "explanation": "「通勤」は職場へ行き来する行為で、節約の反対語ではない。"}, {"text": "献立", "is_correct": false, "explanation": "「献立」は食事の計画を指し、時間や資源の使い方の対義語ではない。"}], "correct_answer": "浪費", "explanations": {"浪費": "時間をむだに費やすことで、時間を節約する反対の意味になる。", "余暇": "「余暇」は仕事以外の自由な時間を指すが、節約の対義語ではない。", "通勤": "「通勤」は職場へ行き来する行為で、節約の反対語ではない。", "献立": "「献立」は食事の計画を指し、時間や資源の使い方の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36430, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "使う物やお金、時間などを、むだにしないように大事に使うこと。", "primary_collocate": null, "pronunciation": "せつやく", "ipa": "setsɯjakɯ", "syllable_count": 4, "sentences": [{"text": "来月は旅行に行くので、食費を節約しています。", "target_word": "節約", "complexity_tier": "T3", "furigana": "来月[らいげつ]は旅行[りょこう]に行[い]くので、食費[しょくひ]を節約[せつやく]しています。", "sentence_source": "generated"}, {"text": "電気をこまめに消して、電気代を節約した。", "target_word": "節約", "complexity_tier": "T3", "furigana": "電気[でんき]をこまめに消[け]して、電気代[でんきだい]を節約[せつやく]した。", "sentence_source": "generated"}, {"text": "時間を節約するために、朝ごはんは前の晩に準備しておく。", "target_word": "節約", "complexity_tier": "T3", "furigana": "時間[じかん]を節約[せつやく]するために、朝[あさ]ごはんは前[まえ]の晩[ばん]に準備[じゅんび]しておく。", "sentence_source": "generated"}, {"text": "紙を節約したいので、メモは裏紙に書いている。", "target_word": "節約", "complexity_tier": "T2", "furigana": "紙[かみ]を節約[せつやく]したいので、メモは裏紙[うらがみ]に書[か]いている。", "sentence_source": "generated"}, {"text": "水を節約するため、歯をみがくあいだは水道を止めます。", "target_word": "節約", "complexity_tier": "T3", "furigana": "水[みず]を節約[せつやく]するため、歯[は]をみがくあいだは水道[すいどう]を止[と]めます。", "sentence_source": "generated"}, {"text": "節約のおかげで、三か月で五万円ためることができた。", "target_word": "節約", "complexity_tier": "T3", "furigana": "節約[せつやく]のおかげで、三[さん]か月[げつ]で五万円[ごまんえん]ためることができた。", "sentence_source": "generated"}, {"text": "学生のころは、お金がなくて毎日お弁当を作って節約していた。", "target_word": "節約", "complexity_tier": "T4", "furigana": "学生[がくせい]のころは、お金[かね]がなくて毎日[まいにち]お弁当[べんとう]を作[つく]って節約[せつやく]していた。", "sentence_source": "generated"}, {"text": "節約と言っても、まったく買い物をしないわけではない。", "target_word": "節約", "complexity_tier": "T3", "furigana": "節約[せつやく]と言[い]っても、まったく買[か]い物[もの]をしないわけではない。", "sentence_source": "generated"}, {"text": "兄は節約が上手で、給料の半分を貯金している。", "target_word": "節約", "complexity_tier": "T3", "furigana": "兄[あに]は節約[せつやく]が上手[じょうず]で、給料[きゅうりょう]の半分[はんぶん]を貯金[ちょきん]している。", "sentence_source": "generated"}, {"text": "急いでいたので、少しでも時間を節約しようと近道を通った。", "target_word": "節約", "complexity_tier": "T4", "furigana": "急[いそ]いでいたので、少[すこ]しでも時間[じかん]を節約[せつやく]しようと近道[ちかみち]を通[とお]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "節約する", "label": "辞書形"}, {"form": "節約した", "label": "過去形"}, {"form": "節約して", "label": "て形"}, {"form": "節約しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "節約:物・お金・時間をむだにせず大事に使う日常の行い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: みがく (Zipf 1.93)']::text[], 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36430, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "節約", "is_correct": true, "explanation": "「食費を節約する」で、無駄にせず使う意味。旅行に備えるという文脈とも合う。"}, {"text": "参加", "is_correct": false, "explanation": "「参加」は「〜に参加する」の形で、食費を対象にはできない。"}, {"text": "訪問", "is_correct": false, "explanation": "「訪問」は人や場所を訪ねる行為で、食費には使わない。"}, {"text": "発見", "is_correct": false, "explanation": "「発見」は見つけることで、食費を対象にして「している」と続けても意味が通らない。"}], "explanations": {"節約": "「食費を節約する」で、無駄にせず使う意味。旅行に備えるという文脈とも合う。", "参加": "「参加」は「〜に参加する」の形で、食費を対象にはできない。", "訪問": "「訪問」は人や場所を訪ねる行為で、食費には使わない。", "発見": "「発見」は見つけることで、食費を対象にして「している」と続けても意味が通らない。"}, "sentence_index": 0, "correct_answer": "節約"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "痛みを節約して、最後まで走った。", "explanation": "ここは〈我慢〉の意味。節約は資源やお金を無駄にしない使い方なので、痛みには使わない。"}, {"text": "借金を節約してから、新しい車を買った。", "explanation": "ここは〈返済〉の意味。借金は節約するものではなく、返すもの。"}, {"text": "食欲を節約して、夜のお菓子を控えた。", "explanation": "ここは〈抑制〉の意味。食欲は節約するものではなく、抑えるもの。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36430, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "節約", "is_correct": true, "explanation": "「お金がなくて」という理由に合い、お弁当で出費を抑える意味になる。"}, {"text": "相談", "is_correct": false, "explanation": "「相談」は人と話し合うことで、お弁当を作る行為とは結びつかない。"}, {"text": "注目", "is_correct": false, "explanation": "「注目」は関心を向けることで、お弁当を作るという行為には合わない。"}, {"text": "通院", "is_correct": false, "explanation": "「通院」は病院へ通うことで、お弁当の文脈には合わない。"}], "explanations": {"節約": "「お金がなくて」という理由に合い、お弁当で出費を抑える意味になる。", "相談": "「相談」は人と話し合うことで、お弁当を作る行為とは結びつかない。", "注目": "「注目」は関心を向けることで、お弁当を作るという行為には合わない。", "通院": "「通院」は病院へ通うことで、お弁当の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "節約"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大切な権利を節約した。", "explanation": "ここは〈放棄〉の意味。権利は節約するものではなく、手放すもの。"}, {"text": "締め切りを節約してもらった。", "explanation": "ここは〈延長〉の意味。締め切りは節約するものではなく、延ばすもの。"}, {"text": "眠気を節約して、最後まで授業を聞いた。", "explanation": "ここは〈辛抱〉の意味。眠気は節約するものではなく、こらえるもの。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36430, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家計の節約を努めている。", "corrected_sentence": "家計の節約に努めている。", "error_description": "「節約に努める」の「に」が正しい。「努める」は「〜に努める」と助詞「に」を取るので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36430, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末は節約ないで、好きなものを買う。", "corrected_sentence": "週末は節約しないで、好きなものを買う。", "error_description": "「節約しないで」の「しない」が正しい。「節約」は名詞なので「する」の否定形が必要で、「ない」だけでは文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36431, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「節約を進める」の「を」。進める対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、節約を主体にする文になり、「進める」の対象として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「節約で進める」では意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「節約と進める」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「節約を進める」の「を」。進める対象を示す。", "が": "「が」は主語を示すので、節約を主体にする文になり、「進める」の対象として成り立たない。", "で": "「で」は手段や場所を示すので、「節約で進める」では意味が通らない。", "と": "「と」は並列や相手を示すので、「節約と進める」は成り立たない。"}, "error_tags": {"が": "subject", "で": "means", "と": "companion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪費", "is_correct": true, "explanation": "「浪費」はお金や物をむだに使うことで、節約と反対の意味で対になる。"}, {"text": "貯蓄", "is_correct": false, "explanation": "「貯蓄」はお金をためる行為で、節約の対義語ではない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は外を歩く楽しみで、物やお金の使い方とは関係がない。"}, {"text": "読書", "is_correct": false, "explanation": "「読書」は本を読む行為で、節約の対義語ではない。"}], "correct_answer": "浪費", "explanations": {"浪費": "「浪費」はお金や物をむだに使うことで、節約と反対の意味で対になる。", "貯蓄": "「貯蓄」はお金をためる行為で、節約の対義語ではない。", "散歩": "「散歩」は外を歩く楽しみで、物やお金の使い方とは関係がない。", "読書": "「読書」は本を読む行為で、節約の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
