INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36431, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "限りある資源やお金、時間などを、無駄なく効率的に使うこと。また、その考え方。", "primary_collocate": null, "pronunciation": "せつやく", "ipa": "setsɯjakɯ", "syllable_count": 4, "sentences": [{"text": "資源が限られているので、国全体で節約の意識を高める必要がある。", "target_word": "節約", "complexity_tier": "T4", "furigana": "資源[しげん]が限[かぎ]られているので、国全体[くにぜんたい]で節約[せつやく]の意識[いしき]を高[たか]める必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "会社は経費の節約を進め、無駄な出張を減らした。", "target_word": "節約", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は経費[けいひ]の節約[せつやく]を進[すす]め、無駄[むだ]な出張[しゅっちょう]を減[へ]らした。", "sentence_source": "generated"}, {"text": "節約とは、ただ我慢することではなく、無駄なく使う工夫である。", "target_word": "節約", "complexity_tier": "T4", "furigana": "節約[せつやく]とは、ただ我慢[がまん]することではなく、無駄[むだ]なく使[つか]う工夫[くふう]である。", "sentence_source": "generated"}, {"text": "この冷蔵庫は、電力を節約する設計になっているので、電気代が安い。", "target_word": "節約", "complexity_tier": "T3", "furigana": "この冷蔵庫[れいぞうこ]は、電力[でんりょく]を節約[せつやく]する設計[せっけい]になっているので、電気代[でんきだい]が安[やす]い。", "sentence_source": "generated"}, {"text": "水不足の夏には、市民に水の節約が呼びかけられた。", "target_word": "節約", "complexity_tier": "T3", "furigana": "水不足[みずぶそく]の夏[なつ]には、市民[しみん]に水[みず]の節約[せつやく]が呼[よ]びかけられた。", "sentence_source": "generated"}, {"text": "節約の考え方は、家庭だけでなく企業の運営にも役立つ。", "target_word": "節約", "complexity_tier": "T4", "furigana": "節約[せつやく]の考[かんが]え方[かた]は、家庭[かてい]だけでなく企業[きぎょう]の運営[うんえい]にも役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "彼は時間の節約を重視し、会議を三十分に区切っている。", "target_word": "節約", "complexity_tier": "T3", "furigana": "彼[かれ]は時間[じかん]の節約[せつやく]を重視[じゅうし]し、会議[かいぎ]を三十分[さんじゅっぷん]に区切[くぎ]っている。", "sentence_source": "generated"}, {"text": "燃料を節約しながら走る運転方法が、環境にも家計にもよい。", "target_word": "節約", "complexity_tier": "T4", "furigana": "燃料[ねんりょう]を節約[せつやく]しながら走[はし]る運転[うんてん]方法[ほうほう]が、環境[かんきょう]にも家計[かけい]にもよい。", "sentence_source": "generated"}, {"text": "予算が少ないプロジェクトでは、人件費の節約が大きな課題になる。", "target_word": "節約", "complexity_tier": "T3", "furigana": "予算[よさん]が少[すく]ないプロジェクトでは、人件費[じんけんひ]の節約[せつやく]が大[おお]きな課題[かだい]になる。", "sentence_source": "generated"}, {"text": "節約の習慣を身につければ、限られた収入でも生活は安定する。", "target_word": "節約", "complexity_tier": "T4", "furigana": "節約[せつやく]の習慣[しゅうかん]を身[み]につければ、限[かぎ]られた収入[しゅうにゅう]でも生活[せいかつ]は安定[あんてい]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "節約する", "label": "辞書形"}, {"form": "節約した", "label": "過去形"}, {"form": "節約して", "label": "て形"}, {"form": "節約しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "節約:限りある資源を効率よく使う方針・考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36431, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "節約", "is_correct": true, "explanation": "「節約の意識」で、資源を大事に使う考え方を指す。「資源が限られている」という文脈とも合う。"}, {"text": "訪問", "is_correct": false, "explanation": "「訪問」は人や場所を訪ねる行為で、「訪問の意識」とは言わない。"}, {"text": "発見", "is_correct": false, "explanation": "「発見」は見つけることで、「発見の意識」は意味が通らない。"}, {"text": "通信", "is_correct": false, "explanation": "「通信」は情報を送り届けることで、資源の使い方を表す語ではない。"}], "explanations": {"節約": "「節約の意識」で、資源を大事に使う考え方を指す。「資源が限られている」という文脈とも合う。", "訪問": "「訪問」は人や場所を訪ねる行為で、「訪問の意識」とは言わない。", "発見": "「発見」は見つけることで、「発見の意識」は意味が通らない。", "通信": "「通信」は情報を送り届けることで、資源の使い方を表す語ではない。"}, "sentence_index": 0, "correct_answer": "節約"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小さな失敗を節約して、次に活かさなかった。", "explanation": "ここは〈見過ごす〉の意味。失敗は節約するものではなく、次に生かすもの。"}, {"text": "騒音を節約する対策を取った。", "explanation": "ここは〈抑制〉の意味。騒音は節約するものではなく、抑えるもの。"}, {"text": "危険を節約するため、道を変えた。", "explanation": "ここは〈回避〉の意味。危険は節約するものではなく、避けるもの。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36431, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "節約", "is_correct": true, "explanation": "「時間の節約」で、時間をむだにしない使い方を指す。「重視し」ともつながる。"}, {"text": "運搬", "is_correct": false, "explanation": "「運搬」は物を運ぶことで、時間を対象にする文には合わない。"}, {"text": "鑑賞", "is_correct": false, "explanation": "「鑑賞」は芸術などを味わうことで、時間の使い方を表す語ではない。"}, {"text": "注文", "is_correct": false, "explanation": "「注文」は品物を頼むことで、時間を対象にする文には合わない。"}], "explanations": {"節約": "「時間の節約」で、時間をむだにしない使い方を指す。「重視し」ともつながる。", "運搬": "「運搬」は物を運ぶことで、時間を対象にする文には合わない。", "鑑賞": "「鑑賞」は芸術などを味わうことで、時間の使い方を表す語ではない。", "注文": "「注文」は品物を頼むことで、時間を対象にする文には合わない。"}, "sentence_index": 6, "correct_answer": "節約"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来年の受験に向けて、毎日勉強を節約している。", "explanation": "ここは〈削る〉の意味。勉強は節約して減らすものではなく、積み重ねるもの。"}, {"text": "涙を節約して、泣かずにいた。", "explanation": "ここは〈こらえる〉の意味。涙は節約するものではなく、こらえるもの。"}, {"text": "新しい技術を節約した。", "explanation": "ここは〈習得〉の意味。技術は節約するものではなく、身につけるもの。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36431, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "省エネのため、暖房の節約を努めている。", "corrected_sentence": "省エネのため、暖房の節約に努めている。", "error_description": "「節約に努める」の「に」が正しい。「努める」は「〜に努める」と取るので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36431, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家計を見直して、節約く暮らしている。", "corrected_sentence": "家計を見直して、節約して暮らしている。", "error_description": "「節約して」の「して」が正しい。「節約」は名詞なので「して」で動詞化して後ろにつなぐ。「く」は形容詞の活用で、名詞には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
