INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36432, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「循環の仕組み」と名詞をつなぐ「の」で、正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、ここでは後ろに名詞「仕組み」が続くため文の形が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の目的語に付くが、「循環を仕組み」では名詞同士がつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、名詞「仕組み」とつながる形にはならない。"}], "correct_answer": "の", "explanations": {"の": "「循環の仕組み」と名詞をつなぐ「の」で、正解。", "が": "「が」は主語を示すが、ここでは後ろに名詞「仕組み」が続くため文の形が成り立たない。", "を": "「を」は動作の目的語に付くが、「循環を仕組み」では名詞同士がつながらない。", "で": "「で」は場所や手段を示すが、名詞「仕組み」とつながる形にはならない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36432, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "血液・水・空気などが一定の経路をめぐって元に戻り、同じ動きをくり返すこと。", "primary_collocate": null, "pronunciation": "じゅんかん", "ipa": "dʑuɴkaɴ", "syllable_count": 4, "sentences": [{"text": "心臓は、血液を体中に循環させる働きをしています。", "target_word": "循環", "complexity_tier": "T3", "furigana": "心臓[しんぞう]は、血液[けつえき]を体中[からだじゅう]に循環[じゅんかん]させる働[はたら]きをしています。", "sentence_source": "generated"}, {"text": "水は海から空へ、空から地上へと循環している。", "target_word": "循環", "complexity_tier": "T3", "furigana": "水[みず]は海[うみ]から空[そら]へ、空[そら]から地上[ちじょう]へと循環[じゅんかん]している。", "sentence_source": "generated"}, {"text": "部屋の空気が循環するように、窓を二か所開けた。", "target_word": "循環", "complexity_tier": "T3", "furigana": "部屋[へや]の空気[くうき]が循環[じゅんかん]するように、窓[まど]を二[に]か所[しょ]開[あ]けた。", "sentence_source": "generated"}, {"text": "季節は春、夏、秋、冬と循環して、また春に戻ります。", "target_word": "循環", "complexity_tier": "T3", "furigana": "季節[きせつ]は春[はる]、夏[なつ]、秋[あき]、冬[ふゆ]と循環[じゅんかん]して、また春[はる]に戻[もど]ります。", "sentence_source": "generated"}, {"text": "寒い日は、運動をして血の循環をよくすると体が温まります。", "target_word": "循環", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、運動[うんどう]をして血[ち]の循環[じゅんかん]をよくすると体[からだ]が温[あたた]まります。", "sentence_source": "generated"}, {"text": "このバスは町の中を循環していて、十分おきに来る。", "target_word": "循環", "complexity_tier": "T3", "furigana": "このバスは町[まち]の中[なか]を循環[じゅんかん]していて、十分[じっぷん]おきに来[く]る。", "sentence_source": "generated"}, {"text": "自然の中では、落ち葉が土になり、木を育てる循環が続いている。", "target_word": "循環", "complexity_tier": "T3", "furigana": "自然[しぜん]の中[なか]では、落[お]ち葉[ば]が土[つち]になり、木[き]を育[そだ]てる循環[じゅんかん]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "資源を捨てずに使う循環の仕組みが、町で作られた。", "target_word": "循環", "complexity_tier": "T3", "furigana": "資源[しげん]を捨[す]てずに使[つか]う循環[じゅんかん]の仕組[しく]みが、町[まち]で作[つく]られた。", "sentence_source": "generated"}, {"text": "お湯が循環する装置のおかげで、お風呂はいつも温かい。", "target_word": "循環", "complexity_tier": "T3", "furigana": "お湯[ゆ]が循環[じゅんかん]する装置[そうち]のおかげで、お風呂[ふろ]はいつも温[あたた]かい。", "sentence_source": "generated"}, {"text": "水が循環しなくなると、池の水はにごってしまう。", "target_word": "循環", "complexity_tier": "T3", "furigana": "水[みず]が循環[じゅんかん]しなくなると、池[いけ]の水[みず]はにごってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "循環する", "label": "辞書形"}, {"form": "循環した", "label": "過去形"}, {"form": "循環して", "label": "て形"}, {"form": "循環させる", "label": "使役形"}], "register": "plain", "sense_fingerprint": "血液・水・空気などが一巡して元に戻り、同じ動きをくり返すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36432, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼吸", "is_correct": false, "explanation": "「血液を呼吸させる」は意味が通らず、空欄には入らない。"}, {"text": "循環", "is_correct": true, "explanation": "「血液を循環させる」は血液が体の中を一巡して流れることを表し、文の意味に合う。"}, {"text": "点火", "is_correct": false, "explanation": "「血液を点火させる」は成り立たず、空欄には入らない。"}, {"text": "解凍", "is_correct": false, "explanation": "「血液を解凍させる」は意味が通らず、空欄には入らない。"}], "explanations": {"呼吸": "「血液を呼吸させる」は意味が通らず、空欄には入らない。", "循環": "「血液を循環させる」は血液が体の中を一巡して流れることを表し、文の意味に合う。", "点火": "「血液を点火させる」は成り立たず、空欄には入らない。", "解凍": "「血液を解凍させる」は意味が通らず、空欄には入らない。"}, "sentence_index": 0, "correct_answer": "循環"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "提出前に、報告書の文章が循環して、読みやすくなった。", "explanation": "ここは〈推敲〉の意味。〈循環〉は流れが一巡して元に戻る動きで、文章を練り直す意味にはならない。"}, {"text": "作業前に、機械の状態が循環した。", "explanation": "ここは〈点検〉の意味。〈循環〉は動きが一巡することで、機械を調べる意味は表せない。"}, {"text": "棚の板が循環して、動かなくなった。", "explanation": "ここは〈固定〉の意味。〈循環〉は動きが続くことで、部品を留めて動かなくする意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36432, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅行", "is_correct": false, "explanation": "「木を育てる旅行」は意味が通らず、空欄には入らない。"}, {"text": "循環", "is_correct": true, "explanation": "「木を育てる循環」は、落ち葉が土になり木を育てるまで一巡する流れを表し、文の意味に合う。"}, {"text": "試験", "is_correct": false, "explanation": "「木を育てる試験」は成り立たず、空欄には入らない。"}, {"text": "手品", "is_correct": false, "explanation": "「木を育てる手品」は意味が通らず、空欄には入らない。"}], "explanations": {"旅行": "「木を育てる旅行」は意味が通らず、空欄には入らない。", "循環": "「木を育てる循環」は、落ち葉が土になり木を育てるまで一巡する流れを表し、文の意味に合う。", "試験": "「木を育てる試験」は成り立たず、空欄には入らない。", "手品": "「木を育てる手品」は意味が通らず、空欄には入らない。"}, "sentence_index": 6, "correct_answer": "循環"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壊れた炊飯器を循環させて直した。", "explanation": "ここは〈修理〉の意味。〈循環〉は流れが一巡することで、壊れた機械を直す意味にはならない。"}, {"text": "英語の手紙を循環させて日本語に直した。", "explanation": "ここは〈翻訳〉の意味。〈循環〉は言葉を別の言語に置き換える意味にはならない。"}, {"text": "会議の時間を循環させた。", "explanation": "ここは〈延長〉の意味。〈循環〉は一巡して戻る動きで、時間を延ばす意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36432, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ポンプで水を循環される。", "corrected_sentence": "ポンプで水を循環させる。", "error_description": "「循環させる」の使役形が正しい（ポンプが水を循環させる）。「循環される」は受け身で、水が循環を受けるという形は不自然。誤りは「循環」に続く「される」の部分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36432, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "資源の循環が進める。", "corrected_sentence": "資源の循環を進める。", "error_description": "「進める」は他動詞で目的語に「を」を取るので「資源の循環を進める」が正しい。「が」では〈循環〉が主語になり不自然で、誤り。誤りは「循環」の直後の助詞の部分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
