INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36434, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものがのびたりちぢんだりすること。", "primary_collocate": null, "pronunciation": "しんしゅく", "ipa": "ɕiɲɕɯkɯ", "syllable_count": 4, "sentences": [{"text": "熱を加えると、この金属の棒は伸縮する。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "熱[ねつ]を加[くわ]えると、この金属[きんぞく]の棒[ぼう]は伸縮[しんしゅく]する。", "sentence_source": "generated"}, {"text": "ゴムは力を加えると伸縮するので、輪にして使える。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "ゴムは力[ちから]を加[くわ]えると伸縮[しんしゅく]するので、輪[わ]にして使[つか]える。", "sentence_source": "generated"}, {"text": "気温が変わると、橋の鉄は伸縮するから、すき間が作ってある。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "気温[きおん]が変[か]わると、橋[はし]の鉄[てつ]は伸縮[しんしゅく]するから、すき間[ま]が作[つく]ってある。", "sentence_source": "generated"}, {"text": "この伸縮の幅が大きすぎて、部品がこわれた。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "この伸縮[しんしゅく]の幅[はば]が大[おお]きすぎて、部品[ぶひん]がこわれた。", "sentence_source": "generated"}, {"text": "熱で伸縮を繰り返したため、板に細かいひびが入った。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "熱[ねつ]で伸縮[しんしゅく]を繰[く]り返[かえ]したため、板[いた]に細[こま]かいひびが入[はい]った。", "sentence_source": "generated"}, {"text": "犬のリードは伸縮して、長さを自由に変えられる。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "犬[いぬ]のリードは伸縮[しんしゅく]して、長[なが]さを自由[じゆう]に変[か]えられる。", "sentence_source": "generated"}, {"text": "筋肉は伸縮することで、体を動かしている。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "筋肉[きんにく]は伸縮[しんしゅく]することで、体[からだ]を動[うご]かしている。", "sentence_source": "generated"}, {"text": "夏と冬では、線路が伸縮するので、つなぎ目にすき間がある。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "夏[なつ]と冬[ふゆ]では、線路[せんろ]が伸縮[しんしゅく]するので、つなぎ目[め]にすき間[ま]がある。", "sentence_source": "generated"}, {"text": "バネが伸縮しなくなったので、新しいものに替えた。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "バネが伸縮[しんしゅく]しなくなったので、新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "湿気でも木材は少し伸縮するから、家具は余裕をもって作る。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "湿気[しっけ]でも木材[もくざい]は少[すこ]し伸縮[しんしゅく]するから、家具[かぐ]は余裕[よゆう]をもって作[つく]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伸縮", "label": "基本形"}, {"form": "伸縮する", "label": "終止形"}, {"form": "伸縮した", "label": "過去形"}, {"form": "伸縮して", "label": "て形"}, {"form": "伸縮しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "物が伸びたり縮んだりする動き(する動詞として使う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36434, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伸縮", "is_correct": true, "explanation": "「伸縮する」で、熱によって金属の棒が伸び縮みする意味に合う。"}, {"text": "解答", "is_correct": false, "explanation": "「解答する」は問いに答えること。金属の棒を主語にしても成り立たない。"}, {"text": "配達", "is_correct": false, "explanation": "「配達する」は品物を届けること。棒が主語では意味が通らない。"}, {"text": "採点", "is_correct": false, "explanation": "「採点する」は答案に点をつけること。金属の棒には使えない。"}], "explanations": {"伸縮": "「伸縮する」で、熱によって金属の棒が伸び縮みする意味に合う。", "解答": "「解答する」は問いに答えること。金属の棒を主語にしても成り立たない。", "配達": "「配達する」は品物を届けること。棒が主語では意味が通らない。", "採点": "「採点する」は答案に点をつけること。金属の棒には使えない。"}, "sentence_index": 0, "correct_answer": "伸縮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この船の旗は伸縮して、風が止むと下がった。", "explanation": "ここは〈下降〉の意味。旗が下がることは下降で、のび縮みを表す伸縮とは違う。"}, {"text": "この時計の針は伸縮して、一時間で一周する。", "explanation": "ここは〈回転〉の意味。ぐるりと回る動きは回転で、伸びたり縮んだりする伸縮とは別。"}, {"text": "この信号の光は伸縮して、一定の間隔でついたり消えたりする。", "explanation": "ここは〈点滅〉の意味。明かりがついたり消えたりすることは点滅で、伸縮は長さや大きさの変化を言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36434, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伸縮", "is_correct": true, "explanation": "「伸縮する」で、筋肉が縮んだりのびたりして体を動かす意味に合う。"}, {"text": "点火", "is_correct": false, "explanation": "「点火する」は火をつけること。筋肉を主語にしては意味が通らない。"}, {"text": "交換", "is_correct": false, "explanation": "「交換する」は別のものと取り替えること。筋肉の動きには当てはまらない。"}, {"text": "出題", "is_correct": false, "explanation": "「出題する」は問題を出すこと。体の動きを表す文では意味が通らない。"}], "explanations": {"伸縮": "「伸縮する」で、筋肉が縮んだりのびたりして体を動かす意味に合う。", "点火": "「点火する」は火をつけること。筋肉を主語にしては意味が通らない。", "交換": "「交換する」は別のものと取り替えること。筋肉の動きには当てはまらない。", "出題": "「出題する」は問題を出すこと。体の動きを表す文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "伸縮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この話題は伸縮して、会議が長引いた。", "explanation": "ここは〈発展〉の意味。話し合いが広がることは発展で、物がのび縮みする伸縮とは違う。"}, {"text": "強い風で、旗が伸縮してねじれた。", "explanation": "ここは〈ねじれる〉の意味。ひねられて形が曲がる動きはねじれで、伸縮とは別。"}, {"text": "この店は伸縮して、毎週、商品を入れ替える。", "explanation": "ここは〈入れ替え〉の意味。品物を取り替えることは交換で、物がのび縮みする伸縮とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36434, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の暑さで、この橋の鉄板は伸縮させる。", "corrected_sentence": "夏の暑さで、この橋の鉄板は伸縮する。", "error_description": "「伸縮させる」は、誰かが物を伸び縮みさせるという使い方。鉄板は自分で伸び縮みするので、「伸縮する」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36434, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "梅雨の時期は、木の板が少し伸縮しするので、ドアの枠にすき間を作っておく。", "corrected_sentence": "梅雨の時期は、木の板が少し伸縮するので、ドアの枠にすき間を作っておく。", "error_description": "「伸縮し」の「し」が余分になっている。伸縮は「する」と組み合わせて「伸縮する」の形で使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
