INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36435, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36435, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物の長さや大きさが、のびたりちぢんだりすること。また、その性質。", "primary_collocate": null, "pronunciation": "しんしゅく", "ipa": "ɕiɲɕɯkɯ", "syllable_count": 4, "sentences": [{"text": "この生地は伸縮が大きいので、体の形に合わせて変わる。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "この生地[きじ]は伸縮[しんしゅく]が大[おお]きいので、体[からだ]の形[かたち]に合[あ]わせて変[か]わる。", "sentence_source": "generated"}, {"text": "伸縮が少ない布は、きつい服には向かない。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "伸縮[しんしゅく]が少[すく]ない布[ぬの]は、きつい服[ふく]には向[む]かない。", "sentence_source": "generated"}, {"text": "このズボンのウエストは伸縮に優れていて、食べたあとも楽だ。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "このズボンのウエストは伸縮[しんしゅく]に優[すぐ]れていて、食[た]べたあとも楽[らく]だ。", "sentence_source": "generated"}, {"text": "伸縮に富んだ素材なので、サイズが多少ちがっても着られる。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "伸縮[しんしゅく]に富[と]んだ素材[そざい]なので、サイズが多少[たしょう]ちがっても着[き]られる。", "sentence_source": "generated"}, {"text": "古いゴムは伸縮が弱くなり、靴下がずり落ちる。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "古[ふる]いゴムは伸縮[しんしゅく]が弱[よわ]くなり、靴下[くつした]がずり落[お]ちる。", "sentence_source": "generated"}, {"text": "このテープは伸縮がほとんどないため、固定に向いている。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "このテープは伸縮[しんしゅく]がほとんどないため、固定[こてい]に向[む]いている。", "sentence_source": "generated"}, {"text": "運動用のシャツは、伸縮と通気性の両方が大切だ。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "運動用[うんどうよう]のシャツは、伸縮[しんしゅく]と通気性[つうきせい]の両方[りょうほう]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "伸縮の程度は素材によってちがうので、買う前に確かめる。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "伸縮[しんしゅく]の程度[ていど]は素材[そざい]によってちがうので、買[か]う前[まえ]に確[たし]かめる。", "sentence_source": "generated"}, {"text": "髪をしばるゴムは、伸縮が十分でないと切れやすい。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "髪[かみ]をしばるゴムは、伸縮[しんしゅく]が十分[じゅうぶん]でないと切[き]れやすい。", "sentence_source": "generated"}, {"text": "伸縮が大きすぎる糸は、編み物では形がくずれやすい。", "target_word": "伸縮", "complexity_tier": "T3", "furigana": "伸縮[しんしゅく]が大[おお]きすぎる糸[いと]は、編[あ]み物[もの]では形[かたち]がくずれやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伸縮", "label": "基本形"}, {"form": "伸縮する", "label": "終止形"}, {"form": "伸縮した", "label": "過去形"}, {"form": "伸縮して", "label": "て形"}, {"form": "伸縮しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "布やゴムなどののび縮みしやすさという性質(大きい・少ないで程度を言う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36435, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伸縮", "is_correct": true, "explanation": "「伸縮が大きい」で、生地ののび縮みしやすさという性質を言う。"}, {"text": "色合い", "is_correct": false, "explanation": "「色合い」は見た目の色の具合。「が大きい」とは言わず、文に合わない。"}, {"text": "産地", "is_correct": false, "explanation": "「産地」は作られた場所。その大きさを「大きい」とは言えない。"}, {"text": "手触り", "is_correct": false, "explanation": "「手触り」は触った感じ。ここでは伸び縮みの程度を表せない。"}], "explanations": {"伸縮": "「伸縮が大きい」で、生地ののび縮みしやすさという性質を言う。", "色合い": "「色合い」は見た目の色の具合。「が大きい」とは言わず、文に合わない。", "産地": "「産地」は作られた場所。その大きさを「大きい」とは言えない。", "手触り": "「手触り」は触った感じ。ここでは伸び縮みの程度を表せない。"}, "sentence_index": 0, "correct_answer": "伸縮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この傘は伸縮して開き、雨の中でも濡れない。", "explanation": "ここは〈伸び縮みする動き〉の意味。傘を開く動作としての伸縮は、性質を表す36435の伸縮とは違う。"}, {"text": "この棒は伸縮して、長さを手早く調節する。", "explanation": "ここは〈伸び縮みする動き〉の意味。動作として伸縮するのは36434の意味で、性質を言う36435とは違う。"}, {"text": "この扉は伸縮して、ゆっくり閉まる。", "explanation": "ここは〈伸び縮みする動き〉の意味。扉の動きとしての伸縮は、性質の伸縮とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36435, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伸縮", "is_correct": true, "explanation": "「伸縮と通気性」で、運動用シャツに必要な伸び縮みのしやすさという性質に合う。"}, {"text": "試着", "is_correct": false, "explanation": "「試着」は服を着て確かめる行為。性質と並べて大切だとは言えない。"}, {"text": "保管", "is_correct": false, "explanation": "「保管」は大切にしまっておくこと。通気性と並べる性質ではない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「洗濯」は洗う作業。通気性と並べて両方が大切だとは言えない。"}], "explanations": {"伸縮": "「伸縮と通気性」で、運動用シャツに必要な伸び縮みのしやすさという性質に合う。", "試着": "「試着」は服を着て確かめる行為。性質と並べて大切だとは言えない。", "保管": "「保管」は大切にしまっておくこと。通気性と並べる性質ではない。", "洗濯": "「洗濯」は洗う作業。通気性と並べて両方が大切だとは言えない。"}, "sentence_index": 6, "correct_answer": "伸縮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車は伸縮が速く、坂道でも加速する。", "explanation": "ここは〈加速〉の意味。速さを増していく動きは加速で、伸び縮みのしやすさを表す36435の伸縮では言えない。"}, {"text": "子どもの伸縮が大きく、毎年服が合わなくなる。", "explanation": "ここは〈成長〉の意味。背が伸びることは成長で、物の伸び縮みを表す伸縮とは合わない。"}, {"text": "彼は伸縮のある考え方で、意見を受け入れた。", "explanation": "ここは〈柔軟〉の意味。考え方の柔らかさは柔軟で、伸縮の性質とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36435, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この布は伸縮を小さいので、ぴったり体に合う。", "corrected_sentence": "この布は伸縮が小さいので、ぴったり体に合う。", "error_description": "「小さい」の主語は「が」で示す。「伸縮を」は誤りで、伸縮の程度を述べるには「伸縮が小さい」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36435, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この糸は伸縮すぎて、形がくずれやすい。", "corrected_sentence": "この糸は伸縮しすぎて、形がくずれやすい。", "error_description": "「伸縮すぎる」は誤り。伸縮は「する」の動詞として使うので、「しすぎる」の形にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36436, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ものに分類する」の「に」で、分類の区分先を示すので正解。"}, {"text": "か", "is_correct": false, "explanation": "「〜か分類する」は二者択一を示す形で、区分の先を示す「に」の代わりには入らない。"}, {"text": "へ", "is_correct": false, "explanation": "「〜へ分類する」は方向を示す形になり、区分の先としては合わない。"}, {"text": "が", "is_correct": false, "explanation": "「色のあるものが分類する」では主語になるが、物は分類する主体になれないので文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「ものに分類する」の「に」で、分類の区分先を示すので正解。", "か": "「〜か分類する」は二者択一を示す形で、区分の先を示す「に」の代わりには入らない。", "へ": "「〜へ分類する」は方向を示す形になり、区分の先としては合わない。", "が": "「色のあるものが分類する」では主語になるが、物は分類する主体になれないので文が成り立たない。"}, "error_tags": {"へ": "方向", "が": "主語", "か": "選択"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36436, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「町ごとに分類する」の「に」で、分類の区分先を示すので正解。"}, {"text": "を", "is_correct": false, "explanation": "「町ごとを分類する」は前の「手紙を」と重なり、目的語が二つになって成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「町ごとと分類する」は並べる相手を示すため、区分の先にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「町ごとより分類する」は比べる基準を示すため、区分の先にはならない。"}], "correct_answer": "に", "explanations": {"に": "「町ごとに分類する」の「に」で、分類の区分先を示すので正解。", "を": "「町ごとを分類する」は前の「手紙を」と重なり、目的語が二つになって成り立たない。", "と": "「町ごとと分類する」は並べる相手を示すため、区分の先にはならない。", "より": "「町ごとより分類する」は比べる基準を示すため、区分の先にはならない。"}, "error_tags": {"を": "二重目的語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36436, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを、同じ仲間ごとに分けること。", "primary_collocate": null, "pronunciation": "ぶんるい", "ipa": "bɯɴɾɯi", "syllable_count": 4, "sentences": [{"text": "おもちゃを色ごとに分類して、箱に入れた。", "target_word": "分類", "complexity_tier": "T2", "furigana": "おもちゃを色(いろ)ごとに分類(ぶんるい)して、箱(はこ)に入(い)れた。", "sentence_source": "generated"}, {"text": "洗濯物を白いものと色のあるものに分類する。", "target_word": "分類", "complexity_tier": "T2", "furigana": "洗濯物(せんたくもの)を白(しろ)いものと色(いろ)のあるものに分類(ぶんるい)する。", "sentence_source": "generated"}, {"text": "兄は集めたカードを、種類ごとに分類している。", "target_word": "分類", "complexity_tier": "T2", "furigana": "兄(あに)は集(あつ)めたカードを、種類(しゅるい)ごとに分類(ぶんるい)している。", "sentence_source": "generated"}, {"text": "ごみの分類を間違えると、回収してもらえないことがある。", "target_word": "分類", "complexity_tier": "T3", "furigana": "ごみの分類(ぶんるい)を間違(まちが)えると、回収(かいしゅう)してもらえないことがある。", "sentence_source": "generated"}, {"text": "図鑑の絵を、動物と植物に分類してみよう。", "target_word": "分類", "complexity_tier": "T2", "furigana": "図鑑(ずかん)の絵(え)を、動物(どうぶつ)と植物(しょくぶつ)に分類(ぶんるい)してみよう。", "sentence_source": "generated"}, {"text": "母は薬を、飲む時間ごとに分類して箱に入れている。", "target_word": "分類", "complexity_tier": "T3", "furigana": "母(はは)は薬(くすり)を、飲(の)む時間(じかん)ごとに分類(ぶんるい)して箱(はこ)に入(い)れている。", "sentence_source": "generated"}, {"text": "貝がらを大きさで分類したら、きれいに並んだ。", "target_word": "分類", "complexity_tier": "T2", "furigana": "貝(かい)がらを大(おお)きさで分類(ぶんるい)したら、きれいに並(なら)んだ。", "sentence_source": "generated"}, {"text": "手紙を送り先の町ごとに分類するのが、郵便局の仕事だ。", "target_word": "分類", "complexity_tier": "T3", "furigana": "手紙(てがみ)を送(おく)り先(さき)の町(まち)ごとに分類(ぶんるい)するのが、郵便局(ゆうびんきょく)の仕事(しごと)だ。", "sentence_source": "generated"}, {"text": "引っ越しの荷物を部屋ごとに分類しておくと、片づけが楽だ。", "target_word": "分類", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)しの荷物(にもつ)を部屋(へや)ごとに分類(ぶんるい)しておくと、片(かた)づけが楽(らく)だ。", "sentence_source": "generated"}, {"text": "本を分類せずに積んでおいたので、探すのに時間がかかった。", "target_word": "分類", "complexity_tier": "T3", "furigana": "本(ほん)を分類(ぶんるい)せずに積(つ)んでおいたので、探(さが)すのに時間(じかん)がかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分類する", "label": "辞書形"}, {"form": "分類した", "label": "過去形"}, {"form": "分類して", "label": "て形"}, {"form": "分類しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "ものを同じ仲間ごとに分ける日常的な行為（サ変名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 貝がら (Zipf 1.93)']::text[], '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36436, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分類", "is_correct": true, "explanation": "「色ごとに分類して」の分類で、同じ仲間ごとに分ける行為を指すので正解。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつけることで、おもちゃを色で分ける文には合わない。"}, {"text": "延期", "is_correct": false, "explanation": "延期は予定の時期を後ろにずらすことで、ここには入らない。"}, {"text": "失恋", "is_correct": false, "explanation": "失恋は恋がかなわないことで、物を色で分ける文には合わない。"}], "explanations": {"分類": "「色ごとに分類して」の分類で、同じ仲間ごとに分ける行為を指すので正解。", "点火": "点火は火をつけることで、おもちゃを色で分ける文には合わない。", "延期": "延期は予定の時期を後ろにずらすことで、ここには入らない。", "失恋": "失恋は恋がかなわないことで、物を色で分ける文には合わない。"}, "sentence_index": 0, "correct_answer": "分類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い時計を分類で分解した。", "explanation": "ここは〈分解〉の意味。時計を部品にばらすのが分解で、分類は同じ仲間ごとに分けるだけなので、機械をばらす文には合わない。"}, {"text": "英語の手紙を日本語に分類した。", "explanation": "ここは〈翻訳〉の意味。ある言語の文章を別の言語に置き換えるのが翻訳で、分類は物を仲間ごとに分ける行為なので合わない。"}, {"text": "壊れた椅子を分類で直した。", "explanation": "ここは〈修理〉の意味。壊れたものを直すのが修理で、分類は仲間ごとに分ける行為なので、「分類で直す」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36436, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分類", "is_correct": true, "explanation": "「大きさで分類したら」の分類で、大きさで仲間分けする作業を表すので正解。"}, {"text": "収穫", "is_correct": false, "explanation": "収穫は作物を取り入れることで、貝がらを選り分ける文には合わない。"}, {"text": "解決", "is_correct": false, "explanation": "解決は問題を片づけることで、貝がらの大きさによる選り分けには合わない。"}, {"text": "発酵", "is_correct": false, "explanation": "発酵は微生物が物質を変える現象で、貝がらを並べる文には合わない。"}], "explanations": {"分類": "「大きさで分類したら」の分類で、大きさで仲間分けする作業を表すので正解。", "収穫": "収穫は作物を取り入れることで、貝がらを選り分ける文には合わない。", "解決": "解決は問題を片づけることで、貝がらの大きさによる選り分けには合わない。", "発酵": "発酵は微生物が物質を変える現象で、貝がらを並べる文には合わない。"}, "sentence_index": 6, "correct_answer": "分類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの店の値段を分類した。", "explanation": "ここは〈比較〉の意味。差を見比べるのが比較で、分類は物を仲間ごとに分けるので、値段を見比べる文には合わない。"}, {"text": "ランチを分類した。", "explanation": "ここは〈注文〉の意味。店に料理を頼むのが注文で、分類は物を仲間ごとに分ける行為なので、料理を頼む文には合わない。"}, {"text": "床を分類した。", "explanation": "ここは〈掃除〉の意味。汚れを取って清潔にするのが掃除で、分類は仲間ごとに分ける行為なので、床をきれいにする文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36436, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボタンを色ごとに分類入れた。", "corrected_sentence": "ボタンを色ごとに分類して入れた。", "error_description": "「分類入れた」が誤り。正しくは「分類して入れた」。サ変名詞の分類は「して」を補って動詞につなぐ必要があり、「分類入れた」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36436, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "読み終えた雑誌を号ごとに分類ておいた。", "corrected_sentence": "読み終えた雑誌を号ごとに分類しておいた。", "error_description": "「分類ておいた」が誤り。正しくは「分類しておいた」。サ変名詞の分類を て形にするには「し」を補って「する」の形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
