INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36437, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある基準に従って、物事を種類やグループに分けること。", "primary_collocate": null, "pronunciation": "ぶんるい", "ipa": "bɯɴɾɯi", "syllable_count": 4, "sentences": [{"text": "教科書の内容を単元ごとに分類した。", "target_word": "分類", "complexity_tier": "T3", "furigana": "教科書(きょうかしょ)の内容(ないよう)を単元(たんげん)ごとに分類(ぶんるい)した。", "sentence_source": "generated"}, {"text": "図書館では、本を内容によって分類して棚に並べている。", "target_word": "分類", "complexity_tier": "T3", "furigana": "図書館(としょかん)では、本(ほん)を内容(ないよう)によって分類(ぶんるい)して棚(たな)に並(なら)べている。", "sentence_source": "generated"}, {"text": "研究者は集めた植物を、花の形を基準に三つに分類した。", "target_word": "分類", "complexity_tier": "T3", "furigana": "研究者(けんきゅうしゃ)は集(あつ)めた植物(しょくぶつ)を、花(はな)の形(かたち)を基準(きじゅん)に三(みっ)つに分類(ぶんるい)した。", "sentence_source": "generated"}, {"text": "顧客の意見を種類ごとに分類すると、不満の原因が見えてきた。", "target_word": "分類", "complexity_tier": "T3", "furigana": "顧客(こきゃく)の意見(いけん)を種類(しゅるい)ごとに分類(ぶんるい)すると、不満(ふまん)の原因(げんいん)が見(み)えてきた。", "sentence_source": "generated"}, {"text": "この問題は、どの基準を使うかによって分類の結果が変わる。", "target_word": "分類", "complexity_tier": "T3", "furigana": "この問題(もんだい)は、どの基準(きじゅん)を使(つか)うかによって分類(ぶんるい)の結果(けっか)が変(か)わる。", "sentence_source": "generated"}, {"text": "農家は野菜を大きさで分類し直した。", "target_word": "分類", "complexity_tier": "T3", "furigana": "農家(のうか)は野菜(やさい)を大(おお)きさで分類(ぶんるい)し直(なお)した。", "sentence_source": "generated"}, {"text": "届いたメールを重要度で分類しておけば、返信の順番を決めやすい。", "target_word": "分類", "complexity_tier": "T3", "furigana": "届(とど)いたメールを重要度(じゅうようど)で分類(ぶんるい)しておけば、返信(へんしん)の順番(じゅんばん)を決(き)めやすい。", "sentence_source": "generated"}, {"text": "先生は生徒の作文を、テーマ別に分類してから講評した。", "target_word": "分類", "complexity_tier": "T3", "furigana": "先生(せんせい)は生徒(せいと)の作文(さくぶん)を、テーマ別(べつ)に分類(ぶんるい)してから講評(こうひょう)した。", "sentence_source": "generated"}, {"text": "化石を年代で分類する作業には、長い経験が必要だ。", "target_word": "分類", "complexity_tier": "T3", "furigana": "化石(かせき)を年代(ねんだい)で分類(ぶんるい)する作業(さぎょう)には、長(なが)い経験(けいけん)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "ごみは素材ごとに分類して出さなければならない。", "target_word": "分類", "complexity_tier": "T3", "furigana": "ごみは素材(そざい)ごとに分類(ぶんるい)して出(だ)さなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分類する", "label": "辞書形"}, {"form": "分類した", "label": "過去形"}, {"form": "分類して", "label": "て形"}, {"form": "分類しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "基準に従って物事を種類別に分ける行為（サ変名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36437, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分類", "is_correct": true, "explanation": "「単元ごとに分類した」の分類で、基準に従って内容を仲間に分ける行為を表すので正解。"}, {"text": "発酵", "is_correct": false, "explanation": "発酵は微生物が物質を変える現象で、体系の名前には入らないので合わない。"}, {"text": "沈黙", "is_correct": false, "explanation": "沈黙は黙ることを表し、「沈黙体系」は意味をなさないので合わない。"}, {"text": "感動", "is_correct": false, "explanation": "感動は心の動きを表し、体系を修飾する語としては成り立たないので合わない。"}], "explanations": {"分類": "「単元ごとに分類した」の分類で、基準に従って内容を仲間に分ける行為を表すので正解。", "発酵": "発酵は微生物が物質を変える現象で、体系の名前には入らないので合わない。", "沈黙": "沈黙は黙ることを表し、「沈黙体系」は意味をなさないので合わない。", "感動": "感動は心の動きを表し、体系を修飾する語としては成り立たないので合わない。"}, "sentence_index": 0, "correct_answer": "分類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "血液を検査して、鉄の量を分類した。", "explanation": "ここは〈分析〉の意味。鉄の量を調べて数値として明らかにするのが分析で、分類は物を種類ごとに分けるので、量を調べる文には合わない。"}, {"text": "大きなケーキを分類して、家族みんなで食べた。", "explanation": "ここは〈分割〉の意味。一つの物を切り分けるのが分割で、分類は同じ種類ごとに分ける行為なので、ケーキを切る文には使わない。"}, {"text": "その答えが正しいかどうかを分類して、先生に伝えた。", "explanation": "ここは〈判断〉の意味。正誤を見きわめて決めるのが判断で、分類は物事を仲間ごとに分けるので、答えの正否を決める文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36437, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分類", "is_correct": true, "explanation": "「重要度で分類しておけば」の分類で、仲間ごとに分けることを表すので正解。"}, {"text": "蒸発", "is_correct": false, "explanation": "蒸発は液体が気体になる現象で、メールを重要度で仕分ける文には合わない。"}, {"text": "停滞", "is_correct": false, "explanation": "停滞は物事が進まなくなることで、重要度を基準に作業する文には合わない。"}, {"text": "修復", "is_correct": false, "explanation": "修復は壊れたものを直すことで、メールを整理する文には合わない。"}], "explanations": {"分類": "「重要度で分類しておけば」の分類で、仲間ごとに分けることを表すので正解。", "蒸発": "蒸発は液体が気体になる現象で、メールを重要度で仕分ける文には合わない。", "停滞": "停滞は物事が進まなくなることで、重要度を基準に作業する文には合わない。", "修復": "修復は壊れたものを直すことで、メールを整理する文には合わない。"}, "sentence_index": 6, "correct_answer": "分類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つのプランから一つを分類した。", "explanation": "ここは〈選択〉の意味。候補の中から一つを選ぶのが選択で、分類は全体を仲間ごとに分ける行為なので合わない。"}, {"text": "二つの製品の性能を分類した。", "explanation": "ここは〈比較〉の意味。性能の違いや共通点を並べて見比べるのが比較で、分類は物を仲間ごとに分けるので合わない。"}, {"text": "薬の分類を守る。", "explanation": "ここは〈分量〉の意味。一回に飲む量を指す分量を守るという表現で、分類は種類による区分を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36437, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古紙は種類ごとに分類に出すことになっている。", "corrected_sentence": "古紙は種類ごとに分類して出すことになっている。", "error_description": "「分類に出す」が誤り。正しくは「分類して出す」。サ変名詞の分類は「分類して」の形で動詞「出す」につなぐ必要があり、「に」を続けると文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36437, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い写真を時代ごとに分類ておいた。", "corrected_sentence": "古い写真を時代ごとに分類しておいた。", "error_description": "「分類ておいた」が誤り。正しくは「分類しておいた」。サ変名詞の分類を て形にするには「し」を補って「する」の形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36438, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「後者」と「ほう」をつなぐ「の」。「後者のほう」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「後者を」と続けると目的語になり、「ほうが安い」の主題が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「後者に」は位置や相手を表し、「ほう」とつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「後者で」は場所や手段を表し、「ほうが安い」の文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "「後者」と「ほう」をつなぐ「の」。「後者のほう」の形になる。", "を": "「後者を」と続けると目的語になり、「ほうが安い」の主題が成り立たない。", "に": "「後者に」は位置や相手を表し、「ほう」とつながらない。", "で": "「後者で」は場所や手段を表し、「ほうが安い」の文脈に合わない。"}, "error_tags": {"を": "目的格", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前者", "is_correct": true, "explanation": "二つのうち先に述べた方を指し、後者と対になる対義語。"}, {"text": "中間", "is_correct": false, "explanation": "真ん中の位置を表し、前後の対にはならない。"}, {"text": "全体", "is_correct": false, "explanation": "まとまり全体を指し、後者と対になる語ではない。"}, {"text": "最初", "is_correct": false, "explanation": "始まりを表し、後者との対義関係にはない。"}], "correct_answer": "前者", "explanations": {"前者": "二つのうち先に述べた方を指し、後者と対になる対義語。", "中間": "真ん中の位置を表し、前後の対にはならない。", "全体": "まとまり全体を指し、後者と対になる語ではない。", "最初": "始まりを表し、後者との対義関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36438, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前者", "is_correct": true, "explanation": "二つのうち先に述べた方を指し、後者と対になる対義語。"}, {"text": "両方", "is_correct": false, "explanation": "二つ全部を指し、後者と対になる語ではない。"}, {"text": "全部", "is_correct": false, "explanation": "すべてを指し、後者との対義関係にはない。"}, {"text": "途中", "is_correct": false, "explanation": "経過の途中を表し、対義語ではない。"}], "correct_answer": "前者", "explanations": {"前者": "二つのうち先に述べた方を指し、後者と対になる対義語。", "両方": "二つ全部を指し、後者と対になる語ではない。", "全部": "すべてを指し、後者との対義関係にはない。", "途中": "経過の途中を表し、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36438, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つあるうちの、あとに出てきた方。", "primary_collocate": null, "pronunciation": "こうしゃ", "ipa": "koːɕa", "syllable_count": 3, "sentences": [{"text": "紅茶とコーヒーなら、私は後者のほうが好きです。", "target_word": "後者", "complexity_tier": "T3", "furigana": "紅茶[こうちゃ]とコーヒーなら、私[わたし]は後者[こうしゃ]のほうが好[す]きです。", "sentence_source": "generated"}, {"text": "電車とバスでは、後者のほうが安いです。", "target_word": "後者", "complexity_tier": "T3", "furigana": "電車[でんしゃ]とバスでは、後者[こうしゃ]のほうが安[やす]いです。", "sentence_source": "generated"}, {"text": "速さと正確さのうち、この仕事では後者が大切だ。", "target_word": "後者", "complexity_tier": "T3", "furigana": "速[はや]さと正確[せいかく]さのうち、この仕事[しごと]では後者[こうしゃ]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "兄と弟のうち、後者はまだ小学生です。", "target_word": "後者", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]のうち、後者[こうしゃ]はまだ小学生[しょうがくせい]です。", "sentence_source": "generated"}, {"text": "新築と中古を比べて、後者を選びました。", "target_word": "後者", "complexity_tier": "T3", "furigana": "新築[しんちく]と中古[ちゅうこ]を比[くら]べて、後者[こうしゃ]を選[えら]びました。", "sentence_source": "generated"}, {"text": "歩く道と自転車の道があるが、後者は坂が多い。", "target_word": "後者", "complexity_tier": "T3", "furigana": "歩[ある]く道[みち]と自転車[じてんしゃ]の道[みち]があるが、後者[こうしゃ]は坂[さか]が多[おお]い。", "sentence_source": "generated"}, {"text": "春と秋では、後者の季節に旅行したい。", "target_word": "後者", "complexity_tier": "T3", "furigana": "春[はる]と秋[あき]では、後者[こうしゃ]の季節[きせつ]に旅行[りょこう]したい。", "sentence_source": "generated"}, {"text": "山と海を考えたが、子どもが喜ぶのは後者だろう。", "target_word": "後者", "complexity_tier": "T3", "furigana": "山[やま]と海[うみ]を考[かんが]えたが、子[こ]どもが喜[よろこ]ぶのは後者[こうしゃ]だろう。", "sentence_source": "generated"}, {"text": "A案とB案のうち、費用が少ないのは後者です。", "target_word": "後者", "complexity_tier": "T3", "furigana": "A案[あん]とB案[あん]のうち、費用[ひよう]が少[すく]ないのは後者[こうしゃ]です。", "sentence_source": "generated"}, {"text": "本を買うか借りるか迷ったが、結局後者にした。", "target_word": "後者", "complexity_tier": "T3", "furigana": "本[ほん]を買[か]うか借[か]りるか迷[まよ]ったが、結局[けっきょく]後者[こうしゃ]にした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "後者", "label": "基本形"}, {"form": "後者の", "label": "連体修飾"}, {"form": "後者を", "label": "目的格"}, {"form": "後者は", "label": "主題"}], "register": "neutral", "sense_fingerprint": "二つ挙げたもののうち、あとの方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36438, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "後者", "is_correct": true, "explanation": "紅茶に続けて挙げたコーヒーを指し、「後者のほうが好きです」と自然に続く。"}, {"text": "後悔", "is_correct": false, "explanation": "「後悔のほうが好き」は飲み物の比較として意味が通らない。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は紅茶やコーヒーと好みを比べる対象にならず、文が成り立たない。"}, {"text": "後片付け", "is_correct": false, "explanation": "後片付けは飲み物と並べて好みを比べる対象にならず、文が不自然になる。"}], "explanations": {"後者": "紅茶に続けて挙げたコーヒーを指し、「後者のほうが好きです」と自然に続く。", "後悔": "「後悔のほうが好き」は飲み物の比較として意味が通らない。", "寝坊": "寝坊は紅茶やコーヒーと好みを比べる対象にならず、文が成り立たない。", "後片付け": "後片付けは飲み物と並べて好みを比べる対象にならず、文が不自然になる。"}, "sentence_index": 0, "correct_answer": "後者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画は後者になってから急に面白くなった。", "explanation": "ここは〈後半〉の意味。後者は二つのうちのあとの方を指すので、一本の映画の後半には使えない。"}, {"text": "三つの案のうち、後者が一番安い。", "explanation": "ここは「三つのうちの最後」の意味。後者は二つを比べたときのあとの方に限られるので、三つ以上の中では使わない。"}, {"text": "私の後者は田中さんです。", "explanation": "ここは〈後任〉の意味。後任は仕事を引き継ぐ人で、後者は二つのうちのあとの方を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36438, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "後者", "is_correct": true, "explanation": "春と秋の二つのうち、あとの季節を指し、「後者の季節に旅行したい」と自然に続く。"}, {"text": "感想", "is_correct": false, "explanation": "「感想の季節」という言い方はなく、旅行の文脈に合わない。"}, {"text": "注意", "is_correct": false, "explanation": "「注意の季節」は意味が通らず、文が成り立たない。"}, {"text": "失敗", "is_correct": false, "explanation": "「失敗の季節に旅行したい」は旅行の希望と結びつかない。"}], "explanations": {"後者": "春と秋の二つのうち、あとの季節を指し、「後者の季節に旅行したい」と自然に続く。", "感想": "「感想の季節」という言い方はなく、旅行の文脈に合わない。", "注意": "「注意の季節」は意味が通らず、文が成り立たない。", "失敗": "「失敗の季節に旅行したい」は旅行の希望と結びつかない。"}, "sentence_index": 6, "correct_answer": "後者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "車の後者にぶつけられた。", "explanation": "ここは〈後部〉の意味。車の後ろの部分は後部と言い、後者は二つのうちのあとの方を指すので合わない。"}, {"text": "列の後者に並んだ。", "explanation": "ここは〈最後尾〉の意味。列の末尾は一つのものの端であり、二つのうちのあとの方を指す後者とは合わない。"}, {"text": "社長の後者を決める。", "explanation": "ここは〈後継者〉の意味。後継者は地位を継ぐ人で、後者は二つのうちのあとの方を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36438, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの案のうち、後者へ選んだ。", "corrected_sentence": "二つの案のうち、後者を選んだ。", "error_description": "「選ぶ」は目的語に「を」をとる。「へ」は方向を表すので誤りで、正しくは「後者を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36438, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つの店のうち、後者にほうが安い。", "corrected_sentence": "二つの店のうち、後者のほうが安い。", "error_description": "「後者」と「ほう」をつなぐのは「の」。「に」は誤りで、正しくは「後者のほう」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
