INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36440, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分がどこにいるかという、その場所のこと。", "primary_collocate": null, "pronunciation": "たちば", "ipa": "tatɕiba", "syllable_count": 3, "sentences": [{"text": "この塔の上は、街全体を見渡せる立場にある。", "target_word": "立場", "complexity_tier": "T3", "furigana": "このとうのうえは、まちぜんたいをみわたせるたちばにある。", "sentence_source": "generated"}, {"text": "霧が深くて、自分の立場がつかめなかった。", "target_word": "立場", "complexity_tier": "T3", "furigana": "きりがふかくて、じぶんのたちばがつかめなかった。", "sentence_source": "generated"}, {"text": "舞台では、客席がよく見える立場に立って歌った。", "target_word": "立場", "complexity_tier": "T3", "furigana": "ぶたいでは、きゃくせきがよくみえるたちばにたってうたった。", "sentence_source": "generated"}, {"text": "高い丘は、遠くの町を見渡せる立場だ。", "target_word": "立場", "complexity_tier": "T3", "furigana": "たかいおかは、とおくのまちをみわたせるたちばだ。", "sentence_source": "generated"}, {"text": "船は揺れて、よい立場を保つのが難しかった。", "target_word": "立場", "complexity_tier": "T3", "furigana": "ふねはゆれて、よいたちばをたもつのがむずかしかった。", "sentence_source": "generated"}, {"text": "写真を撮るために、よく見える立場へ移った。", "target_word": "立場", "complexity_tier": "T3", "furigana": "しゃしんをとるために、よくみえるたちばへうつった。", "sentence_source": "generated"}, {"text": "船の上は揺れるので、立場を安定させるのが難しい。", "target_word": "立場", "complexity_tier": "T3", "furigana": "ふねのうえはゆれるので、たちばをあんていさせるのがむずかしい。", "sentence_source": "generated"}, {"text": "暗い森で、星を見て自分の立場を確かめた。", "target_word": "立場", "complexity_tier": "T3", "furigana": "くらいもりで、ほしをみてじぶんのたちばをたしかめた。", "sentence_source": "generated"}, {"text": "岩場の上は見晴らしのよい立場だが、風が強くて怖かった。", "target_word": "立場", "complexity_tier": "T3", "furigana": "いわばのうえはみはらしのよいたちばだが、かぜがつよくてこわかった。", "sentence_source": "generated"}, {"text": "彼は見晴らしのよい立場を選び、ボールをじっと待った。", "target_word": "立場", "complexity_tier": "T3", "furigana": "かれはみはらしのよいたちばをえらび、ボールをじっとまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "立場", "label": "基本形"}, {"form": "立場を", "label": "を格"}], "register": "neutral", "sense_fingerprint": "自分が立っている場所・位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36440, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立場", "is_correct": true, "explanation": "場所の位置を表す〈立場〉。見渡せる場所に〜にある、と続くので入る。"}, {"text": "責任", "is_correct": false, "explanation": "仕事や行為に伴う務め。見渡せる場所の話には結びつかないので、この空所には入らない。"}, {"text": "義務", "is_correct": false, "explanation": "しなければならないこと。街を見渡せる場所の説明とは意味が合わない。"}, {"text": "期限", "is_correct": false, "explanation": "物事の終わりの日時。場所を述べる文では意味が通らない。"}], "explanations": {"立場": "場所の位置を表す〈立場〉。見渡せる場所に〜にある、と続くので入る。", "責任": "仕事や行為に伴う務め。見渡せる場所の話には結びつかないので、この空所には入らない。", "義務": "しなければならないこと。街を見渡せる場所の説明とは意味が合わない。", "期限": "物事の終わりの日時。場所を述べる文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "立場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今の立場は午後三時です。", "explanation": "ここは〈時刻〉の意味。今何時かを言うのは〈時刻〉で、〈立場〉は時間を表さないので合わない。"}, {"text": "春の立場が来た。", "explanation": "ここは〈季節〉の意味。季節の移り変わりは〈季節〉で、〈立場〉は時期を表さないので合わない。"}, {"text": "彼は部下の立場に立って考えた。", "explanation": "ここは〈立場〉の抽象的な意味（相手の気持ちに立つ）で、場所を表すこの語義とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36440, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立場", "is_correct": true, "explanation": "船の上で保つ位置を表す〈立場〉。安定させる対象として文に合う。"}, {"text": "挨拶", "is_correct": false, "explanation": "人に会ったときの言葉や動作。船の揺れを安定させる対象にはならないので合わない。"}, {"text": "感想", "is_correct": false, "explanation": "物事を見て感じたこと。安定させるものではないので、ここには入らない。"}, {"text": "名簿", "is_correct": false, "explanation": "人の名前を並べた書類。揺れを安定させる対象にはならないので合わない。"}], "explanations": {"立場": "船の上で保つ位置を表す〈立場〉。安定させる対象として文に合う。", "挨拶": "人に会ったときの言葉や動作。船の揺れを安定させる対象にはならないので合わない。", "感想": "物事を見て感じたこと。安定させるものではないので、ここには入らない。", "名簿": "人の名前を並べた書類。揺れを安定させる対象にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "立場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "財布の立場は三千円だった。", "explanation": "ここは〈中身〉の意味。財布に入っている金額は〈中身〉で言い、〈立場〉は金額を表さないので合わない。"}, {"text": "朝、立場を量った。", "explanation": "ここは〈体重〉の意味。体の重さを量るのは〈体重〉で、〈立場〉は測定の対象にならないので合わない。"}, {"text": "立場を変えても、意見は変わらなかった。", "explanation": "ここは〈立場〉の抽象的な意味（考え方の立ち位置）で、場所を表すこの語義とは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36440, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この小屋の屋根の上は、谷全体を見渡せる立場へある。", "corrected_sentence": "この小屋の屋根の上は、谷全体を見渡せる立場にある。", "error_description": "〈立場〉の所在は〈に〉で示す（〜にある）。〈へ〉は移動の方向を表すので、存在の〈ある〉とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36440, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "波が高い日は、甲板で立場を保てのが大変だ。", "corrected_sentence": "波が高い日は、甲板で立場を保つのが大変だ。", "error_description": "〈保つ〉の辞書形の後に〈のが〉が続く形。〈保て〉は命令形なので、〈のが〉の前には入らない。正しくは〈保つのが〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36441, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈立場〉が〈なる〉の結果を示す〈に〉。部長という立場になったと自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。〈立場が なった〉では結果の意味が成り立たないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。〈なった〉の対象にはならないので、ここでは不自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す助詞。〈立場で なった〉では結果の意味にならないので合わない。"}], "correct_answer": "に", "explanations": {"に": "〈立場〉が〈なる〉の結果を示す〈に〉。部長という立場になったと自然に続く。", "が": "主語を示す助詞。〈立場が なった〉では結果の意味が成り立たないので合わない。", "を": "目的語を示す助詞。〈なった〉の対象にはならないので、ここでは不自然。", "で": "場所や手段を示す助詞。〈立場で なった〉では結果の意味にならないので合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36441, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈立場〉が〈わかる〉の目的語を示す〈を〉。相手の立場を理解したと自然に続く。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。〈わかって〉の対象にはならないので、ここでは不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す助詞。〈わかって〉の対象を表さないので、ここでは意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す助詞。〈立場より わかって〉では文の形が成り立たないので合わない。"}], "correct_answer": "を", "explanations": {"を": "〈立場〉が〈わかる〉の目的語を示す〈を〉。相手の立場を理解したと自然に続く。", "へ": "方向を示す助詞。〈わかって〉の対象にはならないので、ここでは不自然。", "と": "相手や並列を示す助詞。〈わかって〉の対象を表さないので、ここでは意味が通らない。", "より": "比較の基準を示す助詞。〈立場より わかって〉では文の形が成り立たないので合わない。"}, "error_tags": {"へ": "方向", "と": "相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36441, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある人が社会の中で占める位置や、物事を考えるときの基盤となる見方。", "primary_collocate": null, "pronunciation": "たちば", "ipa": "tatɕiba", "syllable_count": 3, "sentences": [{"text": "私は先生の立場で、生徒の気持ちを考えた。", "target_word": "立場", "complexity_tier": "T3", "furigana": "私[わたし]は先生[せんせい]の立場[たちば]で、生徒[せいと]の気持[きも]ちを考[かんが]えた。", "sentence_source": "generated"}, {"text": "新しい会社では、部長という立場になった。", "target_word": "立場", "complexity_tier": "T3", "furigana": "新[あたら]しい会社[かいしゃ]では、部長[ぶちょう]という立場[たちば]になった。", "sentence_source": "generated"}, {"text": "相手の立場に立って、もう一度考えてみてください。", "target_word": "立場", "complexity_tier": "T3", "furigana": "相手[あいて]の立場[たちば]に立[た]って、もう一度[いちど]考[かんが]えてみてください。", "sentence_source": "generated"}, {"text": "彼は母親の立場から、この問題について意見を言った。", "target_word": "立場", "complexity_tier": "T3", "furigana": "彼[かれ]は母親[ははおや]の立場[たちば]から、この問題[もんだい]について意見[いけん]を言[い]った。", "sentence_source": "generated"}, {"text": "弱い立場の人を助けることは大切だ。", "target_word": "立場", "complexity_tier": "T3", "furigana": "弱[よわ]い立場[たちば]の人[ひと]を助[たす]けることは大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "上司の立場では、簡単に仕事を休めない。", "target_word": "立場", "complexity_tier": "T3", "furigana": "上司[じょうし]の立場[たちば]では、簡単[かんたん]に仕事[しごと]を休[やす]めない。", "sentence_source": "generated"}, {"text": "二人は立場がちがうので、意見が合わなかった。", "target_word": "立場", "complexity_tier": "T3", "furigana": "二人[ふたり]は立場[たちば]がちがうので、意見[いけん]が合[あ]わなかった。", "sentence_source": "generated"}, {"text": "私の立場をわかってくれて、ありがとう。", "target_word": "立場", "complexity_tier": "T3", "furigana": "私[わたし]の立場[たちば]をわかってくれて、ありがとう。", "sentence_source": "generated"}, {"text": "店長という立場で、客に頭を下げなければならない。", "target_word": "立場", "complexity_tier": "T3", "furigana": "店長[てんちょう]という立場[たちば]で、客[きゃく]に頭[あたま]を下[さ]げなければならない。", "sentence_source": "generated"}, {"text": "彼女は中立の立場を守り、どちらの味方もしなかった。", "target_word": "立場", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は中立[ちゅうりつ]の立場[たちば]を守[まも]り、どちらの味方[みかた]もしなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "立場", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "社会的な地位・物事を見る立ち位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36441, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立場", "is_correct": true, "explanation": "先生という社会的な位置から考えるという意味の〈立場〉。ここに入ると自然に続く。"}, {"text": "年齢", "is_correct": false, "explanation": "生まれてからの年数。先生という立場から考える文の空所には、意味が通らない。"}, {"text": "給料", "is_correct": false, "explanation": "働いて受け取る金銭。生徒の気持ちを考える文脈とは結びつかないので合わない。"}, {"text": "体格", "is_correct": false, "explanation": "体の大きさや作り。考える視点を示す語としては文に合わない。"}], "explanations": {"立場": "先生という社会的な位置から考えるという意味の〈立場〉。ここに入ると自然に続く。", "年齢": "生まれてからの年数。先生という立場から考える文の空所には、意味が通らない。", "給料": "働いて受け取る金銭。生徒の気持ちを考える文脈とは結びつかないので合わない。", "体格": "体の大きさや作り。考える視点を示す語としては文に合わない。"}, "sentence_index": 0, "correct_answer": "立場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の立場は三十度です。", "explanation": "ここは〈気温〉の意味。今の気温は〈気温〉で言い、〈立場〉は温度を表さないので合わない。"}, {"text": "市場の立場に店を構えた。", "explanation": "ここは〈売り場〉の意味（古い用法）。社会的な位置の義項とは違うので誤り。"}, {"text": "立場証明書を見せてください。", "explanation": "ここは〈身分〉の意味。身分証明書の〈身分〉と取り違えやすいが、〈立場〉を証明書の名前に使うことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36441, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立場", "is_correct": true, "explanation": "二人の考え方の基盤になる〈立場〉。立場がちがうので意見が合わない、と自然につながる。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に貼る小さな紙。立場の違いと意見の不一致を結びつけられないので合わない。"}, {"text": "電卓", "is_correct": false, "explanation": "計算に使う機械。二人の考え方の違いを表す語にはならないので入らない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部。二人の意見が合わない理由としては成り立たないので合わない。"}], "explanations": {"立場": "二人の考え方の基盤になる〈立場〉。立場がちがうので意見が合わない、と自然につながる。", "切手": "郵便に貼る小さな紙。立場の違いと意見の不一致を結びつけられないので合わない。", "電卓": "計算に使う機械。二人の考え方の違いを表す語にはならないので入らない。", "窓": "建物の開口部。二人の意見が合わない理由としては成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "立場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この棚は窓の近くの立場に置いてある。", "explanation": "ここは〈位置〉の意味。物を置く場所は〈位置〉で表し、社会的な立場の語義では〈立場〉を物の場所には使わない。"}, {"text": "今日は立場が晴れない。", "explanation": "ここは〈気分〉の意味。心の状態が晴れないことを表すのは〈気分〉で、〈立場〉は気持ちの状態を表さない。"}, {"text": "明日の立場は晴れだ。", "explanation": "ここは〈天気〉の意味。空模様を言うときは〈天気〉を使い、〈立場〉は天気の話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36441, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は親の立場を、子どもの進路を考えた。", "corrected_sentence": "私は親の立場で、子どもの進路を考えた。", "error_description": "〈親の立場で〉は〈立場から見て〉の〈で〉が正しい。〈を〉は目的語を示すので、ここでは〈立場〉を考える対象として置けない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36441, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あなたの立場を感じると、責めることはできない。", "corrected_sentence": "あなたの立場を考えると、責めることはできない。", "error_description": "〈立場〉は〈考える〉で扱う語。〈感じる〉は〈立場〉の目的語として自然に続かないので、〈考える〉に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
