INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36442, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "やりすぎること。", "primary_collocate": null, "pronunciation": "かど", "ipa": "kado", "syllable_count": 2, "sentences": [{"text": "過度な運動は、かえって体をこわす原因になる。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]な運動[うんどう]は、かえって体[からだ]をこわす原因[げんいん]になる。", "sentence_source": "generated"}, {"text": "彼は過度の節約で、必要な食事まで減らしてしまった。", "target_word": "過度", "complexity_tier": "T3", "furigana": "彼[かれ]は過度[かど]の節約[せつやく]で、必要[ひつよう]な食事[しょくじ]まで減[へ]らしてしまった。", "sentence_source": "generated"}, {"text": "過度に練習したせいで、ひざを痛めた。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]に練習[れんしゅう]したせいで、ひざを痛[いた]めた。", "sentence_source": "generated"}, {"text": "過度なダイエットをして、倒れてしまった。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]なダイエットをして、倒[たお]れてしまった。", "sentence_source": "generated"}, {"text": "親の過度の心配は、子どもの自信をうばうことがある。", "target_word": "過度", "complexity_tier": "T3", "furigana": "親[おや]の過度[かど]の心配[しんぱい]は、子[こ]どもの自信[じしん]をうばうことがある。", "sentence_source": "generated"}, {"text": "薬を過度に飲むと、体に悪い。", "target_word": "過度", "complexity_tier": "T3", "furigana": "薬[くすり]を過度[かど]に飲[の]むと、体[からだ]に悪[わる]い。", "sentence_source": "generated"}, {"text": "過度な勉強で、テスト前に熱を出した。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]な勉強[べんきょう]で、テスト前[まえ]に熱[ねつ]を出[だ]した。", "sentence_source": "generated"}, {"text": "彼女は過度に気をつかうので、いつも疲れている。", "target_word": "過度", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は過度[かど]に気[き]をつかうので、いつも疲[つか]れている。", "sentence_source": "generated"}, {"text": "過度の掃除は、かえって家具をいためる。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]の掃除[そうじ]は、かえって家具[かぐ]をいためる。", "sentence_source": "generated"}, {"text": "過度に水を与えたため、植物がかれた。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]に水[みず]を与[あた]えたため、植物[しょくぶつ]がかれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "過度", "label": "基本形"}, {"form": "過度だ", "label": "終止形"}, {"form": "過度な", "label": "連体形"}, {"form": "過度の", "label": "の形"}, {"form": "過度に", "label": "連用形"}], "register": "標準", "sense_fingerprint": "運動・節約・心配などの行いが必要以上になること(やりすぎ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: うばう (Zipf 1.43)','sentence 8 above tier T3: contains vocabulary far above tier T3: いためる (Zipf 1.52)']::text[], 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36442, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "過度", "is_correct": true, "explanation": "「過度な運動」で、やりすぎの運動を表し、体をこわす原因という文に合う。"}, {"text": "寒冷", "is_correct": false, "explanation": "「寒冷」は寒さが厳しいこと。運動の行いの程度には合わない。"}, {"text": "透明", "is_correct": false, "explanation": "「透明」はすき通っていること。運動の行いを修飾できない。"}, {"text": "静粛", "is_correct": false, "explanation": "「静粛」は静かで騒がしくないこと。運動の程度を表す文では意味が通らない。"}], "explanations": {"過度": "「過度な運動」で、やりすぎの運動を表し、体をこわす原因という文に合う。", "寒冷": "「寒冷」は寒さが厳しいこと。運動の行いの程度には合わない。", "透明": "「透明」はすき通っていること。運動の行いを修飾できない。", "静粛": "「静粛」は静かで騒がしくないこと。運動の程度を表す文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "過度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "過度を曲がって、店が見えた。", "explanation": "〈かど（角）〉の意味。程度が普通を超える意味の過度とは別の語。"}, {"text": "過度の時期を経て、新しい段階に入った。", "explanation": "〈移り変わり（過渡）〉の意味。やりすぎの意味ではない。"}, {"text": "過度に少なく食べたので、元気が出た。", "explanation": "程度が普通を超える意味と逆。少ない量には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36442, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "過度", "is_correct": true, "explanation": "「過度な勉強」で、やりすぎの勉強が熱を出した原因になるという文に合う。"}, {"text": "軽快", "is_correct": false, "explanation": "「軽快」は身が軽く動きがよいこと。勉強を修飾すると不自然。"}, {"text": "公平", "is_correct": false, "explanation": "「公平」は偏りがないこと。勉強の程度を表す文には合わない。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔」はよごれがないこと。勉強を修飾する文では意味が通らない。"}], "explanations": {"過度": "「過度な勉強」で、やりすぎの勉強が熱を出した原因になるという文に合う。", "軽快": "「軽快」は身が軽く動きがよいこと。勉強を修飾すると不自然。", "公平": "「公平」は偏りがないこと。勉強の程度を表す文には合わない。", "清潔": "「清潔」はよごれがないこと。勉強を修飾する文では意味が通らない。"}, "sentence_index": 6, "correct_answer": "過度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "過度の角を曲がると、駅がある。", "explanation": "〈かど（角）〉の意味。程度が普通を超える意味の過度とは別の語。"}, {"text": "過度の期間を経て、体は回復に向かった。", "explanation": "〈移り変わり（過渡）〉の意味。やりすぎの意味ではない。"}, {"text": "過度に少ない水で、植物はよく育った。", "explanation": "程度が普通を超える意味と逆。少ない量には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36442, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "過度に練習は、かえって体をこわす原因になる。", "corrected_sentence": "過度な練習は、かえって体をこわす原因になる。", "error_description": "「過度に」は動詞などを修飾する連用形。名詞「練習」の前には連体形の「過度な」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "過度", "is_correct": true, "explanation": "基本形の語幹。文中では「の」が続く形で、語幹の過度がこの位置に当たる。"}, {"text": "過度な", "is_correct": false, "explanation": "名詞の前に来る形だが、この文では「の」が続くので合わない。"}, {"text": "過度に", "is_correct": false, "explanation": "動詞などを修飾する連用形。「の節約」の前には使えない。"}, {"text": "過度だ", "is_correct": false, "explanation": "文末の形。名詞の前に置いて「の節約」とは続かない。"}], "correct_form": "過度", "base_form": "過度", "form_label": "基本形", "sentence_index": 1, "explanations": {"過度": "基本形の語幹。文中では「の」が続く形で、語幹の過度がこの位置に当たる。", "過度な": "名詞の前に来る形だが、この文では「の」が続くので合わない。", "過度に": "動詞などを修飾する連用形。「の節約」の前には使えない。", "過度だ": "文末の形。名詞の前に置いて「の節約」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36442, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "過度だ勉強は、体によくない。", "corrected_sentence": "過度な勉強は、体によくない。", "error_description": "「過度だ」は文末の形。名詞「勉強」の前では「過度な」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "過度", "is_correct": true, "explanation": "基本形の過度。文中の「過度に」の語幹にあたる形。"}, {"text": "過度の", "is_correct": false, "explanation": "「の」が続く形。「過度に気をつかう」の位置には合わない。"}, {"text": "過度で", "is_correct": false, "explanation": "「だ」のて形。「気をつかう」を直接修飾できず、ここでは文の形が合わない。"}, {"text": "過度だった", "is_correct": false, "explanation": "過去を表す断定の形。「気をつかう」を修飾できず、ここでは文が続かない。"}], "correct_form": "過度", "base_form": "過度", "form_label": "基本形", "sentence_index": 7, "explanations": {"過度": "基本形の過度。文中の「過度に」の語幹にあたる形。", "過度の": "「の」が続く形。「過度に気をつかう」の位置には合わない。", "過度で": "「だ」のて形。「気をつかう」を直接修飾できず、ここでは文の形が合わない。", "過度だった": "過去を表す断定の形。「気をつかう」を修飾できず、ここでは文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
