INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36443, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "程度が普通を超えていること。また、行き過ぎであること。", "primary_collocate": null, "pronunciation": "かど", "ipa": "kado", "syllable_count": 2, "sentences": [{"text": "過度な期待をされて、かえって緊張した。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]な期待[きたい]をされて、かえって緊張[きんちょう]した。", "sentence_source": "generated"}, {"text": "過度な暖房のせいで、部屋は汗が出るほど暑い。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]な暖房[だんぼう]のせいで、部屋[へや]は汗[あせ]が出[で]るほど暑[あつ]い。", "sentence_source": "generated"}, {"text": "過度の飾りは、見た目をうるさくしてしまう。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]の飾[かざ]りは、見[み]た目[め]をうるさくしてしまう。", "sentence_source": "generated"}, {"text": "過度な広告は、客にいやな印象をあたえる。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]な広告[こうこく]は、客[きゃく]にいやな印象[いんしょう]をあたえる。", "sentence_source": "generated"}, {"text": "過度の緊張で、声が出なくなった。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]の緊張[きんちょう]で、声[こえ]が出[で]なくなった。", "sentence_source": "generated"}, {"text": "彼の過度な自信は、周りの人を不安にさせた。", "target_word": "過度", "complexity_tier": "T3", "furigana": "彼[かれ]の過度[かど]な自信[じしん]は、周[まわ]りの人[ひと]を不安[ふあん]にさせた。", "sentence_source": "generated"}, {"text": "料理に過度な味つけをすると、素材の味が消える。", "target_word": "過度", "complexity_tier": "T3", "furigana": "料理[りょうり]に過度[かど]な味[あじ]つけをすると、素材[そざい]の味[あじ]が消[き]える。", "sentence_source": "generated"}, {"text": "過度の飲酒は、健康だけでなく仕事にも悪い。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]の飲酒[いんしゅ]は、健康[けんこう]だけでなく仕事[しごと]にも悪[わる]い。", "sentence_source": "generated"}, {"text": "過度に明るい照明は、目が疲れる。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]に明[あか]るい照明[しょうめい]は、目[め]が疲[つか]れる。", "sentence_source": "generated"}, {"text": "過度な安全対策は、費用がかかりすぎる。", "target_word": "過度", "complexity_tier": "T3", "furigana": "過度[かど]な安全[あんぜん]対策[たいさく]は、費用[ひよう]がかかりすぎる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "過度", "label": "基本形"}, {"form": "過度だ", "label": "終止形"}, {"form": "過度な", "label": "連体形"}, {"form": "過度の", "label": "の形"}, {"form": "過度に", "label": "連用形"}], "register": "標準", "sense_fingerprint": "期待・緊張・飾りなどの程度が普通の範囲を超えている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36443, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "過度", "is_correct": true, "explanation": "「過度な期待」で、期待の程度が普通を超えているという意味に合う。"}, {"text": "無色", "is_correct": false, "explanation": "「無色」は色がないこと。期待の程度を表す文では意味が通らない。"}, {"text": "手狭", "is_correct": false, "explanation": "「手狭」は場所が狭いこと。期待を修飾すると不自然。"}, {"text": "高温", "is_correct": false, "explanation": "「高温」は温度が高いこと。期待の程度を表せない。"}], "explanations": {"過度": "「過度な期待」で、期待の程度が普通を超えているという意味に合う。", "無色": "「無色」は色がないこと。期待の程度を表す文では意味が通らない。", "手狭": "「手狭」は場所が狭いこと。期待を修飾すると不自然。", "高温": "「高温」は温度が高いこと。期待の程度を表せない。"}, "sentence_index": 0, "correct_answer": "過度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "過度を曲がって、公園が見えた。", "explanation": "〈かど（角）〉の意味。程度が普通を超える意味の過度とは別の語。"}, {"text": "過度の時期を経て、会社は新しい体制になった。", "explanation": "〈移り変わり（過渡）〉の意味。やりすぎの意味ではない。"}, {"text": "過度に少なく話したので、みんな安心した。", "explanation": "程度が普通を超える意味と逆。少ない量には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36443, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "過度", "is_correct": true, "explanation": "「過度な味つけ」で、味が強すぎて素材の味が消えるという文に合う。"}, {"text": "静粛", "is_correct": false, "explanation": "「静粛」は静かなこと。味つけを修飾すると意味が通らない。"}, {"text": "寒冷", "is_correct": false, "explanation": "「寒冷」は寒さが厳しいこと。味つけには合わない。"}, {"text": "透明", "is_correct": false, "explanation": "「透明」はすき通っていること。味つけを修飾する文では不自然。"}], "explanations": {"過度": "「過度な味つけ」で、味が強すぎて素材の味が消えるという文に合う。", "静粛": "「静粛」は静かなこと。味つけを修飾すると意味が通らない。", "寒冷": "「寒冷」は寒さが厳しいこと。味つけには合わない。", "透明": "「透明」はすき通っていること。味つけを修飾する文では不自然。"}, "sentence_index": 6, "correct_answer": "過度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "過度の角で、車が止まった。", "explanation": "〈かど（角）〉の意味。程度が普通を超える意味の過度とは別の語。"}, {"text": "過度の期間を経て、町は落ち着いた。", "explanation": "〈移り変わり（過渡）〉の意味。やりすぎの意味ではない。"}, {"text": "過度に少ない電気で、部屋は明るかった。", "explanation": "程度が普通を超える意味と逆。少ない量には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36443, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "過度だ期待をかけられて、かえって緊張した。", "corrected_sentence": "過度な期待をかけられて、かえって緊張した。", "error_description": "「過度だ」は文末の形。名詞「期待」の前では「過度な」にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "過度", "is_correct": true, "explanation": "基本形の語幹。文中では「な」が続いている形で、語幹の過度を指す。"}, {"text": "過度に", "is_correct": false, "explanation": "動詞などを修飾する連用形。「暖房」の前には使えない。"}, {"text": "過度だ", "is_correct": false, "explanation": "文末の形。名詞の前に直接置くことはできない。"}, {"text": "過度の", "is_correct": false, "explanation": "「の」を伴う形。「暖房」を修飾する文脈ではここでは使わない。"}], "correct_form": "過度", "base_form": "過度", "form_label": "基本形", "sentence_index": 1, "explanations": {"過度": "基本形の語幹。文中では「な」が続いている形で、語幹の過度を指す。", "過度に": "動詞などを修飾する連用形。「暖房」の前には使えない。", "過度だ": "文末の形。名詞の前に直接置くことはできない。", "過度の": "「の」を伴う形。「暖房」を修飾する文脈ではここでは使わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36443, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "過度を暖房は、部屋を乾かす。", "corrected_sentence": "過度な暖房は、部屋を乾かす。", "error_description": "「過度」は形状詞なので「を」は付かない。名詞「暖房」を修飾するには「過度な」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "過度", "is_correct": true, "explanation": "基本形の過度。文中の「過度の」の語幹にあたる形。"}, {"text": "過度な", "is_correct": false, "explanation": "連体形。ここでは「の飲酒」の位置に当たる「の」の形と合わない。"}, {"text": "過度で", "is_correct": false, "explanation": "「だ」のて形。名詞「飲酒」を修飾できず、「の」の位置に入らない。"}, {"text": "過度だった", "is_correct": false, "explanation": "過去を表す断定の形。名詞「飲酒」を修飾できず、文の主語の位置に合わない。"}], "correct_form": "過度", "base_form": "過度", "form_label": "基本形", "sentence_index": 7, "explanations": {"過度": "基本形の過度。文中の「過度の」の語幹にあたる形。", "過度な": "連体形。ここでは「の飲酒」の位置に当たる「の」の形と合わない。", "過度で": "「だ」のて形。名詞「飲酒」を修飾できず、「の」の位置に入らない。", "過度だった": "過去を表す断定の形。名詞「飲酒」を修飾できず、文の主語の位置に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
