INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36444, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「～してください」という意味で、何かをしてほしいと伝えること。", "primary_collocate": null, "pronunciation": "ようきゅう", "ipa": "joːkʲɯː", "syllable_count": 4, "sentences": [{"text": "お客さんの要求どおり、料理を少し辛くした。", "target_word": "要求", "complexity_tier": "T3", "furigana": "お客[きゃく]さんの要求[ようきゅう]どおり、料理[りょうり]を少[すこ]し辛[から]くした。", "sentence_source": "generated"}, {"text": "先生は生徒に、静かにするよう要求した。", "target_word": "要求", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]に、静[しず]かにするよう要求[ようきゅう]した。", "sentence_source": "generated"}, {"text": "彼は店員に、もう一度説明するよう要求した。", "target_word": "要求", "complexity_tier": "T3", "furigana": "彼[かれ]は店員[てんいん]に、もう一度[いちど]説明[せつめい]するよう要求[ようきゅう]した。", "sentence_source": "generated"}, {"text": "隣の人に、音を小さくしてほしいと要求した。", "target_word": "要求", "complexity_tier": "T3", "furigana": "隣[となり]の人[ひと]に、音[おと]を小[ちい]さくしてほしいと要求[ようきゅう]した。", "sentence_source": "generated"}, {"text": "要求がよくわからなかったので、もう一度聞いた。", "target_word": "要求", "complexity_tier": "T3", "furigana": "要求[ようきゅう]がよくわからなかったので、もう一度[いちど]聞[き]いた。", "sentence_source": "generated"}, {"text": "会議で、資料を早めに送るようにという要求があった。", "target_word": "要求", "complexity_tier": "T3", "furigana": "会議[かいぎ]で、資料[しりょう]を早[はや]めに送[おく]るようにという要求[ようきゅう]があった。", "sentence_source": "generated"}, {"text": "客からの要求に、店員はすぐ対応した。", "target_word": "要求", "complexity_tier": "T3", "furigana": "客[きゃく]からの要求[ようきゅう]に、店員[てんいん]はすぐ対応[たいおう]した。", "sentence_source": "generated"}, {"text": "部長は私たちに、報告書の提出を要求した。", "target_word": "要求", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は私[わたし]たちに、報告書[ほうこくしょ]の提出[ていしゅつ]を要求[ようきゅう]した。", "sentence_source": "generated"}, {"text": "赤ちゃんは言葉の代わりに、泣いてミルクを要求する。", "target_word": "要求", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは言葉[ことば]の代[か]わりに、泣[な]いてミルクを要求[ようきゅう]する。", "sentence_source": "generated"}, {"text": "彼女の要求は、窓を開けてほしいということだった。", "target_word": "要求", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の要求[ようきゅう]は、窓[まど]を開[あ]けてほしいということだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "要求", "label": "基本形"}, {"form": "要求する", "label": "終止形"}, {"form": "要求した", "label": "過去形"}, {"form": "要求している", "label": "継続形"}, {"form": "要求しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "相手に「〜してほしい」と頼んで伝えること(日常の依頼寄り)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36444, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要求", "is_correct": true, "explanation": "「お客さんの要求どおり」は客が頼んだ内容に従うという意味で、辛くした理由として自然に通る。"}, {"text": "年齢", "is_correct": false, "explanation": "「お客さんの年齢どおり」では意味が通らず、料理を辛くする理由にならない。"}, {"text": "財布", "is_correct": false, "explanation": "「お客さんの財布どおり」とは言わず、味付けの話とつながらない。"}, {"text": "天気", "is_correct": false, "explanation": "「お客さんの天気どおり」は成り立たず、客の頼みに従う文脈に合わない。"}], "explanations": {"要求": "「お客さんの要求どおり」は客が頼んだ内容に従うという意味で、辛くした理由として自然に通る。", "年齢": "「お客さんの年齢どおり」では意味が通らず、料理を辛くする理由にならない。", "財布": "「お客さんの財布どおり」とは言わず、味付けの話とつながらない。", "天気": "「お客さんの天気どおり」は成り立たず、客の頼みに従う文脈に合わない。"}, "sentence_index": 0, "correct_answer": "要求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は弟に、部屋の掃除を義務として要求した。", "explanation": "ここは〈強く求める〉の意味。当然の義務として迫る場面で、穏やかな依頼とは違う。"}, {"text": "私は皆に、週末に映画を見に行こうと要求した。", "explanation": "ここは〈提案〉の意味。要求は相手に強く求める言葉なので、軽く勧める提案の場面には合わない。"}, {"text": "祖母に、ありがとうと要求した。", "explanation": "ここは〈感謝する〉の意味。感謝は相手に強いて言わせるものではなく、要求とは組み合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36444, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要求", "is_correct": true, "explanation": "「客からの要求に」は客が求めた内容への対応を表し、店員が対応した文脈に合う。"}, {"text": "地図", "is_correct": false, "explanation": "「客からの地図に」は成り立たず、対応の対象にならない。"}, {"text": "季節", "is_correct": false, "explanation": "「客からの季節に」は意味が通らず、対応の文脈に合わない。"}, {"text": "写真", "is_correct": false, "explanation": "「客からの写真に」は文脈に合わず、店員の対応とつながらない。"}], "explanations": {"要求": "「客からの要求に」は客が求めた内容への対応を表し、店員が対応した文脈に合う。", "地図": "「客からの地図に」は成り立たず、対応の対象にならない。", "季節": "「客からの季節に」は意味が通らず、対応の文脈に合わない。", "写真": "「客からの写真に」は文脈に合わず、店員の対応とつながらない。"}, "sentence_index": 6, "correct_answer": "要求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は上司に、転職の件を要求した。", "explanation": "ここは〈相談〉の意味。要求は強く求めることなので、意見を聞いてもらう相談の場面には合わない。"}, {"text": "私はその大会に、出場を要求した。", "explanation": "ここは〈申し込む〉の意味。参加を申し出る行為に要求を使うと、無理に押しつける印象になり不自然。"}, {"text": "友人を食事に要求した。", "explanation": "ここは〈誘う〉の意味。食事に招く場面では誘うを使い、要求は相手に強く求める語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36444, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客の要求を、もう一度席を変えることだった。", "corrected_sentence": "客の要求は、もう一度席を変えることだった。", "error_description": "「要求は」が正しい。「要求を」にすると要求を目的語とする形になり、「〜ことだった」と続く主題の文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36444, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は客の要求を守るために、部品を変えた。", "corrected_sentence": "会社は客の要求を満たすために、部品を変えた。", "error_description": "要求には「満たす」を組み合わせる。「守る」は約束や決まりに使う動詞なので、要求とは組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
