INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36445, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある事柄を実現するように、相手に強く求めること。また、その内容。", "primary_collocate": null, "pronunciation": "ようきゅう", "ipa": "joːkʲɯː", "syllable_count": 4, "sentences": [{"text": "労働者たちは、賃金を上げるよう会社に要求した。", "target_word": "要求", "complexity_tier": "T3", "furigana": "労働者[ろうどうしゃ]たちは、賃金[ちんぎん]を上[あ]げるよう会社[かいしゃ]に要求[ようきゅう]した。", "sentence_source": "generated"}, {"text": "国民は政府に、説明を強く要求した。", "target_word": "要求", "complexity_tier": "T3", "furigana": "国民[こくみん]は政府[せいふ]に、説明[せつめい]を強[つよ]く要求[ようきゅう]した。", "sentence_source": "generated"}, {"text": "相手の要求が厳しすぎて、交渉は進まなかった。", "target_word": "要求", "complexity_tier": "T3", "furigana": "相手[あいて]の要求[ようきゅう]が厳[きび]しすぎて、交渉[こうしょう]は進[すす]まなかった。", "sentence_source": "generated"}, {"text": "犯人は、お金を渡すよう人質の家族に要求した。", "target_word": "要求", "complexity_tier": "T3", "furigana": "犯人[はんにん]は、お金[かね]を渡[わた]すよう人質[ひとじち]の家族[かぞく]に要求[ようきゅう]した。", "sentence_source": "generated"}, {"text": "彼は謝罪を要求したが、相手は応じなかった。", "target_word": "要求", "complexity_tier": "T3", "furigana": "彼[かれ]は謝罪[しゃざい]を要求[ようきゅう]したが、相手[あいて]は応[おう]じなかった。", "sentence_source": "generated"}, {"text": "会社は新しい要求を受け入れず、話し合いは止まった。", "target_word": "要求", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい要求[ようきゅう]を受[う]け入[い]れず、話[はな]し合[あ]いは止[と]まった。", "sentence_source": "generated"}, {"text": "客は理由もなく、返金を要求してきた。", "target_word": "要求", "complexity_tier": "T3", "furigana": "客[きゃく]は理由[りゆう]もなく、返金[へんきん]を要求[ようきゅう]してきた。", "sentence_source": "generated"}, {"text": "住民たちの要求は、道路の安全を守ることだった。", "target_word": "要求", "complexity_tier": "T3", "furigana": "住民[じゅうみん]たちの要求[ようきゅう]は、道路[どうろ]の安全[あんぜん]を守[まも]ることだった。", "sentence_source": "generated"}, {"text": "組合は休みを増やすことを要求している。", "target_word": "要求", "complexity_tier": "T3", "furigana": "組合[くみあい]は休[やす]みを増[ふ]やすことを要求[ようきゅう]している。", "sentence_source": "generated"}, {"text": "無理な要求を断るのも、大切な仕事だ。", "target_word": "要求", "complexity_tier": "T3", "furigana": "無理[むり]な要求[ようきゅう]を断[ことわ]るのも、大切[たいせつ]な仕事[しごと]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "要求", "label": "基本形"}, {"form": "要求する", "label": "終止形"}, {"form": "要求した", "label": "過去形"}, {"form": "要求している", "label": "継続形"}, {"form": "要求しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "賃上げ・謝罪などの実現を相手に強く求めること、またその求める内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36445, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要求", "is_correct": true, "explanation": "「賃金を上げるよう会社に要求した」の形で、賃上げを強く求める意味に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「会社に散歩した」は成り立たず、賃金の話とつながらない。"}, {"text": "作曲", "is_correct": false, "explanation": "「会社に作曲した」は意味が通らず、文の動作として成り立たない。"}, {"text": "睡眠", "is_correct": false, "explanation": "「会社に睡眠した」とは言わず、賃上げを求める文脈に合わない。"}], "explanations": {"要求": "「賃金を上げるよう会社に要求した」の形で、賃上げを強く求める意味に合う。", "散歩": "「会社に散歩した」は成り立たず、賃金の話とつながらない。", "作曲": "「会社に作曲した」は意味が通らず、文の動作として成り立たない。", "睡眠": "「会社に睡眠した」とは言わず、賃上げを求める文脈に合わない。"}, "sentence_index": 0, "correct_answer": "要求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "業者に、庭の草むしりを要求した。", "explanation": "ここは〈依頼〉の意味。仕事を頼む場面では依頼を使い、要求は相手に強く求める語なので合わない。"}, {"text": "友人に、週末に温泉へ行こうと要求した。", "explanation": "ここは〈提案〉の意味。要求は強く求める言葉なので、軽く誘う提案の場面には合わない。"}, {"text": "妹に、進路の件を要求した。", "explanation": "ここは〈相談〉の意味。要求は一方的に求めることなので、話し合いたい相談の場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36445, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要求", "is_correct": true, "explanation": "「返金を要求してきた」は客が返金を強く求めた意味で、文に合う。"}, {"text": "失敗", "is_correct": false, "explanation": "「返金を失敗してきた」は成り立たず、客の行動として意味が通らない。"}, {"text": "製作", "is_correct": false, "explanation": "「返金を製作」は言えず、客の行動として意味が通らない。"}, {"text": "通訳", "is_correct": false, "explanation": "「返金を通訳してきた」は意味が通らず、客の行動に合わない。"}], "explanations": {"要求": "「返金を要求してきた」は客が返金を強く求めた意味で、文に合う。", "失敗": "「返金を失敗してきた」は成り立たず、客の行動として意味が通らない。", "製作": "「返金を製作」は言えず、客の行動として意味が通らない。", "通訳": "「返金を通訳してきた」は意味が通らず、客の行動に合わない。"}, "sentence_index": 6, "correct_answer": "要求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は友人に、お礼を要求した。", "explanation": "ここは〈お礼を言う〉の意味。お礼は自分から言う言葉で、相手に求めるものではないので要求とは合わない。"}, {"text": "先生に、お辞儀を要求した。", "explanation": "ここは〈お辞儀をする〉の意味。お辞儀は自分から示す動作で、相手に強く求めるものではないので要求とは言わない。"}, {"text": "友人に、道案内を要求した。", "explanation": "ここは〈道を尋ねる〉の意味。道を教えてもらう場面は尋ねるで、強く求める要求とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36445, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "組合の要求に、残業代の支払いだった。", "corrected_sentence": "組合の要求は、残業代の支払いだった。", "error_description": "主題を示す「は」が正しい。「要求に」は相手を示す格助詞で、「〜だった」と続く文の主題の形に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36445, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は労組の要求を食べた。", "corrected_sentence": "会社は労組の要求を飲んだ。", "error_description": "要求は「飲む」（受け入れる）と組み合わせる。「食べる」は食べ物に使う動詞なので、要求とは組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36446, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "押し込む対象（服）を示す格助詞。「服を押し込む」で、入れるものを表す。"}, {"text": "が", "is_correct": false, "explanation": "「服が無理に押し込むと」では服が動作の主体になり、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「服で無理に」は手段の意味になり、押し込む対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「服の無理に」と続くと名詞が途切れ、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "押し込む対象（服）を示す格助詞。「服を押し込む」で、入れるものを表す。", "が": "「服が無理に押し込むと」では服が動作の主体になり、意味が通らない。", "で": "「服で無理に」は手段の意味になり、押し込む対象を示せない。", "の": "「服の無理に」と続くと名詞が途切れ、文が成り立たない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36446, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "押し込む対象（タオル）を示す格助詞。「タオルを押し込んで」で、入れるものを表す。"}, {"text": "と", "is_correct": false, "explanation": "「タオルと押し込んで」は共同の意味になり、押し込む対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「タオルから押し込んで」は起点の意味になり、押し込む対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「タオルより押し込んで」は比較の意味になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "押し込む対象（タオル）を示す格助詞。「タオルを押し込んで」で、入れるものを表す。", "と": "「タオルと押し込んで」は共同の意味になり、押し込む対象を示せない。", "から": "「タオルから押し込んで」は起点の意味になり、押し込む対象にならない。", "より": "「タオルより押し込んで」は比較の意味になり、文が成り立たない。"}, "error_tags": {"と": "共同・並列", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36446, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを中に強く入れること。", "primary_collocate": null, "pronunciation": "おしこむ", "ipa": "oɕikomɯ", "syllable_count": 4, "sentences": [{"text": "急いで荷物をかばんに押し込んだ。", "target_word": "押し込んだ", "complexity_tier": "T3", "furigana": "急[いそ]いで荷物[にもつ]をかばんに押[お]し込[こ]んだ。", "sentence_source": "generated"}, {"text": "引き出しがいっぱいなのに服を無理に押し込むと、しわになる。", "target_word": "押し込む", "complexity_tier": "T3", "furigana": "引[ひ]き出[だ]しがいっぱいなのに服[ふく]を無理[むり]に押[お]し込[こ]むと、しわになる。", "sentence_source": "generated"}, {"text": "弟は宿題のプリントをポケットに押し込んで、遊びに出かけた。", "target_word": "押し込んで", "complexity_tier": "T3", "furigana": "弟[おとうと]は宿題[しゅくだい]のプリントをポケットに押[お]し込[こ]んで、遊[あそ]びに出[で]かけた。", "sentence_source": "generated"}, {"text": "箱が小さすぎて、すべてのおもちゃを押し込むことができなかった。", "target_word": "押し込む", "complexity_tier": "T3", "furigana": "箱[はこ]が小[ちい]さすぎて、すべてのおもちゃを押[お]し込[こ]むことができなかった。", "sentence_source": "generated"}, {"text": "母は冷蔵庫に野菜を押し込んで、ドアを閉めた。", "target_word": "押し込んで", "complexity_tier": "T3", "furigana": "母[はは]は冷蔵庫[れいぞうこ]に野菜[やさい]を押[お]し込[こ]んで、ドアを閉[し]めた。", "sentence_source": "generated"}, {"text": "スーツケースにお土産を押し込んだら、チャックが閉まらなくなった。", "target_word": "押し込んだら", "complexity_tier": "T3", "furigana": "スーツケースにお土産[みやげ]を押[お]し込[こ]んだら、チャックが閉[し]まらなくなった。", "sentence_source": "generated"}, {"text": "部屋を片づける時間がなく、散らかった本を押し入れに押し込んだ。", "target_word": "押し込んだ", "complexity_tier": "T4", "furigana": "部屋[へや]を片[かた]づける時間[じかん]がなく、散[ち]らかった本[ほん]を押[お]し入[い]れに押[お]し込[こ]んだ。", "sentence_source": "generated"}, {"text": "壁の穴にタオルを押し込んで、風が入らないようにした。", "target_word": "押し込んで", "complexity_tier": "T3", "furigana": "壁[かべ]の穴[あな]にタオルを押[お]し込[こ]んで、風[かぜ]が入[はい]らないようにした。", "sentence_source": "generated"}, {"text": "古い新聞を袋に押し込んでから、ごみ置き場へ持っていった。", "target_word": "押し込んで", "complexity_tier": "T3", "furigana": "古[ふる]い新聞[しんぶん]を袋[ふくろ]に押[お]し込[こ]んでから、ごみ置[お]き場[ば]へ持[も]っていった。", "sentence_source": "generated"}, {"text": "彼は口にパンを押し込んで、走って家を出た。", "target_word": "押し込んで", "complexity_tier": "T3", "furigana": "彼[かれ]は口[くち]にパンを押[お]し込[こ]んで、走[はし]って家[いえ]を出[で]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "押し込む", "label": "dictionary form"}, {"form": "押し込んだ", "label": "past"}, {"form": "押し込んで", "label": "te-form"}, {"form": "押し込まない", "label": "negative"}, {"form": "押し込まれる", "label": "passive"}], "register": "neutral", "sense_fingerprint": "狭い入れ物や隙間に、物を力を使って無理に入れる動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36446, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "押し込んだ", "is_correct": true, "explanation": "「急いで荷物をかばんに押し込んだ」は、荷物を強く入れた動作を表し、文に合う。"}, {"text": "眺めた", "is_correct": false, "explanation": "「かばんに眺めた」は成り立たず、荷物を入れる動作として意味が通らない。"}, {"text": "磨いた", "is_correct": false, "explanation": "「かばんに磨いた」は意味が通らず、荷物をかばんに入れる文脈に合わない。"}, {"text": "笑った", "is_correct": false, "explanation": "「かばんに笑った」は成り立たず、荷物を入れる動作として不自然。"}], "explanations": {"押し込んだ": "「急いで荷物をかばんに押し込んだ」は、荷物を強く入れた動作を表し、文に合う。", "眺めた": "「かばんに眺めた」は成り立たず、荷物を入れる動作として意味が通らない。", "磨いた": "「かばんに磨いた」は意味が通らず、荷物をかばんに入れる文脈に合わない。", "笑った": "「かばんに笑った」は成り立たず、荷物を入れる動作として不自然。"}, "sentence_index": 0, "correct_answer": "押し込んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓ガラスに顔を押し込んだ。", "explanation": "ここは〈押し当てる〉の意味。顔をガラスへ当てる動作で、中へ強く入れる押し込むとは言わない。"}, {"text": "倉庫から荷物を押し込んだ。", "explanation": "ここは〈運び出す〉の意味。押し込むは中へ入れる動作なので、倉庫から外へ出す場面には合わない。"}, {"text": "仕事を同僚に押し込んだ。", "explanation": "ここは〈押し付ける〉の意味。相手に無理に負わせる場面で、物を中へ入れる押し込むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36446, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "押し込んだ", "is_correct": true, "explanation": "「押し入れに押し込んだ」は、本を押し入れへ強く入れた動作で、文に合う。"}, {"text": "数えた", "is_correct": false, "explanation": "「押し入れに数えた」は成り立たず、本を入れる動作として意味が通らない。"}, {"text": "焼いた", "is_correct": false, "explanation": "「押し入れに焼いた」は意味が通らず、片づけの文脈に合わない。"}, {"text": "歌った", "is_correct": false, "explanation": "「押し入れに歌った」は成り立たず、本を入れる動作として不自然。"}], "explanations": {"押し込んだ": "「押し入れに押し込んだ」は、本を押し入れへ強く入れた動作で、文に合う。", "数えた": "「押し入れに数えた」は成り立たず、本を入れる動作として意味が通らない。", "焼いた": "「押し入れに焼いた」は意味が通らず、片づけの文脈に合わない。", "歌った": "「押し入れに歌った」は成り立たず、本を入れる動作として不自然。"}, "sentence_index": 6, "correct_answer": "押し込んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コップに牛乳を押し込んだ。", "explanation": "ここは〈注ぐ〉の意味。液体を入れる動作は注ぐと言い、固い物を力で入れる押し込むとは合わない。"}, {"text": "ペンを箱の上に押し込んだ。", "explanation": "ここは〈置く〉の意味。物を上に載せる動作で、中へ強く入れる押し込むとは言わない。"}, {"text": "お菓子を紙で押し込んだ。", "explanation": "ここは〈包む〉の意味。外から覆う動作で、中へ強く入れる押し込むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36446, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は車の荷台に木箱を押し込むた。", "corrected_sentence": "父は車の荷台に木箱を押し込んだ。", "error_description": "過去形は「押し込んだ」。「押し込むた」は活用を誤った形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "押し込む", "is_correct": true, "explanation": "「〜と」の前は辞書形で、「服を無理に押し込むと、しわになる」は一般的な条件を表し文に合う。"}, {"text": "押し込んだ", "is_correct": false, "explanation": "過去形は「押し込んだと」となり、入れ終えた後の出来事を表す。いつも起こる結果を述べる文には合わない。"}, {"text": "押し込んで", "is_correct": false, "explanation": "て形は「〜と」に直接続かず、「押し込んでと、しわになる」は文として成り立たない。"}, {"text": "押し込まれる", "is_correct": false, "explanation": "受け身になると服が入れられる意味になり、服を無理に入れる動作の文に合わない。"}], "correct_form": "押し込む", "base_form": "押し込む", "form_label": "辞書形", "sentence_index": 1, "explanations": {"押し込む": "「〜と」の前は辞書形で、「服を無理に押し込むと、しわになる」は一般的な条件を表し文に合う。", "押し込んだ": "過去形は「押し込んだと」となり、入れ終えた後の出来事を表す。いつも起こる結果を述べる文には合わない。", "押し込んで": "て形は「〜と」に直接続かず、「押し込んでと、しわになる」は文として成り立たない。", "押し込まれる": "受け身になると服が入れられる意味になり、服を無理に入れる動作の文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36446, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは玩具を箱の奥に押し込みた。", "corrected_sentence": "子どもは玩具を箱の奥に押し込んだ。", "error_description": "過去形は「押し込んだ」。「押し込みた」は活用を誤った形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "押し込んで", "is_correct": true, "explanation": "て形で後ろの動作へつなぎ、「タオルを押し込んで、風が入らないようにした」と順序を表し文に合う。"}, {"text": "押し込んだ", "is_correct": false, "explanation": "過去形は文を終えるので、後ろの「風が入らないようにした」へ続かず、文の流れが切れる。"}, {"text": "押し込む", "is_correct": false, "explanation": "辞書形では動作を次へつなぐ用法がなく、「押し込む、風が入らないようにした」は不自然。"}, {"text": "押し込まない", "is_correct": false, "explanation": "否定形は「タオルを入れない」意味になり、タオルを穴へ入れた動作の文に合わない。"}], "correct_form": "押し込んで", "base_form": "押し込む", "form_label": "て形", "sentence_index": 7, "explanations": {"押し込んで": "て形で後ろの動作へつなぎ、「タオルを押し込んで、風が入らないようにした」と順序を表し文に合う。", "押し込んだ": "過去形は文を終えるので、後ろの「風が入らないようにした」へ続かず、文の流れが切れる。", "押し込む": "辞書形では動作を次へつなぐ用法がなく、「押し込む、風が入らないようにした」は不自然。", "押し込まない": "否定形は「タオルを入れない」意味になり、タオルを穴へ入れた動作の文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
