INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36447, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や人を、ある場所の奥の方へ強い力で入れること。", "primary_collocate": null, "pronunciation": "おしこむ", "ipa": "oɕikomɯ", "syllable_count": 4, "sentences": [{"text": "満員電車では、駅員が乗客を電車の中へ押し込む。", "target_word": "押し込む", "complexity_tier": "T3", "furigana": "満員[まんいん]電車[でんしゃ]では、駅員[えきいん]が乗客[じょうきゃく]を電車[でんしゃ]の中[なか]へ押[お]し込[こ]む。", "sentence_source": "generated"}, {"text": "警官は犯人を車の奥へ押し込んだ。", "target_word": "押し込んだ", "complexity_tier": "T3", "furigana": "警官[けいかん]は犯人[はんにん]を車[くるま]の奥[おく]へ押[お]し込[こ]んだ。", "sentence_source": "generated"}, {"text": "洞窟の奥まで荷物を押し込んで、入口を石でふさいだ。", "target_word": "押し込んで", "complexity_tier": "T4", "furigana": "洞窟[どうくつ]の奥[おく]まで荷物[にもつ]を押[お]し込[こ]んで、入口[いりぐち]を石[いし]でふさいだ。", "sentence_source": "generated"}, {"text": "狭い倉庫の奥に古い机を押し込んだので、取り出すのが大変だ。", "target_word": "押し込んだ", "complexity_tier": "T4", "furigana": "狭[せま]い倉庫[そうこ]の奥[おく]に古[ふる]い机[つくえ]を押[お]し込[こ]んだので、取[と]り出[だ]すのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "子どもたちは小さな車に無理に押し込まれて、身動きができなかった。", "target_word": "押し込まれて", "complexity_tier": "T4", "furigana": "子[こ]どもたちは小[ちい]さな車[くるま]に無理[むり]に押[お]し込[こ]まれて、身動[みうご]きができなかった。", "sentence_source": "generated"}, {"text": "彼は棚の一番奥に箱を押し込み、誰にも見つからないようにした。", "target_word": "押し込み", "complexity_tier": "T4", "furigana": "彼[かれ]は棚[たな]の一番[いちばん]奥[おく]に箱[はこ]を押[お]し込[こ]み、誰[だれ]にも見[み]つからないようにした。", "sentence_source": "generated"}, {"text": "引っ越しの日、トラックの奥までソファーを押し込んだ。", "target_word": "押し込んだ", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]、トラックの奥[おく]までソファーを押[お]し込[こ]んだ。", "sentence_source": "generated"}, {"text": "大きな荷物を車のトランクの奥へ押し込んで、やっと出発できた。", "target_word": "押し込んで", "complexity_tier": "T4", "furigana": "大[おお]きな荷物[にもつ]を車[くるま]のトランクの奥[おく]へ押[お]し込[こ]んで、やっと出発[しゅっぱつ]できた。", "sentence_source": "generated"}, {"text": "兄は友達を押し入れの奥に押し込んで、かくれんぼで勝った。", "target_word": "押し込んで", "complexity_tier": "T3", "furigana": "兄[あに]は友達[ともだち]を押[お]し入[い]れの奥[おく]に押[お]し込[こ]んで、かくれんぼで勝[か]った。", "sentence_source": "generated"}, {"text": "工事の人が、長いパイプを壁の穴の奥へ押し込んでいった。", "target_word": "押し込んで", "complexity_tier": "T4", "furigana": "工事[こうじ]の人[ひと]が、長[なが]いパイプを壁[かべ]の穴[あな]の奥[おく]へ押[お]し込[こ]んでいった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "押し込む", "label": "dictionary form"}, {"form": "押し込んだ", "label": "past"}, {"form": "押し込み", "label": "continuative"}, {"form": "押し込まれて", "label": "passive te-form"}, {"form": "押し込まない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "物や人を、車・倉庫・穴などの奥へ力ずくで入れる動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36447, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "押し込む", "is_correct": true, "explanation": "「乗客を電車の中へ押し込む」は、人を中へ強く入れる意味で文に合う。"}, {"text": "焼く", "is_correct": false, "explanation": "「乗客を電車の中へ焼く」は意味が通らず、乗客を入れる文脈に合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "「乗客を電車の中へ眠る」は成り立たず、入れる動作として不自然。"}, {"text": "歌う", "is_correct": false, "explanation": "「乗客を電車の中へ歌う」は意味が通らず、満員電車の文脈に合わない。"}], "explanations": {"押し込む": "「乗客を電車の中へ押し込む」は、人を中へ強く入れる意味で文に合う。", "焼く": "「乗客を電車の中へ焼く」は意味が通らず、乗客を入れる文脈に合わない。", "眠る": "「乗客を電車の中へ眠る」は成り立たず、入れる動作として不自然。", "歌う": "「乗客を電車の中へ歌う」は意味が通らず、満員電車の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "押し込む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポケットの奥から鍵を押し込んだ。", "explanation": "奥から外へ出す向きになり、奥へ入れる押し込むとは反対なので合わない。"}, {"text": "コップにお茶を押し込んだ。", "explanation": "液体を注ぐ場面で、固い物を力ずくで奥へ入れる押し込むとは言わない。"}, {"text": "ケーキを箱の奥から手前へ押し込んだ。", "explanation": "奥から手前へ動かす向きになり、奥へ入れる押し込むとは反対なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36447, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "押し込んだ", "is_correct": true, "explanation": "「トラックの奥までソファーを押し込んだ」は、ソファーを奥へ強く入れた動作で、文に合う。"}, {"text": "笑った", "is_correct": false, "explanation": "「ソファーを笑った」は成り立たず、トラックへ運ぶ文脈に合わない。"}, {"text": "咲いた", "is_correct": false, "explanation": "「ソファーを咲いた」は意味が通らず、動作として成り立たない。"}, {"text": "転んだ", "is_correct": false, "explanation": "「ソファーを転んだ」は成り立たず、ソファーを入れる動作として不自然。"}], "explanations": {"押し込んだ": "「トラックの奥までソファーを押し込んだ」は、ソファーを奥へ強く入れた動作で、文に合う。", "笑った": "「ソファーを笑った」は成り立たず、トラックへ運ぶ文脈に合わない。", "咲いた": "「ソファーを咲いた」は意味が通らず、動作として成り立たない。", "転んだ": "「ソファーを転んだ」は成り立たず、ソファーを入れる動作として不自然。"}, "sentence_index": 6, "correct_answer": "押し込んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "引っ越しの日、トラックの奥からソファーを外へ押し込んだ。", "explanation": "奥から外へ出す向きになり、奥へ入れる押し込むとは反対なので合わない。"}, {"text": "大きな荷物を、トランクの奥から手前へ押し込んで降ろした。", "explanation": "手前へ引き出す向きになり、奥へ入れる押し込むとは反対なので合わない。"}, {"text": "工事の人が、壁の穴の奥にあったパイプを外へ押し込んでいった。", "explanation": "奥から外へ出す向きになり、奥へ入れる押し込むとは反対なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36447, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅員は乗客を車両の奥へ押し込みた。", "corrected_sentence": "駅員は乗客を車両の奥へ押し込んだ。", "error_description": "過去形は「押し込んだ」。「押し込みた」は活用を誤った形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "押し込んだ", "is_correct": true, "explanation": "文末で過去を表す形で、警官が犯人を車の奥へ入れた出来事に合う。"}, {"text": "押し込んで", "is_correct": false, "explanation": "て形は文末に置けず、「警官は犯人を車の奥へ押し込んで。」では文が終わらない。"}, {"text": "押し込み", "is_correct": false, "explanation": "連用形で、文を終える述語にはならない。「押し込み。」では文として成り立たない。"}, {"text": "押し込まれて", "is_correct": false, "explanation": "受け身のて形で、文末に置けない。また主語が犯人に変わり、文の形も合わない。"}], "correct_form": "押し込んだ", "base_form": "押し込む", "form_label": "過去形", "sentence_index": 1, "explanations": {"押し込んだ": "文末で過去を表す形で、警官が犯人を車の奥へ入れた出来事に合う。", "押し込んで": "て形は文末に置けず、「警官は犯人を車の奥へ押し込んで。」では文が終わらない。", "押し込み": "連用形で、文を終える述語にはならない。「押し込み。」では文として成り立たない。", "押し込まれて": "受け身のて形で、文末に置けない。また主語が犯人に変わり、文の形も合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36447, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業員は、古い棚を倉庫の奥へ押し込まれた。", "corrected_sentence": "作業員は、古い棚を倉庫の奥へ押し込んだ。", "error_description": "正しくは能動の「古い棚を押し込んだ」（作業員が入れた）。「押し込まれた」は受け身なので、古い棚を主語にして「古い棚が押し込まれた」とする。「〜を押し込まれた」は不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "押し込んで", "is_correct": true, "explanation": "て形で、荷物を奥へ入れた動作の後に「やっと出発できた」と続く形。"}, {"text": "押し込む", "is_correct": false, "explanation": "辞書形。て形の位置には置けず、「押し込む、やっと出発できた」では文がつながらない。"}, {"text": "押し込まない", "is_correct": false, "explanation": "否定形。入れる動作を打ち消す形になり、「やっと出発できた」と続く流れに合わない。"}, {"text": "押し込め", "is_correct": false, "explanation": "命令形。動作を命じる形になり、過去の出来事の流れを述べる文には合わない。"}], "correct_form": "押し込んで", "base_form": "押し込む", "form_label": "て形", "sentence_index": 7, "explanations": {"押し込んで": "て形で、荷物を奥へ入れた動作の後に「やっと出発できた」と続く形。", "押し込む": "辞書形。て形の位置には置けず、「押し込む、やっと出発できた」では文がつながらない。", "押し込まない": "否定形。入れる動作を打ち消す形になり、「やっと出発できた」と続く流れに合わない。", "押し込め": "命令形。動作を命じる形になり、過去の出来事の流れを述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36448, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「AをBと見なす」の「と」で、賛成したものを賛成として扱う意味に合う。"}, {"text": "に", "is_correct": false, "explanation": "「ものに見なす」は見なすの形として使わない。見なすは「〜と」で結ぶ。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すので、判断の対象を示す見なすには合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、ここでは意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "「AをBと見なす」の「と」で、賛成したものを賛成として扱う意味に合う。", "に": "「ものに見なす」は見なすの形として使わない。見なすは「〜と」で結ぶ。", "で": "「で」は手段や場所を表すので、判断の対象を示す見なすには合わない。", "へ": "「へ」は方向を表すので、ここでは意味が通らない。"}, "error_tags": {"に": "判定の誤用", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36448, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「勤務時間と見なして」の「と」で、判断して扱う意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "「不合格が見なす」は主語にしても意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「不合格の見なす」は名詞修飾になり、見なすの形に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、判断の対象を示す見なすには合わない。"}], "correct_answer": "と", "explanations": {"と": "「勤務時間と見なして」の「と」で、判断して扱う意味に合う。", "が": "「不合格が見なす」は主語にしても意味が通らない。", "の": "「不合格の見なす」は名詞修飾になり、見なすの形に合わない。", "から": "「から」は起点を表すので、判断の対象を示す見なすには合わない。"}, "error_tags": {"が": "主語の誤用", "の": "修飾の誤用", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36448, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "何かを決めて考えること。", "primary_collocate": null, "pronunciation": "みなす", "ipa": "minasɯ", "syllable_count": 3, "sentences": [{"text": "この店では、三十分遅れた人は欠席と見なす。", "target_word": "見なす", "complexity_tier": "T3", "furigana": "この店[みせ]では、三十分[さんじゅっぷん]遅[おく]れた人[ひと]は欠席[けっせき]と見[み]なす。", "sentence_source": "generated"}, {"text": "返事がない場合は、賛成したものと見なします。", "target_word": "見なします", "complexity_tier": "T3", "furigana": "返事[へんじ]がない場合[ばあい]は、賛成[さんせい]したものと見[み]なします。", "sentence_source": "generated"}, {"text": "先生は、宿題を出さない生徒をやる気がないと見なした。", "target_word": "見なした", "complexity_tier": "T3", "furigana": "先生[せんせい]は、宿題[しゅくだい]を出[だ]さない生徒[せいと]をやる気[き]がないと見[み]なした。", "sentence_source": "generated"}, {"text": "法律では、十八歳未満の人を未成年と見なす。", "target_word": "見なす", "complexity_tier": "T3", "furigana": "法律[ほうりつ]では、十八歳[じゅうはっさい]未満[みまん]の人[ひと]を未成年[みせいねん]と見[み]なす。", "sentence_source": "generated"}, {"text": "期限までに連絡がなければ、辞退したと見なされる。", "target_word": "見なされる", "complexity_tier": "T3", "furigana": "期限[きげん]までに連絡[れんらく]がなければ、辞退[じたい]したと見[み]なされる。", "sentence_source": "generated"}, {"text": "彼の沈黙を、反対の意思と見なすのは早すぎる。", "target_word": "見なす", "complexity_tier": "T4", "furigana": "彼[かれ]の沈黙[ちんもく]を、反対[はんたい]の意思[いし]と見[み]なすのは早[はや]すぎる。", "sentence_source": "generated"}, {"text": "会社はこの出来事を事故ではなく、事件と見なした。", "target_word": "見なした", "complexity_tier": "T3", "furigana": "会社[かいしゃ]はこの出来事[できごと]を事故[じこ]ではなく、事件[じけん]と見[み]なした。", "sentence_source": "generated"}, {"text": "試験を三回休んだ学生は、不合格と見なす決まりだ。", "target_word": "見なす", "complexity_tier": "T3", "furigana": "試験[しけん]を三回[さんかい]休[やす]んだ学生[がくせい]は、不合格[ふごうかく]と見[み]なす決[き]まりだ。", "sentence_source": "generated"}, {"text": "警察は、この手紙を犯人からのメッセージと見なして調べている。", "target_word": "見なして", "complexity_tier": "T4", "furigana": "警察[けいさつ]は、この手紙[てがみ]を犯人[はんにん]からのメッセージと見[み]なして調[しら]べている。", "sentence_source": "generated"}, {"text": "彼女は私の質問を批判と見なして、怒ってしまった。", "target_word": "見なして", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は私[わたし]の質問[しつもん]を批判[ひはん]と見[み]なして、怒[おこ]ってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見なす", "label": "dictionary form"}, {"form": "見なします", "label": "polite"}, {"form": "見なした", "label": "past"}, {"form": "見なされる", "label": "passive"}, {"form": "見なさない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "実際はどうでも、ある物事を「〜だ」と決めて扱う・仮定すること(AをBと見なす)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36448, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見なす", "is_correct": true, "explanation": "「欠席と見なす」は、遅れた人を欠席として扱うという意味で文に合う。"}, {"text": "眺める", "is_correct": false, "explanation": "「欠席と眺める」は意味が通らない。眺めるは見て楽しむ動作を表す。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「欠席と運ぶ」は意味が通らない。運ぶは物を移動させる動作を表す。"}, {"text": "散らかす", "is_correct": false, "explanation": "「欠席と散らかす」は不自然。散らかすは物を乱雑に置く意味で、ここに入らない。"}], "explanations": {"見なす": "「欠席と見なす」は、遅れた人を欠席として扱うという意味で文に合う。", "眺める": "「欠席と眺める」は意味が通らない。眺めるは見て楽しむ動作を表す。", "運ぶ": "「欠席と運ぶ」は意味が通らない。運ぶは物を移動させる動作を表す。", "散らかす": "「欠席と散らかす」は不自然。散らかすは物を乱雑に置く意味で、ここに入らない。"}, "sentence_index": 0, "correct_answer": "見なす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その資料を一瞬見なして、すぐに閉じた。", "explanation": "ここは〈ちらっと見る〉の意味。見なすは〜だと判断して扱う意味で、目で軽く確かめる行為は表さないので合わない。"}, {"text": "祖母の病室を見なして、毎週花を届けた。", "explanation": "ここは〈見舞う〉の意味。見なすは〜だと判断して扱う意味で、病人を訪ねて気遣う行為は表さないので合わない。"}, {"text": "森で迷子の犬を見なして、飼い主に連絡した。", "explanation": "ここは〈見つける〉の意味。見なすは判断して扱う意味で、物や人を発見する意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36448, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見なした", "is_correct": true, "explanation": "「事件と見なした」で、事故ではないと判断して扱った意味に合う。"}, {"text": "届けた", "is_correct": false, "explanation": "「事件と届けた」は意味が通らない。届けたは物や知らせを相手に運ぶ意味。"}, {"text": "磨いた", "is_correct": false, "explanation": "「事件と磨いた」は不自然。磨いたは表面をこすって綺麗にする動作を表す。"}, {"text": "焦がした", "is_correct": false, "explanation": "「事件と焦がした」は意味をなさない。焦がしたは熱で色を変える意味。"}], "explanations": {"見なした": "「事件と見なした」で、事故ではないと判断して扱った意味に合う。", "届けた": "「事件と届けた」は意味が通らない。届けたは物や知らせを相手に運ぶ意味。", "磨いた": "「事件と磨いた」は不自然。磨いたは表面をこすって綺麗にする動作を表す。", "焦がした": "「事件と焦がした」は意味をなさない。焦がしたは熱で色を変える意味。"}, "sentence_index": 6, "correct_answer": "見なした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は私の質問を見なして、そのまま怒ってしまった。", "explanation": "ここは〈聞き流す〉の意味。見なすは〜だと判断して扱う意味で、軽く受け流す意味はないので合わない。"}, {"text": "彼女は私の質問を見なして、もう一度読み直した。", "explanation": "ここは〈見直す〉の意味。見なすは判断して扱う意味で、もう一度検討し直す行為は表さない。"}, {"text": "彼女は私の質問を見なして、大事な部分を見落とした。", "explanation": "ここは〈見落とす〉の意味。見なすは判断する意味で、見逃す意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36448, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社では、遅刻を三回した人は欠勤を見なす。", "corrected_sentence": "会社では、遅刻を三回した人は欠勤と見なす。", "error_description": "「見なす」は「AをBと見なす」の形で、Bの直後に助詞「と」を使う。「を」は誤りで、正しくは「と」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36448, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校は、三回の遅刻を欠席に見なして評価する。", "corrected_sentence": "学校は、三回の遅刻を欠席と見なして評価する。", "error_description": "「見なす」は「AをBと見なす」の形で、Bの後に「と」を使う。「に」は誤りで、正しくは「と」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36449, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「商品と見なして」の「と」で、荷物を商品として扱う意味に合う。"}, {"text": "に", "is_correct": false, "explanation": "「商品に見なして」は見なすの形として使わない。見なすは「〜と」で結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「商品を見なして」は目的語にしても、判断の対象を示す見なすの形に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「商品で見なして」は手段を表すことになり、判断の対象を示す意味に合わない。"}], "correct_answer": "と", "explanations": {"と": "「商品と見なして」の「と」で、荷物を商品として扱う意味に合う。", "に": "「商品に見なして」は見なすの形として使わない。見なすは「〜と」で結ぶ。", "を": "「商品を見なして」は目的語にしても、判断の対象を示す見なすの形に合わない。", "で": "「商品で見なして」は手段を表すことになり、判断の対象を示す意味に合わない。"}, "error_tags": {"に": "判定の誤用", "を": "目的語の誤用", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36449, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「勤務時間と見なして」の「と」で、移動時間を勤務時間として扱う意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "「勤務時間が見なして」は主語にしても、判断の対象を示す見なすの形に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「勤務時間の見なして」は名詞修飾になり、見なすの形に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、判断の対象を示す見なすには合わない。"}], "correct_answer": "と", "explanations": {"と": "「勤務時間と見なして」の「と」で、移動時間を勤務時間として扱う意味に合う。", "が": "「勤務時間が見なして」は主語にしても、判断の対象を示す見なすの形に合わない。", "の": "「勤務時間の見なして」は名詞修飾になり、見なすの形に合わない。", "から": "「から」は起点を表すので、判断の対象を示す見なすには合わない。"}, "error_tags": {"が": "主語の誤用", "の": "修飾の誤用", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36449, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "そうだと判断すること。ある物事や状況を、特定の意味や価値があると認めて扱うこと。", "primary_collocate": null, "pronunciation": "みなす", "ipa": "minasɯ", "syllable_count": 3, "sentences": [{"text": "彼の発言は、約束と見なしてもいいと思う。", "target_word": "見なして", "complexity_tier": "T3", "furigana": "彼[かれ]の発言[はつげん]は、約束[やくそく]と見[み]なしてもいいと思[おも]う。", "sentence_source": "generated"}, {"text": "税関では、この荷物を商品と見なして税金を取る。", "target_word": "見なして", "complexity_tier": "T3", "furigana": "税関[ぜいかん]では、この荷物[にもつ]を商品[しょうひん]と見[み]なして税金[ぜいきん]を取[と]る。", "sentence_source": "generated"}, {"text": "古い記録も、大切な歴史の資料と見なされる。", "target_word": "見なされる", "complexity_tier": "T3", "furigana": "古[ふる]い記録[きろく]も、大切[たいせつ]な歴史[れきし]の資料[しりょう]と見[み]なされる。", "sentence_source": "generated"}, {"text": "裁判所は、その契約を有効と見なした。", "target_word": "見なした", "complexity_tier": "T3", "furigana": "裁判所[さいばんしょ]は、その契約[けいやく]を有効[ゆうこう]と見[み]なした。", "sentence_source": "generated"}, {"text": "この国では、握手を友好の印と見なす。", "target_word": "見なす", "complexity_tier": "T3", "furigana": "この国[くに]では、握手[あくしゅ]を友好[ゆうこう]の印[しるし]と見[み]なす。", "sentence_source": "generated"}, {"text": "専門家は、この絵を貴重な文化財と見なしている。", "target_word": "見なしている", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、この絵[え]を貴重[きちょう]な文化財[ぶんかざい]と見[み]なしている。", "sentence_source": "generated"}, {"text": "私は今回の失敗を、成長のチャンスと見なすことにした。", "target_word": "見なす", "complexity_tier": "T3", "furigana": "私[わたし]は今回[こんかい]の失敗[しっぱい]を、成長[せいちょう]のチャンスと見[み]なすことにした。", "sentence_source": "generated"}, {"text": "会社は、出張中の移動時間を勤務時間と見なして給料を払う。", "target_word": "見なして", "complexity_tier": "T4", "furigana": "会社[かいしゃ]は、出張中[しゅっちょうちゅう]の移動[いどう]時間[じかん]を勤務[きんむ]時間[じかん]と見[み]なして給料[きゅうりょう]を払[はら]う。", "sentence_source": "generated"}, {"text": "彼を仲間と見なさない人は、このクラスにはいない。", "target_word": "見なさない", "complexity_tier": "T3", "furigana": "彼[かれ]を仲間[なかま]と見[み]なさない人[ひと]は、このクラスにはいない。", "sentence_source": "generated"}, {"text": "その地域では、この木を神聖なものと見なし、切らない。", "target_word": "見なし", "complexity_tier": "T3", "furigana": "その地域[ちいき]では、この木[き]を神聖[しんせい]なものと見[み]なし、切[き]らない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見なす", "label": "dictionary form"}, {"form": "見なした", "label": "past"}, {"form": "見なして", "label": "te-form"}, {"form": "見なされる", "label": "passive"}, {"form": "見なさない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "ある物事に特定の意味や価値があると判断し、そのように認めて扱う(AをBと見なす)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36449, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見なして", "is_correct": true, "explanation": "「約束と見なしてもいい」で、発言を約束として扱ってよいという意味に合う。"}, {"text": "眺めて", "is_correct": false, "explanation": "「約束と眺めてもいい」は意味が通らない。眺めるは見て楽しむ動作。"}, {"text": "運んで", "is_correct": false, "explanation": "「約束と運んでもいい」は不自然。運ぶは物を移動させる動作。"}, {"text": "散らかして", "is_correct": false, "explanation": "「約束と散らかしてもいい」は意味をなさない。散らかすは物を乱雑にする動作。"}], "explanations": {"見なして": "「約束と見なしてもいい」で、発言を約束として扱ってよいという意味に合う。", "眺めて": "「約束と眺めてもいい」は意味が通らない。眺めるは見て楽しむ動作。", "運んで": "「約束と運んでもいい」は不自然。運ぶは物を移動させる動作。", "散らかして": "「約束と散らかしてもいい」は意味をなさない。散らかすは物を乱雑にする動作。"}, "sentence_index": 0, "correct_answer": "見なして"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裁判所は、その契約が結ばれるのを最後まで見なした。", "explanation": "ここは〈見届ける〉の意味。見なすは〜だと判断して扱う意味で、最後まで見守って確かめる行為は表さないので合わない。"}, {"text": "彼は散らかった部屋を見なして、そのままにした。", "explanation": "ここは〈放置する〉の意味。見なすは判断して扱う意味で、そのままにしておく意味はないので合わない。"}, {"text": "会場の観客を見なして、席を準備した。", "explanation": "ここは〈数える〉の意味。見なすは〜だと判断して扱う意味で、人数を数えて確定する行為は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36449, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見なす", "is_correct": true, "explanation": "「成長のチャンスと見なすことにした」で、失敗を成長の機会として扱うという意味に合う。"}, {"text": "磨く", "is_correct": false, "explanation": "「成長のチャンスと磨くことにした」は意味が通らない。磨くは表面を綺麗にする動作。"}, {"text": "届ける", "is_correct": false, "explanation": "「成長のチャンスと届けることにした」は不自然。届けるは物を相手に運ぶ動作。"}, {"text": "焦がす", "is_correct": false, "explanation": "「成長のチャンスと焦がすことにした」は意味をなさない。焦がすは熱で色を変える動作。"}], "explanations": {"見なす": "「成長のチャンスと見なすことにした」で、失敗を成長の機会として扱うという意味に合う。", "磨く": "「成長のチャンスと磨くことにした」は意味が通らない。磨くは表面を綺麗にする動作。", "届ける": "「成長のチャンスと届けることにした」は不自然。届けるは物を相手に運ぶ動作。", "焦がす": "「成長のチャンスと焦がすことにした」は意味をなさない。焦がすは熱で色を変える動作。"}, "sentence_index": 6, "correct_answer": "見なす"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その地域では、この祭りを毎年見なして、楽しみにしている。", "explanation": "ここは〈見物する〉の意味。見なすは〜だと判断して扱う意味で、催しを眺めて楽しむ行為は表さないので合わない。"}, {"text": "その地域では、この木を毎年見なして、大きさを記録している。", "explanation": "ここは〈測る〉の意味。見なすは〜だと判断して扱う意味で、長さや大きさを計る行為は表さないので合わない。"}, {"text": "その地域では、この木を夜通し見なして、畑の番をしている。", "explanation": "ここは〈見張る〉の意味。見なすは〜だと判断して扱う意味で、そばで警戒して守る行為は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36449, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、この古い建物を文化財に見なして保存する。", "corrected_sentence": "市は、この古い建物を文化財と見なして保存する。", "error_description": "「見なす」は「AをBと見なす」の形で、Bの後に「と」を使う。「に」は誤りで、正しくは「と」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36449, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、この川を観光地に見なして、道を整える。", "corrected_sentence": "市は、この川を観光地と見なして、道を整える。", "error_description": "「見なす」は「AをBと見なす」の形で、Bの後に「と」を使う。「に」は誤りで、正しくは「と」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36450, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「兄と私の考えに相違はほとんどない」と、相違を主題として示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "「相違をほとんどない」は目的語を取る文ではなく、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「相違にほとんどない」は文の骨組みが崩れ、不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "「相違でほとんどない」は手段や場所の意味になり、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「兄と私の考えに相違はほとんどない」と、相違を主題として示す「は」。", "を": "「相違をほとんどない」は目的語を取る文ではなく、文が成り立たない。", "に": "「相違にほとんどない」は文の骨組みが崩れ、不自然になる。", "で": "「相違でほとんどない」は手段や場所の意味になり、文が成り立たない。"}, "error_tags": {"を": "目的格", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致する", "is_correct": true, "explanation": "食い違わないことを表し、相違するの対義語。"}, {"text": "増える", "is_correct": false, "explanation": "数量が多くなることを表し、相違するの対義語ではない。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作を表し、相違するとは関係がない。"}, {"text": "話す", "is_correct": false, "explanation": "言葉を交わす動作を表し、対義語ではない。"}], "correct_answer": "一致する", "explanations": {"一致する": "食い違わないことを表し、相違するの対義語。", "増える": "数量が多くなることを表し、相違するの対義語ではない。", "眺める": "見る動作を表し、相違するとは関係がない。", "話す": "言葉を交わす動作を表し、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36450, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「性格には相違があるものだ」と、ある の主語を示す「が」。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すため、「相違からあるものだ」と続けると意味が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表すため、「相違とあるものだ」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、「相違へあるものだ」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「性格には相違があるものだ」と、ある の主語を示す「が」。", "から": "起点を表すため、「相違からあるものだ」と続けると意味が崩れる。", "と": "並列や相手を表すため、「相違とあるものだ」は文が成り立たない。", "へ": "方向を表すため、「相違へあるものだ」は成り立たない。"}, "error_tags": {"から": "起点", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "食い違わないことを表し、相違の対義語。"}, {"text": "基準", "is_correct": false, "explanation": "比べるときのもとになる目安を表し、対義語ではない。"}, {"text": "手順", "is_correct": false, "explanation": "やり方の順序を表し、相違との対義関係にはない。"}, {"text": "結論", "is_correct": false, "explanation": "考えの最後の判断を表し、対義語ではない。"}], "correct_answer": "一致", "explanations": {"一致": "食い違わないことを表し、相違の対義語。", "基準": "比べるときのもとになる目安を表し、対義語ではない。", "手順": "やり方の順序を表し、相違との対義関係にはない。", "結論": "考えの最後の判断を表し、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36450, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものがちがうこと。", "primary_collocate": null, "pronunciation": "そうい", "ipa": "soːi", "syllable_count": 3, "sentences": [{"text": "二人の意見には大きな相違があります。", "target_word": "相違", "complexity_tier": "T3", "furigana": "二人[ふたり]の意見[いけん]には大[おお]きな相違[そうい]があります。", "sentence_source": "generated"}, {"text": "兄と私の考えに相違はほとんどない。", "target_word": "相違", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]の考[かんが]えに相違[そうい]はほとんどない。", "sentence_source": "generated"}, {"text": "去年と今年の結果に、大きな相違は見られない。", "target_word": "相違", "complexity_tier": "T3", "furigana": "去年[きょねん]と今年[ことし]の結果[けっか]に、大[おお]きな相違[そうい]は見[み]られない。", "sentence_source": "generated"}, {"text": "事実と相違する説明をしたため、先生に注意された。", "target_word": "相違する", "complexity_tier": "T3", "furigana": "事実[じじつ]と相違[そうい]する説明[せつめい]をしたため、先生[せんせい]に注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "地域による味の相違を、食べ比べて楽しんだ。", "target_word": "相違", "complexity_tier": "T3", "furigana": "地域[ちいき]による味[あじ]の相違[そうい]を、食[た]べ比[くら]べて楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "日本と外国の習慣の相違に、最初は驚いた。", "target_word": "相違", "complexity_tier": "T3", "furigana": "日本[にほん]と外国[がいこく]の習慣[しゅうかん]の相違[そうい]に、最初[さいしょ]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "この二つの写真には、小さな相違が三つある。", "target_word": "相違", "complexity_tier": "T3", "furigana": "この二[ふた]つの写真[しゃしん]には、小[ちい]さな相違[そうい]が三[みっ]つある。", "sentence_source": "generated"}, {"text": "双子でも、性格には相違があるものだ。", "target_word": "相違", "complexity_tier": "T3", "furigana": "双子[ふたご]でも、性格[せいかく]には相違[そうい]があるものだ。", "sentence_source": "generated"}, {"text": "見積もりと請求の金額に相違があったので、店に連絡した。", "target_word": "相違", "complexity_tier": "T3", "furigana": "見積[みつ]もりと請求[せいきゅう]の金額[きんがく]に相違[そうい]があったので、店[みせ]に連絡[れんらく]した。", "sentence_source": "generated"}, {"text": "二人の相違を表にまとめてみましょう。", "target_word": "相違", "complexity_tier": "T3", "furigana": "二人[ふたり]の相違[そうい]を表[ひょう]にまとめてみましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "相違", "label": "基本形"}, {"form": "相違する", "label": "サ変動詞"}, {"form": "相違ない", "label": "否定表現"}, {"form": "相違して", "label": "て形"}], "register": "formal", "sense_fingerprint": "二つのものの間にあるちがい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36450, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相違", "is_correct": true, "explanation": "二人の意見の食い違いを表し、「大きな相違がある」と自然に続く。"}, {"text": "砂糖", "is_correct": false, "explanation": "意見の話に「大きな砂糖」は結びつかず、文が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "意見の食い違いを表す文脈に天気は合わない。"}, {"text": "電池", "is_correct": false, "explanation": "意見の話に「大きな電池」は結びつかず、意味が通らない。"}], "explanations": {"相違": "二人の意見の食い違いを表し、「大きな相違がある」と自然に続く。", "砂糖": "意見の話に「大きな砂糖」は結びつかず、文が成り立たない。", "天気": "意見の食い違いを表す文脈に天気は合わない。", "電池": "意見の話に「大きな電池」は結びつかず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "相違"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その計画は両者の相違がそっくり重なった。", "explanation": "ここは〈一致〉の意味。重なって同じになることは一致で表し、相違は違いを指すので合わない。"}, {"text": "一人ひとりの相違がきれいに揃っている。", "explanation": "ここは〈一致〉の意味。意見が揃うことは一致で表し、相違は違いを指すので合わない。"}, {"text": "三人の答えは相違してまとまった。", "explanation": "ここは〈一致〉の意味。答えがまとまることは一致で表し、相違して一つにまとまる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36450, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相違", "is_correct": true, "explanation": "写真の小さな違いを表し、「小さな相違が三つある」と自然に続く。"}, {"text": "駐車場", "is_correct": false, "explanation": "写真の違いを数える文に駐車場は結びつかない。"}, {"text": "教科書", "is_correct": false, "explanation": "写真の違いを表す文脈に教科書は合わない。"}, {"text": "寒気", "is_correct": false, "explanation": "写真の違いを数える文脈に寒気は結びつかず、意味が通らない。"}], "explanations": {"相違": "写真の小さな違いを表し、「小さな相違が三つある」と自然に続く。", "駐車場": "写真の違いを数える文に駐車場は結びつかない。", "教科書": "写真の違いを表す文脈に教科書は合わない。", "寒気": "写真の違いを数える文脈に寒気は結びつかず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "相違"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人の答えは相違がぴったり合った。", "explanation": "ここは〈一致〉の意味。ぴったり合うことを表すのは一致で、相違は違いを指す語。"}, {"text": "二つの計画は完全に相違して、どちらも同じ内容になった。", "explanation": "ここは〈一致〉の意味。相違は違っていることを表し、同じ内容になったという結果と矛盾する。"}, {"text": "会議では皆の相違がそろった。", "explanation": "ここは〈一致〉の意味。意見がそろう場合は一致を使い、相違はそろうものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36450, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "報告書は事実を相違する部分があった。", "corrected_sentence": "報告書は事実と相違する部分があった。", "error_description": "「相違する」は「と」をとる。「を」は誤りで、正しくは「事実と相違する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36450, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三つの絵には、小さな相違を二つある。", "corrected_sentence": "三つの絵には、小さな相違が二つある。", "error_description": "「ある」は主語に「が」をとる。「を」は誤りで、正しくは「相違が二つある」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36451, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「実際と相違していた」と、相違する相手を示す「と」。"}, {"text": "を", "is_correct": false, "explanation": "「実際を相違していた」は目的語を取る文ではなく、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「実際に相違していた」は相違するの形として不自然で、文が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「実際で相違していた」は手段や場所の意味になり、成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「実際と相違していた」と、相違する相手を示す「と」。", "を": "「実際を相違していた」は目的語を取る文ではなく、文が成り立たない。", "に": "「実際に相違していた」は相違するの形として不自然で、文が崩れる。", "で": "「実際で相違していた」は手段や場所の意味になり、成り立たない。"}, "error_tags": {"を": "目的格", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "食い違わないことを表し、相違の対義語。"}, {"text": "方針", "is_correct": false, "explanation": "進め方の指針を表し、対義語ではない。"}, {"text": "予算", "is_correct": false, "explanation": "お金の計画を表し、相違との対義関係にはない。"}, {"text": "手続き", "is_correct": false, "explanation": "手順の意味で、対義語ではない。"}], "correct_answer": "一致", "explanations": {"一致": "食い違わないことを表し、相違の対義語。", "方針": "進め方の指針を表し、対義語ではない。", "予算": "お金の計画を表し、相違との対義関係にはない。", "手続き": "手順の意味で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36451, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「文化の相違を理解する」と、理解の対象を示す「を」。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、「文化の相違へ理解する」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すため、理解の対象を示せず文が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「相違に理解する」は対象を示せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「文化の相違を理解する」と、理解の対象を示す「を」。", "へ": "方向を表すため、「文化の相違へ理解する」は成り立たない。", "より": "比較を表すため、理解の対象を示せず文が崩れる。", "に": "「相違に理解する」は対象を示せず、文が成り立たない。"}, "error_tags": {"へ": "方向", "より": "比較", "に": "位置・相手"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "食い違わないことを表し、相違の対義語。"}, {"text": "基準", "is_correct": false, "explanation": "比べるときの目安を表し、対義語ではない。"}, {"text": "手順", "is_correct": false, "explanation": "やり方の順序を表し、相違との対義関係にはない。"}, {"text": "結論", "is_correct": false, "explanation": "考えの最後の判断を表し、対義語ではない。"}], "correct_answer": "一致", "explanations": {"一致": "食い違わないことを表し、相違の対義語。", "基準": "比べるときの目安を表し、対義語ではない。", "手順": "やり方の順序を表し、相違との対義関係にはない。", "結論": "考えの最後の判断を表し、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36451, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の間に見られる違いや、一致しない点。", "primary_collocate": null, "pronunciation": "そうい", "ipa": "soːi", "syllable_count": 3, "sentences": [{"text": "計画と結果の間に相違が生じた原因を調べる。", "target_word": "相違", "complexity_tier": "T3", "furigana": "計画[けいかく]と結果[けっか]の間[あいだ]に相違[そうい]が生[しょう]じた原因[げんいん]を調[しら]べる。", "sentence_source": "generated"}, {"text": "報告書の内容が実際と相違していた。", "target_word": "相違して", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]の内容[ないよう]が実際[じっさい]と相違[そうい]していた。", "sentence_source": "generated"}, {"text": "双方の主張の相違が大きく、話し合いは長引いた。", "target_word": "相違", "complexity_tier": "T3", "furigana": "双方[そうほう]の主張[しゅちょう]の相違[そうい]が大[おお]きく、話[はな]し合[あ]いは長引[ながび]いた。", "sentence_source": "generated"}, {"text": "契約書の記載に相違がないか、よく確認してください。", "target_word": "相違", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]の記載[きさい]に相違[そうい]がないか、よく確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "世代による価値観の相違は、誰にでもある。", "target_word": "相違", "complexity_tier": "T3", "furigana": "世代[せだい]による価値観[かちかん]の相違[そうい]は、誰[だれ]にでもある。", "sentence_source": "generated"}, {"text": "証言の相違から、事実がはっきりしなくなった。", "target_word": "相違", "complexity_tier": "T3", "furigana": "証言[しょうげん]の相違[そうい]から、事実[じじつ]がはっきりしなくなった。", "sentence_source": "generated"}, {"text": "数字に相違があったため、もう一度計算した。", "target_word": "相違", "complexity_tier": "T3", "furigana": "数字[すうじ]に相違[そうい]があったため、もう一度[いちど]計算[けいさん]した。", "sentence_source": "generated"}, {"text": "文化の相違を理解することが、国際交流の第一歩だ。", "target_word": "相違", "complexity_tier": "T3", "furigana": "文化[ぶんか]の相違[そうい]を理解[りかい]することが、国際交流[こくさいこうりゅう]の第一歩[だいいっぽ]だ。", "sentence_source": "generated"}, {"text": "二つの会社の方針の相違が、合併の障害になった。", "target_word": "相違", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]の方針[ほうしん]の相違[そうい]が、合併[がっぺい]の障害[しょうがい]になった。", "sentence_source": "generated"}, {"text": "説明に相違がないことを、本人が署名して認めた。", "target_word": "相違", "complexity_tier": "T3", "furigana": "説明[せつめい]に相違[そうい]がないことを、本人[ほんにん]が署名[しょめい]して認[みと]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "相違", "label": "基本形"}, {"form": "相違する", "label": "サ変動詞"}, {"form": "相違ない", "label": "否定表現"}, {"form": "相違して", "label": "て形"}], "register": "formal", "sense_fingerprint": "物事の間に見られる違い、また一致しないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36451, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相違", "is_correct": true, "explanation": "計画と結果の食い違いを表し、「相違が生じた原因を調べる」と自然に続く。"}, {"text": "砂糖", "is_correct": false, "explanation": "計画と結果の間に生じるものとして成り立たない。"}, {"text": "寝坊", "is_correct": false, "explanation": "計画と結果の間に生じるものとして意味が通らない。"}, {"text": "電池", "is_correct": false, "explanation": "計画と結果の間に生じるものとして成り立たない。"}], "explanations": {"相違": "計画と結果の食い違いを表し、「相違が生じた原因を調べる」と自然に続く。", "砂糖": "計画と結果の間に生じるものとして成り立たない。", "寝坊": "計画と結果の間に生じるものとして意味が通らない。", "電池": "計画と結果の間に生じるものとして成り立たない。"}, "sentence_index": 0, "correct_answer": "相違"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱の相違は五キロだ。", "explanation": "ここは〈重さ〉の意味。重さは「重さ」と言い、相違は二つのものの違いを表す語なので合わない。"}, {"text": "この服の相違は青い。", "explanation": "ここは〈色〉の意味。色は「色」を使い、相違には色を表す用法がない。"}, {"text": "このクラスの相違は三十人だ。", "explanation": "ここは〈人数〉の意味。人数は「人数」と言い、相違は違いを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36451, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相違", "is_correct": true, "explanation": "数字の食い違いを表し、「数字に相違があった」と自然に続く。"}, {"text": "天気", "is_correct": false, "explanation": "数字に天気があったという文は意味が通らない。"}, {"text": "倉庫", "is_correct": false, "explanation": "数字の食い違いの文脈に倉庫は合わない。"}, {"text": "旅費", "is_correct": false, "explanation": "数字の食い違いとして意味が通らない。"}], "explanations": {"相違": "数字の食い違いを表し、「数字に相違があった」と自然に続く。", "天気": "数字に天気があったという文は意味が通らない。", "倉庫": "数字の食い違いの文脈に倉庫は合わない。", "旅費": "数字の食い違いとして意味が通らない。"}, "sentence_index": 6, "correct_answer": "相違"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人の答えは相違がぴったり合った。", "explanation": "ここは〈一致〉の意味。ぴったり合うことを表すのは一致で、相違は違いを指す語。"}, {"text": "この班の相違は全員一致している。", "explanation": "ここは〈一致〉の意味。相違を主語にして一致していると述べるのは矛盾し、相違は違いを表す語。"}, {"text": "会議では皆の相違がそろった。", "explanation": "ここは〈一致〉の意味。意見がそろう場合は一致を使い、相違はそろうものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36451, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "説明が記録を相違していた。", "corrected_sentence": "説明が記録と相違していた。", "error_description": "「相違する」は「と」をとる。「を」は誤りで、正しくは「記録と相違していた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36451, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "証言に相違を一つあった。", "corrected_sentence": "証言に相違が一つあった。", "error_description": "「ある」は主語に「が」をとる。「を」は誤りで、正しくは「相違が一つあった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36452, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「新しい制度が始まって」の「が」で、制度を主語にする文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「始まる」は自動詞なので目的語の「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「制度へ始まって」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「制度の始まって」は名詞修飾になり、文として成立しない。"}], "correct_answer": "が", "explanations": {"が": "「新しい制度が始まって」の「が」で、制度を主語にする文に合う。", "を": "「始まる」は自動詞なので目的語の「を」は使えない。", "へ": "「へ」は方向を表すので、「制度へ始まって」は意味が通らない。", "の": "「制度の始まって」は名詞修飾になり、文として成立しない。"}, "error_tags": {"を": "目的語の誤用", "へ": "方向", "の": "修飾の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36452, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「税金の制度が複雑なので」の「が」で、制度が複雑だという主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「税金の制度に複雑なので」は、複雑さを示す述語に「に」が付かず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「税金の制度と複雑なので」は並列にも述語の形にもならず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「税金の制度から複雑なので」は起点の「から」が合わず不自然。"}], "correct_answer": "が", "explanations": {"が": "「税金の制度が複雑なので」の「が」で、制度が複雑だという主語を示す。", "に": "「税金の制度に複雑なので」は、複雑さを示す述語に「に」が付かず不自然。", "と": "「税金の制度と複雑なので」は並列にも述語の形にもならず不自然。", "から": "「税金の制度から複雑なので」は起点の「から」が合わず不自然。"}, "error_tags": {"に": "述語との結びつきが不自然", "と": "並列の誤用", "から": "起点の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36452, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "決まったルールや仕組みのこと。", "primary_collocate": null, "pronunciation": "せいど", "ipa": "seːdo", "syllable_count": 3, "sentences": [{"text": "日本には、国民が病院で安く診察を受けられる制度がある。", "target_word": "制度", "complexity_tier": "T4", "furigana": "日本[にほん]には、国民[こくみん]が病院[びょういん]で安[やす]く診察[しんさつ]を受[う]けられる制度[せいど]がある。", "sentence_source": "generated"}, {"text": "新しい制度が始まって、手続きが簡単になった。", "target_word": "制度", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]が始[はじ]まって、手続[てつづ]きが簡単[かんたん]になった。", "sentence_source": "generated"}, {"text": "この制度は古すぎて、今の生活に合わなくなっている。", "target_word": "制度", "complexity_tier": "T3", "furigana": "この制度[せいど]は古[ふる]すぎて、今[いま]の生活[せいかつ]に合[あ]わなくなっている。", "sentence_source": "generated"}, {"text": "留学生のための奨学金制度を使ったので、学費の心配がなくなった。", "target_word": "制度", "complexity_tier": "T4", "furigana": "留学生[りゅうがくせい]のための奨学金[しょうがくきん]制度[せいど]を使[つか]ったので、学費[がくひ]の心配[しんぱい]がなくなった。", "sentence_source": "generated"}, {"text": "制度を変えるには、みんなの意見を聞く必要がある。", "target_word": "制度", "complexity_tier": "T3", "furigana": "制度[せいど]を変[か]えるには、みんなの意見[いけん]を聞[き]く必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "年金制度について、授業で調べた。", "target_word": "制度", "complexity_tier": "T2", "furigana": "年金[ねんきん]制度[せいど]について、授業[じゅぎょう]で調[しら]べた。", "sentence_source": "generated"}, {"text": "国によって、結婚の制度は大きく違う。", "target_word": "制度", "complexity_tier": "T3", "furigana": "国[くに]によって、結婚[けっこん]の制度[せいど]は大[おお]きく違[ちが]う。", "sentence_source": "generated"}, {"text": "税金の制度が複雑なので、専門家に相談した。", "target_word": "制度", "complexity_tier": "T3", "furigana": "税金[ぜいきん]の制度[せいど]が複雑[ふくざつ]なので、専門家[せんもんか]に相談[そうだん]した。", "sentence_source": "generated"}, {"text": "政府は、働き方を選べる制度を新しく作った。", "target_word": "制度", "complexity_tier": "T3", "furigana": "政府[せいふ]は、働[はたら]き方[かた]を選[えら]べる制度[せいど]を新[あたら]しく作[つく]った。", "sentence_source": "generated"}, {"text": "彼は制度の説明を読んで、申し込みの方法を理解した。", "target_word": "制度", "complexity_tier": "T3", "furigana": "彼[かれ]は制度[せいど]の説明[せつめい]を読[よ]んで、申[もう]し込[こ]みの方法[ほうほう]を理解[りかい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "制度", "label": "dictionary form"}, {"form": "制度の", "label": "attributive (の)"}, {"form": "制度を", "label": "object (を)"}], "register": "neutral", "sense_fingerprint": "社会や国で正式に定められた、決まりや仕組み(医療・年金・税などの制度)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36452, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制度", "is_correct": true, "explanation": "「病院で安く診察を受けられる制度」で、国が定めた仕組みを表し文に合う。"}, {"text": "財布", "is_correct": false, "explanation": "「診察を受けられる財布」は意味をなさない。財布は金銭を入れる入れ物。"}, {"text": "花壇", "is_correct": false, "explanation": "「診察を受けられる花壇」は意味が通らない。花壇は花を植える場所。"}, {"text": "雑誌", "is_correct": false, "explanation": "「診察を受けられる雑誌」は不自然。雑誌は定期的に出る出版物。"}], "explanations": {"制度": "「病院で安く診察を受けられる制度」で、国が定めた仕組みを表し文に合う。", "財布": "「診察を受けられる財布」は意味をなさない。財布は金銭を入れる入れ物。", "花壇": "「診察を受けられる花壇」は意味が通らない。花壇は花を植える場所。", "雑誌": "「診察を受けられる雑誌」は不自然。雑誌は定期的に出る出版物。"}, "sentence_index": 0, "correct_answer": "制度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は制度が豊富で、どんな機械でも直せる。", "explanation": "ここは〈技術〉の意味。制度は決まりや仕組みを指すので、腕前や能力を表す使い方はしないので合わない。"}, {"text": "この料理の制度を教えてください。", "explanation": "ここは〈方法〉の意味。制度は社会の決まりや仕組みで、料理の手順には使わないので合わない。"}, {"text": "彼は制度が明るく、いつも笑顔だ。", "explanation": "ここは〈性格〉の意味。制度は仕組みを指すので、人の性質には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36452, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制度", "is_correct": true, "explanation": "「結婚の制度は大きく違う」で、国ごとの決まりや仕組みの違いを表し文に合う。"}, {"text": "風船", "is_correct": false, "explanation": "「結婚の風船は大きく違う」は意味が通らない。風船は空気で膨らませるおもちゃ。"}, {"text": "果物", "is_correct": false, "explanation": "「結婚の果物は大きく違う」は不自然。果物は食べ物の一種。"}, {"text": "照明", "is_correct": false, "explanation": "「結婚の照明は大きく違う」は意味をなさない。照明は部屋を明るくする器具。"}], "explanations": {"制度": "「結婚の制度は大きく違う」で、国ごとの決まりや仕組みの違いを表し文に合う。", "風船": "「結婚の風船は大きく違う」は意味が通らない。風船は空気で膨らませるおもちゃ。", "果物": "「結婚の果物は大きく違う」は不自然。果物は食べ物の一種。", "照明": "「結婚の照明は大きく違う」は意味をなさない。照明は部屋を明るくする器具。"}, "sentence_index": 6, "correct_answer": "制度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日の制度は、午後から雨になる。", "explanation": "ここは〈天気〉の意味。制度は決まりや仕組みを指すので、空模様には使わないので合わない。"}, {"text": "映画の制度を書いて、友達に送った。", "explanation": "ここは〈感想〉の意味。制度は仕組みを指すので、映画に対する考えや印象には使わないので合わない。"}, {"text": "明日の制度は、もう決まっている。", "explanation": "ここは〈予定〉の意味。制度は社会の決まりを指すので、いつ何をするかの計画には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36452, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市の新しい制度を始まって、申し込みが増えた。", "corrected_sentence": "市の新しい制度が始まって、申し込みが増えた。", "error_description": "「始まる」は自動詞なので、主語に助詞「が」を使う。「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36452, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社の制度に作って、社員が働きやすくなった。", "corrected_sentence": "会社の制度を作って、社員が働きやすくなった。", "error_description": "「作る」は他動詞なので目的語に助詞「を」を使う。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36453, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「休暇制度が変わり」の「が」で、制度が変化する主語を示すのに合う。"}, {"text": "を", "is_correct": false, "explanation": "「変わる」は自動詞なので目的語の「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、変化の結果を示す「会社の休暇制度へ変わり」の形には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「休暇制度の変わり」は名詞修飾になり、文として成立しない。"}], "correct_answer": "が", "explanations": {"が": "「休暇制度が変わり」の「が」で、制度が変化する主語を示すのに合う。", "を": "「変わる」は自動詞なので目的語の「を」は使えない。", "へ": "「へ」は方向を表すので、変化の結果を示す「会社の休暇制度へ変わり」の形には合わない。", "の": "「休暇制度の変わり」は名詞修飾になり、文として成立しない。"}, "error_tags": {"を": "目的語の誤用", "へ": "方向", "の": "修飾の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
