INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36453, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会や組織を運営するための決まりやしくみ。例：学校の制度、会社の制度。", "primary_collocate": null, "pronunciation": "せいど", "ipa": "seːdo", "syllable_count": 3, "sentences": [{"text": "私の学校には、生徒が自由に部活を選べる制度がある。", "target_word": "制度", "complexity_tier": "T3", "furigana": "私[わたし]の学校[がっこう]には、生徒[せいと]が自由[じゆう]に部活[ぶかつ]を選[えら]べる制度[せいど]がある。", "sentence_source": "generated"}, {"text": "会社の休暇制度が変わり、社員は半日でも休めるようになった。", "target_word": "制度", "complexity_tier": "T4", "furigana": "会社[かいしゃ]の休暇[きゅうか]制度[せいど]が変[か]わり、社員[しゃいん]は半日[はんにち]でも休[やす]めるようになった。", "sentence_source": "generated"}, {"text": "新しい評価制度に、社員から不満の声が出ている。", "target_word": "制度", "complexity_tier": "T3", "furigana": "新[あたら]しい評価[ひょうか]制度[せいど]に、社員[しゃいん]から不満[ふまん]の声[こえ]が出[で]ている。", "sentence_source": "generated"}, {"text": "この町の図書館には、本を予約する制度がある。", "target_word": "制度", "complexity_tier": "T3", "furigana": "この町[まち]の図書館[としょかん]には、本[ほん]を予約[よやく]する制度[せいど]がある。", "sentence_source": "generated"}, {"text": "教育制度の違いで、留学前に必要な書類が変わる。", "target_word": "制度", "complexity_tier": "T4", "furigana": "教育[きょういく]制度[せいど]の違[ちが]いで、留学前[りゅうがくまえ]に必要[ひつよう]な書類[しょるい]が変[か]わる。", "sentence_source": "generated"}, {"text": "学校の制度が変わったので、来年から制服は自由になる。", "target_word": "制度", "complexity_tier": "T3", "furigana": "学校[がっこう]の制度[せいど]が変[か]わったので、来年[らいねん]から制服[せいふく]は自由[じゆう]になる。", "sentence_source": "generated"}, {"text": "会社の制度として、毎年一回、健康診断を受けることになっている。", "target_word": "制度", "complexity_tier": "T4", "furigana": "会社[かいしゃ]の制度[せいど]として、毎年[まいとし]一回[いっかい]、健康[けんこう]診断[しんだん]を受[う]けることになっている。", "sentence_source": "generated"}, {"text": "市は、子育てを支える新しい制度を作った。", "target_word": "制度", "complexity_tier": "T3", "furigana": "市[し]は、子育[こそだ]てを支[ささ]える新[あたら]しい制度[せいど]を作[つく]った。", "sentence_source": "generated"}, {"text": "古い制度のままでは、組織はうまく動かない。", "target_word": "制度", "complexity_tier": "T3", "furigana": "古[ふる]い制度[せいど]のままでは、組織[そしき]はうまく動[うご]かない。", "sentence_source": "generated"}, {"text": "制度が整っているから、新入社員も安心して働ける。", "target_word": "制度", "complexity_tier": "T3", "furigana": "制度[せいど]が整[ととの]っているから、新入[しんにゅう]社員[しゃいん]も安心[あんしん]して働[はたら]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "制度", "label": "dictionary form"}, {"form": "制度の", "label": "attributive (の)"}, {"form": "制度が", "label": "subject (が)"}], "register": "neutral", "sense_fingerprint": "学校・会社・市など組織を動かすために設けられた、運営上の決まりと仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2b6ffcd-146d-4568-8e44-7323c72186a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36453, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制度", "is_correct": true, "explanation": "「部活を選べる制度がある」で、学校が定めた仕組みを表し文に合う。"}, {"text": "花瓶", "is_correct": false, "explanation": "「部活を選べる花瓶がある」は意味をなさない。花瓶は花を生ける器。"}, {"text": "果物", "is_correct": false, "explanation": "「部活を選べる果物がある」は意味が通らない。果物は食べ物の一種。"}, {"text": "照明", "is_correct": false, "explanation": "「部活を選べる照明がある」は不自然。照明は部屋を明るくする器具。"}], "explanations": {"制度": "「部活を選べる制度がある」で、学校が定めた仕組みを表し文に合う。", "花瓶": "「部活を選べる花瓶がある」は意味をなさない。花瓶は花を生ける器。", "果物": "「部活を選べる果物がある」は意味が通らない。果物は食べ物の一種。", "照明": "「部活を選べる照明がある」は不自然。照明は部屋を明るくする器具。"}, "sentence_index": 0, "correct_answer": "制度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は怒りの制度を強くもっていた。", "explanation": "ここは〈感情〉の意味。制度は決まりや仕組みを指すので、気持ちの強さには使わないので合わない。"}, {"text": "このスープの制度は濃くて、飲みにくい。", "explanation": "ここは〈味〉の意味。制度は仕組みを指すので、料理の味の濃さには使わないので合わない。"}, {"text": "学校までの制度は、歩いて三十分だ。", "explanation": "ここは〈距離〉の意味。制度は決まりや仕組みを指すので、場所の離れ具合には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36453, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制度", "is_correct": true, "explanation": "「会社の制度として、健康診断を受ける」で、会社が定めた決まりを表し文に合う。"}, {"text": "絵画", "is_correct": false, "explanation": "「会社の絵画として、健康診断を受ける」は意味をなさない。絵画は絵の作品。"}, {"text": "家具", "is_correct": false, "explanation": "「会社の家具として、健康診断を受ける」は意味が通らない。家具は生活に使う道具。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "「会社の歯ブラシとして、健康診断を受ける」は不自然。歯ブラシは歯を磨く道具。"}], "explanations": {"制度": "「会社の制度として、健康診断を受ける」で、会社が定めた決まりを表し文に合う。", "絵画": "「会社の絵画として、健康診断を受ける」は意味をなさない。絵画は絵の作品。", "家具": "「会社の家具として、健康診断を受ける」は意味が通らない。家具は生活に使う道具。", "歯ブラシ": "「会社の歯ブラシとして、健康診断を受ける」は不自然。歯ブラシは歯を磨く道具。"}, "sentence_index": 6, "correct_answer": "制度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の制度は派手で、いつも目立つ。", "explanation": "ここは〈服装〉の意味。制度は決まりや仕組みを指すので、身なりの派手さには使わないので合わない。"}, {"text": "この文章の制度が整っていて、読みやすい。", "explanation": "ここは〈構成〉の意味。制度は社会の決まりや仕組みを指すので、文章の組み立てには使わないので合わない。"}, {"text": "体の制度が整っているから、元気に過ごせる。", "explanation": "ここは〈体調〉の意味。制度は仕組みを指すので、体の状態には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36453, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校の評価制度を変わり、生徒の成績が見やすくなった。", "corrected_sentence": "学校の評価制度が変わり、生徒の成績が見やすくなった。", "error_description": "「変わる」は自動詞なので、主語に助詞「が」を使う。「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36453, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校は、生徒の意見を聞く制度を変わった。", "corrected_sentence": "学校は、生徒の意見を聞く制度を変えた。", "error_description": "「制度を変える」は他動詞の形。「変わった」は自動詞なので、目的語を取る文には合わない。正しくは「変えた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c24c39f1-7f21-48ee-8610-84159302fd25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
