INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36454, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "法律（ほうりつ）にかんすること。", "primary_collocate": null, "pronunciation": "ほうてき", "ipa": "hoːteki", "syllable_count": 4, "sentences": [{"text": "これは法的な問題だから、弁護士に相談する。", "target_word": "法的", "complexity_tier": "T3", "furigana": "これは法的[ほうてき]な問題[もんだい]だから、弁護士[べんごし]に相談[そうだん]する。", "sentence_source": "generated"}, {"text": "会社は法的な責任を負うことになった。", "target_word": "法的", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は法的[ほうてき]な責任[せきにん]を負[お]うことになった。", "sentence_source": "generated"}, {"text": "法的に見ると、この契約は正しくない。", "target_word": "法的", "complexity_tier": "T3", "furigana": "法的[ほうてき]に見[み]ると、この契約[けいやく]は正[ただ]しくない。", "sentence_source": "generated"}, {"text": "彼女は法的な知識が豊富で、よく相談を受ける。", "target_word": "法的", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は法的[ほうてき]な知識[ちしき]が豊富[ほうふ]で、よく相談[そうだん]を受[う]ける。", "sentence_source": "generated"}, {"text": "法的な手続きには、時間がかかる。", "target_word": "法的", "complexity_tier": "T3", "furigana": "法的[ほうてき]な手続[てつづ]きには、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "この書類には法的な意味はない。", "target_word": "法的", "complexity_tier": "T3", "furigana": "この書類[しょるい]には法的[ほうてき]な意味[いみ]はない。", "sentence_source": "generated"}, {"text": "法的な助けが必要な人のために、無料の窓口がある。", "target_word": "法的", "complexity_tier": "T3", "furigana": "法的[ほうてき]な助[たす]けが必要[ひつよう]な人[ひと]のために、無料[むりょう]の窓口[まどぐち]がある。", "sentence_source": "generated"}, {"text": "兄は法的なことを学ぶために大学へ行った。", "target_word": "法的", "complexity_tier": "T3", "furigana": "兄[あに]は法的[ほうてき]なことを学[まな]ぶために大学[だいがく]へ行[い]った。", "sentence_source": "generated"}, {"text": "法的には問題がないが、道徳的には問題がある。", "target_word": "法的", "complexity_tier": "T3", "furigana": "法的[ほうてき]には問題[もんだい]がないが、道徳的[どうとくてき]には問題[もんだい]がある。", "sentence_source": "generated"}, {"text": "法的な問題が起こる前に、規則を確認しよう。", "target_word": "法的", "complexity_tier": "T3", "furigana": "法的[ほうてき]な問題[もんだい]が起[お]こる前[まえ]に、規則[きそく]を確認[かくにん]しよう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "法的", "label": "語幹"}, {"form": "法的な", "label": "連体形"}, {"form": "法的に", "label": "連用形"}, {"form": "法的だ", "label": "断定形"}], "register": "中立（普通体）", "sense_fingerprint": "法律に関わる問題・知識・責任などの性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36454, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法的", "is_correct": true, "explanation": "形状詞の語幹で、「〜な問題」の形に入り、法律に関する問題という文の内容に合う。"}, {"text": "法的じゃ", "is_correct": false, "explanation": "語幹の不完全な形で、「問題」と続かず、文が成立しない。"}, {"text": "法的だ", "is_correct": false, "explanation": "断定形で、「問題」の前に続けると文法的に成立しない。"}, {"text": "法的さ", "is_correct": false, "explanation": "名詞化した形で、「問題」を直接修飾できず、文が成立しない。"}], "explanations": {"法的": "形状詞の語幹で、「〜な問題」の形に入り、法律に関する問題という文の内容に合う。", "法的じゃ": "語幹の不完全な形で、「問題」と続かず、文が成立しない。", "法的だ": "断定形で、「問題」の前に続けると文法的に成立しない。", "法的さ": "名詞化した形で、「問題」を直接修飾できず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "法的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は言い争いのあと、法的に怒りを爆発させた。", "explanation": "法的は法律に関することなので、怒りに任せて爆発する様子には合わない。"}, {"text": "彼とは法的に親しい間柄だ。", "explanation": "法的は法律上のことなので、人との親しさを表す文には合わない。"}, {"text": "彼女は法的な笑顔で客を迎えた。", "explanation": "法的は法律に関することなので、笑顔の印象を表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36454, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法的", "is_correct": true, "explanation": "形状詞の語幹で、「法的な助け」の形になり、法律に関する助けという文の内容に合う。"}, {"text": "法外", "is_correct": false, "explanation": "〈常識を超えた〉の意味で、無料の窓口の文脈と合わない。"}, {"text": "不法", "is_correct": false, "explanation": "〈法律に反する〉の意味で、無料の窓口を説明する文と合わない。"}, {"text": "無法", "is_correct": false, "explanation": "〈法がない状態〉の意味で、窓口の説明とは合わない。"}], "explanations": {"法的": "形状詞の語幹で、「法的な助け」の形になり、法律に関する助けという文の内容に合う。", "法外": "〈常識を超えた〉の意味で、無料の窓口の文脈と合わない。", "不法": "〈法律に反する〉の意味で、無料の窓口を説明する文と合わない。", "無法": "〈法がない状態〉の意味で、窓口の説明とは合わない。"}, "sentence_index": 6, "correct_answer": "法的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は会議で、法的な挨拶だけをして席に戻った。", "explanation": "法的は法律に関することなので、型どおりの挨拶という意味には合わない。"}, {"text": "彼女は法的な料理を用意した。", "explanation": "法的は法律に関する意味なので、料理の豪華さを表す文には合わない。"}, {"text": "夕焼けが、法的な赤で空を染めた。", "explanation": "法的は法律に関することなので、色の鮮やかさを表す文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36454, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その契約は法的から有効だ。", "corrected_sentence": "その契約は法的に有効だ。", "error_description": "「法的に」の「に」が正しい。「から」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "法的", "is_correct": true, "explanation": "語幹で、後ろの「な」を続けると「法的な責任」となり、文の内容に合う。"}, {"text": "法的じゃ", "is_correct": false, "explanation": "語幹の不完全な形で、「責任」と続かず、文が成立しない。"}, {"text": "法的だ", "is_correct": false, "explanation": "断定形で、後ろの「な責任」と続かず、文が成立しない。"}, {"text": "法的さ", "is_correct": false, "explanation": "名詞化した形で、「責任」を直接修飾できず、文が成立しない。"}], "correct_form": "法的", "base_form": "法的", "form_label": "語幹", "sentence_index": 1, "explanations": {"法的": "語幹で、後ろの「な」を続けると「法的な責任」となり、文の内容に合う。", "法的じゃ": "語幹の不完全な形で、「責任」と続かず、文が成立しない。", "法的だ": "断定形で、後ろの「な責任」と続かず、文が成立しない。", "法的さ": "名詞化した形で、「責任」を直接修飾できず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36454, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この件は法的だ問題がある。", "corrected_sentence": "この件は法的な問題がある。", "error_description": "名詞の前には「な」を使う。「だ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "法的", "is_correct": true, "explanation": "語幹で、後ろの「な」を続けると「法的なこと」となり、学ぶ対象を説明する文に合う。"}, {"text": "法的な", "is_correct": false, "explanation": "連体形で、後ろの「な」と重なり「法的なな」となって成立しない。"}, {"text": "法的じゃ", "is_correct": false, "explanation": "語幹の不完全な形で、「こと」と続かず、名詞句として成立しない。"}, {"text": "法的で", "is_correct": false, "explanation": "て形で、「こと」と続かず、名詞句として成立しない。"}], "correct_form": "法的", "base_form": "法的", "form_label": "語幹", "sentence_index": 7, "explanations": {"法的": "語幹で、後ろの「な」を続けると「法的なこと」となり、学ぶ対象を説明する文に合う。", "法的な": "連体形で、後ろの「な」と重なり「法的なな」となって成立しない。", "法的じゃ": "語幹の不完全な形で、「こと」と続かず、名詞句として成立しない。", "法的で": "て形で、「こと」と続かず、名詞句として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
