INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36455, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "法律に関係するさま。法律に基づいている、または法律で定められていること。", "primary_collocate": null, "pronunciation": "ほうてき", "ipa": "hoːteki", "syllable_count": 4, "sentences": [{"text": "この年齢から選挙に行けるのは、法的に決まっている。", "target_word": "法的", "complexity_tier": "T3", "furigana": "この年齢[ねんれい]から選挙[せんきょ]に行[い]けるのは、法的[ほうてき]に決[き]まっている。", "sentence_source": "generated"}, {"text": "十八歳になると、法的には大人として扱われる。", "target_word": "法的", "complexity_tier": "T3", "furigana": "十八歳[じゅうはっさい]になると、法的[ほうてき]には大人[おとな]として扱[あつか]われる。", "sentence_source": "generated"}, {"text": "法的な効力のある書類には、必ず印をおす。", "target_word": "法的", "complexity_tier": "T3", "furigana": "法的[ほうてき]な効力[こうりょく]のある書類[しょるい]には、必[かなら]ず印[いん]をおす。", "sentence_source": "generated"}, {"text": "結婚は法的に認められた関係だ。", "target_word": "法的", "complexity_tier": "T3", "furigana": "結婚[けっこん]は法的[ほうてき]に認[みと]められた関係[かんけい]だ。", "sentence_source": "generated"}, {"text": "会社の法的な義務として、社員の健康診断を行う。", "target_word": "法的", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の法的[ほうてき]な義務[ぎむ]として、社員[しゃいん]の健康診断[けんこうしんだん]を行[おこな]う。", "sentence_source": "generated"}, {"text": "法的な根拠がないので、この罰金は無効だ。", "target_word": "法的", "complexity_tier": "T3", "furigana": "法的[ほうてき]な根拠[こんきょ]がないので、この罰金[ばっきん]は無効[むこう]だ。", "sentence_source": "generated"}, {"text": "国は法的に決められた税金を集めている。", "target_word": "法的", "complexity_tier": "T3", "furigana": "国[くに]は法的[ほうてき]に決[き]められた税金[ぜいきん]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "法的に許されている範囲で、商売を広げる。", "target_word": "法的", "complexity_tier": "T3", "furigana": "法的[ほうてき]に許[ゆる]されている範囲[はんい]で、商売[しょうばい]を広[ひろ]げる。", "sentence_source": "generated"}, {"text": "彼らは法的な手段で、土地を取り戻そうとした。", "target_word": "法的", "complexity_tier": "T3", "furigana": "彼[かれ]らは法的[ほうてき]な手段[しゅだん]で、土地[とち]を取[と]り戻[もど]そうとした。", "sentence_source": "generated"}, {"text": "約束だけでは、法的な拘束力は持たない。", "target_word": "法的", "complexity_tier": "T3", "furigana": "約束[やくそく]だけでは、法的[ほうてき]な拘束力[こうそくりょく]は持[も]たない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "法的", "label": "語幹"}, {"form": "法的な", "label": "連体形"}, {"form": "法的に", "label": "連用形"}, {"form": "法的だ", "label": "断定形"}], "register": "中立（普通体）", "sense_fingerprint": "法律に基づく、または法律で定められているさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36455, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法的", "is_correct": true, "explanation": "形状詞の語幹で、「に決まっている」の前に入り、法律で定められているという文の内容に合う。"}, {"text": "法的な", "is_correct": false, "explanation": "連体形のため、「に決まっている」の前に続けると文法的に成立しない。"}, {"text": "法的だ", "is_correct": false, "explanation": "断定形のため、「に決まっている」の前に続けると不自然で成立しない。"}, {"text": "法的で", "is_correct": false, "explanation": "て形のため、「に決まっている」の前に続けると文法的に成立しない。"}], "explanations": {"法的": "形状詞の語幹で、「に決まっている」の前に入り、法律で定められているという文の内容に合う。", "法的な": "連体形のため、「に決まっている」の前に続けると文法的に成立しない。", "法的だ": "断定形のため、「に決まっている」の前に続けると不自然で成立しない。", "法的で": "て形のため、「に決まっている」の前に続けると文法的に成立しない。"}, "sentence_index": 0, "correct_answer": "法的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の努力は、法的にほめられた。", "explanation": "ここは〈評価される〉（人の努力を認める）の意味。法的は法律上のことなので、努力への評価には使わない。"}, {"text": "その説は、法的に大胆だ。", "explanation": "ここは〈斬新〉（今までにない新しさ）の意味。法的は法律上のことなので、説の新しさには使わない。"}, {"text": "その作品は、法的に表現された。", "explanation": "ここは〈芸術的〉（美的な感性による）の意味。法的は法律に関することなので、作品の作り方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36455, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法的", "is_correct": true, "explanation": "形状詞の語幹で、「に決められた」の前に入り、法律で定められた税金という文の内容に合う。"}, {"text": "法外", "is_correct": false, "explanation": "〈常識を超えた〉の意味で、税金が法律で定められたという文脈と合わない。"}, {"text": "不法", "is_correct": false, "explanation": "〈法律に反する〉の意味で、法律で定めた税金の文と合わない。"}, {"text": "無法", "is_correct": false, "explanation": "〈法がない状態〉の意味で、法律に基づく税金の文と合わない。"}], "explanations": {"法的": "形状詞の語幹で、「に決められた」の前に入り、法律で定められた税金という文の内容に合う。", "法外": "〈常識を超えた〉の意味で、税金が法律で定められたという文脈と合わない。", "不法": "〈法律に反する〉の意味で、法律で定めた税金の文と合わない。", "無法": "〈法がない状態〉の意味で、法律に基づく税金の文と合わない。"}, "sentence_index": 6, "correct_answer": "法的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の言葉は、法的に温かかった。", "explanation": "ここは〈心が和む〉（気持ちがやわらぐ）の意味。法的は法律上のことなので、言葉が人の心に与える効果には使わない。"}, {"text": "その政策は、法的に劇的な変化をもたらした。", "explanation": "ここは〈急激〉（急に大きく変わる）の意味。法的は法律に関することなので、変化の激しさを表す文には合わない。"}, {"text": "彼は一人で、法的に世界を旅している。", "explanation": "ここは〈自由に〉（しばられずに）の意味。法的は法律に関することなので、旅のしかたを表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36455, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬は法的で認められている。", "corrected_sentence": "この薬は法的に認められている。", "error_description": "「認められている」を修飾するには副詞形「法的に」を使う。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "法的", "is_correct": true, "explanation": "語幹の形で、「法的には」として法律上の扱いを述べる文に合う。"}, {"text": "法的な", "is_correct": false, "explanation": "連体形で、「には」に続く形にならず、文の形と合わない。"}, {"text": "法的に", "is_correct": false, "explanation": "副詞形で、「には」と重なるため、文の形と合わない。"}, {"text": "法的だ", "is_correct": false, "explanation": "断定形で、「には」に続かず、文の形と合わない。"}], "correct_form": "法的", "base_form": "法的", "form_label": "語幹", "sentence_index": 1, "explanations": {"法的": "語幹の形で、「法的には」として法律上の扱いを述べる文に合う。", "法的な": "連体形で、「には」に続く形にならず、文の形と合わない。", "法的に": "副詞形で、「には」と重なるため、文の形と合わない。", "法的だ": "断定形で、「には」に続かず、文の形と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36455, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その契約は法的を無効だ。", "corrected_sentence": "その契約は法的に無効だ。", "error_description": "「無効だ」を修飾するには副詞形「法的に」を使う。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "法的だった", "is_correct": false, "explanation": "過去の断定形で、「に許されている」と続かず、文が成立しない。"}, {"text": "法的ではない", "is_correct": false, "explanation": "否定形で、「に許されている」と続かず、文の形と合わない。"}, {"text": "法的で", "is_correct": false, "explanation": "て形で、「に許されている」と続かず、文が成立しない。"}, {"text": "法的", "is_correct": true, "explanation": "語幹で、後ろの「に」を続けると「法的に許されている」となり、許容の範囲を述べる文に合う。"}], "correct_form": "法的", "base_form": "法的", "form_label": "語幹", "sentence_index": 7, "explanations": {"法的だった": "過去の断定形で、「に許されている」と続かず、文が成立しない。", "法的ではない": "否定形で、「に許されている」と続かず、文の形と合わない。", "法的で": "て形で、「に許されている」と続かず、文が成立しない。", "法的": "語幹で、後ろの「に」を続けると「法的に許されている」となり、許容の範囲を述べる文に合う。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36456, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36456, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「やぶる」の対象を示す〈を〉で、「契約をやぶると」が自然。"}, {"text": "と", "is_correct": false, "explanation": "「契約と破る」は並べる意味にならず、対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「契約の破ると」は所有の形で、「やぶる」の対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "「契約から破る」は起点の意味になり、対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「やぶる」の対象を示す〈を〉で、「契約をやぶると」が自然。", "と": "「契約と破る」は並べる意味にならず、対象を示せない。", "の": "「契約の破ると」は所有の形で、「やぶる」の対象にならない。", "から": "「契約から破る」は起点の意味になり、対象にはならない。"}, "error_tags": {"と": "並列", "の": "所有", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36456, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人と人の間で、こういうことをしますと約束することです。", "primary_collocate": null, "pronunciation": "けいやく", "ipa": "keːjakɯ", "syllable_count": 4, "sentences": [{"text": "新しい携帯電話の契約をしに、店へ行った。", "target_word": "契約", "complexity_tier": "T3", "furigana": "新[あたら]しい携帯電話[けいたいでんわ]の契約[けいやく]をしに、店[みせ]へ行[い]った。", "sentence_source": "generated"}, {"text": "部屋を借りるとき、大家さんと契約を結んだ。", "target_word": "契約", "complexity_tier": "T3", "furigana": "部屋[へや]を借[か]りるとき、大家[おおや]さんと契約[けいやく]を結[むす]んだ。", "sentence_source": "generated"}, {"text": "契約の日に、はんこを持っていくのを忘れた。", "target_word": "契約", "complexity_tier": "T3", "furigana": "契約[けいやく]の日[ひ]に、はんこを持[も]っていくのを忘[わす]れた。", "sentence_source": "generated"}, {"text": "インターネットの契約を変えたら、料金が安くなった。", "target_word": "契約", "complexity_tier": "T3", "furigana": "インターネットの契約[けいやく]を変[か]えたら、料金[りょうきん]が安[やす]くなった。", "sentence_source": "generated"}, {"text": "ジムの契約は、一年ごとに更新する。", "target_word": "契約", "complexity_tier": "T3", "furigana": "ジムの契約[けいやく]は、一年[いちねん]ごとに更新[こうしん]する。", "sentence_source": "generated"}, {"text": "契約する前に、料金をよく確かめた。", "target_word": "契約", "complexity_tier": "T3", "furigana": "契約[けいやく]する前[まえ]に、料金[りょうきん]をよく確[たし]かめた。", "sentence_source": "generated"}, {"text": "母は新聞の契約をやめることにした。", "target_word": "契約", "complexity_tier": "T3", "furigana": "母[はは]は新聞[しんぶん]の契約[けいやく]をやめることにした。", "sentence_source": "generated"}, {"text": "契約をやぶると、お金を払わなければならない。", "target_word": "契約", "complexity_tier": "T3", "furigana": "契約[けいやく]をやぶると、お金[かね]を払[はら]わなければならない。", "sentence_source": "generated"}, {"text": "駐車場を契約したので、車を置けるようになった。", "target_word": "契約", "complexity_tier": "T3", "furigana": "駐車場[ちゅうしゃじょう]を契約[けいやく]したので、車[くるま]を置[お]けるようになった。", "sentence_source": "generated"}, {"text": "店との契約の手続きに遅れてしまい、担当者に謝った。", "target_word": "契約", "complexity_tier": "T3", "furigana": "店[みせ]との契約[けいやく]の手続[てつづ]きに遅[おく]れてしまい、担当者[たんとうしゃ]に謝[あやま]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "契約する", "label": "辞書形"}, {"form": "契約した", "label": "過去形"}, {"form": "契約して", "label": "て形"}, {"form": "契約しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "日常生活でサービスや部屋などについて約束を交わすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 借りる (Zipf 3.86), 大家 (Zipf 3.66), 結ん (Zipf 3.96)','sentence 7 above tier T1: contains vocabulary far above tier T1: やぶる (Zipf 1.95)']::text[], '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36456, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "契約", "is_correct": true, "explanation": "携帯電話の利用について取り決めを結ぶ〈契約〉で、「契約をしに」が自然に成り立つ。"}, {"text": "散歩", "is_correct": false, "explanation": "「携帯電話の散歩」は成り立たず、文の空欄に入らない。"}, {"text": "旅行", "is_correct": false, "explanation": "「携帯電話の旅行をしに」は意味が通らない。"}, {"text": "運動", "is_correct": false, "explanation": "「携帯電話の運動」は成り立たず、契約の代わりにならない。"}], "explanations": {"契約": "携帯電話の利用について取り決めを結ぶ〈契約〉で、「契約をしに」が自然に成り立つ。", "散歩": "「携帯電話の散歩」は成り立たず、文の空欄に入らない。", "旅行": "「携帯電話の旅行をしに」は意味が通らない。", "運動": "「携帯電話の運動」は成り立たず、契約の代わりにならない。"}, "sentence_index": 0, "correct_answer": "契約"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "選挙で、政治家が契約を掲げた。", "explanation": "ここは〈公約〉の意味。選挙で示す将来の約束は公約で、契約を掲げるとは言わない。"}, {"text": "店は、ぬれた床の損害賠償を契約した。", "explanation": "ここは〈請求〉の意味。権利として金銭を求める行為は請求で、契約では表せない。"}, {"text": "面接で、自分の長所を契約した。", "explanation": "ここは〈説明〉の意味。相手に事情を伝える行為は説明で、契約の意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36456, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "契約", "is_correct": true, "explanation": "新聞の購読について結ぶ取り決めを指し、「契約をやめる」と合う。"}, {"text": "練習", "is_correct": false, "explanation": "「新聞の練習をやめる」は成り立たない。"}, {"text": "料理", "is_correct": false, "explanation": "「新聞の料理」は意味が通らない。"}, {"text": "掃除", "is_correct": false, "explanation": "「新聞の掃除」は契約の代わりにならず、やめる対象として不自然。"}], "explanations": {"契約": "新聞の購読について結ぶ取り決めを指し、「契約をやめる」と合う。", "練習": "「新聞の練習をやめる」は成り立たない。", "料理": "「新聞の料理」は意味が通らない。", "掃除": "「新聞の掃除」は契約の代わりにならず、やめる対象として不自然。"}, "sentence_index": 6, "correct_answer": "契約"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "役所に、住民票の契約を出した。", "explanation": "ここは〈申請〉の意味。役所へ書類で手続きを求めるのは申請で、取り決めを結ぶ契約とは合わない。"}, {"text": "レストランで、料理の契約を済ませた。", "explanation": "ここは〈注文〉の意味。料理を頼む行為は注文で、継続する取り決めを表す契約とは合わない。"}, {"text": "二人は話し合いで、結論に契約した。", "explanation": "ここは〈合意〉の意味。話し合いで意見が一致することは合意で、契約とは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36456, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "携帯電話の契約が変えたので、料金が安くなった。", "corrected_sentence": "携帯電話の契約を変えたので、料金が安くなった。", "error_description": "「変える」は「を」で対象を示す。「契約が」と書くと主語のように読まれ、目的語の欠けた誤りになる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36456, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先月から母は、新聞の契約をやめるにした。", "corrected_sentence": "先月から母は、新聞の契約をやめることにした。", "error_description": "「～ことにした」の形を取るべきところを「～るにした」と誤った形にしている。「やめる」の連体形と「こと」の組み合わせが必要になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
