INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36457, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「契約を解除する」の「を」。解除するの目的語になる正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「解除する」は他動詞なので、主語の「が」を置くと文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「契約に解除する」は目的語を示す助詞として誤り。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、解除の対象を示す位置に合わない。"}], "correct_answer": "を", "explanations": {"を": "「契約を解除する」の「を」。解除するの目的語になる正しい助詞。", "が": "「解除する」は他動詞なので、主語の「が」を置くと文が成り立たない。", "に": "「契約に解除する」は目的語を示す助詞として誤り。", "へ": "方向を表す「へ」は、解除の対象を示す位置に合わない。"}, "error_tags": {"が": "主語（他動詞と不一致）", "に": "位置・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36457, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二者以上の間で、法的な効力を持つ約束や取り決めをすること。また、その文書。", "primary_collocate": null, "pronunciation": "けいやく", "ipa": "keːjakɯ", "syllable_count": 4, "sentences": [{"text": "両社は、三年間の契約を結んだ。", "target_word": "契約", "complexity_tier": "T3", "furigana": "両社[りょうしゃ]は、三年間[さんねんかん]の契約[けいやく]を結[むす]んだ。", "sentence_source": "generated"}, {"text": "契約にサインする前に、弁護士が内容を確認した。", "target_word": "契約", "complexity_tier": "T3", "furigana": "契約[けいやく]にサインする前[まえ]に、弁護士[べんごし]が内容[ないよう]を確認[かくにん]した。", "sentence_source": "generated"}, {"text": "契約の期間が終わったら、更新するかどうかを決める。", "target_word": "契約", "complexity_tier": "T3", "furigana": "契約[けいやく]の期間[きかん]が終[お]わったら、更新[こうしん]するかどうかを決[き]める。", "sentence_source": "generated"}, {"text": "彼は契約に反して、情報を外部に漏らした。", "target_word": "契約", "complexity_tier": "T3", "furigana": "彼[かれ]は契約[けいやく]に反[はん]して、情報[じょうほう]を外部[がいぶ]に漏[も]らした。", "sentence_source": "generated"}, {"text": "この契約は、双方の同意がなければ変更できない。", "target_word": "契約", "complexity_tier": "T3", "furigana": "この契約[けいやく]は、双方[そうほう]の同意[どうい]がなければ変更[へんこう]できない。", "sentence_source": "generated"}, {"text": "会社は新しい選手と二年の契約を交わした。", "target_word": "契約", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい選手[せんしゅ]と二年[にねん]の契約[けいやく]を交[か]わした。", "sentence_source": "generated"}, {"text": "契約が成立し、工事が始まった。", "target_word": "契約", "complexity_tier": "T3", "furigana": "契約[けいやく]が成立[せいりつ]し、工事[こうじ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "この契約を解除するには、一か月前に連絡が必要だ。", "target_word": "契約", "complexity_tier": "T3", "furigana": "この契約[けいやく]を解除[かいじょ]するには、一[いっ]か月前[げつまえ]に連絡[れんらく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "契約の内容に不明な点があり、説明を求めた。", "target_word": "契約", "complexity_tier": "T3", "furigana": "契約[けいやく]の内容[ないよう]に不明[ふめい]な点[てん]があり、説明[せつめい]を求[もと]めた。", "sentence_source": "generated"}, {"text": "この契約の原本は、会社の金庫に大切に保管されている。", "target_word": "契約", "complexity_tier": "T3", "furigana": "この契約[けいやく]の原本[げんぽん]は、会社[かいしゃ]の金庫[きんこ]に大切[たいせつ]に保管[ほかん]されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "契約する", "label": "辞書形"}, {"form": "契約した", "label": "過去形"}, {"form": "契約して", "label": "て形"}, {"form": "契約しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "法的効力を持つ取り決め・契約書", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36457, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "契約", "is_correct": true, "explanation": "「三年間の契約を結ぶ」の形で、法的な取り決めを指す「契約」が入る。"}, {"text": "会議", "is_correct": false, "explanation": "会議は開くもので、契約を結ぶ対象にはならないので合わない。"}, {"text": "報告", "is_correct": false, "explanation": "報告は知らせるもので、結んで成立させるものではないので合わない。"}, {"text": "広告", "is_correct": false, "explanation": "広告は出すもので、契約を結ぶ対象にはならないので合わない。"}], "explanations": {"契約": "「三年間の契約を結ぶ」の形で、法的な取り決めを指す「契約」が入る。", "会議": "会議は開くもので、契約を結ぶ対象にはならないので合わない。", "報告": "報告は知らせるもので、結んで成立させるものではないので合わない。", "広告": "広告は出すもので、契約を結ぶ対象にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "契約"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カフェでアイスコーヒーを契約した。", "explanation": "ここは〈注文〉の意味。飲み物を頼むのは注文で、契約は法的効力のある取り決めを指すので合わない。"}, {"text": "来週の美容院の席を、三日前に契約しておいた。", "explanation": "ここは〈予約〉の意味。席を前もって取るのは予約で、契約は法的な取り決めを指すので合わない。"}, {"text": "友だちと、来週いっしょに映画を見に行く契約をした。", "explanation": "ここは〈約束〉の意味。法的効力のない私的な約束に契約は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36457, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "契約", "is_correct": true, "explanation": "「契約が成立する」で、取り決めがまとまるという意味になるので合う。"}, {"text": "検査", "is_correct": false, "explanation": "検査は行うもので、「検査が成立する」とは言わないので合わない。"}, {"text": "通知", "is_correct": false, "explanation": "通知は届くもので、成立するものではないので合わない。"}, {"text": "点検", "is_correct": false, "explanation": "点検は行うもので、「点検が成立する」という言い方はしないので合わない。"}], "explanations": {"契約": "「契約が成立する」で、取り決めがまとまるという意味になるので合う。", "検査": "検査は行うもので、「検査が成立する」とは言わないので合わない。", "通知": "通知は届くもので、成立するものではないので合わない。", "点検": "点検は行うもので、「点検が成立する」という言い方はしないので合わない。"}, "sentence_index": 6, "correct_answer": "契約"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎月の給料の一部を、契約しておいた。", "explanation": "ここは〈貯金〉の意味。お金をためるのは貯金で、契約は取り決めを結ぶことを指すので合わない。"}, {"text": "大切な写真を、パソコンに契約しておいた。", "explanation": "ここは〈保存〉の意味。データを残すのは保存で、契約とは言えないので合わない。"}, {"text": "雨で中止になった遠足を、先生が来週に契約した。", "explanation": "ここは〈延期〉の意味。日程を後ろにずらすのは延期で、契約とは言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36457, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は会社と新しい契約に結ぶ前に、内容をよく読んだ。", "corrected_sentence": "彼は会社と新しい契約を結ぶ前に、内容をよく読んだ。", "error_description": "「契約を結ぶ」は目的語に「を」を取る。「契約に結ぶ」の「に」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36457, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この契約の原本を、会社の金庫に大切に保管されていた。", "corrected_sentence": "この契約の原本は、会社の金庫に大切に保管されていた。", "error_description": "保管される物の話題は「原本は」で示す。「原本を」の「を」が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
