INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36458, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "やくそくしたことを、ちゃんとすること。", "primary_collocate": null, "pronunciation": "りこう", "ipa": "ɾikoː", "syllable_count": 3, "sentences": [{"text": "約束の履行が遅れて、相手を怒らせてしまった。", "target_word": "履行", "complexity_tier": "T3", "furigana": "約束[やくそく]の履行[りこう]が遅[おく]れて、相手[あいて]を怒[おこ]らせてしまった。", "sentence_source": "generated"}, {"text": "彼は一度した約束は必ず履行する人だ。", "target_word": "履行", "complexity_tier": "T3", "furigana": "彼[かれ]は一度[いちど]した約束[やくそく]は必[かなら]ず履行[りこう]する人[ひと]だ。", "sentence_source": "generated"}, {"text": "社長は、社員との約束を履行すると宣言した。", "target_word": "履行", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は、社員[しゃいん]との約束[やくそく]を履行[りこう]すると宣言[せんげん]した。", "sentence_source": "generated"}, {"text": "約束を履行しなければ、信用を失う。", "target_word": "履行", "complexity_tier": "T3", "furigana": "約束[やくそく]を履行[りこう]しなければ、信用[しんよう]を失[うしな]う。", "sentence_source": "generated"}, {"text": "子どもとの約束の履行を、父は何よりも大切にしている。", "target_word": "履行", "complexity_tier": "T4", "furigana": "子[こ]どもとの約束[やくそく]の履行[りこう]を、父[ちち]は何[なに]よりも大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "市長は選挙で公約した計画の履行を求められている。", "target_word": "履行", "complexity_tier": "T4", "furigana": "市長[しちょう]は選挙[せんきょ]で公約[こうやく]した計画[けいかく]の履行[りこう]を求[もと]められている。", "sentence_source": "generated"}, {"text": "口先だけで、約束を履行する気はないようだ。", "target_word": "履行", "complexity_tier": "T3", "furigana": "口先[くちさき]だけで、約束[やくそく]を履行[りこう]する気[き]はないようだ。", "sentence_source": "generated"}, {"text": "彼女は引っ越しの手伝いという約束をきちんと履行してくれた。", "target_word": "履行", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は引[ひ]っ越[こ]しの手伝[てつだ]いという約束[やくそく]をきちんと履行[りこう]してくれた。", "sentence_source": "generated"}, {"text": "履行できない約束は、最初からしないほうがいい。", "target_word": "履行", "complexity_tier": "T3", "furigana": "履行[りこう]できない約束[やくそく]は、最初[さいしょ]からしないほうがいい。", "sentence_source": "generated"}, {"text": "約束の履行には、時間と努力が必要だ。", "target_word": "履行", "complexity_tier": "T3", "furigana": "約束[やくそく]の履行[りこう]には、時間[じかん]と努力[どりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "履行する", "label": "辞書形"}, {"form": "履行した", "label": "過去形"}, {"form": "履行して", "label": "て形"}, {"form": "履行しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "履行:交わした約束を守ってきちんと実行すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36458, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "履行", "is_correct": true, "explanation": "「約束の履行」で、約束を果たすこと。「遅れて」という文脈とも合う。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつける行為で、約束の遅れの文には合わない。"}, {"text": "修理", "is_correct": false, "explanation": "「修理」は壊れた物を直すことで、約束には使わない。"}, {"text": "消毒", "is_correct": false, "explanation": "「消毒」は菌を取り除く行為で、約束の遅れの文には合わない。"}], "explanations": {"履行": "「約束の履行」で、約束を果たすこと。「遅れて」という文脈とも合う。", "点火": "「点火」は火をつける行為で、約束の遅れの文には合わない。", "修理": "「修理」は壊れた物を直すことで、約束には使わない。", "消毒": "「消毒」は菌を取り除く行為で、約束の遅れの文には合わない。"}, "sentence_index": 0, "correct_answer": "履行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作品の履行を待つ。", "explanation": "ここは〈完成〉の意味。作品は履行するものではなく、完成するもの。"}, {"text": "上司が提案を履行した。", "explanation": "ここは〈承認〉の意味。提案は履行するものではなく、認めるもの。"}, {"text": "体調不良で、出場の履行を取り消した。", "explanation": "ここは〈辞退〉の意味。出場は履行するものではなく、自分から断るもの。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36458, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "履行", "is_correct": true, "explanation": "「約束を履行する」で、交わした約束を実際に果たす意味。「口先だけ」とも合う。"}, {"text": "遠慮", "is_correct": false, "explanation": "「遠慮する」は控えることで、「約束を遠慮する気」とは言わない。"}, {"text": "撮影", "is_correct": false, "explanation": "「撮影」は写真や映像を撮る行為で、約束とは結びつかない。"}, {"text": "注目", "is_correct": false, "explanation": "「注目」は関心を向けることで、約束を対象にする文には合わない。"}], "explanations": {"履行": "「約束を履行する」で、交わした約束を実際に果たす意味。「口先だけ」とも合う。", "遠慮": "「遠慮する」は控えることで、「約束を遠慮する気」とは言わない。", "撮影": "「撮影」は写真や映像を撮る行為で、約束とは結びつかない。", "注目": "「注目」は関心を向けることで、約束を対象にする文には合わない。"}, "sentence_index": 6, "correct_answer": "履行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "レストランで、ステーキを履行した。", "explanation": "ここは〈注文〉の意味。料理は履行するものではなく、頼むもの。"}, {"text": "毎晩十時に履行している。", "explanation": "ここは〈就寝〉の意味。寝ることは約束を果たす行為ではないので、履行とは言わない。"}, {"text": "新しい靴を履行して、外に出かけた。", "explanation": "ここは〈はく〉の意味。靴は履行するものではなく、はくもの。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
