INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36459, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「履行が難しくなった」の「が」。「難しくなる」の主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「履行に難しくなった」は成り立たず、「難しくなる」の主語には「が」を使う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「履行で難しくなった」は文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「履行へ難しくなった」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「履行が難しくなった」の「が」。「難しくなる」の主語を示す。", "に": "「履行に難しくなった」は成り立たず、「難しくなる」の主語には「が」を使う。", "で": "「で」は手段や場所を示すので、「履行で難しくなった」は文が通らない。", "へ": "「へ」は方向を示すので、「履行へ難しくなった」は成り立たない。"}, "error_tags": {"に": "result", "で": "means", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36459, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "契約や約束などの内容を実際に行うこと。", "primary_collocate": null, "pronunciation": "りこう", "ipa": "ɾikoː", "syllable_count": 3, "sentences": [{"text": "売り手が契約を履行しないため、買い手は代金の支払いを止めた。", "target_word": "履行", "complexity_tier": "T4", "furigana": "売[う]り手[て]が契約[けいやく]を履行[りこう]しないため、買[か]い手[て]は代金[だいきん]の支払[しはら]いを止[と]めた。", "sentence_source": "generated"}, {"text": "契約の履行には、双方の協力が欠かせない。", "target_word": "履行", "complexity_tier": "T4", "furigana": "契約[けいやく]の履行[りこう]には、双方[そうほう]の協力[きょうりょく]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "期日までに義務を履行できなかった場合は、違約金が発生する。", "target_word": "履行", "complexity_tier": "T4", "furigana": "期日[きじつ]までに義務[ぎむ]を履行[りこう]できなかった場合[ばあい]は、違約金[いやくきん]が発生[はっせい]する。", "sentence_source": "generated"}, {"text": "工事会社は、契約書に書かれた内容を誠実に履行した。", "target_word": "履行", "complexity_tier": "T4", "furigana": "工事[こうじ]会社[がいしゃ]は、契約書[けいやくしょ]に書[か]かれた内容[ないよう]を誠実[せいじつ]に履行[りこう]した。", "sentence_source": "generated"}, {"text": "裁判所は、被告に債務の履行を命じた。", "target_word": "履行", "complexity_tier": "T4", "furigana": "裁判所[さいばんしょ]は、被告[ひこく]に債務[さいむ]の履行[りこう]を命[めい]じた。", "sentence_source": "generated"}, {"text": "契約内容が履行されたか確認するため、担当者が現場を訪れた。", "target_word": "履行", "complexity_tier": "T4", "furigana": "契約内容[けいやくないよう]が履行[りこう]されたか確認[かくにん]するため、担当者[たんとうしゃ]が現場[げんば]を訪[おとず]れた。", "sentence_source": "generated"}, {"text": "合意した条件が履行されているか、毎月点検する。", "target_word": "履行", "complexity_tier": "T3", "furigana": "合意[ごうい]した条件[じょうけん]が履行[りこう]されているか、毎月[まいつき]点検[てんけん]する。", "sentence_source": "generated"}, {"text": "契約の履行が難しくなったときは、早めに相手へ連絡してください。", "target_word": "履行", "complexity_tier": "T4", "furigana": "契約[けいやく]の履行[りこう]が難[むずか]しくなったときは、早[はや]めに相手[あいて]へ連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "契約どおりに履行したので、請求書を発行します。", "target_word": "履行", "complexity_tier": "T3", "furigana": "契約[けいやく]どおりに履行[りこう]したので、請求書[せいきゅうしょ]を発行[はっこう]します。", "sentence_source": "generated"}, {"text": "当社は、保証の履行について責任を負います。", "target_word": "履行", "complexity_tier": "T4", "furigana": "当社[とうしゃ]は、保証[ほしょう]の履行[りこう]について責任[せきにん]を負[お]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "履行する", "label": "辞書形"}, {"form": "履行した", "label": "過去形"}, {"form": "履行して", "label": "て形"}, {"form": "履行しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "履行:契約・義務・債務の内容を実際に行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36459, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "履行", "is_correct": true, "explanation": "「契約を履行する」で、契約の内容を実際に行う意味。「代金の支払いを止めた」という文脈とも合う。"}, {"text": "購入", "is_correct": false, "explanation": "「購入」は物を買うことで、契約を対象にはできない。"}, {"text": "訪問", "is_correct": false, "explanation": "「訪問」は人や場所を訪ねる行為で、契約を対象にする文には合わない。"}, {"text": "修理", "is_correct": false, "explanation": "「修理」は壊れた物を直すことで、契約には使わない。"}], "explanations": {"履行": "「契約を履行する」で、契約の内容を実際に行う意味。「代金の支払いを止めた」という文脈とも合う。", "購入": "「購入」は物を買うことで、契約を対象にはできない。", "訪問": "「訪問」は人や場所を訪ねる行為で、契約を対象にする文には合わない。", "修理": "「修理」は壊れた物を直すことで、契約には使わない。"}, "sentence_index": 0, "correct_answer": "履行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "映画の履行を終えた。", "explanation": "ここは〈撮影〉の意味。映画は履行するものではなく、撮影するもの。"}, {"text": "古い建物を履行した。", "explanation": "ここは〈解体〉の意味。建物は履行するものではなく、壊すもの。"}, {"text": "新しい曲を履行した。", "explanation": "ここは〈作曲〉の意味。曲は履行するものではなく、作るもの。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36459, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "履行", "is_correct": true, "explanation": "「履行されている」で、合意した内容が実際に行われている意味。「点検する」という文脈とも合う。"}, {"text": "販売", "is_correct": false, "explanation": "「販売」は商品を売ることで、条件を対象にする文は意味が通らない。"}, {"text": "撮影", "is_correct": false, "explanation": "「撮影」は写真や映像を撮る行為で、条件には使わない。"}, {"text": "配送", "is_correct": false, "explanation": "「配送」は荷物を届けることで、条件を主語にする文には合わない。"}], "explanations": {"履行": "「履行されている」で、合意した内容が実際に行われている意味。「点検する」という文脈とも合う。", "販売": "「販売」は商品を売ることで、条件を対象にする文は意味が通らない。", "撮影": "「撮影」は写真や映像を撮る行為で、条件には使わない。", "配送": "「配送」は荷物を届けることで、条件を主語にする文には合わない。"}, "sentence_index": 6, "correct_answer": "履行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "映画館で、チケットを履行した。", "explanation": "ここは〈購入〉の意味。チケットは履行するものではなく、買うもの。"}, {"text": "全員に、資料を履行した。", "explanation": "ここは〈配布〉の意味。資料は履行するものではなく、配るもの。"}, {"text": "看板を履行して、道をあけた。", "explanation": "ここは〈撤去〉の意味。看板は履行するものではなく、取り除くもの。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
