INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36460, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、心のもち方やようす。", "primary_collocate": null, "pronunciation": "たいど", "ipa": "taido", "syllable_count": 3, "sentences": [{"text": "その態度はよくないよ。", "target_word": "態度", "complexity_tier": "T2", "furigana": "その態度[たいど]はよくないよ。", "sentence_source": "generated"}, {"text": "兄は大きな態度で話す。", "target_word": "態度", "complexity_tier": "T2", "furigana": "兄[あに]は大[おお]きな態度[たいど]で話[はな]す。", "sentence_source": "generated"}, {"text": "彼は、いつも同じ態度だ。", "target_word": "態度", "complexity_tier": "T2", "furigana": "彼[かれ]は、いつも同[おな]じ態度[たいど]だ。", "sentence_source": "generated"}, {"text": "先生の態度が急に変わった。", "target_word": "態度", "complexity_tier": "T2", "furigana": "先生[せんせい]の態度[たいど]が急[きゅう]に変[か]わった。", "sentence_source": "generated"}, {"text": "子どもの態度を見て、母は笑った。", "target_word": "態度", "complexity_tier": "T3", "furigana": "子[こ]どもの態度[たいど]を見[み]て、母[はは]は笑[わら]った。", "sentence_source": "generated"}, {"text": "態度が悪いと、友だちが減ってしまう。", "target_word": "態度", "complexity_tier": "T3", "furigana": "態度[たいど]が悪[わる]いと、友[とも]だちが減[へ]ってしまう。", "sentence_source": "generated"}, {"text": "怒った態度で部屋を出ていった。", "target_word": "態度", "complexity_tier": "T3", "furigana": "怒[おこ]った態度[たいど]で部屋[へや]を出[で]ていった。", "sentence_source": "generated"}, {"text": "謝るときは、態度も大切です。", "target_word": "態度", "complexity_tier": "T3", "furigana": "謝[あやま]るときは、態度[たいど]も大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "彼女の態度には、やさしさが感じられる。", "target_word": "態度", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の態度[たいど]には、やさしさが感[かん]じられる。", "sentence_source": "generated"}, {"text": "態度に出さなくても、気持ちは伝わるものだ。", "target_word": "態度", "complexity_tier": "T4", "furigana": "態度[たいど]に出[だ]さなくても、気持[きも]ちは伝[つた]わるものだ。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | するときの心のもち方やようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47a9a169-f8ce-40f2-ac03-946696cdfb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36460, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "態度", "is_correct": true, "explanation": "たいど。見出し語そのもの。"}, {"text": "程度", "is_correct": false, "explanation": "ていど。最初の一拍だけが違う。"}, {"text": "制度", "is_correct": false, "explanation": "せいど。最初の一拍だけが違う。"}, {"text": "大河", "is_correct": false, "explanation": "たいが。最後の一拍だけが違う。"}], "explanations": {"態度": "たいど。見出し語そのもの。", "程度": "ていど。最初の一拍だけが違う。", "制度": "せいど。最初の一拍だけが違う。", "大河": "たいが。最後の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "態度"}, "level_3": {"options": [{"text": "態度", "is_correct": true, "explanation": "「よくない」と評価される心のもち方として合う。"}, {"text": "昨日", "is_correct": false, "explanation": "形は合うが、「その昨日」とは言えず意味が合わない。"}, {"text": "先週", "is_correct": false, "explanation": "「その先週」とは言えず、文として成り立たない。"}, {"text": "今朝", "is_correct": false, "explanation": "「その今朝」とは言えず、文として成り立たない。"}], "explanations": {"態度": "「よくない」と評価される心のもち方として合う。", "昨日": "形は合うが、「その昨日」とは言えず意味が合わない。", "先週": "「その先週」とは言えず、文として成り立たない。", "今朝": "「その今朝」とは言えず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "態度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝から態度が降っているので傘を持った。", "explanation": "「態度」は降るものではなく、天気を表さないので誤り。"}, {"text": "この箱の態度は、とても重い。", "explanation": "「態度」は物の重さを表さないので誤り。"}, {"text": "駅まで態度で十分かかる。", "explanation": "「態度」は移動の手段や時間を表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
