INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36461, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「態度を決める」と目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「態度へ決めかねて」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「態度から決めかねて」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「決めかねる」は他動詞なので、「態度が決めかねて」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「態度を決める」と目的語を示す。", "へ": "「態度へ決めかねて」は文として成り立たない。", "から": "「態度から決めかねて」は意味が通らない。", "が": "「決めかねる」は他動詞なので、「態度が決めかねて」は文として成り立たない。"}, "error_tags": {"へ": "direction", "から": "origin", "が": "subject"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36461, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事に対する考え方や行動の仕方。その姿勢。", "primary_collocate": null, "pronunciation": "たいど", "ipa": "taido", "syllable_count": 3, "sentences": [{"text": "建築を単なる機能の集合体ではなく、記号が織りなすテキストとして読み解く態度が、ポスト構造主義に基づく批評の核心です。", "target_word": "態度", "complexity_tier": "T6", "furigana": "建築[けんちく]を単[たん]なる機能[きのう]の集合体[しゅうごうたい]ではなく、記号[きごう]が織[お]りなすテキストとして読[よ]み解[と]く態度[たいど]が、ポスト構造主義[こうぞうしゅぎ]に基[もと]づく批評[ひひょう]の核心[かくしん]です。", "sentence_source": "mined"}, {"text": "彼の態度は真剣だった。", "target_word": "態度", "complexity_tier": "T2", "furigana": "彼[かれ]の態度[たいど]は真剣[しんけん]だった。", "sentence_source": "generated"}, {"text": "先生は私の態度を注意した。", "target_word": "態度", "complexity_tier": "T2", "furigana": "先生[せんせい]は私[わたし]の態度[たいど]を注意[ちゅうい]した。", "sentence_source": "generated"}, {"text": "仕事に対する態度が変わってきた。", "target_word": "態度", "complexity_tier": "T3", "furigana": "仕事[しごと]に対[たい]する態度[たいど]が変[か]わってきた。", "sentence_source": "generated"}, {"text": "客に失礼な態度をとってはいけない。", "target_word": "態度", "complexity_tier": "T3", "furigana": "客[きゃく]に失礼[しつれい]な態度[たいど]をとってはいけない。", "sentence_source": "generated"}, {"text": "はっきりした態度を示す必要がある。", "target_word": "態度", "complexity_tier": "T3", "furigana": "はっきりした態度[たいど]を示[しめ]す必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "彼女は、問題に前向きな態度で取り組んでいる。", "target_word": "態度", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は、問題[もんだい]に前向[まえむ]きな態度[たいど]で取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "態度を決めかねて、返事が遅れた。", "target_word": "態度", "complexity_tier": "T3", "furigana": "態度[たいど]を決[き]めかねて、返事[へんじ]が遅[おく]れた。", "sentence_source": "generated"}, {"text": "批判されても、彼は冷静な態度を保った。", "target_word": "態度", "complexity_tier": "T4", "furigana": "批判[ひはん]されても、彼[かれ]は冷静[れいせい]な態度[たいど]を保[たも]った。", "sentence_source": "generated"}, {"text": "彼の態度から、本心を読み取ることはできない。", "target_word": "態度", "complexity_tier": "T4", "furigana": "彼[かれ]の態度[たいど]から、本心[ほんしん]を読[よ]み取[と]ることはできない。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 物事への考え方や行動の姿勢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47a9a169-f8ce-40f2-ac03-946696cdfb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36461, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "態度", "is_correct": true, "explanation": "たいど。見出し語そのもの。"}, {"text": "程度", "is_correct": false, "explanation": "ていど。最初の一拍だけが違う。"}, {"text": "制度", "is_correct": false, "explanation": "せいど。最初の一拍だけが違う。"}, {"text": "大河", "is_correct": false, "explanation": "たいが。最後の一拍だけが違う。"}], "explanations": {"態度": "たいど。見出し語そのもの。", "程度": "ていど。最初の一拍だけが違う。", "制度": "せいど。最初の一拍だけが違う。", "大河": "たいが。最後の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "態度"}, "level_3": {"options": [{"text": "態度", "is_correct": true, "explanation": "物事の読み解き方という姿勢を表し、文意に合う。"}, {"text": "体温", "is_correct": false, "explanation": "形は合うが、読み解くものではなく意味が合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、批評の核心にはならず意味が合わない。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、読み解く対象ではなく意味が合わない。"}], "explanations": {"態度": "物事の読み解き方という姿勢を表し、文意に合う。", "体温": "形は合うが、読み解くものではなく意味が合わない。", "湿度": "形は合うが、批評の核心にはならず意味が合わない。", "気温": "形は合うが、読み解く対象ではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "態度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋の態度は、冬になるとかなり低くなる。", "explanation": "「態度」は気温のような数値ではなく、姿勢を表す語なので誤り。"}, {"text": "彼は態度を三つ買って帰った。", "explanation": "「態度」は買える物ではなく、数える対象でもないので誤り。"}, {"text": "この橋の態度は、長さが百メートルある。", "explanation": "「態度」は物の大きさや形を表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36461, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "態度", "is_correct": true, "explanation": "たいど。見出し語そのもの。"}, {"text": "対価", "is_correct": false, "explanation": "たいか。最後の一拍だけが違う。"}, {"text": "太鼓", "is_correct": false, "explanation": "たいこ。最後の一拍だけが違う。"}, {"text": "退治", "is_correct": false, "explanation": "たいじ。最後の一拍だけが違う。"}, {"text": "大使", "is_correct": false, "explanation": "たいし。最後の一拍だけが違う。"}], "explanations": {"態度": "たいど。見出し語そのもの。", "対価": "たいか。最後の一拍だけが違う。", "太鼓": "たいこ。最後の一拍だけが違う。", "退治": "たいじ。最後の一拍だけが違う。", "大使": "たいし。最後の一拍だけが違う。"}, "sentence_index": null, "correct_answer": "態度"}, "level_3": {"options": [{"text": "態度", "is_correct": true, "explanation": "問題に向かう姿勢を表し、文意に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、取り組み方を表さず意味が合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、前向きとは結びつかず意味が合わない。"}, {"text": "場所", "is_correct": false, "explanation": "形は合うが、取り組む様子を表さず意味が合わない。"}], "explanations": {"態度": "問題に向かう姿勢を表し、文意に合う。", "天気": "形は合うが、取り組み方を表さず意味が合わない。", "値段": "形は合うが、前向きとは結びつかず意味が合わない。", "場所": "形は合うが、取り組む様子を表さず意味が合わない。"}, "sentence_index": 6, "correct_answer": "態度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅から家までの態度は歩いて十分だ。", "explanation": "「態度」は距離を表さないので誤り。"}, {"text": "兄は態度を飲んで寝た。", "explanation": "「態度」は飲めるものではないので誤り。"}, {"text": "このスープは態度がとても濃い。", "explanation": "「態度」は味の濃さを表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
