INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36465, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つのものが激しくぶつかること。また、意見や利害が対立すること。", "primary_collocate": null, "pronunciation": "しょうとつ", "ipa": "ɕoːtotsɯ", "syllable_count": 4, "sentences": [{"text": "しかし現代ファッションの文脈では、この伝統的な職人技はデジタルデザインという新たなパラダイムと衝突し、あるいは融合しつつある。", "target_word": "衝突", "complexity_tier": "T4", "furigana": "しかし現代[げんだい]ファッションの文脈[ぶんみゃく]では、この伝統的[でんとうてき]な職人技[しょくにんわざ]はデジタルデザインという新[あら]たなパラダイムと衝突[しょうとつ]し、あるいは融合[ゆうごう]しつつある。", "sentence_source": "mined"}, {"text": "交差点で車と自転車が衝突し、自転車の男性が軽いけがをした。", "target_word": "衝突", "complexity_tier": "T3", "furigana": "交差点[こうさてん]で車[くるま]と自転車[じてんしゃ]が衝突[しょうとつ]し、自転車[じてんしゃ]の男性[だんせい]が軽[かる]いけがをした。", "sentence_source": "generated"}, {"text": "霧が濃くて前が見えず、二台の車が衝突した。", "target_word": "衝突", "complexity_tier": "T3", "furigana": "霧[きり]が濃[こ]くて前[まえ]が見[み]えず、二台[にだい]の車[くるま]が衝突[しょうとつ]した。", "sentence_source": "generated"}, {"text": "新しい制度をめぐって、経営者と労働組合の意見が衝突した。", "target_word": "衝突", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]をめぐって、経営者[けいえいしゃ]と労働組合[ろうどうくみあい]の意見[いけん]が衝突[しょうとつ]した。", "sentence_source": "generated"}, {"text": "兄とは考え方が違うので、しばしば衝突する。", "target_word": "衝突", "complexity_tier": "T3", "furigana": "兄[あに]とは考[かんが]え方[かた]が違[ちが]うので、しばしば衝突[しょうとつ]する。", "sentence_source": "generated"}, {"text": "小惑星が地球に衝突すれば、大きな被害が出るだろう。", "target_word": "衝突", "complexity_tier": "T4", "furigana": "小惑星[しょうわくせい]が地球[ちきゅう]に衝突[しょうとつ]すれば、大[おお]きな被害[ひがい]が出[で]るだろう。", "sentence_source": "generated"}, {"text": "二人の利害が衝突したため、話し合いは長引いた。", "target_word": "衝突", "complexity_tier": "T3", "furigana": "二人[ふたり]の利害[りがい]が衝突[しょうとつ]したため、話[はな]し合[あ]いは長引[ながび]いた。", "sentence_source": "generated"}, {"text": "強風で船が岸壁に衝突し、船体に穴があいた。", "target_word": "衝突", "complexity_tier": "T4", "furigana": "強風[きょうふう]で船[ふね]が岸壁[がんぺき]に衝突[しょうとつ]し、船体[せんたい]に穴[あな]があいた。", "sentence_source": "generated"}, {"text": "上司と衝突するのを避けて、彼は黙っていた。", "target_word": "衝突", "complexity_tier": "T3", "furigana": "上司[じょうし]と衝突[しょうとつ]するのを避[さ]けて、彼[かれ]は黙[だま]っていた。", "sentence_source": "generated"}, {"text": "監督と選手が練習方法で衝突し、チームの雰囲気が悪くなった。", "target_word": "衝突", "complexity_tier": "T4", "furigana": "監督[かんとく]と選手[せんしゅ]が練習方法[れんしゅうほうほう]で衝突[しょうとつ]し、チームの雰囲気[ふんいき]が悪[わる]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "衝突する", "label": "辞書形"}, {"form": "衝突した", "label": "過去形"}, {"form": "衝突しない", "label": "否定形"}, {"form": "衝突して", "label": "て形"}, {"form": "衝突すれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "激しくぶつかる／意見・利害が対立する(する動詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d0f991-e104-4570-8ba0-8f096408c859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36465, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衝突", "is_correct": true, "explanation": "新しい考えと既存の技法が激しくぶつかる、という意味で文に合う。"}, {"text": "解約", "is_correct": false, "explanation": "解約は契約を断つことで、「パラダイムと解約し」は文脈に合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "清掃は掃除を指し、パラダイムとの関係を述べる文には入らない。"}, {"text": "販売", "is_correct": false, "explanation": "販売は商品を売ることで、新しいパラダイムとの関係を表す文には合わない。"}], "explanations": {"衝突": "新しい考えと既存の技法が激しくぶつかる、という意味で文に合う。", "解約": "解約は契約を断つことで、「パラダイムと解約し」は文脈に合わない。", "清掃": "清掃は掃除を指し、パラダイムとの関係を述べる文には入らない。", "販売": "販売は商品を売ることで、新しいパラダイムとの関係を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "衝突"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その知らせは、社員に大きな衝突を与えた。", "explanation": "衝突は『与える』ものではなく、この文では衝撃が入る。"}, {"text": "二人は衝突を交わして、仲直りした。", "explanation": "衝突は『交わす』の対象にならず、握手を交わすと言う。"}, {"text": "同じ極どうしの磁石は、近づけると衝突する。", "explanation": "同極の磁石は押し返し合うので、衝突とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36465, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衝突", "is_correct": true, "explanation": "二人の利害がぶつかり合ったという意味で、話し合いが長引く理由として文が成り立つ。"}, {"text": "納得", "is_correct": false, "explanation": "納得は理解して受け入れることで、利害を主語にして「納得したため」とは言えない。"}, {"text": "反省", "is_correct": false, "explanation": "反省は自分の行いを省みることで、利害の変化を述べる文には合わない。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は礼の気持ちを表すことで、利害の動きを述べる文には入らない。"}], "explanations": {"衝突": "二人の利害がぶつかり合ったという意味で、話し合いが長引く理由として文が成り立つ。", "納得": "納得は理解して受け入れることで、利害を主語にして「納得したため」とは言えない。", "反省": "反省は自分の行いを省みることで、利害の変化を述べる文には合わない。", "感謝": "感謝は礼の気持ちを表すことで、利害の動きを述べる文には入らない。"}, "sentence_index": 6, "correct_answer": "衝突"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は衝突を抑えきれず、高い服を買ってしまった。", "explanation": "急な欲求は衝動と言い、衝突では表さない。"}, {"text": "この二本の道は、ここで衝突している。", "explanation": "道の交わりは交差と言い、衝突とは言わない。"}, {"text": "彼は上司の態度に衝突を抱いた。", "explanation": "『抱く』対象は反感であり、衝突は抱くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36465, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族との意見の衝突に、どう避けるか考えた。", "corrected_sentence": "家族との意見の衝突を、どう避けるか考えた。", "error_description": "「避ける」は他動詞で目的語を「を」で示す。「衝突に」と「に」を使うのは誤りで、「衝突を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36465, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "急ブレーキで衝突しを避けた。", "corrected_sentence": "急ブレーキで衝突を避けた。", "error_description": "「衝突」は名詞なので「衝突を避ける」の形で使う。「衝突しを」と「し」を挿入するのは誤りで、「衝突を避けた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '826421d7-1723-419d-8cff-cba6bb8dc086') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
