INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36466, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "好ましくないことを、自分の意志でわざとしないでおくこと。", "primary_collocate": null, "pronunciation": "さける", "ipa": "sakeɾɯ", "syllable_count": 3, "sentences": [{"text": "彼は私との会話を避けているようだ。", "target_word": "避けて", "complexity_tier": "T3", "furigana": "彼[かれ]は私[わたし]との会話[かいわ]を避[さ]けているようだ。", "sentence_source": "generated"}, {"text": "夜遅くの食事は避けたほうがいい。", "target_word": "避けた", "complexity_tier": "T2", "furigana": "夜遅[よるおそ]くの食事[しょくじ]は避[さ]けたほうがいい。", "sentence_source": "generated"}, {"text": "医者に、お酒を飲むのを避けるように言われた。", "target_word": "避ける", "complexity_tier": "T3", "furigana": "医者[いしゃ]に、お酒[さけ]を飲[の]むのを避[さ]けるように言[い]われた。", "sentence_source": "generated"}, {"text": "雨の日の外出を避けて、家で本を読んだ。", "target_word": "避けて", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]の外出[がいしゅつ]を避[さ]けて、家[いえ]で本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "彼女はけんかになるのを避けて、何も言わなかった。", "target_word": "避けて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はけんかになるのを避[さ]けて、何[なに]も言[い]わなかった。", "sentence_source": "generated"}, {"text": "混む時間を避けて、午前中に買い物に行く。", "target_word": "避けて", "complexity_tier": "T3", "furigana": "混[こ]む時間[じかん]を避[さ]けて、午前中[ごぜんちゅう]に買[か]い物[もの]に行[い]く。", "sentence_source": "generated"}, {"text": "失敗を避けたいなら、準備をしっかりすることだ。", "target_word": "避けたい", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を避[さ]けたいなら、準備[じゅんび]をしっかりすることだ。", "sentence_source": "generated"}, {"text": "辛い物は避けているので、このカレーは食べられません。", "target_word": "避けて", "complexity_tier": "T3", "furigana": "辛[から]い物[もの]は避[さ]けているので、このカレーは食[た]べられません。", "sentence_source": "generated"}, {"text": "私は人前で話すことを避けてきた。", "target_word": "避けて", "complexity_tier": "T3", "furigana": "私[わたし]は人前[ひとまえ]で話[はな]すことを避[さ]けてきた。", "sentence_source": "generated"}, {"text": "彼は理由を言うのを避け、笑ってごまかした。", "target_word": "避け", "complexity_tier": "T4", "furigana": "彼[かれ]は理由[りゆう]を言[い]うのを避[さ]け、笑[わら]ってごまかした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "避ける", "label": "辞書形"}, {"form": "避けた", "label": "過去形"}, {"form": "避けて", "label": "て形"}, {"form": "避けない", "label": "否定形"}, {"form": "避ければ", "label": "仮定形"}, {"form": "避けよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "避ける:好ましくないことをわざとしないでおく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36466, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "避けて", "is_correct": true, "explanation": "「避けている」の形で、会話を避けている様子を表す。"}, {"text": "避けた", "is_correct": false, "explanation": "過去形だと「避けたいる」となり、「避けている」の形が続かない。"}, {"text": "避けよう", "is_correct": false, "explanation": "意志形だと「避けようている」となり、「避けている」に続かない。"}, {"text": "避ける", "is_correct": false, "explanation": "辞書形だと「避けるいる」となり、「避けている」の形にならない。"}], "explanations": {"避けて": "「避けている」の形で、会話を避けている様子を表す。", "避けた": "過去形だと「避けたいる」となり、「避けている」の形が続かない。", "避けよう": "意志形だと「避けようている」となり、「避けている」に続かない。", "避ける": "辞書形だと「避けるいる」となり、「避けている」の形にならない。"}, "sentence_index": 0, "correct_answer": "避けて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議で、うっかり意見を避けてしまった。", "explanation": "ここは〈言い忘れる〉（うっかり言わないでいる）の意味。避けるは自分の意志で何かをしないことなので、うっかりの意味では使わない。"}, {"text": "彼は夢を避けて、家業を継いだ。", "explanation": "ここは〈諦める〉の意味。避けるは危険や好ましくないことを前もってしないことで、自分の夢を手放す意味では使わない。"}, {"text": "袋が避けて、中身がこぼれた。", "explanation": "ここは〈裂ける〉（破れる）の意味。避けるは人が自分の意志で何かをしないことで、袋が破れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36466, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "避けたい", "is_correct": true, "explanation": "「避けたいなら」の形で、避けたいという望みを表す。"}, {"text": "避けろ", "is_correct": false, "explanation": "命令形だと「避けろなら」となり、「なら」に続かない。"}, {"text": "避けず", "is_correct": false, "explanation": "否定の連用形だと「避けずなら」となり、「なら」に続かない。"}, {"text": "避けます", "is_correct": false, "explanation": "丁寧形だと「避けますなら」となり、「なら」に続かない。"}], "explanations": {"避けたい": "「避けたいなら」の形で、避けたいという望みを表す。", "避けろ": "命令形だと「避けろなら」となり、「なら」に続かない。", "避けず": "否定の連用形だと「避けずなら」となり、「なら」に続かない。", "避けます": "丁寧形だと「避けますなら」となり、「なら」に続かない。"}, "sentence_index": 6, "correct_answer": "避けたい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "忙しくて、勉強に時間を避けなかった。", "explanation": "ここは〈割く〉（時間を都合する）の意味。避けるは「わざとしないこと」なので、時間を作る意味では使わない。"}, {"text": "屋根が避けて、雨が漏れた。", "explanation": "ここは〈裂ける〉（割れて裂ける）の意味。避けるは人が自分の意志で何かをしないことで、屋根が裂ける意味では使わない。"}, {"text": "道路が避けて、車が通れなくなった。", "explanation": "ここは〈裂ける〉（割れる）の意味。避けるは人が自分の意志で何かをしないことで、道路が割れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36466, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人混みに避けて、早めに帰った。", "corrected_sentence": "人混みを避けて、早めに帰った。", "error_description": "「避ける」は対象を「を」で示す。「人混みに」の「に」は誤りで、正しくは「人混みを避けて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "避けた", "is_correct": true, "explanation": "過去形で「避けたほうがいい」となり、「食事は避けたほうがいい」の意味になる。"}, {"text": "避けて", "is_correct": false, "explanation": "て形だと「避けてほうがいい」となり、文が成り立たない。"}, {"text": "避け", "is_correct": false, "explanation": "連用形だと「避けほうがいい」となり、「ほうがいい」に続かない。"}, {"text": "避けられ", "is_correct": false, "explanation": "受身・可能の連用形だと「避けられほうがいい」となり、意味も文も成り立たない。"}], "correct_form": "避けた", "base_form": "避ける", "form_label": "過去形", "sentence_index": 1, "explanations": {"避けた": "過去形で「避けたほうがいい」となり、「食事は避けたほうがいい」の意味になる。", "避けて": "て形だと「避けてほうがいい」となり、文が成り立たない。", "避け": "連用形だと「避けほうがいい」となり、「ほうがいい」に続かない。", "避けられ": "受身・可能の連用形だと「避けられほうがいい」となり、意味も文も成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36466, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車の混雑を避けてほうがいいので、早めに家を出た。", "corrected_sentence": "電車の混雑を避けたほうがいいので、早めに家を出た。", "error_description": "「避けたほうがいい」の形が正しい。「避けてほうがいい」の「て形」は「ほうがいい」に続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "避けて", "is_correct": true, "explanation": "て形で「避けているので」とつながる。"}, {"text": "避けず", "is_correct": false, "explanation": "連用否定形だと「避けずいる」となり、「いる」に続かない。"}, {"text": "避けます", "is_correct": false, "explanation": "丁寧形だと「避けますいる」となり、文が成り立たない。"}, {"text": "避けろ", "is_correct": false, "explanation": "命令形だと「避けろいる」となり、文が成り立たない。"}], "correct_form": "避けて", "base_form": "避ける", "form_label": "て形", "sentence_index": 7, "explanations": {"避けて": "て形で「避けているので」とつながる。", "避けず": "連用否定形だと「避けずいる」となり、「いる」に続かない。", "避けます": "丁寧形だと「避けますいる」となり、文が成り立たない。", "避けろ": "命令形だと「避けろいる」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36467, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36467, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「避けて」の対象を示す「を」で、「日差しを避けて」となる。"}, {"text": "の", "is_correct": false, "explanation": "「日差しの避けて」では連体の「の」が避ける対象を示せず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「日差しで避けて」は手段の「で」となり、避ける対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「日差しより避けて」は比較の「より」となり、避ける対象の意味にならない。"}], "correct_answer": "を", "explanations": {"を": "「避けて」の対象を示す「を」で、「日差しを避けて」となる。", "の": "「日差しの避けて」では連体の「の」が避ける対象を示せず、文が成り立たない。", "で": "「日差しで避けて」は手段の「で」となり、避ける対象を示せない。", "より": "「日差しより避けて」は比較の「より」となり、避ける対象の意味にならない。"}, "error_tags": {"の": "連体の格", "で": "手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36467, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある行動や状態を、自分の意志で行わないようにすること。", "primary_collocate": null, "pronunciation": "さける", "ipa": "sakeɾɯ", "syllable_count": 3, "sentences": [{"text": "無理な運動は避け、軽い散歩から始めましょう。", "target_word": "避け", "complexity_tier": "T3", "furigana": "無理[むり]な運動[うんどう]は避[さ]け、軽[かる]い散歩[さんぽ]から始[はじ]めましょう。", "sentence_source": "generated"}, {"text": "会議では、結論を急ぐことを避けるべきだ。", "target_word": "避ける", "complexity_tier": "T4", "furigana": "会議[かいぎ]では、結論[けつろん]を急[いそ]ぐことを避[さ]けるべきだ。", "sentence_source": "generated"}, {"text": "彼は責任のある仕事を避けて、楽な役ばかり選ぶ。", "target_word": "避けて", "complexity_tier": "T3", "furigana": "彼[かれ]は責任[せきにん]のある仕事[しごと]を避[さ]けて、楽[らく]な役[やく]ばかり選[えら]ぶ。", "sentence_source": "generated"}, {"text": "風邪をひいているときは、人が多い場所を避ける。", "target_word": "避ける", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいているときは、人[ひと]が多[おお]い場所[ばしょ]を避[さ]ける。", "sentence_source": "generated"}, {"text": "専門家は、むやみに薬に頼ることを避けるよう勧めている。", "target_word": "避ける", "complexity_tier": "T4", "furigana": "専門家[せんもんか]は、むやみに薬[くすり]に頼[たよ]ることを避[さ]けるよう勧[すす]めている。", "sentence_source": "generated"}, {"text": "誤解を避けるために、メールの文章は短くはっきり書く。", "target_word": "避ける", "complexity_tier": "T4", "furigana": "誤解[ごかい]を避[さ]けるために、メールの文章[ぶんしょう]は短[みじか]くはっきり書[か]く。", "sentence_source": "generated"}, {"text": "二人は目を合わせるのを避けるように、窓の外を見ていた。", "target_word": "避ける", "complexity_tier": "T4", "furigana": "二人[ふたり]は目[め]を合[あ]わせるのを避[さ]けるように、窓[まど]の外[そと]を見[み]ていた。", "sentence_source": "generated"}, {"text": "夏の昼間は、強い日差しを避けて木の下で休んだ。", "target_word": "避けて", "complexity_tier": "T3", "furigana": "夏[なつ]の昼間[ひるま]は、強[つよ]い日差[ひざ]しを避[さ]けて木[き]の下[した]で休[やす]んだ。", "sentence_source": "generated"}, {"text": "危険な道を避けて、遠回りをして帰った。", "target_word": "避けて", "complexity_tier": "T3", "furigana": "危険[きけん]な道[みち]を避[さ]けて、遠回[とおまわ]りをして帰[かえ]った。", "sentence_source": "generated"}, {"text": "争いを避ける性格なので、反対意見があっても黙っている。", "target_word": "避ける", "complexity_tier": "T4", "furigana": "争[あらそ]いを避[さ]ける性格[せいかく]なので、反対意見[はんたいいけん]があっても黙[だま]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "避ける", "label": "辞書形"}, {"form": "避けた", "label": "過去形"}, {"form": "避けて", "label": "て形"}, {"form": "避けない", "label": "否定形"}, {"form": "避ければ", "label": "仮定形"}, {"form": "避けよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "避ける:ある行動や状態を自分の意志で選ばないようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36467, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "避け", "is_correct": true, "explanation": "連用形で、「、」でつないで「軽い散歩から始めましょう」へ続ける。"}, {"text": "避けた", "is_correct": false, "explanation": "過去形だと「避けた、」となり、これから始める提案の文脈に合わない。"}, {"text": "避ける", "is_correct": false, "explanation": "辞書形だと「避ける、」で文が終止形で切れ、「、」の後の文とつながらない。"}, {"text": "避けろ", "is_correct": false, "explanation": "命令形だと「避けろ、」となり、やわらかな勧めの文と合わない。"}], "explanations": {"避け": "連用形で、「、」でつないで「軽い散歩から始めましょう」へ続ける。", "避けた": "過去形だと「避けた、」となり、これから始める提案の文脈に合わない。", "避ける": "辞書形だと「避ける、」で文が終止形で切れ、「、」の後の文とつながらない。", "避けろ": "命令形だと「避けろ、」となり、やわらかな勧めの文と合わない。"}, "sentence_index": 0, "correct_answer": "避け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "紙が避けてしまったので、テープで貼った。", "explanation": "ここは〈裂ける〉（破れる）の意味。避けるは人が意志で何かをしないことで、紙が破れる意味では使わない。"}, {"text": "屋根が避けて、雨が漏れた。", "explanation": "ここは〈裂ける〉（割れて裂ける）の意味。避けるは人が自分の意志で何かをしないことで、屋根が裂ける意味では使わない。"}, {"text": "大事な宿題を、うっかり避けてしまい、提出が遅れた。", "explanation": "ここは〈やり忘れる〉の意味。避けるは自分の意志で行わないことなので、うっかりの意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36467, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "避ける", "is_correct": true, "explanation": "「避けるように」で、目を合わせるのを避ける様子を表す。"}, {"text": "数える", "is_correct": false, "explanation": "「数えるように」では、目を合わせるのを数える意味になり、文が合わない。"}, {"text": "磨く", "is_correct": false, "explanation": "「磨くように」では、目を合わせるのを磨く意味になり、文が合わない。"}, {"text": "煮る", "is_correct": false, "explanation": "「煮るように」では、目を合わせるのを煮る意味になり、文が合わない。"}], "explanations": {"避ける": "「避けるように」で、目を合わせるのを避ける様子を表す。", "数える": "「数えるように」では、目を合わせるのを数える意味になり、文が合わない。", "磨く": "「磨くように」では、目を合わせるのを磨く意味になり、文が合わない。", "煮る": "「煮るように」では、目を合わせるのを煮る意味になり、文が合わない。"}, "sentence_index": 6, "correct_answer": "避ける"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木の板が避けて、床がきしんだ。", "explanation": "ここは〈裂ける〉（反り割れる）の意味。避けるは人が自分の意志で何かをしないことで、木の板が裂ける意味では使わない。"}, {"text": "長い準備の末、作品を避けた。", "explanation": "ここは〈完成させる〉の意味。避けるは相手や物事にかかわらないようにすることで、作り上げる意味では使わない。"}, {"text": "予算を避けなかった。", "explanation": "ここは〈割く〉（余裕を作って当てる）の意味。避けるは、しないでおく意味で、予算を当てる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36467, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "体調の悪い日は激しい運動を避けてべきだ。", "corrected_sentence": "体調の悪い日は激しい運動を避けるべきだ。", "error_description": "「べきだ」には辞書形「避ける」が続く。「避けてべきだ」の「て形」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "避ける", "is_correct": true, "explanation": "辞書形で「べきだ」に続き、「避けるべきだ」の意味になる。"}, {"text": "避けた", "is_correct": false, "explanation": "過去形だと「避けたべきだ」となり、「べきだ」に続かない。"}, {"text": "避け", "is_correct": false, "explanation": "連用形だと「避けべきだ」となり、「べきだ」に直接続かない。"}, {"text": "避けろ", "is_correct": false, "explanation": "命令形だと「避けろべきだ」となり、「べきだ」に続かない。"}], "correct_form": "避ける", "base_form": "避ける", "form_label": "辞書形", "sentence_index": 1, "explanations": {"避ける": "辞書形で「べきだ」に続き、「避けるべきだ」の意味になる。", "避けた": "過去形だと「避けたべきだ」となり、「べきだ」に続かない。", "避け": "連用形だと「避けべきだ」となり、「べきだ」に直接続かない。", "避けろ": "命令形だと「避けろべきだ」となり、「べきだ」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36467, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "争いに避けるため、会話を控えた。", "corrected_sentence": "争いを避けるため、会話を控えた。", "error_description": "「避ける」の対象は「を」で示す。「争いに避ける」の「に」は誤りで、正しくは「争いを避ける」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "避けて", "is_correct": true, "explanation": "て形で「休んだ」へ続き、日差しをよけた上で休んだという意味になる。"}, {"text": "避けず", "is_correct": false, "explanation": "連用否定形だと日差しをよけない意味になり、木陰で休む文脈と逆になる。"}, {"text": "避けます", "is_correct": false, "explanation": "丁寧形だと「避けます木の下で」となり、名詞に直接続かず文が成り立たない。"}, {"text": "避けられ", "is_correct": false, "explanation": "受身・可能の連用形だと「避けられ木の下で」となり、文が成り立たない。"}], "correct_form": "避けて", "base_form": "避ける", "form_label": "て形", "sentence_index": 7, "explanations": {"避けて": "て形で「休んだ」へ続き、日差しをよけた上で休んだという意味になる。", "避けず": "連用否定形だと日差しをよけない意味になり、木陰で休む文脈と逆になる。", "避けます": "丁寧形だと「避けます木の下で」となり、名詞に直接続かず文が成り立たない。", "避けられ": "受身・可能の連用形だと「避けられ木の下で」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36468, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「本棚に」で置き場所を示し、片付けるの着点になる。"}, {"text": "が", "is_correct": false, "explanation": "主格。本棚が片付けるの主語になり、文として不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾。本棚の片付けてくださいとなり、文が成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点。置き場所を示せず、文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「本棚に」で置き場所を示し、片付けるの着点になる。", "が": "主格。本棚が片付けるの主語になり、文として不自然。", "の": "連体修飾。本棚の片付けてくださいとなり、文が成立しない。", "より": "比較・起点。置き場所を示せず、文脈に合わない。"}, "error_tags": {"が": "主格（主語を示す）", "の": "連体修飾", "より": "比較・起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散らかす", "is_correct": true, "explanation": "正解。物を乱して整っていない状態にする意味で、片付けるの対義語にあたる。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる動詞で、片付けの対義語ではない。"}, {"text": "磨く", "is_correct": false, "explanation": "表面をきれいにする動作で、片付けの対義語ではない。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作を表す語で、物を整える動作の対義語ではない。"}], "correct_answer": "散らかす", "explanations": {"散らかす": "正解。物を乱して整っていない状態にする意味で、片付けるの対義語にあたる。", "運ぶ": "物を移動させる動詞で、片付けの対義語ではない。", "磨く": "表面をきれいにする動作で、片付けの対義語ではない。", "眺める": "見る動作を表す語で、物を整える動作の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36468, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散らかす", "is_correct": true, "explanation": "正解。物を乱して整っていない状態にする意味で、片付けるの対義語にあたる。"}, {"text": "描く", "is_correct": false, "explanation": "絵や図を作る動作で、片付けの対義語ではない。"}, {"text": "包む", "is_correct": false, "explanation": "物を覆う動作で、片付けの対義語ではない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "大きな声を出す動作で、片付けの対義語ではない。"}], "correct_answer": "散らかす", "explanations": {"散らかす": "正解。物を乱して整っていない状態にする意味で、片付けるの対義語にあたる。", "描く": "絵や図を作る動作で、片付けの対義語ではない。", "包む": "物を覆う動作で、片付けの対義語ではない。", "叫ぶ": "大きな声を出す動作で、片付けの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36468, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ちらかっているものを、もとのばしょにもどすこと。", "primary_collocate": null, "pronunciation": "かたづける", "ipa": "katadzɯɾɯ", "syllable_count": 5, "sentences": [{"text": "遊んだあとは、おもちゃをかごに片付けましょう。", "target_word": "片付けましょう", "complexity_tier": "T3", "furigana": "遊[あそ]んだあとは、おもちゃをかごに片付[かたづ]けましょう。", "sentence_source": "generated"}, {"text": "読み終わった本は、本棚に片付けてください。", "target_word": "片付けてください", "complexity_tier": "T3", "furigana": "読[よ]み終[お]わった本[ほん]は、本棚[ほんだな]に片付[かたづ]けてください。", "sentence_source": "generated"}, {"text": "食事が終わったら、皿を食器棚に片付ける。", "target_word": "片付ける", "complexity_tier": "T3", "furigana": "食事[しょくじ]が終[お]わったら、皿[さら]を食器棚[しょっきだな]に片付[かたづ]ける。", "sentence_source": "generated"}, {"text": "客が来る前に、出しっぱなしの道具を全部片付けた。", "target_word": "片付けた", "complexity_tier": "T3", "furigana": "客[きゃく]が来[く]る前[まえ]に、出[だ]しっぱなしの道具[どうぐ]を全部[ぜんぶ]片付[かたづ]けた。", "sentence_source": "generated"}, {"text": "使った工具を元の場所に片付けないと、次に探すとき困る。", "target_word": "片付けない", "complexity_tier": "T3", "furigana": "使[つか]った工具[こうぐ]を元[もと]の場所[ばしょ]に片付[かたづ]けないと、次[つぎ]に探[さが]すとき困[こま]る。", "sentence_source": "generated"}, {"text": "弟は脱いだ服を片付けないので、母によく注意される。", "target_word": "片付けない", "complexity_tier": "T3", "furigana": "弟[おとうと]は脱[ぬ]いだ服[ふく]を片付[かたづ]けないので、母[はは]によく注意[ちゅうい]される。", "sentence_source": "generated"}, {"text": "机の上の書類を引き出しに片付けて、帰宅した。", "target_word": "片付けて", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の書類[しょるい]を引[ひ]き出[だ]しに片付[かたづ]けて、帰宅[きたく]した。", "sentence_source": "generated"}, {"text": "夏になったので、冬の服を押し入れに片付けた。", "target_word": "片付けた", "complexity_tier": "T3", "furigana": "夏[なつ]になったので、冬[ふゆ]の服[ふく]を押[お]し入[い]れに片付[かたづ]けた。", "sentence_source": "generated"}, {"text": "部屋が散らかっているから、まず床の物を片付けよう。", "target_word": "片付けよう", "complexity_tier": "T3", "furigana": "部屋[へや]が散[ち]らかっているから、まず床[ゆか]の物[もの]を片付[かたづ]けよう。", "sentence_source": "generated"}, {"text": "子どもたちは、遊び終わると自分で積み木を片付けられる。", "target_word": "片付けられる", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、遊[あそ]び終[お]わると自分[じぶん]で積[つ]み木[き]を片付[かたづ]けられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "片付ける", "label": "辞書形"}, {"form": "片付けます", "label": "ます形"}, {"form": "片付けない", "label": "否定形"}, {"form": "片付けた", "label": "過去形"}, {"form": "片付けて", "label": "て形"}, {"form": "片付けれ", "label": "仮定形"}, {"form": "片付けよう", "label": "意志形"}, {"form": "片付けられる", "label": "可能形"}], "register": "標準（日常語）", "sense_fingerprint": "散らかった物を元の場所へ戻す（しまう）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a20f6f9-5c1c-4724-a88a-cb37d143b680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36468, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "片付けましょう", "is_correct": true, "explanation": "正解。「ましょう」の勧誘形で、遊んだ後におもちゃを元の場所に戻すよう提案する文に合う。"}, {"text": "散らかしましょう", "is_correct": false, "explanation": "「散らかす」は物を乱す意味で、かごに入れる文脈と合わない。提案の内容も逆になる。"}, {"text": "洗いましょう", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作で、おもちゃをかごに入れる意味にならない。"}, {"text": "壊しましょう", "is_correct": false, "explanation": "「壊す」は物を壊す意味で、遊んだ後にかごへ入れる提案としては成り立たない。"}], "explanations": {"片付けましょう": "正解。「ましょう」の勧誘形で、遊んだ後におもちゃを元の場所に戻すよう提案する文に合う。", "散らかしましょう": "「散らかす」は物を乱す意味で、かごに入れる文脈と合わない。提案の内容も逆になる。", "洗いましょう": "「洗う」は汚れを落とす動作で、おもちゃをかごに入れる意味にならない。", "壊しましょう": "「壊す」は物を壊す意味で、遊んだ後にかごへ入れる提案としては成り立たない。"}, "sentence_index": 0, "correct_answer": "片付けましょう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、寝癖を片付けてから家を出た。", "explanation": "ここは〈整える〉の意味。片付けるは散らかった物を元の場所に戻す意味で、寝癖の乱れには使わない。"}, {"text": "彼は返事の手紙を、ポストに片付けた。", "explanation": "ここは〈出す〉の意味。ポストに入れるのは〈出す〉で、片付けるは物を元の場所に戻す意味なので合わない。"}, {"text": "毎日、彼女は駅前の塾に片付けている。", "explanation": "ここは〈通う〉の意味。場所へ行き来することを表す語で、片付けるは物を元の場所に戻す意味なので使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36468, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "片付けて", "is_correct": true, "explanation": "正解。て形で、書類を引き出しに戻してから帰宅したという流れを表す。"}, {"text": "破いて", "is_correct": false, "explanation": "「破く」は紙を裂く意味で、書類を引き出しに入れる文脈と合わない。"}, {"text": "燃やして", "is_correct": false, "explanation": "「燃やす」は燃焼させる意味で、書類を引き出しに入れる文に合わない。"}, {"text": "濡らして", "is_correct": false, "explanation": "「濡らす」は水で湿らせる意味で、書類を引き出しに入れる文脈と合わない。"}], "explanations": {"片付けて": "正解。て形で、書類を引き出しに戻してから帰宅したという流れを表す。", "破いて": "「破く」は紙を裂く意味で、書類を引き出しに入れる文脈と合わない。", "燃やして": "「燃やす」は燃焼させる意味で、書類を引き出しに入れる文に合わない。", "濡らして": "「濡らす」は水で湿らせる意味で、書類を引き出しに入れる文脈と合わない。"}, "sentence_index": 6, "correct_answer": "片付けて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古いカーテンを、新しいものに片付けた。", "explanation": "ここは〈取り替える〉の意味。片付けるは物を元の場所に戻す意味で、物を別のものに替える動作とは合わない。"}, {"text": "体重を片付けた。", "explanation": "ここは〈減らす〉の意味。片付けるは物を元に戻す意味で、体重を減らす意味にはならない。"}, {"text": "コップに水を片付けた。", "explanation": "ここは〈注ぐ〉の意味。片付けるは物を元に戻す意味で、液体を入れる動作とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36468, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "使い終わった道具は、元の場所に片付けるます。", "corrected_sentence": "使い終わった道具は、元の場所に片付けます。", "error_description": "「片付けるます」は誤り。ます形は連用形「片付け」に「ます」を付けて「片付けます」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "片付けてください", "is_correct": true, "explanation": "正解。て形に「ください」を付けた依頼の形で、本を本棚に戻すよう頼む文に合う。"}, {"text": "片付けさせ", "is_correct": false, "explanation": "使役の語幹。文が途中で切れて成立しない。"}, {"text": "片付け", "is_correct": false, "explanation": "連用形の語幹だけで、文末の述語として成立しない。"}, {"text": "片付けれ", "is_correct": false, "explanation": "仮定形の語幹。文末に置くと成立しない。"}], "correct_form": "片付けてください", "base_form": "片付ける", "form_label": "て形＋ください（依頼）", "sentence_index": 1, "explanations": {"片付けてください": "正解。て形に「ください」を付けた依頼の形で、本を本棚に戻すよう頼む文に合う。", "片付けさせ": "使役の語幹。文が途中で切れて成立しない。", "片付け": "連用形の語幹だけで、文末の述語として成立しない。", "片付けれ": "仮定形の語幹。文末に置くと成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36468, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "食べ終わった皿が、すぐ食器棚に片付けた。", "corrected_sentence": "食べ終わった皿を、すぐ食器棚に片付けた。", "error_description": "「皿が」は主語を示す形で、他動詞「片付けた」の対象は「皿を」になる。「皿が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "片付けた", "is_correct": true, "explanation": "正解。た形で、冬の服を押し入れに戻した過去の動作を表す。"}, {"text": "片付けて", "is_correct": false, "explanation": "て形の途中で文が切れ、文末の述語として成立しない。"}, {"text": "片付けたら", "is_correct": false, "explanation": "条件節の形で、文末に置くと文が成立しない。"}, {"text": "片付けながら", "is_correct": false, "explanation": "同時動作を表す形で、文末に置くと文が成立しない。"}], "correct_form": "片付けた", "base_form": "片付ける", "form_label": "た形（過去）", "sentence_index": 7, "explanations": {"片付けた": "正解。た形で、冬の服を押し入れに戻した過去の動作を表す。", "片付けて": "て形の途中で文が切れ、文末の述語として成立しない。", "片付けたら": "条件節の形で、文末に置くと文が成立しない。", "片付けながら": "同時動作を表す形で、文末に置くと文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36469, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「仕事の前に」で時点を表し、片付けるタイミングを示す。"}, {"text": "で", "is_correct": false, "explanation": "「前で」は場所や手段の意味になり、時点を表せない。"}, {"text": "が", "is_correct": false, "explanation": "主格。前が片付けたという主語になり、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す語で、時間には使えず「前へ」は不自然。"}], "correct_answer": "に", "explanations": {"に": "正解。「仕事の前に」で時点を表し、片付けるタイミングを示す。", "で": "「前で」は場所や手段の意味になり、時点を表せない。", "が": "主格。前が片付けたという主語になり、不自然。", "へ": "方向を表す語で、時間には使えず「前へ」は不自然。"}, "error_tags": {"で": "場所・手段", "が": "主格（主語）", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散らかす", "is_correct": true, "explanation": "正解。整っていない状態にする意味で、片付けるの対義語にあたる。"}, {"text": "買う", "is_correct": false, "explanation": "入手する動作で、対義語ではない。"}, {"text": "歌う", "is_correct": false, "explanation": "声を出す動作で、対義語ではない。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作で、対義語ではない。"}], "correct_answer": "散らかす", "explanations": {"散らかす": "正解。整っていない状態にする意味で、片付けるの対義語にあたる。", "買う": "入手する動作で、対義語ではない。", "歌う": "声を出す動作で、対義語ではない。", "眺める": "見る動作で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36469, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「部屋を」で、片付ける対象を表す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾。部屋の片付けてとなり、動詞を続けられない。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同。部屋と片付けてとなり、文が成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較。部屋より片付けてとなり、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「部屋を」で、片付ける対象を表す。", "の": "連体修飾。部屋の片付けてとなり、動詞を続けられない。", "と": "並列・共同。部屋と片付けてとなり、文が成立しない。", "より": "比較。部屋より片付けてとなり、目的語を示せない。"}, "error_tags": {"の": "連体修飾", "と": "並列・共同", "より": "比較"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散らかす", "is_correct": true, "explanation": "正解。整っていない状態にする意味で、片付けるの対義語にあたる。"}, {"text": "描く", "is_correct": false, "explanation": "絵や図を作る動作で、対義語ではない。"}, {"text": "包む", "is_correct": false, "explanation": "物を覆う動作で、対義語ではない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "大きな声を出す動作で、対義語ではない。"}], "correct_answer": "散らかす", "explanations": {"散らかす": "正解。整っていない状態にする意味で、片付けるの対義語にあたる。", "描く": "絵や図を作る動作で、対義語ではない。", "包む": "物を覆う動作で、対義語ではない。", "叫ぶ": "大きな声を出す動作で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36469, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "散らかっている物を整理して、きちんとした状態にする。", "primary_collocate": null, "pronunciation": "かたづける", "ipa": "katadzɯɾɯ", "syllable_count": 5, "sentences": [{"text": "週末は朝から部屋を片付けて、すっきりした。", "target_word": "片付けて", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は朝[あさ]から部屋[へや]を片付[かたづ]けて、すっきりした。", "sentence_source": "generated"}, {"text": "机の上が汚いので、仕事の前に片付けた。", "target_word": "片付けた", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]が汚[きたな]いので、仕事[しごと]の前[まえ]に片付[かたづ]けた。", "sentence_source": "generated"}, {"text": "大掃除の前に、まず押し入れの中を片付けるつもりだ。", "target_word": "片付ける", "complexity_tier": "T3", "furigana": "大掃除[おおそうじ]の前[まえ]に、まず押[お]し入[い]れの中[なか]を片付[かたづ]けるつもりだ。", "sentence_source": "generated"}, {"text": "台所をきちんと片付けてから、寝ることにしている。", "target_word": "片付けて", "complexity_tier": "T3", "furigana": "台所[だいどころ]をきちんと片付[かたづ]けてから、寝[ね]ることにしている。", "sentence_source": "generated"}, {"text": "引っ越しの荷物が多くて、なかなか片付けられない。", "target_word": "片付けられない", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの荷物[にもつ]が多[おお]くて、なかなか片付[かたづ]けられない。", "sentence_source": "generated"}, {"text": "友だちが泊まりに来るので、リビングを片付けておいた。", "target_word": "片付けて", "complexity_tier": "T3", "furigana": "友[とも]だちが泊[と]まりに来[く]るので、リビングを片付[かたづ]けておいた。", "sentence_source": "generated"}, {"text": "母は毎日、家の中を片付けて、いつもきれいにしている。", "target_word": "片付けて", "complexity_tier": "T3", "furigana": "母[はは]は毎日[まいにち]、家[いえ]の中[なか]を片付[かたづ]けて、いつもきれいにしている。", "sentence_source": "generated"}, {"text": "散らかった庭を片付けたら、広く使えるようになった。", "target_word": "片付けた", "complexity_tier": "T3", "furigana": "散[ち]らかった庭[にわ]を片付[かたづ]けたら、広[ひろ]く使[つか]えるようになった。", "sentence_source": "generated"}, {"text": "彼は机を片付けない人だから、書類がいつも山になっている。", "target_word": "片付けない", "complexity_tier": "T3", "furigana": "彼[かれ]は机[つくえ]を片付[かたづ]けない人[ひと]だから、書類[しょるい]がいつも山[やま]になっている。", "sentence_source": "generated"}, {"text": "来月までに倉庫を片付けて、新しい棚を置く予定だ。", "target_word": "片付けて", "complexity_tier": "T3", "furigana": "来月[らいげつ]までに倉庫[そうこ]を片付[かたづ]けて、新[あたら]しい棚[たな]を置[お]く予定[よてい]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "片付ける", "label": "辞書形"}, {"form": "片付けます", "label": "ます形"}, {"form": "片付けない", "label": "否定形"}, {"form": "片付けた", "label": "過去形"}, {"form": "片付けて", "label": "て形"}, {"form": "片付けれ", "label": "仮定形"}, {"form": "片付けよう", "label": "意志形"}, {"form": "片付けられる", "label": "可能形"}], "register": "標準（日常語）", "sense_fingerprint": "散らかった物を整理して整った状態にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a20f6f9-5c1c-4724-a88a-cb37d143b680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36469, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "片付けて", "is_correct": true, "explanation": "正解。て形で、部屋を整えてすっきりしたという前後関係を表す。"}, {"text": "壊して", "is_correct": false, "explanation": "「壊す」は物を壊す意味で、部屋をすっきりさせる文と合わない。"}, {"text": "散らかして", "is_correct": false, "explanation": "「散らかす」は乱す意味で、すっきりした結果と逆になる。"}, {"text": "脱いで", "is_correct": false, "explanation": "「脱ぐ」は衣類を脱ぐ動作で、部屋を整える意味にならない。"}], "explanations": {"片付けて": "正解。て形で、部屋を整えてすっきりしたという前後関係を表す。", "壊して": "「壊す」は物を壊す意味で、部屋をすっきりさせる文と合わない。", "散らかして": "「散らかす」は乱す意味で、すっきりした結果と逆になる。", "脱いで": "「脱ぐ」は衣類を脱ぐ動作で、部屋を整える意味にならない。"}, "sentence_index": 0, "correct_answer": "片付けて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出かける前に身だしなみを片付けた。", "explanation": "ここは〈整える〉の意味。片付けるは散らかった物を整理する意味で、身だしなみには使わない。"}, {"text": "壁をペンキで片付けた。", "explanation": "ここは〈塗る〉の意味。片付けるは物を整理する意味で、壁を塗る動作には使わない。"}, {"text": "庭に花を片付けた。", "explanation": "ここは〈植える〉の意味。片付けるは物を整える意味で、植物を植える動作とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36469, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "片付けて", "is_correct": true, "explanation": "正解。て形で、家の中を整えていつもきれいに保っている流れを表す。"}, {"text": "燃やして", "is_correct": false, "explanation": "「燃やす」は焼く動作で、家の中を整える意味と合わない。"}, {"text": "汚して", "is_correct": false, "explanation": "「汚す」は汚くする意味で、いつもきれいにしている文と逆になる。"}, {"text": "破いて", "is_correct": false, "explanation": "「破く」は裂く動作で、家の中を整える意味にならない。"}], "explanations": {"片付けて": "正解。て形で、家の中を整えていつもきれいに保っている流れを表す。", "燃やして": "「燃やす」は焼く動作で、家の中を整える意味と合わない。", "汚して": "「汚す」は汚くする意味で、いつもきれいにしている文と逆になる。", "破いて": "「破く」は裂く動作で、家の中を整える意味にならない。"}, "sentence_index": 6, "correct_answer": "片付けて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の木を片付けて、大きくした。", "explanation": "ここは〈育てる〉の意味。片付けるは物を整理する意味で、木を育てる動作とは合わない。"}, {"text": "試合のルールを片付けて、練習を始めた。", "explanation": "ここは〈覚える〉の意味。片付けるは物を整える意味で、ルールを覚える意味にはならない。"}, {"text": "朝、パンをこんがり片付けた。", "explanation": "ここは〈焼く〉の意味。片付けるは物を整える意味で、パンを焼く動作とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36469, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は朝から部屋が片付けて、ゆっくりした。", "corrected_sentence": "週末は朝から部屋を片付けて、ゆっくりした。", "error_description": "「部屋が」は主語を示す。「片付ける」は他動詞なので目的語「部屋を」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "片付けた", "is_correct": true, "explanation": "正解。た形で、仕事の前に机を整えた過去の動作を表す。"}, {"text": "片付けさせ", "is_correct": false, "explanation": "使役の語幹。文が途中で切れて成立しない。"}, {"text": "片付け", "is_correct": false, "explanation": "連用形の語幹だけで、文末の述語として成立しない。"}, {"text": "片付けれ", "is_correct": false, "explanation": "仮定形の語幹。文末に置くと成立しない。"}], "correct_form": "片付けた", "base_form": "片付ける", "form_label": "た形（過去）", "sentence_index": 1, "explanations": {"片付けた": "正解。た形で、仕事の前に机を整えた過去の動作を表す。", "片付けさせ": "使役の語幹。文が途中で切れて成立しない。", "片付け": "連用形の語幹だけで、文末の述語として成立しない。", "片付けれ": "仮定形の語幹。文末に置くと成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36469, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "連休中に書斎を片付けれ、本を整理した。", "corrected_sentence": "連休中に書斎を片付けて、本を整理した。", "error_description": "「片付けれ」は仮定形で、続けて動作を述べる文には「片付けて」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "片付けた", "is_correct": true, "explanation": "正解。た形に「たら」が続き、庭を整理した後の結果を表す。"}, {"text": "片付けます", "is_correct": false, "explanation": "ます形。丁寧な非過去の形で、「たら」の条件節に合わない。"}, {"text": "片付けて", "is_correct": false, "explanation": "て形。「たら」の前には過去の「た形」が必要で、この文に合わない。"}, {"text": "片付けられる", "is_correct": false, "explanation": "可能形。能力を表し、庭を整えた結果を述べる文に合わない。"}], "correct_form": "片付けた", "base_form": "片付ける", "form_label": "た形（たら節）", "sentence_index": 7, "explanations": {"片付けた": "正解。た形に「たら」が続き、庭を整理した後の結果を表す。", "片付けます": "ます形。丁寧な非過去の形で、「たら」の条件節に合わない。", "片付けて": "て形。「たら」の前には過去の「た形」が必要で、この文に合わない。", "片付けられる": "可能形。能力を表し、庭を整えた結果を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36470, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「其々に」で、一人ずつへ課題を渡す意味を表す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾。「の」は後に名詞が必要で、文が成立しない。"}, {"text": "が", "is_correct": false, "explanation": "主格。其々が課題を出したという意味になり、不自然。"}, {"text": "を", "is_correct": false, "explanation": "対象。課題を出すの目的語が二つになり、不自然。"}], "correct_answer": "に", "explanations": {"に": "正解。「其々に」で、一人ずつへ課題を渡す意味を表す。", "の": "連体修飾。「の」は後に名詞が必要で、文が成立しない。", "が": "主格。其々が課題を出したという意味になり、不自然。", "を": "対象。課題を出すの目的語が二つになり、不自然。"}, "error_tags": {"の": "連体修飾", "が": "主格（主語）", "を": "対象（目的語）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
