INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36470, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "それぞれの物や人について、一つ一つを別々に考えるときの言葉です。", "primary_collocate": null, "pronunciation": "それぞれ", "ipa": "soɾedzoɾe", "syllable_count": 4, "sentences": [{"text": "兄弟は其々の部屋を持っていて、互いに入らない決まりだ。", "target_word": "其々", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]は其々[それぞれ]の部屋[へや]を持[も]っていて、互[たが]いに入[はい]らない決[き]まりだ。", "sentence_source": "generated"}, {"text": "先生は生徒の其々に、違う課題を出した。", "target_word": "其々", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の其々[それぞれ]に、違[ちが]う課題[かだい]を出[だ]した。", "sentence_source": "generated"}, {"text": "其々に事情があるので、全員に同じ答えを求めるのは難しい。", "target_word": "其々", "complexity_tier": "T3", "furigana": "其々[それぞれ]に事情[じじょう]があるので、全員[ぜんいん]に同[おな]じ答[こた]えを求[もと]めるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "この店のカレーは三種類あり、其々の味が大きく違う。", "target_word": "其々", "complexity_tier": "T3", "furigana": "この店[みせ]のカレーは三種類[さんしゅるい]あり、其々[それぞれ]の味[あじ]が大[おお]きく違[ちが]う。", "sentence_source": "generated"}, {"text": "会議では、参加者の其々が自分の意見を短く述べた。", "target_word": "其々", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、参加者[さんかしゃ]の其々[それぞれ]が自分[じぶん]の意見[いけん]を短[みじか]く述[の]べた。", "sentence_source": "generated"}, {"text": "国には其々の習慣があるから、旅行の前に調べておくといい。", "target_word": "其々", "complexity_tier": "T3", "furigana": "国[くに]には其々[それぞれ]の習慣[しゅうかん]があるから、旅行[りょこう]の前[まえ]に調[しら]べておくといい。", "sentence_source": "generated"}, {"text": "荷物が混ざらないよう、其々の名前を箱に書いた。", "target_word": "其々", "complexity_tier": "T3", "furigana": "荷物[にもつ]が混[ま]ざらないよう、其々[それぞれ]の名前[なまえ]を箱[はこ]に書[か]いた。", "sentence_source": "generated"}, {"text": "四人の姉妹は其々の道を歩み、今は別の町に住んでいる。", "target_word": "其々", "complexity_tier": "T3", "furigana": "四人[よにん]の姉妹[しまい]は其々[それぞれ]の道[みち]を歩[あゆ]み、今[いま]は別[べつ]の町[まち]に住[す]んでいる。", "sentence_source": "generated"}, {"text": "人の考えは其々だから、無理に合わせなくてもいい。", "target_word": "其々", "complexity_tier": "T3", "furigana": "人[ひと]の考[かんが]えは其々[それぞれ]だから、無理[むり]に合[あ]わせなくてもいい。", "sentence_source": "generated"}, {"text": "贈り物は、受け取る人の其々に合わせて選んでいる。", "target_word": "其々", "complexity_tier": "T3", "furigana": "贈[おく]り物[もの]は、受[う]け取[と]る人[ひと]の其々[それぞれ]に合[あ]わせて選[えら]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "其々", "label": "基本形"}, {"form": "其々の", "label": "連体形"}], "register": "標準（日常語）", "sense_fingerprint": "名詞：各自・一つ一つを別々にとらえたもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a20f6f9-5c1c-4724-a88a-cb37d143b680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36470, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "其々", "is_correct": true, "explanation": "正解。名詞「其々の部屋」で、一人ずつ別々に部屋を持つ意味に合う。"}, {"text": "玄関", "is_correct": false, "explanation": "「玄関の部屋」は意味が成り立たず、部屋を持つ文と合わない。"}, {"text": "天井", "is_correct": false, "explanation": "「天井の部屋」は不自然で、部屋を持つ文に合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫の部屋」は不自然で、部屋を持つ文に合わない。"}], "explanations": {"其々": "正解。名詞「其々の部屋」で、一人ずつ別々に部屋を持つ意味に合う。", "玄関": "「玄関の部屋」は意味が成り立たず、部屋を持つ文と合わない。", "天井": "「天井の部屋」は不自然で、部屋を持つ文に合わない。", "冷蔵庫": "「冷蔵庫の部屋」は不自然で、部屋を持つ文に合わない。"}, "sentence_index": 0, "correct_answer": "其々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店のカレーは一種類だけなので、其々の味が違う。", "explanation": "ここは〈単一〉の意味。其々は複数を一つずつ区別する語なので、一種類だけの場面には使わない。"}, {"text": "試合の前に、全員が其々一緒に円陣を組んだ。", "explanation": "ここは〈一括〉の意味。其々は一つ一つ別々に扱う語なので、皆で同時にまとめて行う場面とは合わない。"}, {"text": "会社には其々ただ一人の社長がいる。", "explanation": "ここは〈唯一〉の意味。其々は複数を個別に扱う語なので、一人だけを指す文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36470, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其々", "is_correct": true, "explanation": "正解。名詞「其々の名前」で、箱ごとに一人ずつ名前を書く意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の名前」は意味が成り立たず、箱に書く文と合わない。"}, {"text": "寝室", "is_correct": false, "explanation": "「寝室の名前」は不自然で、荷物に名前を書く文と合わない。"}, {"text": "交差点", "is_correct": false, "explanation": "「交差点の名前」は不自然で、荷物に名前を書く文と合わない。"}], "explanations": {"其々": "正解。名詞「其々の名前」で、箱ごとに一人ずつ名前を書く意味に合う。", "天気": "「天気の名前」は意味が成り立たず、箱に書く文と合わない。", "寝室": "「寝室の名前」は不自然で、荷物に名前を書く文と合わない。", "交差点": "「交差点の名前」は不自然で、荷物に名前を書く文と合わない。"}, "sentence_index": 6, "correct_answer": "其々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この大会の優勝者は、其々一人だけだった。", "explanation": "ここは〈単独〉の意味。其々は複数を個別に扱う語なので、ただ一人を指す文には使わない。"}, {"text": "友だちは、其々一緒に映画を見に行くと言った。", "explanation": "ここは〈共同〉の意味。其々は別々を表すので、共同で行動する意味と矛盾する。"}, {"text": "彼は其々の話を、まとめて一度に聞いた。", "explanation": "ここは〈一斉に〉の意味。其々は一つずつ別々に扱う語なので、一度に聞く文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36470, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三人は其々な飲み物を注文した。", "corrected_sentence": "三人は其々の飲み物を注文した。", "error_description": "「其々」は名詞なので連体修飾は「の」。「な」は形容動詞の語尾で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36470, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三人の子どもは其々にの部屋を使っている。", "corrected_sentence": "三人の子どもは其々の部屋を使っている。", "error_description": "「にの」は助詞が二重に重なった誤り。名詞「其々」は「の」で部屋を修飾する。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
