INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36471, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "複数の物事や人について、一つ一つ別々に、あるいは個別にという意味の副詞。", "primary_collocate": null, "pronunciation": "それぞれ", "ipa": "soɾedzoɾe", "syllable_count": 4, "sentences": [{"text": "三人は其々好きな飲み物を注文した。", "target_word": "其々", "complexity_tier": "T3", "furigana": "三人[さんにん]は其々[それぞれ]好[す]きな飲[の]み物[もの]を注文[ちゅうもん]した。", "sentence_source": "generated"}, {"text": "パーティーが終わると、みんなは其々自分の家に帰った。", "target_word": "其々", "complexity_tier": "T3", "furigana": "パーティーが終[お]わると、みんなは其々[それぞれ]自分[じぶん]の家[いえ]に帰[かえ]った。", "sentence_source": "generated"}, {"text": "双子は同じ服を着ているが、性格は其々違う。", "target_word": "其々", "complexity_tier": "T3", "furigana": "双子[ふたご]は同[おな]じ服[ふく]を着[き]ているが、性格[せいかく]は其々[それぞれ]違[ちが]う。", "sentence_source": "generated"}, {"text": "部員たちは其々違う楽器を練習している。", "target_word": "其々", "complexity_tier": "T3", "furigana": "部員[ぶいん]たちは其々[それぞれ]違[ちが]う楽器[がっき]を練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "この三つの箱は、其々重さが違うので、運ぶ順番を考えた。", "target_word": "其々", "complexity_tier": "T3", "furigana": "この三[みっ]つの箱[はこ]は、其々[それぞれ]重[おも]さが違[ちが]うので、運[はこ]ぶ順番[じゅんばん]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "先生の質問に、生徒たちは其々自分の考えを答えた。", "target_word": "其々", "complexity_tier": "T3", "furigana": "先生[せんせい]の質問[しつもん]に、生徒[せいと]たちは其々[それぞれ]自分[じぶん]の考[かんが]えを答[こた]えた。", "sentence_source": "generated"}, {"text": "二つの会社は其々独立して運営されている。", "target_word": "其々", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]は其々[それぞれ]独立[どくりつ]して運営[うんえい]されている。", "sentence_source": "generated"}, {"text": "参加者は其々違う町から集まった。", "target_word": "其々", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]は其々[それぞれ]違[ちが]う町[まち]から集[あつ]まった。", "sentence_source": "generated"}, {"text": "弁当は其々別に包んで、冷蔵庫に入れた。", "target_word": "其々", "complexity_tier": "T3", "furigana": "弁当[べんとう]は其々[それぞれ]別[べつ]に包[つつ]んで、冷蔵庫[れいぞうこ]に入[い]れた。", "sentence_source": "generated"}, {"text": "兄と姉は其々別の大学に進学した。", "target_word": "其々", "complexity_tier": "T3", "furigana": "兄[あに]と姉[あね]は其々[それぞれ]別[べつ]の大学[だいがく]に進学[しんがく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "其々", "label": "基本形"}], "register": "標準（日常語）", "sense_fingerprint": "副詞：各自が別々に、個別に", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a20f6f9-5c1c-4724-a88a-cb37d143b680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36471, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "其々", "is_correct": true, "explanation": "正解。副詞「其々」で、三人がそれぞれ別々に好きな飲み物を選ぶ意味に合う。"}, {"text": "二度と", "is_correct": false, "explanation": "否定と呼応する副詞で、肯定の注文文には合わない。"}, {"text": "決して", "is_correct": false, "explanation": "否定と呼応する副詞で、肯定の注文文には合わない。"}, {"text": "全く", "is_correct": false, "explanation": "程度や否定を強める語で、注文が個別であることを示す文脈に合わない。"}], "explanations": {"其々": "正解。副詞「其々」で、三人がそれぞれ別々に好きな飲み物を選ぶ意味に合う。", "二度と": "否定と呼応する副詞で、肯定の注文文には合わない。", "決して": "否定と呼応する副詞で、肯定の注文文には合わない。", "全く": "程度や否定を強める語で、注文が個別であることを示す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "其々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部員たちは其々一斉に楽器を練習している。", "explanation": "ここは〈同時〉の意味。其々は個別を表すので、同時に行う意味と矛盾する。"}, {"text": "部員たちは其々、同じ楽器を全員で演奏している。", "explanation": "ここは〈共同〉の意味。其々は一つずつ別々を表すので、同じ行動を皆で行う文とは合わない。"}, {"text": "部員の其々の楽器を、一つずつ数えた。", "explanation": "ここは名詞〈それぞれの物〉の用法。副詞の「別々に」ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36471, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其々", "is_correct": true, "explanation": "正解。副詞「其々」で、二つの会社がそれぞれ別個に独立して運営されているという意味に合う。"}, {"text": "一緒に", "is_correct": false, "explanation": "共に行う意味で、独立して運営される文と矛盾する。"}, {"text": "まとめて", "is_correct": false, "explanation": "一括にする意味で、独立して運営される文脈に合わない。"}, {"text": "ふと", "is_correct": false, "explanation": "思いつくさまを表す副詞で、運営の様子を述べる文に合わない。"}], "explanations": {"其々": "正解。副詞「其々」で、二つの会社がそれぞれ別個に独立して運営されているという意味に合う。", "一緒に": "共に行う意味で、独立して運営される文と矛盾する。", "まとめて": "一括にする意味で、独立して運営される文脈に合わない。", "ふと": "思いつくさまを表す副詞で、運営の様子を述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "其々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄は其々一人暮らしを始めた。", "explanation": "ここは〈単独〉の意味。其々は複数を個別に扱う語で、一人の行動を述べる文には使わない。"}, {"text": "兄と姉は、其々の大学の案内を読んだ。", "explanation": "ここは名詞〈それぞれの物〉の用法。副詞の「別々に」ではない。"}, {"text": "兄と姉は其々の進学を、一度にまとめて決めた。", "explanation": "ここは〈一括〉の意味。其々は一つずつ別々に扱う語なので、一度に決める文とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36471, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三人の性格は其々の違う。", "corrected_sentence": "三人の性格は其々違う。", "error_description": "副詞「其々」は連体修飾の「の」を取らず、「其々違う」と述語を直接修飾する。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36471, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つの店は其々と独自の味を出している。", "corrected_sentence": "二つの店は其々独自の味を出している。", "error_description": "副詞「其々」の後に助詞「と」は付かない。「其々独自の味」と直接続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36472, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不当", "is_correct": true, "explanation": "「妥当」の反対で、根拠や道理に合わないことを表す。"}, {"text": "豪華", "is_correct": false, "explanation": "立派で華やかな様子を表し、妥当の反対語ではない。"}, {"text": "器用", "is_correct": false, "explanation": "手際の良さを表し、妥当の反対語ではない。"}, {"text": "健康", "is_correct": false, "explanation": "体の状態を表し、妥当とは対にならない。"}], "correct_answer": "不当", "explanations": {"不当": "「妥当」の反対で、根拠や道理に合わないことを表す。", "豪華": "立派で華やかな様子を表し、妥当の反対語ではない。", "器用": "手際の良さを表し、妥当の反対語ではない。", "健康": "体の状態を表し、妥当とは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36472, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不当", "is_correct": true, "explanation": "「妥当」の反対で、根拠や道理に合わないことを表す。"}, {"text": "地味", "is_correct": false, "explanation": "派手さのなさを表し、妥当の反対語ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "ていねいな様子を表し、妥当とは対にならない。"}, {"text": "安全", "is_correct": false, "explanation": "危険がないことを表し、妥当とは対にならない。"}], "correct_answer": "不当", "explanations": {"不当": "「妥当」の反対で、根拠や道理に合わないことを表す。", "地味": "派手さのなさを表し、妥当の反対語ではない。", "丁寧": "ていねいな様子を表し、妥当とは対にならない。", "安全": "危険がないことを表し、妥当とは対にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36472, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "その考えややり方が正しいかどうかを考えるとき、ちゃんと理由があって正しいと言えること。", "primary_collocate": null, "pronunciation": "だとう", "ipa": "datoː", "syllable_count": 3, "sentences": [{"text": "理由をていねいに説明したので、彼の考えは妥当だと認められた。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "理由[りゆう]をていねいに説明[せつめい]したので、彼[かれ]の考[かんが]えは妥当[だとう]だと認[みと]められた。", "sentence_source": "generated"}, {"text": "データを調べたところ、この方法がいちばん妥当だと分かった。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "データを調[しら]べたところ、この方法[ほうほう]がいちばん妥当[だとう]だと分[わ]かった。", "sentence_source": "generated"}, {"text": "彼女の意見は感情だけで、理由がなく、妥当とは言えない。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の意見[いけん]は感情[かんじょう]だけで、理由[りゆう]がなく、妥当[だとう]とは言[い]えない。", "sentence_source": "generated"}, {"text": "先生の説明には根拠があって、とても妥当な考え方だと思う。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "先生[せんせい]の説明[せつめい]には根拠[こんきょ]があって、とても妥当[だとう]な考[かんが]え方[かた]だと思[おも]う。", "sentence_source": "generated"}, {"text": "実験の結果から見ると、その説は妥当だと言える。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "実験[じっけん]の結果[けっか]から見[み]ると、その説[せつ]は妥当[だとう]だと言[い]える。", "sentence_source": "generated"}, {"text": "材料の数を考えれば、この作り方は妥当なやり方だ。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "材料[ざいりょう]の数[かず]を考[かんが]えれば、この作[つく]り方[かた]は妥当[だとう]なやり方[かた]だ。", "sentence_source": "generated"}, {"text": "理由もなく反対するより、まず妥当な案を出してほしい。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "理由[りゆう]もなく反対[はんたい]するより、まず妥当[だとう]な案[あん]を出[だ]してほしい。", "sentence_source": "generated"}, {"text": "彼の話は筋が通っていて、妥当だと感じた。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は筋[すじ]が通[とお]っていて、妥当[だとう]だと感[かん]じた。", "sentence_source": "generated"}, {"text": "その結論が妥当かどうかは、もう一度確かめないと分からない。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "その結論[けつろん]が妥当[だとう]かどうかは、もう一度[いちど]確[たし]かめないと分[わ]からない。", "sentence_source": "generated"}, {"text": "反対の理由が弱いので、会社の方針は妥当だと考えられる。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "反対[はんたい]の理由[りゆう]が弱[よわ]いので、会社[かいしゃ]の方針[ほうしん]は妥当[だとう]だと考[かんが]えられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "妥当だ", "label": "断定形"}, {"form": "妥当な", "label": "連体形"}, {"form": "妥当で", "label": "連用形"}, {"form": "妥当ではない", "label": "否定形"}, {"form": "妥当だった", "label": "過去形"}], "register": "formal", "sense_fingerprint": "考え・方法・説明に根拠があり、正しいと認められること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36472, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妥当", "is_correct": true, "explanation": "形状詞で、「考えは妥当だと認められた」と根拠があって正しいことを表す。"}, {"text": "静か", "is_correct": false, "explanation": "「静かだ」は音や雰囲気の穏やかさを表し、考えの正しさを表さない。"}, {"text": "不器用", "is_correct": false, "explanation": "「不器用だ」は手先や要領の悪さを表し、考えが正しいという意味にならない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気だ」は性格や雰囲気の明るさを表し、考えの正しさには合わない。"}], "explanations": {"妥当": "形状詞で、「考えは妥当だと認められた」と根拠があって正しいことを表す。", "静か": "「静かだ」は音や雰囲気の穏やかさを表し、考えの正しさを表さない。", "不器用": "「不器用だ」は手先や要領の悪さを表し、考えが正しいという意味にならない。", "陽気": "「陽気だ」は性格や雰囲気の明るさを表し、考えの正しさには合わない。"}, "sentence_index": 0, "correct_answer": "妥当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は質問に妥当な顔をして、先生に叱られた。", "explanation": "ここは〈とりつくろう〉の意味。妥当は道理に合うことで、顔つきや態度には使わないので誤り。"}, {"text": "チームは強敵の妥当を目指して、練習を重ねた。", "explanation": "ここは〈打倒〉（相手を倒す）の意味。妥当は道理に合っていることで、相手を倒す意味では使わない。"}, {"text": "この靴は足にとても妥当だった。", "explanation": "ここは〈ぴったり合う〉（寸法が合う）の意味。妥当は理由があって正しいことを表し、体に合うことは言わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36472, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妥当", "is_correct": true, "explanation": "「まず妥当な案」で、根拠があり道理に合った案を表す。"}, {"text": "無口", "is_correct": false, "explanation": "「無口な案」は話す量が少ない人を表し、案の内容には合わない。"}, {"text": "陰気", "is_correct": false, "explanation": "「陰気な案」は雰囲気の暗さを表し、案の内容には合わない。"}, {"text": "不潔", "is_correct": false, "explanation": "「不潔な案」は衛生面の汚れを表し、案の内容には合わない。"}], "explanations": {"妥当": "「まず妥当な案」で、根拠があり道理に合った案を表す。", "無口": "「無口な案」は話す量が少ない人を表し、案の内容には合わない。", "陰気": "「陰気な案」は雰囲気の暗さを表し、案の内容には合わない。", "不潔": "「不潔な案」は衛生面の汚れを表し、案の内容には合わない。"}, "sentence_index": 6, "correct_answer": "妥当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工事は妥当な音を立てて進んでいる。", "explanation": "ここは〈順調〉の意味ではなく、音の描写にも使えない。妥当は理にかなっていて正しいことを表すので誤り。"}, {"text": "昨日は仕事が多くて、妥当に疲れた。", "explanation": "ここは〈相当に〉（かなり）の意味。妥当は根拠や道理に合っていることで、程度の強さは表さない。"}, {"text": "長い話し合いの末、ついに交渉が妥当を迎えた。", "explanation": "ここは〈妥結〉（話し合いがまとまる）の意味。妥当は道理に合うことで、話がまとまる意味は表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36472, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "説明が筋道立っていて、妥当の結論だ。", "corrected_sentence": "説明が筋道立っていて、妥当な結論だ。", "error_description": "形状詞「妥当」は名詞を修飾するとき「な」を付ける。「の」では名詞に続かず誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "妥当", "is_correct": true, "explanation": "語幹で、「だと」の前に置いて「いちばん妥当だと分かった」となる。"}, {"text": "妥当な", "is_correct": false, "explanation": "連体形だと「妥当なだと」となり、「だと」に続かない。"}, {"text": "妥当で", "is_correct": false, "explanation": "連用形だと「妥当でだと」となり、「だと」に続かない。"}, {"text": "妥当に", "is_correct": false, "explanation": "副詞形だと「妥当にだと」となり、「だと」に続かない。"}], "correct_form": "妥当", "base_form": "妥当", "form_label": "語幹", "sentence_index": 1, "explanations": {"妥当": "語幹で、「だと」の前に置いて「いちばん妥当だと分かった」となる。", "妥当な": "連体形だと「妥当なだと」となり、「だと」に続かない。", "妥当で": "連用形だと「妥当でだと」となり、「だと」に続かない。", "妥当に": "副詞形だと「妥当にだと」となり、「だと」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36472, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の判断は状況を考えると妥当で思う。", "corrected_sentence": "彼の判断は状況を考えると妥当だと思う。", "error_description": "「思う」の前には引用の「と」が必要。「妥当で」は連用形で、正しくは「妥当だと思う」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "妥当", "is_correct": true, "explanation": "語幹で、「だ」の前に置いて「妥当だ」となり、「だと感じた」の形に続く。"}, {"text": "妥当だ", "is_correct": false, "explanation": "断定形の「だ」が重なり、「妥当だだと感じた」となるので文に合わない。"}, {"text": "妥当ではない", "is_correct": false, "explanation": "否定形で、「妥当ではないだと感じた」となり、「だと」に続かない。"}, {"text": "妥当だった", "is_correct": false, "explanation": "過去形で、「妥当だっただと感じた」となり、「だと」に続かない。"}], "correct_form": "妥当", "base_form": "妥当", "form_label": "語幹", "sentence_index": 7, "explanations": {"妥当": "語幹で、「だ」の前に置いて「妥当だ」となり、「だと感じた」の形に続く。", "妥当だ": "断定形の「だ」が重なり、「妥当だだと感じた」となるので文に合わない。", "妥当ではない": "否定形で、「妥当ではないだと感じた」となり、「だと」に続かない。", "妥当だった": "過去形で、「妥当だっただと感じた」となり、「だと」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36473, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不当", "is_correct": true, "explanation": "「妥当」の反対で、判断や値段が状況や道理に合わないことを表す。"}, {"text": "陰気", "is_correct": false, "explanation": "雰囲気の暗さを表し、妥当の反対語ではない。"}, {"text": "地味", "is_correct": false, "explanation": "派手さのなさを表し、妥当とは対にならない。"}, {"text": "丁寧", "is_correct": false, "explanation": "ていねいな様子を表し、妥当とは対にならない。"}], "correct_answer": "不当", "explanations": {"不当": "「妥当」の反対で、判断や値段が状況や道理に合わないことを表す。", "陰気": "雰囲気の暗さを表し、妥当の反対語ではない。", "地味": "派手さのなさを表し、妥当とは対にならない。", "丁寧": "ていねいな様子を表し、妥当とは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
