INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36473, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事の考え方や判断が、状況や道理に合っていて正しいこと。", "primary_collocate": null, "pronunciation": "だとう", "ipa": "datoː", "syllable_count": 3, "sentences": [{"text": "遅刻が三回続いたので、注意を受けるのは妥当だ。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "遅刻[ちこく]が三回[さんかい]続[つづ]いたので、注意[ちゅうい]を受[う]けるのは妥当[だとう]だ。", "sentence_source": "generated"}, {"text": "品質を考えると、この値段は妥当だと思う。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "品質[ひんしつ]を考[かんが]えると、この値段[ねだん]は妥当[だとう]だと思[おも]う。", "sentence_source": "generated"}, {"text": "雨が強いので、試合を中止にした判断は妥当だった。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]いので、試合[しあい]を中止[ちゅうし]にした判断[はんだん]は妥当[だとう]だった。", "sentence_source": "generated"}, {"text": "彼は何も悪くないのに、そんな罰は妥当ではない。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]も悪[わる]くないのに、そんな罰[ばつ]は妥当[だとう]ではない。", "sentence_source": "generated"}, {"text": "仕事の量が多いので、給料が上がるのは妥当な結果だ。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "仕事[しごと]の量[りょう]が多[おお]いので、給料[きゅうりょう]が上[あ]がるのは妥当[だとう]な結果[けっか]だ。", "sentence_source": "generated"}, {"text": "状況を考えれば、彼女が断ったのも妥当な対応だった。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "状況[じょうきょう]を考[かんが]えれば、彼女[かのじょ]が断[ことわ]ったのも妥当[だとう]な対応[たいおう]だった。", "sentence_source": "generated"}, {"text": "部屋の広さのわりに家賃が高く、妥当とは言えない。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "部屋[へや]の広[ひろ]さのわりに家賃[やちん]が高[たか]く、妥当[だとう]とは言[い]えない。", "sentence_source": "generated"}, {"text": "十分に練習したのだから、彼が選ばれたのは妥当だ。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]に練習[れんしゅう]したのだから、彼[かれ]が選[えら]ばれたのは妥当[だとう]だ。", "sentence_source": "generated"}, {"text": "事故の原因は店にあるので、店が代金を返すのは妥当だ。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]は店[みせ]にあるので、店[みせ]が代金[だいきん]を返[かえ]すのは妥当[だとう]だ。", "sentence_source": "generated"}, {"text": "医者が休むように言ったのは、熱が高かったので妥当な指示だった。", "target_word": "妥当", "complexity_tier": "T3", "furigana": "医者[いしゃ]が休[やす]むように言[い]ったのは、熱[ねつ]が高[たか]かったので妥当[だとう]な指示[しじ]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "妥当だ", "label": "断定形"}, {"form": "妥当な", "label": "連体形"}, {"form": "妥当で", "label": "連用形"}, {"form": "妥当ではない", "label": "否定形"}, {"form": "妥当だった", "label": "過去形"}], "register": "formal", "sense_fingerprint": "判断・結果・値段などが状況や道理に合っていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36473, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妥当", "is_correct": true, "explanation": "「注意を受けるのは妥当だ」で、状況や道理に合っていることを表す。"}, {"text": "豪華", "is_correct": false, "explanation": "「豪華だ」は派手で立派なことを表し、注意の道理には合わない。"}, {"text": "元気", "is_correct": false, "explanation": "「元気だ」は体の調子や活気を表し、注意の是非には合わない。"}, {"text": "几帳面", "is_correct": false, "explanation": "「几帳面だ」は細かく正確な性格を表し、注意を受けるという判断には合わない。"}], "explanations": {"妥当": "「注意を受けるのは妥当だ」で、状況や道理に合っていることを表す。", "豪華": "「豪華だ」は派手で立派なことを表し、注意の道理には合わない。", "元気": "「元気だ」は体の調子や活気を表し、注意の是非には合わない。", "几帳面": "「几帳面だ」は細かく正確な性格を表し、注意を受けるという判断には合わない。"}, "sentence_index": 0, "correct_answer": "妥当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その日は妥当に寒かったので、上着を着た。", "explanation": "ここは〈相当に〉（かなり）の意味。妥当は状況や道理に合っていることで、程度の強さは表さないので誤り。"}, {"text": "昨夜は妥当な夢を見て、朝まで眠った。", "explanation": "ここは〈ぐっすり〉（深く眠る）の意味。妥当は道理に合うことで、眠りの深さや夢の内容は表さないので誤り。"}, {"text": "王者の妥当を目指して、チームは燃えた。", "explanation": "ここは〈打倒〉（相手を倒す）の意味。妥当は状況や道理に合っていることで、相手を倒す意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36473, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妥当", "is_correct": true, "explanation": "「妥当とは言えない」で、状況に合った適切さを表す。"}, {"text": "無口", "is_correct": false, "explanation": "「無口とは言えない」は話す量の少なさを表し、家賃の評価には合わない。"}, {"text": "不潔", "is_correct": false, "explanation": "「不潔とは言えない」は衛生面を表し、家賃の評価には合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気とは言えない」は性格の明るさを表し、家賃の評価には合わない。"}], "explanations": {"妥当": "「妥当とは言えない」で、状況に合った適切さを表す。", "無口": "「無口とは言えない」は話す量の少なさを表し、家賃の評価には合わない。", "不潔": "「不潔とは言えない」は衛生面を表し、家賃の評価には合わない。", "陽気": "「陽気とは言えない」は性格の明るさを表し、家賃の評価には合わない。"}, "sentence_index": 6, "correct_answer": "妥当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ようやく両者が妥当の箱を開けた。", "explanation": "ここは〈妥結〉（話し合いがまとまる）の意味。妥当は道理に合うことで、話し合いのまとまりは表さないので誤り。"}, {"text": "夜更けに妥当な知らせが届いた。", "explanation": "ここは〈不吉〉（縁起が悪い）の意味。妥当は状況や道理に合っていることで、縁起の悪さを表さないので誤り。"}, {"text": "会議室に妥当な空気が流れた。", "explanation": "ここは〈不穏〉（落ち着かない）の意味。妥当は道理に合っていることで、空気の不安定さを表さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36473, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "遅刻に罰を与えるのは妥当で判断だ。", "corrected_sentence": "遅刻に罰を与えるのは妥当な判断だ。", "error_description": "名詞を修飾するときは「妥当な」。連用形の「妥当で」は名詞に続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "妥当", "is_correct": true, "explanation": "語幹で、「だと思う」の前に置いて「この値段は妥当だと思う」となる。"}, {"text": "妥当な", "is_correct": false, "explanation": "連体形だと「だと思う」に続かず、文が成り立たない。"}, {"text": "妥当で", "is_correct": false, "explanation": "連用形だと「だと」の前に続かず、文が成り立たない。"}, {"text": "妥当に", "is_correct": false, "explanation": "副詞形だと「この値段は妥当にだと思う」となり、文が成り立たない。"}], "correct_form": "妥当", "base_form": "妥当", "form_label": "語幹", "sentence_index": 1, "explanations": {"妥当": "語幹で、「だと思う」の前に置いて「この値段は妥当だと思う」となる。", "妥当な": "連体形だと「だと思う」に続かず、文が成り立たない。", "妥当で": "連用形だと「だと」の前に続かず、文が成り立たない。", "妥当に": "副詞形だと「この値段は妥当にだと思う」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36473, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "価格を考えれば、その提案は妥当だ思う。", "corrected_sentence": "価格を考えれば、その提案は妥当だと思う。", "error_description": "引用の「と」が抜けている。「妥当だと思う」の形が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "妥当", "is_correct": true, "explanation": "語幹で、「だ」を付けて「妥当だ」となり、判断の評価を述べる文に続く。"}, {"text": "妥当だ", "is_correct": false, "explanation": "断定形の「だ」が重なり、「妥当だだ」となるので文が成り立たない。"}, {"text": "妥当ではない", "is_correct": false, "explanation": "否定形で、「妥当ではないだ」となり、「妥当だ」の形にならず文に合わない。"}, {"text": "妥当だった", "is_correct": false, "explanation": "過去形で、「妥当だっただ」となり、現在の断定の文に合わない。"}], "correct_form": "妥当", "base_form": "妥当", "form_label": "語幹", "sentence_index": 7, "explanations": {"妥当": "語幹で、「だ」を付けて「妥当だ」となり、判断の評価を述べる文に続く。", "妥当だ": "断定形の「だ」が重なり、「妥当だだ」となるので文が成り立たない。", "妥当ではない": "否定形で、「妥当ではないだ」となり、「妥当だ」の形にならず文に合わない。", "妥当だった": "過去形で、「妥当だっただ」となり、現在の断定の文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36474, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「視座に立つ」は「立場に立つ」と同じ形で、立つ基準を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「視座が立つ」は視座を主語にしても立つ動作が成り立たず、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「視座を立つ」は立つの目的語にできず、誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「視座へ立つ」は方向を表すが、「視座に立つ」という慣用の形と合わない。"}], "correct_answer": "に", "explanations": {"に": "「視座に立つ」は「立場に立つ」と同じ形で、立つ基準を示す正しい助詞。", "が": "「視座が立つ」は視座を主語にしても立つ動作が成り立たず、不自然。", "を": "「視座を立つ」は立つの目的語にできず、誤り。", "へ": "「視座へ立つ」は方向を表すが、「視座に立つ」という慣用の形と合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36474, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「庶民の視座から描く」の形で、描く立場の出発点を示す正しい助詞。"}, {"text": "と", "is_correct": false, "explanation": "「視座と描く」は並列や相手を表すが、描く立場を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「視座より描く」は比較を表し、描く立場の意味にならない。"}, {"text": "の", "is_correct": false, "explanation": "「視座の描く」は連体修飾で、動詞が直接続く形にならず不自然。"}], "correct_answer": "から", "explanations": {"から": "「庶民の視座から描く」の形で、描く立場の出発点を示す正しい助詞。", "と": "「視座と描く」は並列や相手を表すが、描く立場を示せない。", "より": "「視座より描く」は比較を表し、描く立場の意味にならない。", "の": "「視座の描く」は連体修飾で、動詞が直接続く形にならず不自然。"}, "error_tags": {"と": "並列・相手", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36474, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものの見方や考え方の立場のこと。", "primary_collocate": null, "pronunciation": "しざ", "ipa": "ɕiza", "syllable_count": 2, "sentences": [{"text": "社長と新入社員では、物事を見る視座が大きく違う。", "target_word": "視座", "complexity_tier": "T3", "furigana": "社長[しゃちょう]と新入社員[しんにゅうしゃいん]では、物事[ものごと]を見[み]る視座[しざ]が大[おお]きく違[ちが]う。", "sentence_source": "generated"}, {"text": "彼は消費者の視座に立って、商品の説明を書き直した。", "target_word": "視座", "complexity_tier": "T3", "furigana": "彼[かれ]は消費者[しょうひしゃ]の視座[しざ]に立[た]って、商品[しょうひん]の説明[せつめい]を書[か]き直[なお]した。", "sentence_source": "generated"}, {"text": "同じ事件でも、被害者の視座から見ると、まったく別の問題に思える。", "target_word": "視座", "complexity_tier": "T3", "furigana": "同[おな]じ事件[じけん]でも、被害者[ひがいしゃ]の視座[しざ]から見[み]ると、まったく別[べつ]の問題[もんだい]に思[おも]える。", "sentence_source": "generated"}, {"text": "専門家だけでなく、市民の視座も取り入れて計画を作るべきだ。", "target_word": "視座", "complexity_tier": "T3", "furigana": "専門家[せんもんか]だけでなく、市民[しみん]の視座[しざ]も取[と]り入[い]れて計画[けいかく]を作[つく]るべきだ。", "sentence_source": "generated"}, {"text": "親になってから、子どもの視座で世界を考えるようになった。", "target_word": "視座", "complexity_tier": "T3", "furigana": "親[おや]になってから、子[こ]どもの視座[しざ]で世界[せかい]を考[かんが]えるようになった。", "sentence_source": "generated"}, {"text": "彼女の話は視座が独特なので、聞くたびに発見がある。", "target_word": "視座", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の話[はなし]は視座[しざ]が独特[どくとく]なので、聞[き]くたびに発見[はっけん]がある。", "sentence_source": "generated"}, {"text": "視座が違うと、同じ言葉でも意味の受け取り方が変わる。", "target_word": "視座", "complexity_tier": "T3", "furigana": "視座[しざ]が違[ちが]うと、同[おな]じ言葉[ことば]でも意味[いみ]の受[う]け取[と]り方[かた]が変[か]わる。", "sentence_source": "generated"}, {"text": "筆者は歴史を、庶民の視座から描こうとした。", "target_word": "視座", "complexity_tier": "T3", "furigana": "筆者[ひっしゃ]は歴史[れきし]を、庶民[しょみん]の視座[しざ]から描[えが]こうとした。", "sentence_source": "generated"}, {"text": "会議では、各部署の視座をぶつけ合って結論を出した。", "target_word": "視座", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、各部署[かくぶしょ]の視座[しざ]をぶつけ合[あ]って結論[けつろん]を出[だ]した。", "sentence_source": "generated"}, {"text": "外国人の視座を知ることで、自国の文化を見直すことができた。", "target_word": "視座", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]の視座[しざ]を知[し]ることで、自国[じこく]の文化[ぶんか]を見直[みなお]すことができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "視座", "label": "基本形"}], "register": "やや硬い（書き言葉・ビジネス）", "sense_fingerprint": "ものの見方・考え方の立場", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a20f6f9-5c1c-4724-a88a-cb37d143b680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36474, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "視座", "is_correct": true, "explanation": "ものの見方の立場を表し、「物事を見る視座が大きく違う」と自然につながる。"}, {"text": "予算", "is_correct": false, "explanation": "金銭の見積もりを指すため、「物事を見る予算」とは言えず文が成り立たない。"}, {"text": "締め切り", "is_correct": false, "explanation": "期限を表す語で、「物事を見る締め切り」は意味が通らない。"}, {"text": "報酬", "is_correct": false, "explanation": "仕事への見返りの金銭で、物事を見る対象にはならない。"}], "explanations": {"視座": "ものの見方の立場を表し、「物事を見る視座が大きく違う」と自然につながる。", "予算": "金銭の見積もりを指すため、「物事を見る予算」とは言えず文が成り立たない。", "締め切り": "期限を表す語で、「物事を見る締め切り」は意味が通らない。", "報酬": "仕事への見返りの金銭で、物事を見る対象にはならない。"}, "sentence_index": 0, "correct_answer": "視座"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は視座が大きく、会議室の端まで響く。", "explanation": "ここは〈声の大きさ〉の意味。「声が大きい」は自然だが、視座は立場を指すので声量の話には使えない。"}, {"text": "霧が濃くて視座が悪く、遠くの山が見えない。", "explanation": "ここは〈視野〉の意味。見通せる範囲は視座では表さず、「視野が悪い」と言うべき場面。"}, {"text": "祖父は年々視座が落ち、新聞の小さな字が読めなくなった。", "explanation": "ここは〈視力〉の意味。目の働きの低下を指すのは視力で、見る立場の視座は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36474, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "視座", "is_correct": true, "explanation": "ものの見方の立場を表し、「視座が違うと意味の受け取り方が変わる」と文脈に合う。"}, {"text": "勝敗", "is_correct": false, "explanation": "勝ち負けの結果を指し、ものの見方の違いとして文が成り立たない。"}, {"text": "手順", "is_correct": false, "explanation": "作業の順序を指し、言葉の受け取り方の違いを主語にできない。"}, {"text": "残高", "is_correct": false, "explanation": "お金の残りを表す語で、言葉の意味の受け取り方とは結びつかない。"}], "explanations": {"視座": "ものの見方の立場を表し、「視座が違うと意味の受け取り方が変わる」と文脈に合う。", "勝敗": "勝ち負けの結果を指し、ものの見方の違いとして文が成り立たない。", "手順": "作業の順序を指し、言葉の受け取り方の違いを主語にできない。", "残高": "お金の残りを表す語で、言葉の意味の受け取り方とは結びつかない。"}, "sentence_index": 6, "correct_answer": "視座"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は視座が重く、一人では運べない。", "explanation": "ここは〈重さ〉の意味。「荷物が重い」は自然だが、視座は立場を指すので物の重さは表せない。"}, {"text": "窓を開けると、視座が広くて気持ちよく見渡せる。", "explanation": "ここは〈視界〉の意味。見渡せる範囲は「視界が広い」と言うべきで、視座は見る立場を指す。"}, {"text": "この包丁は視座が鋭く、野菜がすぐ切れる。", "explanation": "ここは〈切れ味〉の意味。「切れ味が鋭い」は自然だが、視座は見る立場を指すので道具の切れ味は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36474, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新人は先輩の視座を立って、顧客の声を聞くようにした。", "corrected_sentence": "新人は先輩の視座に立って、顧客の声を聞くようにした。", "error_description": "「立つ」の基準点を示すのは「に」。「視座を立つ」は「を」が誤りで、正しくは「視座に立つ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36474, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "視座を変えれ、問題の見え方が変わる。", "corrected_sentence": "視座を変えれば、問題の見え方が変わる。", "error_description": "「変える」の仮定形は「変えれば」。「変えれ」は条件を表せず、活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36475, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「視座を上げる」の目的語で、上げる対象を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「視座が一段上げて」は視座を主語にすると上げる目的語が欠け、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「視座の一段上げて」は連体修飾の形で、動詞「上げて」に続かず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「視座と上げる」は並列を表し、一段上げる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「視座を上げる」の目的語で、上げる対象を示す正しい助詞。", "が": "「視座が一段上げて」は視座を主語にすると上げる目的語が欠け、文として成り立たない。", "の": "「視座の一段上げて」は連体修飾の形で、動詞「上げて」に続かず不自然。", "と": "「視座と上げる」は並列を表し、一段上げる対象を示せない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36475, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「視座が低く」の主語を示す正しい助詞で、状態の主体を表す。"}, {"text": "を", "is_correct": false, "explanation": "「視座を低く」は形容詞に続く目的語の形にならず、誤り。"}, {"text": "で", "is_correct": false, "explanation": "「視座で低く」は手段や場所を示す助詞で、形容詞の主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「視座の低く」は連体修飾の形で、「低く」と続くこの文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「視座が低く」の主語を示す正しい助詞で、状態の主体を表す。", "を": "「視座を低く」は形容詞に続く目的語の形にならず、誤り。", "で": "「視座で低く」は手段や場所を示す助詞で、形容詞の主語にならない。", "の": "「視座の低く」は連体修飾の形で、「低く」と続くこの文には合わない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36475, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を観察したり考えたりするときの、自分が立っている位置や角度。", "primary_collocate": null, "pronunciation": "しざ", "ipa": "ɕiza", "syllable_count": 2, "sentences": [{"text": "管理職になって視座が高くなり、会社全体の流れが見えてきた。", "target_word": "視座", "complexity_tier": "T3", "furigana": "管理職[かんりしょく]になって視座[しざ]が高[たか]くなり、会社[かいしゃ]全体[ぜんたい]の流[なが]れが見[み]えてきた。", "sentence_source": "generated"}, {"text": "視座を一段上げて考えれば、小さな問題にこだわらずにすむ。", "target_word": "視座", "complexity_tier": "T3", "furigana": "視座[しざ]を一段[いちだん]上[あ]げて考[かんが]えれば、小[ちい]さな問題[もんだい]にこだわらずにすむ。", "sentence_source": "generated"}, {"text": "現場の視座が低すぎて、市全体の課題が見えていなかった。", "target_word": "視座", "complexity_tier": "T3", "furigana": "現場[げんば]の視座[しざ]が低[ひく]すぎて、市全体[しぜんたい]の課題[かだい]が見[み]えていなかった。", "sentence_source": "generated"}, {"text": "研究では、観察者の視座によって結果の見え方が変わる。", "target_word": "視座", "complexity_tier": "T3", "furigana": "研究[けんきゅう]では、観察者[かんさつしゃ]の視座[しざ]によって結果[けっか]の見[み]え方[かた]が変[か]わる。", "sentence_source": "generated"}, {"text": "一歩引いた視座で自分の仕事を見直したら、無駄が見つかった。", "target_word": "視座", "complexity_tier": "T3", "furigana": "一歩[いっぽ]引[ひ]いた視座[しざ]で自分[じぶん]の仕事[しごと]を見直[みなお]したら、無駄[むだ]が見[み]つかった。", "sentence_source": "generated"}, {"text": "視座を変えて問題を眺めると、新しい解決の糸口が見えてくる。", "target_word": "視座", "complexity_tier": "T3", "furigana": "視座[しざ]を変[か]えて問題[もんだい]を眺[なが]めると、新[あたら]しい解決[かいけつ]の糸口[いとぐち]が見[み]えてくる。", "sentence_source": "generated"}, {"text": "上司は常に高い視座から、チームの方向を決めている。", "target_word": "視座", "complexity_tier": "T3", "furigana": "上司[じょうし]は常[つね]に高[たか]い視座[しざ]から、チームの方向[ほうこう]を決[き]めている。", "sentence_source": "generated"}, {"text": "初心者は視座が低く、細部ばかりに目が向いてしまう。", "target_word": "視座", "complexity_tier": "T3", "furigana": "初心者[しょしんしゃ]は視座[しざ]が低[ひく]く、細部[さいぶ]ばかりに目[め]が向[む]いてしまう。", "sentence_source": "generated"}, {"text": "若手の視座では見えない課題を、ベテランが指摘した。", "target_word": "視座", "complexity_tier": "T3", "furigana": "若手[わかて]の視座[しざ]では見[み]えない課題[かだい]を、ベテランが指摘[してき]した。", "sentence_source": "generated"}, {"text": "自分の視座を意識しないと、偏った判断をしてしまう。", "target_word": "視座", "complexity_tier": "T3", "furigana": "自分[じぶん]の視座[しざ]を意識[いしき]しないと、偏[かたよ]った判断[はんだん]をしてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "視座", "label": "基本形"}], "register": "やや硬い（書き言葉・ビジネス）", "sense_fingerprint": "観察・思考するときの自分の位置・角度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a20f6f9-5c1c-4724-a88a-cb37d143b680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36475, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "視座", "is_correct": true, "explanation": "観察や思考の立ち位置を表し、「視座が高くなり」と自然につながる。"}, {"text": "締め切り", "is_correct": false, "explanation": "期限を表す語で、高くなるものではないため文が成り立たない。"}, {"text": "手順", "is_correct": false, "explanation": "作業の順序を表し、「手順が高くなり」とは言えない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様の意味で、「管理職になって天気が高くなり」は意味をなさない。"}], "explanations": {"視座": "観察や思考の立ち位置を表し、「視座が高くなり」と自然につながる。", "締め切り": "期限を表す語で、高くなるものではないため文が成り立たない。", "手順": "作業の順序を表し、「手順が高くなり」とは言えない。", "天気": "空模様の意味で、「管理職になって天気が高くなり」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "視座"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は声の視座が大きく、会議室の端まで響く。", "explanation": "ここは〈声量〉の意味。「声量が大きい」は自然だが、視座は見る立場で、声の大きさは表せない。"}, {"text": "窓が汚れていて視座が狭く、外がよく見えなかった。", "explanation": "ここは〈視野〉の意味。見通せる範囲は「視野が狭い」と言うべきで、視座の意味とずれる。"}, {"text": "彼は視座をそらして、答えを避けた。", "explanation": "ここは〈視線〉の意味。「視線をそらす」は自然だが、視座は目の向きを指さないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36475, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "視座", "is_correct": true, "explanation": "観察や思考の立ち位置を表し、「高い視座から」と文脈に合う。"}, {"text": "感想", "is_correct": false, "explanation": "印象や考えを述べたものを指し、「高い感想から」は成り立たない。"}, {"text": "残高", "is_correct": false, "explanation": "お金の残りを表す語で、「高い残高から」は意味をなさない。"}, {"text": "行列", "is_correct": false, "explanation": "人の並びを指し、「高い行列から」では方向の基準にならない。"}], "explanations": {"視座": "観察や思考の立ち位置を表し、「高い視座から」と文脈に合う。", "感想": "印象や考えを述べたものを指し、「高い感想から」は成り立たない。", "残高": "お金の残りを表す語で、「高い残高から」は意味をなさない。", "行列": "人の並びを指し、「高い行列から」では方向の基準にならない。"}, "sentence_index": 6, "correct_answer": "視座"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は視座が大きく、制服がきつそうに見える。", "explanation": "ここは〈体格〉の意味。「体格が大きい」は自然だが、視座は見る立場で、体の大きさは言えない。"}, {"text": "霧で視座が悪く、車の運転がとても危ない。", "explanation": "ここは〈視界〉の意味。霧で見通しが悪い状態は「視界が悪い」と言うべきで、視座では表せない。"}, {"text": "祖父は視座が弱くなり、細かい字が読めない。", "explanation": "ここは〈視力〉の意味。目の機能の低下は「視力が弱い」で表し、見る立場の視座は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36475, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩の視座に見ると、この企画の弱点がよく分かる。", "corrected_sentence": "先輩の視座から見ると、この企画の弱点がよく分かる。", "error_description": "「視座から見る」の起点を示すのは「から」。「に」は誤りで、正しくは「視座から見る」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36475, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "視座を高く保つば、全体の流れが見えてくる。", "corrected_sentence": "視座を高く保てば、全体の流れが見えてくる。", "error_description": "「保つ」の仮定形は「保てば」。「保つば」は活用の誤りで、正しくは「保てば」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
