INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36478, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "大事なことに、かかわること。", "primary_collocate": null, "pronunciation": "ふれる", "ipa": "ɸɯɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "首相は演説で、教育の問題に触れた。", "target_word": "触れた", "complexity_tier": "T3", "furigana": "首相[しゅしょう]は演説[えんぜつ]で、教育[きょういく]の問題[もんだい]に触[ふ]れた。", "sentence_source": "generated"}, {"text": "彼はその件には触れないで、すぐに話を変えた。", "target_word": "触れない", "complexity_tier": "T3", "furigana": "彼[かれ]はその件[けん]には触[ふ]れないで、すぐに話[はなし]を変[か]えた。", "sentence_source": "generated"}, {"text": "記事は、事故の原因にはまったく触れていなかった。", "target_word": "触れていなかった", "complexity_tier": "T3", "furigana": "記事[きじ]は、事故[じこ]の原因[げんいん]にはまったく触[ふ]れていなかった。", "sentence_source": "generated"}, {"text": "本の最後で、筆者は将来の課題にも触れている。", "target_word": "触れている", "complexity_tier": "T3", "furigana": "本[ほん]の最後[さいご]で、筆者[ひっしゃ]は将来[しょうらい]の課題[かだい]にも触[ふ]れている。", "sentence_source": "generated"}, {"text": "会議では、お金の問題に触れると空気が重くなった。", "target_word": "触れる", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、お金[かね]の問題[もんだい]に触[ふ]れると空気[くうき]が重[おも]くなった。", "sentence_source": "generated"}, {"text": "先生は授業の中で、戦争の歴史に少し触れた。", "target_word": "触れた", "complexity_tier": "T3", "furigana": "先生[せんせい]は授業[じゅぎょう]の中[なか]で、戦争[せんそう]の歴史[れきし]に少[すこ]し触[ふ]れた。", "sentence_source": "generated"}, {"text": "話が核心に触れたとき、彼は急に黙ってしまった。", "target_word": "触れた", "complexity_tier": "T3", "furigana": "話[はなし]が核心[かくしん]に触[ふ]れたとき、彼[かれ]は急[きゅう]に黙[だま]ってしまった。", "sentence_source": "generated"}, {"text": "時間がないので、細かい点には触れられない。", "target_word": "触れられない", "complexity_tier": "T3", "furigana": "時間[じかん]がないので、細[こま]かい点[てん]には触[ふ]れられない。", "sentence_source": "generated"}, {"text": "契約書には、費用の払い方について触れている部分がない。", "target_word": "触れている", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]には、費用[ひよう]の払[はら]い方[かた]について触[ふ]れている部分[ぶぶん]がない。", "sentence_source": "generated"}, {"text": "社長は新しい計画について、まだ公には触れていない。", "target_word": "触れていない", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は新[あたら]しい計画[けいかく]について、まだ公[おおやけ]には触[ふ]れていない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "触れる", "label": "辞書形"}, {"form": "触れない", "label": "否定形"}, {"form": "触れます", "label": "丁寧形"}, {"form": "触れて", "label": "て形"}, {"form": "触れた", "label": "た形"}, {"form": "触れれば", "label": "仮定形"}, {"form": "触れられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "ある事柄や問題について話や文章の中で言及する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36478, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "触れた", "is_correct": true, "explanation": "「問題に言及した」の意味で、演説の文脈に合う。"}, {"text": "叩いた", "is_correct": false, "explanation": "「叩く」は打つ動作で、「教育の問題に」と結びつかず言及の意味にならない。"}, {"text": "掘った", "is_correct": false, "explanation": "「掘る」は地面などを掘る動作で、「問題に掘った」では文が成り立たない。"}, {"text": "踏んだ", "is_correct": false, "explanation": "「踏む」は足で押す動作で、「問題に」と合わず文に入らない。"}], "explanations": {"触れた": "「問題に言及した」の意味で、演説の文脈に合う。", "叩いた": "「叩く」は打つ動作で、「教育の問題に」と結びつかず言及の意味にならない。", "掘った": "「掘る」は地面などを掘る動作で、「問題に掘った」では文が成り立たない。", "踏んだ": "「踏む」は足で押す動作で、「問題に」と合わず文に入らない。"}, "sentence_index": 0, "correct_answer": "触れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨で山の斜面が触れて、道がふさがった。", "explanation": "ここは〈崩れる〉の意味。斜面の崩壊は〈崩れる〉で表すので、〈触れる〉では合わない。"}, {"text": "授業の終わりを告げて、ベルが触れた。", "explanation": "ここは〈鳴る〉の意味。ベルの音は〈鳴る〉で表すので、〈触れる〉では誤り。"}, {"text": "メーターの針が大きく触れた。", "explanation": "ここは〈振れる（揺れ動く）〉の意味。針の動きは〈振れる〉で表すので、〈触れる〉では誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36478, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "触れた", "is_correct": true, "explanation": "「核心に言及した」の意味で、話題が核心に及んだ文に合う。"}, {"text": "殴った", "is_correct": false, "explanation": "「殴る」は打つ動作で、「核心に」とは結びつかず文に合わない。"}, {"text": "洗った", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作で、「核心に」とは合わない。"}, {"text": "削った", "is_correct": false, "explanation": "「削る」は表面を取り去る動作で、「核心に」とは合わず文が成り立たない。"}], "explanations": {"触れた": "「核心に言及した」の意味で、話題が核心に及んだ文に合う。", "殴った": "「殴る」は打つ動作で、「核心に」とは結びつかず文に合わない。", "洗った": "「洗う」は汚れを落とす動作で、「核心に」とは合わない。", "削った": "「削る」は表面を取り去る動作で、「核心に」とは合わず文が成り立たない。"}, "sentence_index": 6, "correct_answer": "触れた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の声が少し触れた。", "explanation": "ここは〈震える〉の意味。声の揺れは〈震える〉で表すので、〈触れる〉では誤り。"}, {"text": "カーテンが勢いよく触れた。", "explanation": "ここは〈揺れる〉の意味。布の動きは〈揺れる〉で表すので、〈触れる〉では合わない。"}, {"text": "会議の結果、来年の日程が触れた。", "explanation": "ここは〈決まる〉の意味。日程が定まる意味では〈決まる〉を使うので、〈触れる〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36478, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "講義の最後に、教授は戦争の歴史を触れた。", "corrected_sentence": "講義の最後に、教授は戦争の歴史に触れた。", "error_description": "助詞の誤り。「触れる」は「に」を取るので「を」は誤り。正しくは「歴史に」（「に」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "触れない", "is_correct": true, "explanation": "否定形。「〜ないで」につながる「ない」の形で、文に合う。"}, {"text": "触れた", "is_correct": false, "explanation": "過去形。「〜ないで」の否定の形にならないので誤り。"}, {"text": "触れる", "is_correct": false, "explanation": "辞書形。「〜ないで」に続かないので誤り。"}, {"text": "触れます", "is_correct": false, "explanation": "丁寧形。「〜ないで」に続かないので誤り。"}], "correct_form": "触れない", "base_form": "触れる", "form_label": "否定形", "sentence_index": 1, "explanations": {"触れない": "否定形。「〜ないで」につながる「ない」の形で、文に合う。", "触れた": "過去形。「〜ないで」の否定の形にならないので誤り。", "触れる": "辞書形。「〜ないで」に続かないので誤り。", "触れます": "丁寧形。「〜ないで」に続かないので誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36478, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社長は新製品の価格について、まだ誰にも触れていた。", "corrected_sentence": "社長は新製品の価格について、まだ誰にも触れていない。", "error_description": "活用の誤り。「まだ〜ていない」で否定すべきところを「〜ていた」と肯定にしたため、「まだ」と矛盾する。正しくは「触れていない」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "触れられない", "is_correct": true, "explanation": "可能形の否定形。「できない」の意味で、「細かい点には」の文の流れに合う。"}, {"text": "触れて", "is_correct": false, "explanation": "て形。可能の否定の意味にならず、文に合わない。"}, {"text": "触れれば", "is_correct": false, "explanation": "仮定形。条件の意味になり、文の意味が合わない。"}, {"text": "触れている", "is_correct": false, "explanation": "〜ている形。状態を表し、「できない」の意味にならない。"}], "correct_form": "触れられない", "base_form": "触れる", "form_label": "可能形の否定形", "sentence_index": 7, "explanations": {"触れられない": "可能形の否定形。「できない」の意味で、「細かい点には」の文の流れに合う。", "触れて": "て形。可能の否定の意味にならず、文に合わない。", "触れれば": "仮定形。条件の意味になり、文の意味が合わない。", "触れている": "〜ている形。状態を表し、「できない」の意味にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36479, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「本質に触れる」の「に」で、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「触れる」は「を」ではなく「に」を取るので誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「本質へ触れる」は意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を表すので、「本質と触れる」は不自然。"}], "correct_answer": "に", "explanations": {"に": "「本質に触れる」の「に」で、文に合う。", "を": "「触れる」は「を」ではなく「に」を取るので誤り。", "へ": "「へ」は方向を表すので、「本質へ触れる」は意味が合わない。", "と": "「と」は相手を表すので、「本質と触れる」は不自然。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36479, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「心の奥に触れる」の「に」で、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すので、「心の奥が触れる」は文の意味が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を表すので、「心の奥で触れる」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体の働きで、「心の奥の触れる作品」では文の構造が合わない。"}], "correct_answer": "に", "explanations": {"に": "「心の奥に触れる」の「に」で、文に合う。", "が": "「が」は主語を表すので、「心の奥が触れる」は文の意味が合わない。", "で": "「で」は手段を表すので、「心の奥で触れる」は不自然。", "の": "「の」は連体の働きで、「心の奥の触れる作品」では文の構造が合わない。"}, "error_tags": {"が": "主語", "で": "手段", "の": "連体の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36479, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事の本質や核心、大切な部分に関わる。または、それを体験する。", "primary_collocate": null, "pronunciation": "ふれる", "ipa": "ɸɯɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "留学して初めて、日本の文化の本質に触れた気がした。", "target_word": "触れた", "complexity_tier": "T3", "furigana": "留学[りゅうがく]して初[はじ]めて、日本[にほん]の文化[ぶんか]の本質[ほんしつ]に触[ふ]れた気[き]がした。", "sentence_source": "generated"}, {"text": "その研究は、言語の成り立ちという本質に触れている。", "target_word": "触れている", "complexity_tier": "T3", "furigana": "その研究[けんきゅう]は、言語[げんご]の成[な]り立[た]ちという本質[ほんしつ]に触[ふ]れている。", "sentence_source": "generated"}, {"text": "その展示は、来館者が古代の文化の本質に触れる機会になった。", "target_word": "触れる", "complexity_tier": "T3", "furigana": "その展示[てんじ]は、来館者[らいかんしゃ]が古代[こだい]の文化[ぶんか]の本質[ほんしつ]に触[ふ]れる機会[きかい]になった。", "sentence_source": "generated"}, {"text": "祭りに参加して、地元の人の暮らしの中心に触れることができた。", "target_word": "触れる", "complexity_tier": "T3", "furigana": "祭[まつ]りに参加[さんか]して、地元[じもと]の人[ひと]の暮[く]らしの中心[ちゅうしん]に触[ふ]れることができた。", "sentence_source": "generated"}, {"text": "国の大切な伝統に触れるには、まず言葉を学ぶことが大事だ。", "target_word": "触れる", "complexity_tier": "T3", "furigana": "国[くに]の大切[たいせつ]な伝統[でんとう]に触[ふ]れるには、まず言葉[ことば]を学[まな]ぶことが大事[だいじ]だ。", "sentence_source": "generated"}, {"text": "相手の宗教に関わる冗談は、深い部分に触れるので注意したい。", "target_word": "触れる", "complexity_tier": "T3", "furigana": "相手[あいて]の宗教[しゅうきょう]に関[かか]わる冗談[じょうだん]は、深[ふか]い部分[ぶぶん]に触[ふ]れるので注意[ちゅうい]したい。", "sentence_source": "generated"}, {"text": "彼女の過去の傷に触れる質問をして、場の空気が凍った。", "target_word": "触れる", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の過去[かこ]の傷[きず]に触[ふ]れる質問[しつもん]をして、場[ば]の空気[くうき]が凍[こお]った。", "sentence_source": "generated"}, {"text": "この映画は、人間の心の奥に触れる作品だと言われている。", "target_word": "触れる", "complexity_tier": "T3", "furigana": "この映画[えいが]は、人間[にんげん]の心[こころ]の奥[おく]に触[ふ]れる作品[さくひん]だと言[い]われている。", "sentence_source": "generated"}, {"text": "問題の核心に触れた発言に、会場は静かになった。", "target_word": "触れた", "complexity_tier": "T3", "furigana": "問題[もんだい]の核心[かくしん]に触[ふ]れた発言[はつげん]に、会場[かいじょう]は静[しず]かになった。", "sentence_source": "generated"}, {"text": "農家で働いて、その土地の本当の暮らしに触れた。", "target_word": "触れた", "complexity_tier": "T3", "furigana": "農家[のうか]で働[はたら]いて、その土地[とち]の本当[ほんとう]の暮[く]らしに触[ふ]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "触れる", "label": "辞書形"}, {"form": "触れない", "label": "否定形"}, {"form": "触れます", "label": "丁寧形"}, {"form": "触れて", "label": "て形"}, {"form": "触れた", "label": "た形"}, {"form": "触れれば", "label": "仮定形"}, {"form": "触れられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "物事の本質・核心・大切な部分に関わる、またはそれを体験する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36479, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "触れた", "is_correct": true, "explanation": "「本質に関わった」の意味で、文の「気がした」に合う。"}, {"text": "掘った", "is_correct": false, "explanation": "「掘る」は地面などを掘る動作で、「本質に」とは合わない。"}, {"text": "叩いた", "is_correct": false, "explanation": "「叩く」は打つ動作で、「本質に」とは結びつかず文に合わない。"}, {"text": "踏んだ", "is_correct": false, "explanation": "「踏む」は足で押す動作で、「本質に」とは合わず文に入らない。"}], "explanations": {"触れた": "「本質に関わった」の意味で、文の「気がした」に合う。", "掘った": "「掘る」は地面などを掘る動作で、「本質に」とは合わない。", "叩いた": "「叩く」は打つ動作で、「本質に」とは結びつかず文に合わない。", "踏んだ": "「踏む」は足で押す動作で、「本質に」とは合わず文に入らない。"}, "sentence_index": 0, "correct_answer": "触れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "授業の終わりを告げて、ベルが触れた。", "explanation": "ここは〈鳴る〉の意味。ベルの音は〈鳴る〉で表すので、〈触れる〉では誤り。"}, {"text": "ブランコが大きく触れた。", "explanation": "ここは〈振れる（揺れ動く）〉の意味。ブランコの動きは〈振れる〉で表すので、〈触れる〉では合わない。"}, {"text": "その時、膝が大きく触れた。", "explanation": "ここは〈震える〉の意味。体の震えは〈震える〉で表すので、〈触れる〉では誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36479, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "触れる", "is_correct": true, "explanation": "「傷に関わる」の意味で、後ろの「質問」を修飾する形として文に合う。"}, {"text": "塗った", "is_correct": false, "explanation": "「塗る」は薬などを塗る動作で、「傷に塗った質問」は意味が通らない。"}, {"text": "殴った", "is_correct": false, "explanation": "「殴る」は打つ動作で、「傷に殴った質問」は文の意味が通らない。"}, {"text": "洗った", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作で、「傷に洗った質問」は文に合わない。"}], "explanations": {"触れる": "「傷に関わる」の意味で、後ろの「質問」を修飾する形として文に合う。", "塗った": "「塗る」は薬などを塗る動作で、「傷に塗った質問」は意味が通らない。", "殴った": "「殴る」は打つ動作で、「傷に殴った質問」は文の意味が通らない。", "洗った": "「洗う」は汚れを落とす動作で、「傷に洗った質問」は文に合わない。"}, "sentence_index": 6, "correct_answer": "触れる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の結果、来年の日程が触れた。", "explanation": "ここは〈決まる〉の意味。日程が定まる意味では〈決まる〉を使うので、〈触れる〉では合わない。"}, {"text": "風で旗が大きく触れた。", "explanation": "ここは〈揺れる〉の意味。旗の動きは〈揺れる〉で表すので、〈触れる〉では合わない。"}, {"text": "夜空に、遠くの雷が触れた。", "explanation": "ここは〈鳴る〉の意味。雷の音は〈鳴る〉で表すので、〈触れる〉では誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36479, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その講義は、言語の成り立ちという核心を触れていた。", "corrected_sentence": "その講義は、言語の成り立ちという核心に触れていた。", "error_description": "助詞の誤り。「触れる」は「に」を取るので「を」は誤り。正しくは「核心に」（「に」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "触れている", "is_correct": true, "explanation": "〜ている形。「本質に関わっている」という状態を表し、文に合う。"}, {"text": "触れて", "is_correct": false, "explanation": "て形。文を言い切らず、述語にならないので文が成り立たない。"}, {"text": "触れない", "is_correct": false, "explanation": "否定形。「本質に関わっていない」の意味になるので文に合わない。"}, {"text": "触れれば", "is_correct": false, "explanation": "仮定形。条件節で止まり、文の述語にならないので誤り。"}], "correct_form": "触れている", "base_form": "触れる", "form_label": "〜ている形", "sentence_index": 1, "explanations": {"触れている": "〜ている形。「本質に関わっている」という状態を表し、文に合う。", "触れて": "て形。文を言い切らず、述語にならないので文が成り立たない。", "触れない": "否定形。「本質に関わっていない」の意味になるので文に合わない。", "触れれば": "仮定形。条件節で止まり、文の述語にならないので誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36479, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この詩は読む人の心の奥が触れる力を持っている。", "corrected_sentence": "この詩は読む人の心の奥に触れる力を持っている。", "error_description": "助詞の誤り。「触れる」は「に」を取るので「が」は誤り。正しくは「心の奥に」（「に」）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "触れる", "is_correct": true, "explanation": "辞書形。名詞「作品」を修飾する形で、文に合う。"}, {"text": "触れよう", "is_correct": false, "explanation": "意向形。「触れよう」は意志を表し、名詞「作品」を修飾できないので文が成り立たない。"}, {"text": "触れろ", "is_correct": false, "explanation": "命令形。命令の意味になり、名詞「作品」を修飾できないので文に合わない。"}, {"text": "触れます", "is_correct": false, "explanation": "丁寧形。名詞を修飾できず、この文の形に合わない。"}], "correct_form": "触れる", "base_form": "触れる", "form_label": "辞書形（名詞修飾）", "sentence_index": 7, "explanations": {"触れる": "辞書形。名詞「作品」を修飾する形で、文に合う。", "触れよう": "意向形。「触れよう」は意志を表し、名詞「作品」を修飾できないので文が成り立たない。", "触れろ": "命令形。命令の意味になり、名詞「作品」を修飾できないので文に合わない。", "触れます": "丁寧形。名詞を修飾できず、この文の形に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36480, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「指示に従う」の「に」で文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「従う」は「を」ではなく「に」を取るので誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「指示へ従う」は意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を表すが、「指示と従う」は不自然。"}], "correct_answer": "に", "explanations": {"に": "「指示に従う」の「に」で文に合う。", "を": "「従う」は「を」ではなく「に」を取るので誤り。", "へ": "「へ」は方向を表すので、「指示へ従う」は意味が合わない。", "と": "「と」は相手を表すが、「指示と従う」は不自然。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向", "と": "相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逆らう", "is_correct": true, "explanation": "「従う」の対義語で、指示や決まりに背く意味。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作で、「従う」の対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移す動作で、「従う」の対義語ではない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "声を上げる動作で、「従う」の対義語ではない。"}], "correct_answer": "逆らう", "explanations": {"逆らう": "「従う」の対義語で、指示や決まりに背く意味。", "眺める": "見る動作で、「従う」の対義語ではない。", "運ぶ": "物を移す動作で、「従う」の対義語ではない。", "叫ぶ": "声を上げる動作で、「従う」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36480, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「希望に従う」の「に」で文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すので、「希望が従う」は文の意味が合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「希望から従う」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を表すので、「希望で従う」は文に合わない。"}], "correct_answer": "に", "explanations": {"に": "「希望に従う」の「に」で文に合う。", "が": "「が」は主語を表すので、「希望が従う」は文の意味が合わない。", "から": "「から」は起点を表すので、「希望から従う」は不自然。", "で": "「で」は手段を表すので、「希望で従う」は文に合わない。"}, "error_tags": {"が": "主語", "から": "起点", "で": "手段"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逆らう", "is_correct": true, "explanation": "「従う」の対義語で、決定や規則に背く意味。"}, {"text": "数える", "is_correct": false, "explanation": "数を数える動作で、「従う」の対義語ではない。"}, {"text": "抱く", "is_correct": false, "explanation": "抱える動作で、「従う」の対義語ではない。"}, {"text": "尋ねる", "is_correct": false, "explanation": "問いかける動作で、「従う」の対義語ではない。"}], "correct_answer": "逆らう", "explanations": {"逆らう": "「従う」の対義語で、決定や規則に背く意味。", "数える": "数を数える動作で、「従う」の対義語ではない。", "抱く": "抱える動作で、「従う」の対義語ではない。", "尋ねる": "問いかける動作で、「従う」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36480, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人の言うことや決まりを、そのまま行う。", "primary_collocate": null, "pronunciation": "したがう", "ipa": "ɕitaɡaɯ", "syllable_count": 4, "sentences": [{"text": "子どもは親の言うことに従って、早く寝た。", "target_word": "従って", "complexity_tier": "T3", "furigana": "子[こ]どもは親[おや]の言[い]うことに従[したが]って、早[はや]く寝[ね]た。", "sentence_source": "generated"}, {"text": "危ないので、係の人の指示に従う必要がある。", "target_word": "従う", "complexity_tier": "T3", "furigana": "危[あぶ]ないので、係[かかり]の人[ひと]の指示[しじ]に従[したが]う必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "彼は会社の規則に従わず、何度も注意された。", "target_word": "従わ", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]の規則[きそく]に従[したが]わず、何度[なんど]も注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "私は医者の言葉に従って、お酒をやめた。", "target_word": "従って", "complexity_tier": "T3", "furigana": "私[わたし]は医者[いしゃ]の言葉[ことば]に従[したが]って、お酒[さけ]をやめた。", "sentence_source": "generated"}, {"text": "国の法律には、だれでも従わなければならない。", "target_word": "従わ", "complexity_tier": "T3", "furigana": "国[くに]の法律[ほうりつ]には、だれでも従[したが]わなければならない。", "sentence_source": "generated"}, {"text": "先輩の命令に従うだけでなく、自分でも考えるべきだ。", "target_word": "従う", "complexity_tier": "T3", "furigana": "先輩[せんぱい]の命令[めいれい]に従[したが]うだけでなく、自分[じぶん]でも考[かんが]えるべきだ。", "sentence_source": "generated"}, {"text": "試合中は、審判の判断に従うのがルールだ。", "target_word": "従う", "complexity_tier": "T3", "furigana": "試合中[しあいちゅう]は、審判[しんぱん]の判断[はんだん]に従[したが]うのがルールだ。", "sentence_source": "generated"}, {"text": "彼女は家族の希望に従って、地元の大学に進んだ。", "target_word": "従って", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は家族[かぞく]の希望[きぼう]に従[したが]って、地元[じもと]の大学[だいがく]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "道が工事中なので、案内の矢印に従って遠回りした。", "target_word": "従って", "complexity_tier": "T3", "furigana": "道[みち]が工事中[こうじちゅう]なので、案内[あんない]の矢印[やじるし]に従[したが]って遠回[とおまわ]りした。", "sentence_source": "generated"}, {"text": "反対だったが、多数決の結果に従うことにした。", "target_word": "従う", "complexity_tier": "T3", "furigana": "反対[はんたい]だったが、多数決[たすうけつ]の結果[けっか]に従[したが]うことにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "従う", "label": "辞書形"}, {"form": "従わない", "label": "否定形"}, {"form": "従います", "label": "丁寧形"}, {"form": "従って", "label": "て形"}, {"form": "従った", "label": "た形"}, {"form": "従えば", "label": "仮定形"}, {"form": "従える", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "人の指示・忠告・決まりを受け入れてそのとおりに行動する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36480, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "従って", "is_correct": true, "explanation": "「言いつけに従った」の意味で、文に合う。"}, {"text": "頼んで", "is_correct": false, "explanation": "「頼む」は依頼する動作で、「言うことに頼んで」は文の意味が通らない。"}, {"text": "叱って", "is_correct": false, "explanation": "「叱る」は怒る動作で、「言うことに叱って」は文に合わない。"}, {"text": "眺めて", "is_correct": false, "explanation": "「眺める」は見る動作で、「言うことに眺めて」は文に合わない。"}], "explanations": {"従って": "「言いつけに従った」の意味で、文に合う。", "頼んで": "「頼む」は依頼する動作で、「言うことに頼んで」は文の意味が通らない。", "叱って": "「叱る」は怒る動作で、「言うことに叱って」は文に合わない。", "眺めて": "「眺める」は見る動作で、「言うことに眺めて」は文に合わない。"}, "sentence_index": 0, "correct_answer": "従って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大きな成功には、大きな責任が従う。", "explanation": "ここは〈伴う（付随する）〉の意味。責任がついてくる意味では〈伴う〉を使うので、〈従う〉では合わない。"}, {"text": "この店は、料金に従った設備を整えている。", "explanation": "ここは〈見合う〉の意味。料金と釣り合う意味では〈見合う〉を使うので、〈従う〉では誤り。"}, {"text": "嫌な噂が、彼に従って離れなかった。", "explanation": "ここは〈つきまとう〉の意味。噂が離れない意味では〈つきまとう〉を使うので、〈従う〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36480, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "従う", "is_correct": true, "explanation": "「判断に従う」の意味で、ルールとして文に合う。"}, {"text": "洗う", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作で、「判断に」とは合わない。"}, {"text": "刻む", "is_correct": false, "explanation": "「刻む」は細かく切る動作で、「判断に」とは合わない。"}, {"text": "煮る", "is_correct": false, "explanation": "「煮る」は加熱する動作で、「判断に」とは合わず文が成り立たない。"}], "explanations": {"従う": "「判断に従う」の意味で、ルールとして文に合う。", "洗う": "「洗う」は汚れを落とす動作で、「判断に」とは合わない。", "刻む": "「刻む」は細かく切る動作で、「判断に」とは合わない。", "煮る": "「煮る」は加熱する動作で、「判断に」とは合わず文が成り立たない。"}, "sentence_index": 6, "correct_answer": "従う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は長年、研究に従っている。", "explanation": "ここは〈従事する（携わる）〉の意味。研究に携わる意味で、〈従う〉では意味が通らない。"}, {"text": "大きな事故には、長い混乱が従う。", "explanation": "ここは〈伴う（付随する）〉の意味。付随する結果を表す〈伴う〉を使うので、〈従う〉では誤り。"}, {"text": "雨の日には、湿気が従ってくる。", "explanation": "ここは〈伴う（付随する）〉の意味。付き添って生じる状態は〈伴う〉で表すので、〈従う〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36480, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店員の案内を従って、奥の席へ進んだ。", "corrected_sentence": "店員の案内に従って、奥の席へ進んだ。", "error_description": "助詞の誤り。「従う」は「に」を取るので「を」は誤り。正しくは「案内に」（「に」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "従う", "is_correct": true, "explanation": "辞書形。「指示に従う必要がある」の形で、文に合う。"}, {"text": "従った", "is_correct": false, "explanation": "過去形。「必要がある」と続く形ではないので文に合わない。"}, {"text": "従えば", "is_correct": false, "explanation": "仮定形。「従えば必要がある」は意味が通らないので誤り。"}, {"text": "従わない", "is_correct": false, "explanation": "否定形。「従わない必要がある」は意味が反対になるので文に合わない。"}], "correct_form": "従う", "base_form": "従う", "form_label": "辞書形", "sentence_index": 1, "explanations": {"従う": "辞書形。「指示に従う必要がある」の形で、文に合う。", "従った": "過去形。「必要がある」と続く形ではないので文に合わない。", "従えば": "仮定形。「従えば必要がある」は意味が通らないので誤り。", "従わない": "否定形。「従わない必要がある」は意味が反対になるので文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36480, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は会社の方針に従うず、独自の道を選んだ。", "corrected_sentence": "彼女は会社の方針に従わず、独自の道を選んだ。", "error_description": "否定形の活用の誤り。「従う」の否定は「従わず」が正しく、「従うず」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "従って", "is_correct": true, "explanation": "て形。「希望に従って、大学に進んだ」の形で文に合う。"}, {"text": "従う", "is_correct": false, "explanation": "辞書形。「従う、大学に進んだ」と続けられず、文に合わない。"}, {"text": "従わず", "is_correct": false, "explanation": "否定の連用形。「従わず」では意味が反対になり、文に合わない。"}, {"text": "従える", "is_correct": false, "explanation": "可能形。「従わせる」の意味になり、文の意味が変わる。"}], "correct_form": "従って", "base_form": "従う", "form_label": "て形", "sentence_index": 7, "explanations": {"従って": "て形。「希望に従って、大学に進んだ」の形で文に合う。", "従う": "辞書形。「従う、大学に進んだ」と続けられず、文に合わない。", "従わず": "否定の連用形。「従わず」では意味が反対になり、文に合わない。", "従える": "可能形。「従わせる」の意味になり、文の意味が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36481, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「命令に従う」の「に」で文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「従う」は「を」ではなく「に」を取るので誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「命令へ従う」は意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を表すが、「命令と従う」は不自然。"}], "correct_answer": "に", "explanations": {"に": "「命令に従う」の「に」で文に合う。", "を": "「従う」は「を」ではなく「に」を取るので誤り。", "へ": "「へ」は方向を表すので、「命令へ従う」は意味が合わない。", "と": "「と」は相手を表すが、「命令と従う」は不自然。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向", "と": "相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逆らう", "is_correct": true, "explanation": "「従う」の対義語で、指示に背く意味。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作で、「従う」の対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移す動作で、「従う」の対義語ではない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "声を上げる動作で、「従う」の対義語ではない。"}], "correct_answer": "逆らう", "explanations": {"逆らう": "「従う」の対義語で、指示に背く意味。", "眺める": "見る動作で、「従う」の対義語ではない。", "運ぶ": "物を移す動作で、「従う」の対義語ではない。", "叫ぶ": "声を上げる動作で、「従う」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36481, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「放送に従う」の「に」で文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すので、「放送が従う」は文の意味が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を表すが、「放送で従う」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「放送から従う」は不自然。"}], "correct_answer": "に", "explanations": {"に": "「放送に従う」の「に」で文に合う。", "が": "「が」は主語を表すので、「放送が従う」は文の意味が合わない。", "で": "「で」は手段を表すが、「放送で従う」は不自然。", "から": "「から」は起点を表すので、「放送から従う」は不自然。"}, "error_tags": {"が": "主語", "で": "手段", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逆らう", "is_correct": true, "explanation": "「従う」の対義語で、親の指示に背く意味。"}, {"text": "煮る", "is_correct": false, "explanation": "加熱する動作で、「従う」の対義語ではない。"}, {"text": "測る", "is_correct": false, "explanation": "長さなどを計る動作で、「従う」の対義語ではない。"}, {"text": "磨く", "is_correct": false, "explanation": "表面をこする動作で、「従う」の対義語ではない。"}], "correct_answer": "逆らう", "explanations": {"逆らう": "「従う」の対義語で、親の指示に背く意味。", "煮る": "加熱する動作で、「従う」の対義語ではない。", "測る": "長さなどを計る動作で、「従う」の対義語ではない。", "磨く": "表面をこする動作で、「従う」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36481, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "他人の指示や命令、規則などを聞き入れて、それに沿って行動する。また、あるものに続いて動く。", "primary_collocate": null, "pronunciation": "したがう", "ipa": "ɕitaɡaɯ", "syllable_count": 4, "sentences": [{"text": "生徒たちは先生に従って、静かに廊下を歩いた。", "target_word": "従って", "complexity_tier": "T3", "furigana": "生徒[せいと]たちは先生[せんせい]に従[したが]って、静[しず]かに廊下[ろうか]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "兵士は上官の命令に従い、すぐに出発した。", "target_word": "従い", "complexity_tier": "T3", "furigana": "兵士[へいし]は上官[じょうかん]の命令[めいれい]に従[したが]い、すぐに出発[しゅっぱつ]した。", "sentence_source": "generated"}, {"text": "登山者はガイドに従って、細い道を進んだ。", "target_word": "従って", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]はガイドに従[したが]って、細[ほそ]い道[みち]を進[すす]んだ。", "sentence_source": "generated"}, {"text": "説明書に従って組み立てたら、三十分で終わった。", "target_word": "従って", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]に従[したが]って組[く]み立[た]てたら、三十分[さんじゅっぷん]で終[お]わった。", "sentence_source": "generated"}, {"text": "学校の決まりに従わない生徒は、先生に呼ばれた。", "target_word": "従わ", "complexity_tier": "T3", "furigana": "学校[がっこう]の決[き]まりに従[したが]わない生徒[せいと]は、先生[せんせい]に呼[よ]ばれた。", "sentence_source": "generated"}, {"text": "彼は上司の指示に従うしかなく、不満でも黙っていた。", "target_word": "従う", "complexity_tier": "T3", "furigana": "彼[かれ]は上司[じょうし]の指示[しじ]に従[したが]うしかなく、不満[ふまん]でも黙[だま]っていた。", "sentence_source": "generated"}, {"text": "犬は飼い主に従って、公園の中を歩いていた。", "target_word": "従って", "complexity_tier": "T3", "furigana": "犬[いぬ]は飼[か]い主[ぬし]に従[したが]って、公園[こうえん]の中[なか]を歩[ある]いていた。", "sentence_source": "generated"}, {"text": "避難の放送に従って、客は出口へ向かった。", "target_word": "従って", "complexity_tier": "T3", "furigana": "避難[ひなん]の放送[ほうそう]に従[したが]って、客[きゃく]は出口[でぐち]へ向[む]かった。", "sentence_source": "generated"}, {"text": "契約の内容に従えば、来月までに代金を払う必要がある。", "target_word": "従えば", "complexity_tier": "T3", "furigana": "契約[けいやく]の内容[ないよう]に従[したが]えば、来月[らいげつ]までに代金[だいきん]を払[はら]う必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "子どもが親に従わなくなるのは、成長している印でもある。", "target_word": "従わ", "complexity_tier": "T3", "furigana": "子[こ]どもが親[おや]に従[したが]わなくなるのは、成長[せいちょう]している印[しるし]でもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "従う", "label": "辞書形"}, {"form": "従わない", "label": "否定形"}, {"form": "従います", "label": "丁寧形"}, {"form": "従って", "label": "て形"}, {"form": "従った", "label": "た形"}, {"form": "従えば", "label": "仮定形"}, {"form": "従える", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "指示・命令・規則に沿って動く、または人のあとについて行く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b426c55d-0127-4220-a130-b3ebed1028fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36481, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "従って", "is_correct": true, "explanation": "「先生の後について」の意味で、文に合う。"}, {"text": "眺めて", "is_correct": false, "explanation": "「眺める」は見る動作で、「先生に」と結びつかず文に合わない。"}, {"text": "運んで", "is_correct": false, "explanation": "「運ぶ」は物を移す動作で、「先生に」とは合わない。"}, {"text": "洗って", "is_correct": false, "explanation": "「洗う」は汚れを落とす動作で、「先生に」と合わず文に入らない。"}], "explanations": {"従って": "「先生の後について」の意味で、文に合う。", "眺めて": "「眺める」は見る動作で、「先生に」と結びつかず文に合わない。", "運んで": "「運ぶ」は物を移す動作で、「先生に」とは合わない。", "洗って": "「洗う」は汚れを落とす動作で、「先生に」と合わず文に入らない。"}, "sentence_index": 0, "correct_answer": "従って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨の後には、土砂崩れの危険が従う。", "explanation": "ここは〈伴う（付随する）〉の意味。危険が付いてくる意味では〈伴う〉を使うので、〈従う〉では合わない。"}, {"text": "彼は長年、事業に従っている。", "explanation": "ここは〈従事する（携わる）〉の意味。仕事に携わる意味で、〈従う〉では意味が通らない。"}, {"text": "彼の実力に従った地位が、ようやく与えられた。", "explanation": "ここは〈見合う〉の意味。実力と釣り合う意味では〈見合う〉を使うので、〈従う〉では誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36481, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "従って", "is_correct": true, "explanation": "「飼い主の後について」の意味で、文に合う。"}, {"text": "噛んで", "is_correct": false, "explanation": "「噛む」は歯で挟む動作で、「飼い主に噛んで」は文の意味が通らない。"}, {"text": "磨いて", "is_correct": false, "explanation": "「磨く」は表面をこする動作で、「飼い主に」とは合わない。"}, {"text": "測って", "is_correct": false, "explanation": "「測る」は長さなどを計る動作で、「飼い主に」と結びつかず文に合わない。"}], "explanations": {"従って": "「飼い主の後について」の意味で、文に合う。", "噛んで": "「噛む」は歯で挟む動作で、「飼い主に噛んで」は文の意味が通らない。", "磨いて": "「磨く」は表面をこする動作で、「飼い主に」とは合わない。", "測って": "「測る」は長さなどを計る動作で、「飼い主に」と結びつかず文に合わない。"}, "sentence_index": 6, "correct_answer": "従って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風で旗が大きく従った。", "explanation": "ここは〈揺れる〉の意味。旗の動きは〈揺れる〉で表すので、〈従う〉では合わない。"}, {"text": "その計画には、大きな不安が従っている。", "explanation": "ここは〈伴う（付随する）〉の意味。付随する状態は〈伴う〉で表すので、〈従う〉では誤り。"}, {"text": "彼は十年、農業に従っている。", "explanation": "ここは〈従事する（携わる）〉の意味。仕事に携わる意味で、〈従う〉では意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36481, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "隊員は隊長の命令を従い、すぐに出発した。", "corrected_sentence": "隊員は隊長の命令に従い、すぐに出発した。", "error_description": "助詞の誤り。「従う」は「に」を取るので「を」は誤り。正しくは「命令に」（「に」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "従い", "is_correct": true, "explanation": "連用形。「従い、すぐに出発した」と動作を続ける形で文に合う。"}, {"text": "従う", "is_correct": false, "explanation": "辞書形。「従う、すぐに出発した」と動作を並べる形にならないので合わない。"}, {"text": "従った", "is_correct": false, "explanation": "過去形。「従った、すぐに出発した」は文の流れに合わない。"}, {"text": "従えば", "is_correct": false, "explanation": "仮定形。条件の意味になり、事実を述べる文に合わない。"}], "correct_form": "従い", "base_form": "従う", "form_label": "連用形", "sentence_index": 1, "explanations": {"従い": "連用形。「従い、すぐに出発した」と動作を続ける形で文に合う。", "従う": "辞書形。「従う、すぐに出発した」と動作を並べる形にならないので合わない。", "従った": "過去形。「従った、すぐに出発した」は文の流れに合わない。", "従えば": "仮定形。条件の意味になり、事実を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36481, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "避難の放送に従いて、市民は速やかに校庭へ集まった。", "corrected_sentence": "避難の放送に従って、市民は速やかに校庭へ集まった。", "error_description": "て形の誤り。「従う」のて形は「従って」で、「従いて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "従って", "is_correct": true, "explanation": "て形。「放送に従って、出口へ向かった」の形で文に合う。"}, {"text": "従わず", "is_correct": false, "explanation": "否定の連用形。「従わず」では客が指示に背いた意味になり、文に合わない。"}, {"text": "従わない", "is_correct": false, "explanation": "否定形。「従わない」は意味が反対になり、文に合わない。"}, {"text": "従える", "is_correct": false, "explanation": "可能形。「従わせる」の意味になり、文の意味が変わる。"}], "correct_form": "従って", "base_form": "従う", "form_label": "て形", "sentence_index": 7, "explanations": {"従って": "て形。「放送に従って、出口へ向かった」の形で文に合う。", "従わず": "否定の連用形。「従わず」では客が指示に背いた意味になり、文に合わない。", "従わない": "否定形。「従わない」は意味が反対になり、文に合わない。", "従える": "可能形。「従わせる」の意味になり、文の意味が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b9ef07-728e-435c-aa4c-06ed72f95eee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36482, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「取り扱いには」で、取り扱いという事柄に関して注意が必要だと示す。「取り扱いに注意」と同じ用法。"}, {"text": "が", "is_correct": false, "explanation": "「取り扱いが」となると直後の「は」と続かず、文の形が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「取り扱いを」は目的語を示すが、直後の「は」と続かず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「取り扱いへは」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "正解。「取り扱いには」で、取り扱いという事柄に関して注意が必要だと示す。「取り扱いに注意」と同じ用法。", "が": "「取り扱いが」となると直後の「は」と続かず、文の形が崩れる。", "を": "「取り扱いを」は目的語を示すが、直後の「は」と続かず不自然。", "へ": "「へ」は方向を示す。「取り扱いへは」では意味が通らない。"}, "error_tags": {"が": "主格", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36482, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「取り扱いの注意」で、取り扱いに関する注意を表す名詞修飾の「の」。"}, {"text": "が", "is_correct": false, "explanation": "「取り扱いが注意が書いてある」となり、「注意」を修飾できず文が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「取り扱いを注意」は名詞どうしをつなげられず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場面を示す。「取り扱いで注意」は名詞の修飾にならず不自然。"}], "correct_answer": "の", "explanations": {"の": "正解。「取り扱いの注意」で、取り扱いに関する注意を表す名詞修飾の「の」。", "が": "「取り扱いが注意が書いてある」となり、「注意」を修飾できず文が崩れる。", "を": "「取り扱いを注意」は名詞どうしをつなげられず、不自然。", "で": "「で」は手段や場面を示す。「取り扱いで注意」は名詞の修飾にならず不自然。"}, "error_tags": {"が": "主格", "を": "対象", "で": "場面"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36482, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを使うときの、そのやり方や決まりのこと。", "primary_collocate": null, "pronunciation": "とりあつかい", "ipa": "toɾiatsɯkai", "syllable_count": 6, "sentences": [{"text": "この機械の取り扱いは、説明書をよく読んでからにする。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "この機械[きかい]の取[と]り扱[あつか]いは、説明書[せつめいしょ]をよく読[よ]んでからにする。", "sentence_source": "generated"}, {"text": "ガラス製品の取り扱いには、十分な注意が必要だ。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "ガラス製品[せいひん]の取[と]り扱[あつか]いには、十分[じゅうぶん]な注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "薬の取り扱いを間違えると、危険なことがある。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "薬[くすり]の取[と]り扱[あつか]いを間違[まちが]えると、危険[きけん]なことがある。", "sentence_source": "generated"}, {"text": "実験室では、薬品の取り扱いのルールが決まっている。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "実験室[じっけんしつ]では、薬品[やくひん]の取[と]り扱[あつか]いのルールが決[き]まっている。", "sentence_source": "generated"}, {"text": "この道具は取り扱いが難しいので、子どもには使わせない。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は取[と]り扱[あつか]いが難[むずか]しいので、子[こ]どもには使[つか]わせない。", "sentence_source": "generated"}, {"text": "新しい電子レンジの取り扱いを、店の人が教えてくれた。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "新[あたら]しい電子[でんし]レンジの取[と]り扱[あつか]いを、店[みせ]の人[ひと]が教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "刃物の取り扱いに慣れていないので、料理中はゆっくり切る。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "刃物[はもの]の取[と]り扱[あつか]いに慣[な]れていないので、料理中[りょうりちゅう]はゆっくり切[き]る。", "sentence_source": "generated"}, {"text": "箱に取り扱いの注意が書いてあるので、先に確認した。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "箱[はこ]に取[と]り扱[あつか]いの注意[ちゅうい]が書[か]いてあるので、先[さき]に確認[かくにん]した。", "sentence_source": "generated"}, {"text": "カメラの取り扱いを覚えるまで、練習用の機械を使う。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "カメラの取[と]り扱[あつか]いを覚[おぼ]えるまで、練習用[れんしゅうよう]の機械[きかい]を使[つか]う。", "sentence_source": "generated"}, {"text": "取り扱いの説明を聞かずに使ったため、機械が壊れた。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "取[と]り扱[あつか]いの説明[せつめい]を聞[き]かずに使[つか]ったため、機械[きかい]が壊[こわ]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り扱い", "label": "基本形"}, {"form": "取り扱いの", "label": "連体形(の)"}, {"form": "取り扱いが", "label": "主格(が)"}], "register": "neutral", "sense_fingerprint": "取り扱い: 道具や機械など物を使うときのやり方・決まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ca05e1-aa05-4ad7-add9-a71a38ebfa4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36482, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り扱い", "is_correct": true, "explanation": "正解。機械を使うときのやり方を表し、「説明書をよく読んでからにする」という内容に合う。"}, {"text": "故障", "is_correct": false, "explanation": "機械が壊れることを表す。「故障は説明書を読んでからにする」とは言えず、やり方の話にならない。"}, {"text": "寿命", "is_correct": false, "explanation": "機械が使える期間を表す。説明書を読んでから決めるものではなく、文が成り立たない。"}, {"text": "重さ", "is_correct": false, "explanation": "物の重さの程度を表す。説明書を読んでからにする対象にはならない。"}], "explanations": {"取り扱い": "正解。機械を使うときのやり方を表し、「説明書をよく読んでからにする」という内容に合う。", "故障": "機械が壊れることを表す。「故障は説明書を読んでからにする」とは言えず、やり方の話にならない。", "寿命": "機械が使える期間を表す。説明書を読んでから決めるものではなく、文が成り立たない。", "重さ": "物の重さの程度を表す。説明書を読んでからにする対象にはならない。"}, "sentence_index": 0, "correct_answer": "取り扱い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この自転車の取り扱いは、週に一度する。", "explanation": "ここは〈手入れ〉の意味。取り扱いは使い方や決まりを指し、定期的に手をかけて整える意味では使わない。"}, {"text": "この果物は、冷蔵庫に入れて取り扱いを長く保つ。", "explanation": "ここは〈保存〉の意味。取り扱いは使い方や決まりを指し、食べ物を長く保っておく意味では使わない。"}, {"text": "壊れたテレビを、取り扱いに出して直してもらった。", "explanation": "ここは「修理」の意味で、「修理に出す」と言う場面。「取り扱い」は使い方や決まりを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36482, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り扱い", "is_correct": true, "explanation": "正解。刃物の使い方に慣れていない、という意味になる。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語。「刃物の天気に慣れていない」とは言えず、文が成り立たない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の湿り具合を表す語。刃物に慣れるという文の対象にはならない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠くなる感覚を表す語。「刃物の眠気に慣れていない」という文にはならない。"}], "explanations": {"取り扱い": "正解。刃物の使い方に慣れていない、という意味になる。", "天気": "空模様を表す語。「刃物の天気に慣れていない」とは言えず、文が成り立たない。", "湿度": "空気の湿り具合を表す語。刃物に慣れるという文の対象にはならない。", "眠気": "眠くなる感覚を表す語。「刃物の眠気に慣れていない」という文にはならない。"}, "sentence_index": 6, "correct_answer": "取り扱い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は機械を組み立てる取り扱いが高い。", "explanation": "ここは「技術・腕前」の意味。「取り扱い」は使い方や決まりを指し、腕前の高さを「高い」で表すことはできない。"}, {"text": "この飛行機は、出発前に取り扱いを整える。", "explanation": "ここは〈整備〉の意味。取り扱いは使い方や決まりを指し、機体を点検して整える意味では使わない。"}, {"text": "この梅干しは、取り扱いが濃くて酸っぱい。", "explanation": "ここは〈塩加減〉の意味。「濃い」は味の濃さに使い、取り扱いの程度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36482, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ホットプレートの取り扱いが、友人に教えてもらった。", "corrected_sentence": "ホットプレートの取り扱いを、友人に教えてもらった。", "error_description": "「教えてもらう」の対象は「取り扱い」なので、格助詞は「を」が正しい。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36482, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道具は取り扱うに注意して使う。", "corrected_sentence": "この道具は取り扱いに注意して使う。", "error_description": "「注意する」の前には名詞の「取り扱い」が来る。動詞の「取り扱う」の形は誤りで、「取り扱いに注意」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36483, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「取り扱いが悪いと」で、取り扱いという事柄が悪い、と主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「取り扱いを悪いと」は目的語の形になり、形容詞「悪い」と続かない。"}, {"text": "で", "is_correct": false, "explanation": "「取り扱いで悪いと」は場面を示すが、「悪い」の主語にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「取り扱いへ悪いと」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「取り扱いが悪いと」で、取り扱いという事柄が悪い、と主語を示す。", "を": "「取り扱いを悪いと」は目的語の形になり、形容詞「悪い」と続かない。", "で": "「取り扱いで悪いと」は場面を示すが、「悪い」の主語にならず不自然。", "へ": "「へ」は方向を示す。「取り扱いへ悪いと」では意味が通らない。"}, "error_tags": {"を": "対象", "で": "場面", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36483, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「食品の取り扱いは」で、取り扱いを主題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「取り扱いを、衛生面の管理が」は目的語の形になり、主題の文として続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「取り扱いへ」では文の主題にならない。"}, {"text": "の", "is_correct": false, "explanation": "「取り扱いの、」と切れると主題の文が成り立たず、「の」は不可。"}], "correct_answer": "は", "explanations": {"は": "正解。「食品の取り扱いは」で、取り扱いを主題として示す。", "を": "「取り扱いを、衛生面の管理が」は目的語の形になり、主題の文として続かない。", "へ": "「へ」は方向を示す。「取り扱いへ」では文の主題にならない。", "の": "「取り扱いの、」と切れると主題の文が成り立たず、「の」は不可。"}, "error_tags": {"を": "対象", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36483, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を扱う方法や態度。また、処理や管理のしかた。", "primary_collocate": null, "pronunciation": "とりあつかい", "ipa": "toɾiatsɯkai", "syllable_count": 6, "sentences": [{"text": "個人情報の取り扱いには、会社として厳しい決まりがある。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "個人情報[こじんじょうほう]の取[と]り扱[あつか]いには、会社[かいしゃ]として厳[きび]しい決[き]まりがある。", "sentence_source": "generated"}, {"text": "客への取り扱いが悪いと、店の評判が下がる。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "客[きゃく]への取[と]り扱[あつか]いが悪[わる]いと、店[みせ]の評判[ひょうばん]が下[さ]がる。", "sentence_source": "generated"}, {"text": "この荷物は割れやすいため、取り扱いに注意して運ぶ。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "この荷物[にもつ]は割[わ]れやすいため、取[と]り扱[あつか]いに注意[ちゅうい]して運[はこ]ぶ。", "sentence_source": "generated"}, {"text": "問題の取り扱いを間違えて、会議が長引いた。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "問題[もんだい]の取[と]り扱[あつか]いを間違[まちが]えて、会議[かいぎ]が長引[ながび]いた。", "sentence_source": "generated"}, {"text": "郵便局では、手紙の取り扱いが丁寧で信頼できる。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "郵便局[ゆうびんきょく]では、手紙[てがみ]の取[と]り扱[あつか]いが丁寧[ていねい]で信頼[しんらい]できる。", "sentence_source": "generated"}, {"text": "書類の取り扱いを新人に教えるのも、先輩の仕事だ。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "書類[しょるい]の取[と]り扱[あつか]いを新人[しんじん]に教[おし]えるのも、先輩[せんぱい]の仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "差別的な取り扱いを受けたと、彼女は市役所に訴えた。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "差別的[さべつてき]な取[と]り扱[あつか]いを受[う]けたと、彼女[かのじょ]は市役所[しやくしょ]に訴[うった]えた。", "sentence_source": "generated"}, {"text": "食品の取り扱いは、衛生面の管理が最も大切だ。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "食品[しょくひん]の取[と]り扱[あつか]いは、衛生面[えいせいめん]の管理[かんり]が最[もっと]も大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "ごみの取り扱いについて、市が新しい方法を決めた。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "ごみの取[と]り扱[あつか]いについて、市[し]が新[あたら]しい方法[ほうほう]を決[き]めた。", "sentence_source": "generated"}, {"text": "取り扱いの責任者が代わって、手続きが早くなった。", "target_word": "取り扱い", "complexity_tier": "T3", "furigana": "取[と]り扱[あつか]いの責任者[せきにんしゃ]が代[か]わって、手続[てつづ]きが早[はや]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り扱い", "label": "基本形"}, {"form": "取り扱いの", "label": "連体形(の)"}, {"form": "取り扱いが", "label": "主格(が)"}], "register": "neutral", "sense_fingerprint": "取り扱い: 物事・人・情報などへの対応の態度、処理や管理のしかた", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ca05e1-aa05-4ad7-add9-a71a38ebfa4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36483, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り扱い", "is_correct": true, "explanation": "正解。個人情報の扱い方に関する厳しい決まりがある、という内容に合う。"}, {"text": "値段", "is_correct": false, "explanation": "価格を表す語。個人情報の値段に会社として厳しい決まりがあるという文にはならない。"}, {"text": "色", "is_correct": false, "explanation": "見た目の性質を表す語。個人情報の色に厳しい決まりがあるという意味にならない。"}, {"text": "大きさ", "is_correct": false, "explanation": "量や規模を表す語。個人情報の大きさに決まりを設けるという文は成り立たない。"}], "explanations": {"取り扱い": "正解。個人情報の扱い方に関する厳しい決まりがある、という内容に合う。", "値段": "価格を表す語。個人情報の値段に会社として厳しい決まりがあるという文にはならない。", "色": "見た目の性質を表す語。個人情報の色に厳しい決まりがあるという意味にならない。", "大きさ": "量や規模を表す語。個人情報の大きさに決まりを設けるという文は成り立たない。"}, "sentence_index": 0, "correct_answer": "取り扱い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は、生徒の答案を取り扱いで採点した。", "explanation": "ここは〈採点〉の意味。取り扱いは処理や管理のしかたを指し、点数をつける意味では使わない。"}, {"text": "赤ちゃんの取り扱いを測るため、体温計を用意した。", "explanation": "ここは「体温を測る」の意味。「取り扱い」は物事の扱い方を指し、体温の測定には使えない。"}, {"text": "この新製品は、多くの人の取り扱いを集めている。", "explanation": "ここは「人の関心を引く」の意味。「取り扱い」は物事への対応を指し、人の注目には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36483, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り扱い", "is_correct": true, "explanation": "正解。差別的な扱いを受けた、という内容に合う。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語。「差別的な季節を受けた」とは言えない。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の風味を表す語。「差別的な味を受けた」という文にはならない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の湿り具合を表す語。「差別的な湿度を受けた」は成り立たない。"}], "explanations": {"取り扱い": "正解。差別的な扱いを受けた、という内容に合う。", "季節": "時期を表す語。「差別的な季節を受けた」とは言えない。", "味": "食べ物の風味を表す語。「差別的な味を受けた」という文にはならない。", "湿度": "空気の湿り具合を表す語。「差別的な湿度を受けた」は成り立たない。"}, "sentence_index": 6, "correct_answer": "取り扱い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "取り扱いが回復して、洗濯物がようやく乾いた。", "explanation": "ここは「天候が回復する」の意味。「取り扱い」は物事の扱い方を指し、天候の回復とは結びつかない。"}, {"text": "この部屋は、取り扱いを会議向けに変えて使うことが多い。", "explanation": "ここは「使う」の意味。「取り扱う」は物事への対応や処理を指し、部屋を用途に使う意味では使わない。"}, {"text": "この映画は、取り扱いの色が鮮やかで涙が出た。", "explanation": "ここは〈色彩〉の意味。取り扱いは扱い方を指し、色の鮮やかさは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36483, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食品は取り扱うに注意して保存する。", "corrected_sentence": "食品は取り扱いに注意して保存する。", "error_description": "「注意する」の前には名詞の「取り扱い」が来る。動詞の「取り扱う」は誤りで、「取り扱いに注意」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36483, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お客様の取り扱いを注意しながら、丁寧に接する。", "corrected_sentence": "お客様の取り扱いに注意しながら、丁寧に接する。", "error_description": "「注意する」は「〜に注意する」と言うので、取り扱いに続く助詞は「を」ではなく「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36484, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「礼儀を知る」の目的語で、知る対象を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「礼儀が知らない」は主語が合わず、知らないの対象にならない。"}, {"text": "に", "is_correct": false, "explanation": "「礼儀に知らない」は場所や到達の助詞で、知る対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「礼儀へ知らない」は方向を表す助詞で、知る対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「礼儀を知る」の目的語で、知る対象を示す正しい助詞。", "が": "「礼儀が知らない」は主語が合わず、知らないの対象にならない。", "に": "「礼儀に知らない」は場所や到達の助詞で、知る対象を示せない。", "へ": "「礼儀へ知らない」は方向を表す助詞で、知る対象にはならない。"}, "error_tags": {"が": "主語", "に": "場所・到達", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
