INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36484, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人と人とが気持ちよく過ごすために、相手を大切に思う気持ちを行動に表すこと。", "primary_collocate": null, "pronunciation": "れいぎ", "ipa": "ɾeːɡi", "syllable_count": 3, "sentences": [{"text": "食事の前に挨拶をするのは、基本的な礼儀だ。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "食事[しょくじ]の前[まえ]に挨拶[あいさつ]をするのは、基本的[きほんてき]な礼儀[れいぎ]だ。", "sentence_source": "generated"}, {"text": "彼は礼儀を知らないので、先輩の前でも足を組んで座る。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "彼[かれ]は礼儀[れいぎ]を知[し]らないので、先輩[せんぱい]の前[まえ]でも足[あし]を組[く]んで座[すわ]る。", "sentence_source": "generated"}, {"text": "初めて会う人には、礼儀として名刺を両手で渡す。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "初[はじ]めて会[あ]う人[ひと]には、礼儀[れいぎ]として名刺[めいし]を両手[りょうて]で渡[わた]す。", "sentence_source": "generated"}, {"text": "友達の家に行くときは、手みやげを持っていくのが礼儀だと教わった。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "友達[ともだち]の家[いえ]に行[い]くときは、手[て]みやげを持[も]っていくのが礼儀[れいぎ]だと教[おそ]わった。", "sentence_source": "generated"}, {"text": "親しい友人にも礼儀を忘れないことが、つきあいを長く続ける秘訣だ。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "親[した]しい友人[ゆうじん]にも礼儀[れいぎ]を忘[わす]れないことが、つきあいを長[なが]く続[つづ]ける秘訣[ひけつ]だ。", "sentence_source": "generated"}, {"text": "礼儀を守らない客に、店員は困った顔をした。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "礼儀[れいぎ]を守[まも]らない客[きゃく]に、店員[てんいん]は困[こま]った顔[かお]をした。", "sentence_source": "generated"}, {"text": "面接では、礼儀を大切にして、はっきり挨拶した。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "面接[めんせつ]では、礼儀[れいぎ]を大切[たいせつ]にして、はっきり挨拶[あいさつ]した。", "sentence_source": "generated"}, {"text": "電車で席をゆずるのは、年上の人への礼儀でもある。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "電車[でんしゃ]で席[せき]をゆずるのは、年上[としうえ]の人[ひと]への礼儀[れいぎ]でもある。", "sentence_source": "generated"}, {"text": "彼女は礼儀に厳しい家庭で育ったので、箸の持ち方もきれいだ。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は礼儀[れいぎ]に厳[きび]しい家庭[かてい]で育[そだ]ったので、箸[はし]の持[も]ち方[かた]もきれいだ。", "sentence_source": "generated"}, {"text": "遅れるときに連絡をしないのは、相手に対する礼儀に欠ける。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "遅[おく]れるときに連絡[れんらく]をしないのは、相手[あいて]に対[たい]する礼儀[れいぎ]に欠[か]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "礼儀", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "相手を大切に思う気持ちを、挨拶や振る舞いなどの行動で示すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: 手みやげ (Zipf 1.62)']::text[], '8a20f6f9-5c1c-4724-a88a-cb37d143b680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36484, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "礼儀", "is_correct": true, "explanation": "相手を思う態度や作法を指し、「基本的な礼儀だ」と文脈に合う。"}, {"text": "予算", "is_correct": false, "explanation": "金銭の見積もりを指し、「基本的な予算だ」は作法の話として成り立たない。"}, {"text": "締め切り", "is_correct": false, "explanation": "期限を表す語で、「基本的な締め切りだ」は意味が通らない。"}, {"text": "残高", "is_correct": false, "explanation": "お金の残りを表す語で、挨拶の文脈では「基本的な残高」は成り立たない。"}], "explanations": {"礼儀": "相手を思う態度や作法を指し、「基本的な礼儀だ」と文脈に合う。", "予算": "金銭の見積もりを指し、「基本的な予算だ」は作法の話として成り立たない。", "締め切り": "期限を表す語で、「基本的な締め切りだ」は意味が通らない。", "残高": "お金の残りを表す語で、挨拶の文脈では「基本的な残高」は成り立たない。"}, "sentence_index": 0, "correct_answer": "礼儀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年の夏は礼儀が暑く、外に出るのが辛い。", "explanation": "ここは〈暑さ〉の意味。「暑さが厳しい」は自然だが、礼儀は態度や作法を指すので気温には使えない。"}, {"text": "彼は礼儀が豊富で、難しい試験の問題もすぐ解ける。", "explanation": "ここは〈知識〉の意味。量の豊かさは知識で表し、礼儀は態度や作法を指すので合わない。"}, {"text": "あの料理人は礼儀が確かで、包丁さばきがすばらしい。", "explanation": "ここは〈腕前〉の意味。技量の確かさは腕前で表し、礼儀では言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36484, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "礼儀", "is_correct": true, "explanation": "相手を敬う態度を指し、「面接では礼儀を大切にして」と文脈に合う。"}, {"text": "天候", "is_correct": false, "explanation": "天気の状態を指し、面接で大切にするものとしては成り立たない。"}, {"text": "行列", "is_correct": false, "explanation": "人の並びを指し、面接で大切にする対象とは言えない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌の言葉を指し、面接の場面で大切にする対象にならない。"}], "explanations": {"礼儀": "相手を敬う態度を指し、「面接では礼儀を大切にして」と文脈に合う。", "天候": "天気の状態を指し、面接で大切にするものとしては成り立たない。", "行列": "人の並びを指し、面接で大切にする対象とは言えない。", "歌詞": "歌の言葉を指し、面接の場面で大切にする対象にならない。"}, "sentence_index": 6, "correct_answer": "礼儀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は礼儀が派手で、いつも目立つ服を着ている。", "explanation": "ここは〈見た目〉の意味。「見た目が派手」は自然だが、礼儀は態度や作法で外見の話には使えない。"}, {"text": "風邪で彼は礼儀が高く、ずっと寝込んでいる。", "explanation": "ここは〈体温〉の意味。「体温が高い」は自然だが、礼儀の高さという言い方はしない。"}, {"text": "この料理は礼儀が濃く、食べると喉が渇く。", "explanation": "ここは〈味の濃さ〉の意味。「味が濃い」は自然だが、礼儀は態度や作法を指すので料理の味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36484, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "初対面の人には礼儀に守って、丁寧に挨拶する。", "corrected_sentence": "初対面の人には礼儀を守って、丁寧に挨拶する。", "error_description": "「守る」の対象は「を」で示す。「礼儀に守る」は助詞の誤りで、正しくは「礼儀を守る」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36484, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "返事を遅らせるのは、相手への礼儀を欠くた行為だ。", "corrected_sentence": "返事を遅らせるのは、相手への礼儀を欠く行為だ。", "error_description": "「欠く」の連体形は「欠く」。「欠くた」は活用形の誤りで、正しくは「欠く行為」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36485, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「礼儀を守る」の目的語で、守る対象を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「礼儀が守らない」は主語が合わず、守る対象にならない。"}, {"text": "に", "is_correct": false, "explanation": "「礼儀に守らない」は「守る」に続かない助詞の使い方で、誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「礼儀へ守らない」は方向の助詞で、守る対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「礼儀を守る」の目的語で、守る対象を示す正しい助詞。", "が": "「礼儀が守らない」は主語が合わず、守る対象にならない。", "に": "「礼儀に守らない」は「守る」に続かない助詞の使い方で、誤り。", "へ": "「礼儀へ守らない」は方向の助詞で、守る対象を示せない。"}, "error_tags": {"が": "主語", "に": "場所・到達", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36485, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「礼儀を教える」の目的語で、教える内容を示す正しい助詞。"}, {"text": "と", "is_correct": false, "explanation": "「礼儀と教えた」は並列を表し、教える内容を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「礼儀より教えた」は比較の助詞で、教える対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「礼儀の教えた」は連体修飾で、動詞が直接続く形にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "「礼儀を教える」の目的語で、教える内容を示す正しい助詞。", "と": "「礼儀と教えた」は並列を表し、教える内容を示せない。", "より": "「礼儀より教えた」は比較の助詞で、教える対象にならない。", "の": "「礼儀の教えた」は連体修飾で、動詞が直接続く形にならず不自然。"}, "error_tags": {"と": "並列・相手", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36485, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会生活を円滑に進めるために、相手を敬い、思いやる態度や行動。", "primary_collocate": null, "pronunciation": "れいぎ", "ipa": "ɾeːɡi", "syllable_count": 3, "sentences": [{"text": "礼儀は、社会で人と円滑に付き合うために欠かせない。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "礼儀[れいぎ]は、社会[しゃかい]で人[ひと]と円滑[えんかつ]に付[つ]き合[あ]うために欠[か]かせない。", "sentence_source": "generated"}, {"text": "会社では、上司への礼儀を守らないと信頼を失う。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "会社[かいしゃ]では、上司[じょうし]への礼儀[れいぎ]を守[まも]らないと信頼[しんらい]を失[うしな]う。", "sentence_source": "generated"}, {"text": "外国の文化の礼儀を知らずに、恥ずかしい思いをした。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "外国[がいこく]の文化[ぶんか]の礼儀[れいぎ]を知[し]らずに、恥[は]ずかしい思[おも]いをした。", "sentence_source": "generated"}, {"text": "お礼の手紙を送るのは、世話になった人への礼儀だ。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "お礼[れい]の手紙[てがみ]を送[おく]るのは、世話[せわ]になった人[ひと]への礼儀[れいぎ]だ。", "sentence_source": "generated"}, {"text": "彼は礼儀を重んじるので、約束の時間より早く来る。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "彼[かれ]は礼儀[れいぎ]を重[おも]んじるので、約束[やくそく]の時間[じかん]より早[はや]く来[く]る。", "sentence_source": "generated"}, {"text": "メールでも礼儀を忘れず、最初に挨拶の言葉を書く。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "メールでも礼儀[れいぎ]を忘[わす]れず、最初[さいしょ]に挨拶[あいさつ]の言葉[ことば]を書[か]く。", "sentence_source": "generated"}, {"text": "日本では、お辞儀は代表的な礼儀の一つだ。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "日本[にほん]では、お辞儀[じぎ]は代表的[だいひょうてき]な礼儀[れいぎ]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "新入社員に、電話の礼儀を一から教えた。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "新入[しんにゅう]社員[しゃいん]に、電話[でんわ]の礼儀[れいぎ]を一[いち]から教[おし]えた。", "sentence_source": "generated"}, {"text": "礼儀をわきまえた態度で、彼は客に接した。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "礼儀[れいぎ]をわきまえた態度[たいど]で、彼[かれ]は客[きゃく]に接[せっ]した。", "sentence_source": "generated"}, {"text": "いくら忙しくても、返事をしないのは礼儀に反する。", "target_word": "礼儀", "complexity_tier": "T3", "furigana": "いくら忙[いそが]しくても、返事[へんじ]をしないのは礼儀[れいぎ]に反[はん]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "礼儀", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "社会で円滑に付き合うために求められる、相手を敬う態度や作法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a20f6f9-5c1c-4724-a88a-cb37d143b680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36485, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "礼儀", "is_correct": true, "explanation": "社会で円滑に付き合うための態度や作法を指し、「礼儀は欠かせない」と文脈に合う。"}, {"text": "残高", "is_correct": false, "explanation": "お金の残りを表す語で、社会での付き合い方の話には当てはまらない。"}, {"text": "勝敗", "is_correct": false, "explanation": "勝ち負けの結果を指し、「勝敗は欠かせない」は付き合い方の文として成り立たない。"}, {"text": "締め切り", "is_correct": false, "explanation": "期限を表す語で、社会での付き合いに欠かせないものとは言えない。"}], "explanations": {"礼儀": "社会で円滑に付き合うための態度や作法を指し、「礼儀は欠かせない」と文脈に合う。", "残高": "お金の残りを表す語で、社会での付き合い方の話には当てはまらない。", "勝敗": "勝ち負けの結果を指し、「勝敗は欠かせない」は付き合い方の文として成り立たない。", "締め切り": "期限を表す語で、社会での付き合いに欠かせないものとは言えない。"}, "sentence_index": 0, "correct_answer": "礼儀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は礼儀がかかるので、作るのに二時間もかかる。", "explanation": "ここは〈手間〉の意味。「手間がかかる」は自然だが、礼儀は態度や作法で、かかるものとしては使えない。"}, {"text": "彼は礼儀が高く、難しい計算もすぐに解く。", "explanation": "ここは〈能力〉の意味。能力の高さは能力で表し、礼儀は態度や作法を指すので合わない。"}, {"text": "この製品は礼儀が高く、長く使える。", "explanation": "ここは〈品質〉の意味。製品の出来の良さは品質で表し、礼儀の高さとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36485, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "礼儀", "is_correct": true, "explanation": "お辞儀が代表的な礼儀の一つだという文脈に合う、正しい語。"}, {"text": "行列", "is_correct": false, "explanation": "人の並びを指し、「代表的な行列の一つ」は意味をなさない。"}, {"text": "配線", "is_correct": false, "explanation": "機器の電気的なつながりを指し、お辞儀の分類の文に合わない。"}, {"text": "天候", "is_correct": false, "explanation": "天気の状態を指し、「代表的な天候の一つ」は意味が通らない。"}], "explanations": {"礼儀": "お辞儀が代表的な礼儀の一つだという文脈に合う、正しい語。", "行列": "人の並びを指し、「代表的な行列の一つ」は意味をなさない。", "配線": "機器の電気的なつながりを指し、お辞儀の分類の文に合わない。", "天候": "天気の状態を指し、「代表的な天候の一つ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "礼儀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車は礼儀が速く、高速道路でもぐんぐん加速する。", "explanation": "ここは〈速度〉の意味。「速度が速い」は自然だが、礼儀の速さとは言わない。"}, {"text": "梅雨の部屋は礼儀が多く、洗濯物が乾かない。", "explanation": "ここは〈湿気〉の意味。「湿気が多い」は自然だが、礼儀は態度や作法を指すので空気の湿り具合は表せない。"}, {"text": "昼時の店は礼儀が長く、三十分並んだ。", "explanation": "ここは〈行列〉の意味。長く続く列の話で、礼儀の長さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36485, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "相手に礼儀が尽くして名刺を渡す。", "corrected_sentence": "相手に礼儀を尽くして名刺を渡す。", "error_description": "「尽くす」の対象は「を」で示す。「礼儀が尽くす」は助詞の誤りで、正しくは「礼儀を尽くす」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36485, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "礼儀を守るば、初対面の相手にも信頼される。", "corrected_sentence": "礼儀を守れば、初対面の相手にも信頼される。", "error_description": "「守る」の仮定形は「守れば」。「守るば」は活用の誤りで、正しくは「守れば」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36486, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この論は」と、話題にする論を主題として示す。説明する主体として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "説明できる対象は「現象」なので、論に直接「を」を付けると文の意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「論に」は着点を示し、説明するという動作の相手にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「論と」は並列を示すが、論が現象を説明する主語になるという意味から外れる。"}], "correct_answer": "は", "explanations": {"は": "「この論は」と、話題にする論を主題として示す。説明する主体として自然に続く。", "を": "説明できる対象は「現象」なので、論に直接「を」を付けると文の意味が通らない。", "に": "「論に」は着点を示し、説明するという動作の相手にはならない。", "と": "「論と」は並列を示すが、論が現象を説明する主語になるという意味から外れる。"}, "error_tags": {"を": "目的語の格", "に": "着点・相手", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36486, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「論を確かめる」の「を」。確かめる対象を示すので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「論が確かめる」は論が動作主になり、確かめる対象を表せないので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を示すが、確かめる対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「論の確かめるために」は名詞句として成り立たず、文の流れが崩れる。"}], "correct_answer": "を", "explanations": {"を": "「論を確かめる」の「を」。確かめる対象を示すので正しい。", "が": "「論が確かめる」は論が動作主になり、確かめる対象を表せないので不自然。", "へ": "「へ」は向かう先を示すが、確かめる対象にはならない。", "の": "「論の確かめるために」は名詞句として成り立たず、文の流れが崩れる。"}, "error_tags": {"が": "主語の格", "へ": "方向", "の": "連体・所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36486, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとについての筋道立った意見や説。", "primary_collocate": null, "pronunciation": "ろん", "ipa": "ɾoɴ", "syllable_count": 2, "sentences": [{"text": "この論によれば、重い物ほど速く落ちるわけではない。", "target_word": "論", "complexity_tier": "T3", "furigana": "この論[ろん]によれば、重い物[おもいもの]ほど速く落[お]ちるわけではない。", "sentence_source": "generated"}, {"text": "この論は、観察した現象をうまく説明できる。", "target_word": "論", "complexity_tier": "T3", "furigana": "この論[ろん]は、観察[かんさつ]した現象[げんしょう]をうまく説明[せつめい]できる。", "sentence_source": "generated"}, {"text": "この問題については、専門家の間でも論が分かれている。", "target_word": "論", "complexity_tier": "T3", "furigana": "この問題[もんだい]については、専門家[せんもんか]の間[あいだ]でも論[ろん]が分[わ]かれている。", "sentence_source": "generated"}, {"text": "先生は自分の論を黒板に書いて説明した。", "target_word": "論", "complexity_tier": "T3", "furigana": "先生[せんせい]は自分[じぶん]の論[ろん]を黒板[こくばん]に書[か]いて説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この論には、説明できない現象がある。", "target_word": "論", "complexity_tier": "T3", "furigana": "この論[ろん]には、説明[せつめい]できない現象[げんしょう]がある。", "sentence_source": "generated"}, {"text": "論を立てるときは、まず前提をはっきりさせたほうがいい。", "target_word": "論", "complexity_tier": "T3", "furigana": "論[ろん]を立[た]てるときは、まず前提[ぜんてい]をはっきりさせたほうがいい。", "sentence_source": "generated"}, {"text": "研究会で、田中さんは新しい論を発表した。", "target_word": "論", "complexity_tier": "T3", "furigana": "研究会[けんきゅうかい]で、田中[たなか]さんは新[あたら]しい論[ろん]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "この論を確かめるために、少しは手を動かして実験しなさい。", "target_word": "論", "complexity_tier": "T3", "furigana": "この論[ろん]を確[たし]かめるために、少[すこ]しは手[て]を動[うご]かして実験[じっけん]しなさい。", "sentence_source": "generated"}, {"text": "この論に対して、鈴木さんは別の説明を示した。", "target_word": "論", "complexity_tier": "T3", "furigana": "この論[ろん]に対[たい]して、鈴木[すずき]さんは別[べつ]の説明[せつめい]を示[しめ]した。", "sentence_source": "generated"}, {"text": "この論はわかりやすくて、学生にも人気がある。", "target_word": "論", "complexity_tier": "T3", "furigana": "この論[ろん]はわかりやすくて、学生[がくせい]にも人気[にんき]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "論", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ものごとについての筋道立った意見や説", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36486, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "論", "is_correct": true, "explanation": "文中の〈論〉が入る。「論によれば」で、ある考え方や説を根拠として示している。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、「によれば」で根拠を示す対象にはならない。"}, {"text": "義務", "is_correct": false, "explanation": "義務は果たすべきことで、重い物の落ち方について根拠として挙げる語ではない。"}, {"text": "感情", "is_correct": false, "explanation": "感情は気持ちのことで、物がどう落ちるかを示す根拠にはならない。"}], "explanations": {"論": "文中の〈論〉が入る。「論によれば」で、ある考え方や説を根拠として示している。", "天気": "天気は空模様のことで、「によれば」で根拠を示す対象にはならない。", "義務": "義務は果たすべきことで、重い物の落ち方について根拠として挙げる語ではない。", "感情": "感情は気持ちのことで、物がどう落ちるかを示す根拠にはならない。"}, "sentence_index": 0, "correct_answer": "論"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹は古い論を開けて、中のお菓子を取り出した。", "explanation": "ここは〈論〉（ものごとの筋道や考え）の意味。論は箱のように物を入れる入れ物を指さないので、「開けて取り出す」とは合わない。"}, {"text": "映画のラストで、悲しい論がわいてきた。", "explanation": "〈感情〉の位置に入れた文。「感情がわく」は自然だが、論は考えの筋道なので気持ちとして「わく」とは言わない。"}, {"text": "この店のスープは、論が濃くて香りがいい。", "explanation": "〈味〉の位置に入れた文。「味が濃い」は自然だが、論は味を表さないので、この使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36486, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "論", "is_correct": true, "explanation": "文中の〈論〉が入る。「新しい論を発表する」の論は、説として発表された考えを指す。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理道具で、研究会で発表する対象にはならない。"}, {"text": "階段", "is_correct": false, "explanation": "階段は建物の段差で、発表する対象にはならない。"}, {"text": "疲れ", "is_correct": false, "explanation": "疲れは体の状態で、「発表する」の対象として合わない。"}], "explanations": {"論": "文中の〈論〉が入る。「新しい論を発表する」の論は、説として発表された考えを指す。", "鍋": "鍋は調理道具で、研究会で発表する対象にはならない。", "階段": "階段は建物の段差で、発表する対象にはならない。", "疲れ": "疲れは体の状態で、「発表する」の対象として合わない。"}, "sentence_index": 6, "correct_answer": "論"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春になると、庭の論が次々と咲いた。", "explanation": "〈花〉の位置に入れた文。花は咲くが、論は咲くものではないので、この使い方はしない。"}, {"text": "雨の日は、論を履いて出かけた。", "explanation": "〈靴〉の位置に入れた文。靴は履くものだが、論は身につけるものではないので、この動詞とは組まない。"}, {"text": "朝は、論を洗って化粧を始めた。", "explanation": "〈顔〉の位置に入れた文。顔は洗うものだが、論は洗う対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36486, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その問題について、学者の間で論を分かれている。", "corrected_sentence": "その問題について、学者の間で論が分かれている。", "error_description": "「分かれる」は主語を「が」で示す自動詞。論が主語なので「が」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36486, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "田中さんは研究会で新しい論に発表した。", "corrected_sentence": "田中さんは研究会で新しい論を発表した。", "error_description": "「発表する」は対象を「を」で示す。論が対象なので「を」が正しく、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
