INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36488, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを受け入れること。", "primary_collocate": null, "pronunciation": "じゅよう", "ipa": "dʑɯjoː", "syllable_count": 3, "sentences": [{"text": "市民は新しいルールを受容し、街は落ち着きを取り戻した。", "target_word": "受容", "complexity_tier": "T3", "furigana": "市民[しみん]は新[あたら]しいルールを受容[じゅよう]し、街[まち]は落[お]ち着[つ]きを取[と]り戻[もど]した。", "sentence_source": "generated"}, {"text": "若者の間で、その音楽が広く受容されている。", "target_word": "受容", "complexity_tier": "T3", "furigana": "若者[わかもの]の間[あいだ]で、その音楽[おんがく]が広[ひろ]く受容[じゅよう]されている。", "sentence_source": "generated"}, {"text": "外国の技術を受容して、国の産業が発展した。", "target_word": "受容", "complexity_tier": "T3", "furigana": "外国[がいこく]の技術[ぎじゅつ]を受容[じゅよう]して、国[くに]の産業[さんぎょう]が発展[はってん]した。", "sentence_source": "generated"}, {"text": "彼は厳しい現実を受容するしかなかった。", "target_word": "受容", "complexity_tier": "T3", "furigana": "彼[かれ]は厳[きび]しい現実[げんじつ]を受容[じゅよう]するしかなかった。", "sentence_source": "generated"}, {"text": "読者による作品の受容は、時代によって変わる。", "target_word": "受容", "complexity_tier": "T3", "furigana": "読者[どくしゃ]による作品[さくひん]の受容[じゅよう]は、時代[じだい]によって変[か]わる。", "sentence_source": "generated"}, {"text": "新しい考え方の受容には、時間がかかるものだ。", "target_word": "受容", "complexity_tier": "T3", "furigana": "新[あたら]しい考[かんが]え方[かた]の受容[じゅよう]には、時間[じかん]がかかるものだ。", "sentence_source": "generated"}, {"text": "この制度は、住民に受容されなければ意味がない。", "target_word": "受容", "complexity_tier": "T3", "furigana": "この制度[せいど]は、住民[じゅうみん]に受容[じゅよう]されなければ意味[いみ]がない。", "sentence_source": "generated"}, {"text": "外来の文化を受容する一方で、独自の伝統も守ってきた。", "target_word": "受容", "complexity_tier": "T3", "furigana": "外来[がいらい]の文化[ぶんか]を受容[じゅよう]する一方[いっぽう]で、独自[どくじ]の伝統[でんとう]も守[まも]ってきた。", "sentence_source": "generated"}, {"text": "彼女は検査の結果を、静かに受容した。", "target_word": "受容", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は検査[けんさ]の結果[けっか]を、静[しず]かに受容[じゅよう]した。", "sentence_source": "generated"}, {"text": "新技術が社会に受容される過程を、歴史から学ぶ。", "target_word": "受容", "complexity_tier": "T3", "furigana": "新技術[しんぎじゅつ]が社会[しゃかい]に受容[じゅよう]される過程[かてい]を、歴史[れきし]から学[まな]ぶ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受容", "label": "基本形"}, {"form": "受容する", "label": "する動詞・終止形"}, {"form": "受容した", "label": "過去形"}, {"form": "受容される", "label": "受身形"}, {"form": "受容できる", "label": "可能形"}], "register": "formal", "sense_fingerprint": "物事や文化・作品などを受け入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36488, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受容", "is_correct": true, "explanation": "ここは「受け入れる」の意味。「ルールを受容し」と自然に続く。"}, {"text": "撮影", "is_correct": false, "explanation": "撮影は写真や映像を撮る行為で、ルールを対象にはできない。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつけることで、ルールには当てはまらない。"}, {"text": "降雨", "is_correct": false, "explanation": "降雨は雨が降ることで、人がルールに対して行う動作ではない。"}], "explanations": {"受容": "ここは「受け入れる」の意味。「ルールを受容し」と自然に続く。", "撮影": "撮影は写真や映像を撮る行為で、ルールを対象にはできない。", "点火": "点火は火をつけることで、ルールには当てはまらない。", "降雨": "降雨は雨が降ることで、人がルールに対して行う動作ではない。"}, "sentence_index": 0, "correct_answer": "受容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は来週、病院で検診を受容する予定だ。", "explanation": "ここは「受診」の意味。受容は受け入れることで、医療機関で診察を受けるのには使わない。"}, {"text": "祖母は毎月の年金を受容している。", "explanation": "ここは「受給」の意味。年金などの給付を受け取るのは「受給」で、「受容」は何かを受け入れることを指すので、この文では合わない。"}, {"text": "彼は夏期講習を受容した。", "explanation": "ここは「受講」の意味。講座や授業を受けるのは「受講」で、「受容」は受け入れることを指すので、講習には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36488, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受容", "is_correct": true, "explanation": "ここは「受け入れられる」の意味。「住民に受容される」は、制度を受け入れてもらう文として自然。"}, {"text": "舗装", "is_correct": false, "explanation": "舗装は道路などを固める作業で、制度には当てはまらず文が成り立たない。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲をつくる行為で、制度を対象にできない。"}, {"text": "放牧", "is_correct": false, "explanation": "放牧は家畜を放し飼いにすることで、制度には使えない。"}], "explanations": {"受容": "ここは「受け入れられる」の意味。「住民に受容される」は、制度を受け入れてもらう文として自然。", "舗装": "舗装は道路などを固める作業で、制度には当てはまらず文が成り立たない。", "作曲": "作曲は曲をつくる行為で、制度を対象にできない。", "放牧": "放牧は家畜を放し飼いにすることで、制度には使えない。"}, "sentence_index": 6, "correct_answer": "受容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "優秀な研究者が、大きな賞を受容した。", "explanation": "ここは「受賞」の意味。賞を受けて表彰されることは「受賞」で、「受容」は何かを受け入れることを指すので、賞を受ける文では合わない。"}, {"text": "彼女は来月、入試を受容する予定だ。", "explanation": "ここは「受験」の意味。試験を受けることは「受験」と言い、「受容」は何かを受け入れることを指すので、入試には使わない。"}, {"text": "彼女は奨学金を受容して、留学を決めた。", "explanation": "ここは「受給」の意味。奨学金のような給付を受け取るのは「受給」で、「受容」は何かを受け入れることを指すので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36488, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は昔からの習慣を受容に、新しい生活に馴染んだ。", "corrected_sentence": "彼は昔からの習慣を受容して、新しい生活に馴染んだ。", "error_description": "正しくは「受容して」（「する」のて形）。「受容に」は動詞「する」が必要な所に格助詞を置いた誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36488, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その提案は、現場の人たちに受容せれてこそ意味がある。", "corrected_sentence": "その提案は、現場の人たちに受容されてこそ意味がある。", "error_description": "正しくは「受容されて」（サ変の受け身）。「受容せれて」は「する」の受け身として成り立たない形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
