INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36489, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "他者の考えや状況を、自分のものとして認めて受け入れること。", "primary_collocate": null, "pronunciation": "じゅよう", "ipa": "dʑɯjoː", "syllable_count": 3, "sentences": [{"text": "そこには、理屈や打算といった人為的な思惑が介在する余地はなく、ただ生命の根源的な渇望と、眼前の事物に対する純粋な受容があるのみだ。", "target_word": "受容", "complexity_tier": "T5", "furigana": "そこには、理屈[りくつ]や打算[ださん]といった人為的[じんいてき]な思惑[おもわく]が介在[かいざい]する余地[よち]はなく、ただ生命[せいめい]の根源的[こんげんてき]な渇望[かつぼう]と、眼前[がんぜん]の事物[じぶつ]に対[たい]する純粋[じゅんすい]な受容[じゅよう]があるのみだ。", "sentence_source": "mined"}, {"text": "相手の意見を受容する姿勢が、よい話し合いを生む。", "target_word": "受容", "complexity_tier": "T3", "furigana": "相手[あいて]の意見[いけん]を受容[じゅよう]する姿勢[しせい]が、よい話[はな]し合[あ]いを生[う]む。", "sentence_source": "generated"}, {"text": "彼は病気を受容するまでに、長い時間がかかった。", "target_word": "受容", "complexity_tier": "T3", "furigana": "彼[かれ]は病気[びょうき]を受容[じゅよう]するまでに、長[なが]い時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "親が子どもの個性を受容すると、子どもは安心して成長できる。", "target_word": "受容", "complexity_tier": "T3", "furigana": "親[おや]が子[こ]どもの個性[こせい]を受容[じゅよう]すると、子[こ]どもは安心[あんしん]して成長[せいちょう]できる。", "sentence_source": "generated"}, {"text": "異なる文化の受容は、時に戸惑いを伴う。", "target_word": "受容", "complexity_tier": "T3", "furigana": "異[こと]なる文化[ぶんか]の受容[じゅよう]は、時[とき]に戸惑[とまど]いを伴[ともな]う。", "sentence_source": "generated"}, {"text": "上司の考えを受容できず、彼は会社を辞めた。", "target_word": "受容", "complexity_tier": "T3", "furigana": "上司[じょうし]の考[かんが]えを受容[じゅよう]できず、彼[かれ]は会社[かいしゃ]を辞[や]めた。", "sentence_source": "generated"}, {"text": "自分の失敗を受容することが、成長の第一歩だ。", "target_word": "受容", "complexity_tier": "T3", "furigana": "自分[じぶん]の失敗[しっぱい]を受容[じゅよう]することが、成長[せいちょう]の第一歩[だいいっぽ]だ。", "sentence_source": "generated"}, {"text": "先生は生徒の悩みを否定せず、まず受容してくれた。", "target_word": "受容", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の悩[なや]みを否定[ひてい]せず、まず受容[じゅよう]してくれた。", "sentence_source": "generated"}, {"text": "新しい制度を受容するかどうかで、職場の意見が分かれた。", "target_word": "受容", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]を受容[じゅよう]するかどうかで、職場[しょくば]の意見[いけん]が分[わ]かれた。", "sentence_source": "generated"}, {"text": "変化を受容できる人は、環境が変わっても強い。", "target_word": "受容", "complexity_tier": "T3", "furigana": "変化[へんか]を受容[じゅよう]できる人[ひと]は、環境[かんきょう]が変[か]わっても強[つよ]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受容", "label": "基本形"}, {"form": "受容する", "label": "する動詞・終止形"}, {"form": "受容した", "label": "過去形"}, {"form": "受容される", "label": "受身形"}, {"form": "受容できる", "label": "可能形"}], "register": "formal", "sense_fingerprint": "他人の考えや現実の状況を認めて自分のものとして受け入れる心の働き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01a0093-f309-4ff5-a271-da84eab4a7f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36489, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受容", "is_correct": true, "explanation": "ここは「ありのままを受け入れる心」の意味。「純粋な受容」と自然に続く。"}, {"text": "重量", "is_correct": false, "explanation": "重量は物の重さを表し、心の受け入れを指さないので「純粋な重量」は成立しない。"}, {"text": "配置", "is_correct": false, "explanation": "配置は物の並べ方を表し、心の受け止めの語としては合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "旋律は音の並びを表し、受け入れる心の働きには当てはまらない。"}], "explanations": {"受容": "ここは「ありのままを受け入れる心」の意味。「純粋な受容」と自然に続く。", "重量": "重量は物の重さを表し、心の受け入れを指さないので「純粋な重量」は成立しない。", "配置": "配置は物の並べ方を表し、心の受け止めの語としては合わない。", "旋律": "旋律は音の並びを表し、受け入れる心の働きには当てはまらない。"}, "sentence_index": 0, "correct_answer": "受容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもは来年、難関大学を受容する予定だ。", "explanation": "ここは「受験」の意味。受容は考えや状況を受け入れることで、試験を受けるのには使わない。"}, {"text": "医院は保険証を受容して、診察券を渡した。", "explanation": "ここは「受理」の意味。受容は心や考えを受け入れることで、書類を正式に受け付ける場合には使わない。"}, {"text": "宅配便の荷物を受容した。", "explanation": "ここは「受け取る」の意味。受容は物を受け取ることではなく、考えや状況を受け入れることを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36489, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受容", "is_correct": true, "explanation": "ここは「失敗を受け入れる」の意味。「失敗を受容すること」と自然に続く。"}, {"text": "舗装", "is_correct": false, "explanation": "舗装は道路を固める作業で、失敗を対象にはできない。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲をつくる行為で、失敗とは結びつかない。"}, {"text": "放牧", "is_correct": false, "explanation": "放牧は家畜を放し飼いにすることで、失敗には当てはまらない。"}], "explanations": {"受容": "ここは「失敗を受け入れる」の意味。「失敗を受容すること」と自然に続く。", "舗装": "舗装は道路を固める作業で、失敗を対象にはできない。", "作曲": "作曲は曲をつくる行為で、失敗とは結びつかない。", "放牧": "放牧は家畜を放し飼いにすることで、失敗には当てはまらない。"}, "sentence_index": 6, "correct_answer": "受容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来場者は入口の受容で名前を書き、会場に入った。", "explanation": "ここは「受付」の意味。受容は心や考えを受け入れることで、窓口での受け付けは指さない。"}, {"text": "遠くの電波を受容して、画面に番組が映った。", "explanation": "ここは「受信」の意味。受容は電波を受け取る意味では使わない。"}, {"text": "体は食べ物から栄養を受容して、力を生み出す。", "explanation": "ここは「摂取」の意味。受容は心や考えを受け入れることで、栄養を体に取り入れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36489, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は現実を受容されず、しばらく部屋に閉じこもった。", "corrected_sentence": "彼女は現実を受容できず、しばらく部屋に閉じこもった。", "error_description": "正しくは「受容できず」（可能形）。「受容されず」は受け身で、受け入れられる側が主語になるため「現実を」と合わず意味が通らない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36489, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は失敗を受容しるようになって、前向きになった。", "corrected_sentence": "彼は失敗を受容できるようになって、前向きになった。", "error_description": "正しくは「受容できる」（「受容する」の可能形）。「受容しる」は「する」の活用として成り立たない形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e53031df-6980-48ca-a5bb-0a1c3700d2f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36490, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「寝ていた」の主語を示す。猫が寝ているという関係を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「寝る」は自動詞なので、「猫を寝ていた」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や位置を示す。「猫に寝ていた」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「猫へ寝ていた」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「寝ていた」の主語を示す。猫が寝ているという関係を表す。", "を": "「を」は目的語を示す。「寝る」は自動詞なので、「猫を寝ていた」は成り立たない。", "に": "「に」は相手や位置を示す。「猫に寝ていた」では意味が通らない。", "へ": "「へ」は方向を示す。「猫へ寝ていた」は成り立たない。"}, "error_tags": {"を": "目的語（自動詞と合わない）", "に": "相手・位置（寝る動作と合わない）", "へ": "方向（主語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36490, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「いる」の主語（存在するもの）を示す。三匹の猫が存在する関係を表す。"}, {"text": "で", "is_correct": false, "explanation": "「猫で」は手段や資格を表すので、「いる」の主語にならず、存在を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「猫から」は起点を表すので、存在を示す「いる」とは合わない。"}, {"text": "より", "is_correct": false, "explanation": "「猫より」は比較を表すので、存在を示す「いる」とは合わない。"}], "correct_answer": "が", "explanations": {"が": "「いる」の主語（存在するもの）を示す。三匹の猫が存在する関係を表す。", "で": "「猫で」は手段や資格を表すので、「いる」の主語にならず、存在を示せない。", "から": "「猫から」は起点を表すので、存在を示す「いる」とは合わない。", "より": "「猫より」は比較を表すので、存在を示す「いる」とは合わない。"}, "error_tags": {"で": "手段・資格（存在の主語にならない）", "から": "起点（存在を示せない）", "より": "比較（存在を示せない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36490, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いえでかうこともできる、小さいどうぶつです。", "primary_collocate": null, "pronunciation": "ねこ", "ipa": "neko", "syllable_count": 2, "sentences": [{"text": "うちの猫は、毎朝わたしの部屋の前で鳴く。", "target_word": "猫", "complexity_tier": "T3", "furigana": "うちの猫[ねこ]は、毎朝[まいあさ]わたしの部屋[へや]の前[まえ]で鳴[な]く。", "sentence_source": "generated"}, {"text": "公園のベンチで、猫が気持ちよさそうに寝ていた。", "target_word": "猫", "complexity_tier": "T3", "furigana": "公園[こうえん]のベンチで、猫[ねこ]が気持[きも]ちよさそうに寝[ね]ていた。", "sentence_source": "generated"}, {"text": "猫にえさをやるのが、弟の仕事だ。", "target_word": "猫", "complexity_tier": "T3", "furigana": "猫[ねこ]にえさをやるのが、弟[おとうと]の仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "アパートは小さいので、犬ではなく猫を飼うことにした。", "target_word": "猫", "complexity_tier": "T3", "furigana": "アパートは小[ちい]さいので、犬[いぬ]ではなく猫[ねこ]を飼[か]うことにした。", "sentence_source": "generated"}, {"text": "黒い猫が道を横切って、塀の上に飛び乗った。", "target_word": "猫", "complexity_tier": "T3", "furigana": "黒[くろ]い猫[ねこ]が道[みち]を横切[よこぎ]って、塀[へい]の上[うえ]に飛[と]び乗[の]った。", "sentence_source": "generated"}, {"text": "猫はお風呂が嫌いなので、洗うのが大変だ。", "target_word": "猫", "complexity_tier": "T3", "furigana": "猫[ねこ]はお風呂[ふろ]が嫌[きら]いなので、洗[あら]うのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "雨の日は、猫がずっと窓の外を見ている。", "target_word": "猫", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、猫[ねこ]がずっと窓[まど]の外[そと]を見[み]ている。", "sentence_source": "generated"}, {"text": "友達の家には、三匹の猫がいる。", "target_word": "猫", "complexity_tier": "T3", "furigana": "友達[ともだち]の家[いえ]には、三匹[さんびき]の猫[ねこ]がいる。", "sentence_source": "generated"}, {"text": "猫が新しいおもちゃで、夢中になって遊んでいる。", "target_word": "猫", "complexity_tier": "T3", "furigana": "猫[ねこ]が新[あたら]しいおもちゃで、夢中[むちゅう]になって遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "子どものころ、わたしは猫と一緒に育った。", "target_word": "猫", "complexity_tier": "T3", "furigana": "子[こ]どものころ、わたしは猫[ねこ]と一緒[いっしょ]に育[そだ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "猫", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "家で飼える小さな動物としての猫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 横切っ (Zipf 2.97), 塀 (Zipf 3.6), 飛び乗っ (Zipf 2.68)']::text[], '8a20f6f9-5c1c-4724-a88a-cb37d143b680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36490, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "猫", "is_correct": true, "explanation": "家で飼われ、鳴く動物を表すので、文の主語として自然。"}, {"text": "金魚", "is_correct": false, "explanation": "金魚は鳴かないので、「毎朝鳴く」と合わない。"}, {"text": "亀", "is_correct": false, "explanation": "亀は鳴かないので、「毎朝鳴く」と合わない。"}, {"text": "蝶", "is_correct": false, "explanation": "蝶は鳴かないので、「毎朝鳴く」と合わない。"}], "explanations": {"猫": "家で飼われ、鳴く動物を表すので、文の主語として自然。", "金魚": "金魚は鳴かないので、「毎朝鳴く」と合わない。", "亀": "亀は鳴かないので、「毎朝鳴く」と合わない。", "蝶": "蝶は鳴かないので、「毎朝鳴く」と合わない。"}, "sentence_index": 0, "correct_answer": "猫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "うちの猫は、夜になると庭で一晩中吠えて、近所から苦情が来た。", "explanation": "ここは〈犬〉の行動（夜通し吠える）の内容。猫は普通吠えないので、動物の猫の意味では合わない。"}, {"text": "うちの猫は、毎朝たまごを産んで、ひなを育てている。", "explanation": "ここは鳥（卵を産み、ひなを育てる）の内容。猫は哺乳類で卵を産まないので、動物の猫の意味では合わない。"}, {"text": "うちの猫は、冬になると冬眠して、春まで起きてこない。", "explanation": "ここは冬眠する動物（熊など）の内容。猫は冬眠しないので、動物の猫の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36490, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "猫", "is_correct": true, "explanation": "窓の外を見る主語として自然な生き物。"}, {"text": "時計", "is_correct": false, "explanation": "時計は窓の外を見ないので、主語として文が成り立たない。"}, {"text": "植木鉢", "is_correct": false, "explanation": "植木鉢は見る動作をしないので、「見ている」と合わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機は窓の外を見ないので、文の主語に合わない。"}], "explanations": {"猫": "窓の外を見る主語として自然な生き物。", "時計": "時計は窓の外を見ないので、主語として文が成り立たない。", "植木鉢": "植木鉢は見る動作をしないので、「見ている」と合わない。", "洗濯機": "洗濯機は窓の外を見ないので、文の主語に合わない。"}, "sentence_index": 6, "correct_answer": "猫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "うちの猫は、毎朝ヒレを使って水槽の中を泳いでいる。", "explanation": "ここは魚（ヒレで泳ぐ）の内容。猫には合わない。"}, {"text": "猫は、毎年秋になると翼を広げて南の国へ渡っていく。", "explanation": "ここは渡り鳥（翼で遠くへ移動する）の内容。猫には合わない。"}, {"text": "猫は、庭の木の枝に巣を作って、卵を三つ温めている。", "explanation": "ここは鳥の巣作りと抱卵の内容。猫には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36490, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓辺で、猫を気持ちよさそうに丸くなっていた。", "corrected_sentence": "窓辺で、猫が気持ちよさそうに丸くなっていた。", "error_description": "「猫」に続く助詞が誤り。「丸くなる」は自動詞なので、主語の「猫」には「が」を使う。「を」は目的語を示すため不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36490, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ひなたの縁側で、三本の猫が丸くなって眠っていた。", "corrected_sentence": "ひなたの縁側で、三匹の猫が丸くなって眠っていた。", "error_description": "「猫」の助数詞の誤り。動物の猫は「匹」で数えるので、「本」は不可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
