INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36492, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "ねむいというのは、ねたいきもちのことです。", "primary_collocate": null, "pronunciation": "ねむい", "ipa": "nemɯi", "syllable_count": 3, "sentences": [{"text": "昨日は遅くまで起きていたので、今日は朝から眠い。", "target_word": "眠い", "complexity_tier": "T3", "furigana": "昨日[きのう]は遅[おそ]くまで起[お]きていたので、今日[きょう]は朝[あさ]から眠[ねむ]い。", "sentence_source": "generated"}, {"text": "授業が退屈で、だんだん眠くなってきた。", "target_word": "眠く", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が退屈[たいくつ]で、だんだん眠[ねむ]くなってきた。", "sentence_source": "generated"}, {"text": "眠いときは、無理をしないで早く寝たほうがいい。", "target_word": "眠い", "complexity_tier": "T3", "furigana": "眠[ねむ]いときは、無理[むり]をしないで早[はや]く寝[ね]たほうがいい。", "sentence_source": "generated"}, {"text": "夜中に電話がかかってきて、とても眠かった。", "target_word": "眠かった", "complexity_tier": "T3", "furigana": "夜中[よなか]に電話[でんわ]がかかってきて、とても眠[ねむ]かった。", "sentence_source": "generated"}, {"text": "コーヒーを飲んだのに、まだ眠い。", "target_word": "眠い", "complexity_tier": "T3", "furigana": "コーヒーを飲[の]んだのに、まだ眠[ねむ]い。", "sentence_source": "generated"}, {"text": "お腹がいっぱいになると、どうしても眠くなる。", "target_word": "眠く", "complexity_tier": "T3", "furigana": "お腹[なか]がいっぱいになると、どうしても眠[ねむ]くなる。", "sentence_source": "generated"}, {"text": "眠くて、本の内容が頭に入らなかった。", "target_word": "眠くて", "complexity_tier": "T3", "furigana": "眠[ねむ]くて、本[ほん]の内容[ないよう]が頭[あたま]に入[はい]らなかった。", "sentence_source": "generated"}, {"text": "弟は眠いと、すぐ機嫌が悪くなる。", "target_word": "眠い", "complexity_tier": "T3", "furigana": "弟[おとうと]は眠[ねむ]いと、すぐ機嫌[きげん]が悪[わる]くなる。", "sentence_source": "generated"}, {"text": "運転中に眠くなったら、休憩を取るべきだ。", "target_word": "眠く", "complexity_tier": "T3", "furigana": "運転中[うんてんちゅう]に眠[ねむ]くなったら、休憩[きゅうけい]を取[と]るべきだ。", "sentence_source": "generated"}, {"text": "昼ごはんの後は、いつも眠くてしかたがない。", "target_word": "眠くて", "complexity_tier": "T3", "furigana": "昼[ひる]ごはんの後[あと]は、いつも眠[ねむ]くてしかたがない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眠い", "label": "終止形"}, {"form": "眠く", "label": "連用形"}, {"form": "眠くて", "label": "て形"}, {"form": "眠かった", "label": "過去形"}, {"form": "眠くない", "label": "否定形"}, {"form": "眠ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "寝たいと感じる気持ちや、その状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a20f6f9-5c1c-4724-a88a-cb37d143b680') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36492, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眠い", "is_correct": true, "explanation": "眠気を表す形容詞で、「今日は朝から」の述語として自然。"}, {"text": "甘い", "is_correct": false, "explanation": "甘いは味を表すので、「今日は朝から」の述語として文が通らない。"}, {"text": "広い", "is_correct": false, "explanation": "広いは空間を表すので、この文の述語として通らない。"}, {"text": "遠い", "is_correct": false, "explanation": "遠いは距離を表すので、この文の述語として通らない。"}], "explanations": {"眠い": "眠気を表す形容詞で、「今日は朝から」の述語として自然。", "甘い": "甘いは味を表すので、「今日は朝から」の述語として文が通らない。", "広い": "広いは空間を表すので、この文の述語として通らない。", "遠い": "遠いは距離を表すので、この文の述語として通らない。"}, "sentence_index": 0, "correct_answer": "眠い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熱が出て、体が眠くて一日中動けなかった。", "explanation": "ここは「だるい」（体に力が入らない）の意味。「眠い」は眠気を表すので、体の状態には合わない。"}, {"text": "お腹が眠くなったので、何か食べに行った。", "explanation": "ここは「空腹」（お腹がすく）の意味。「眠い」は眠気を表すので、お腹の感覚には合わない。"}, {"text": "のどが眠くなったので、水を一杯飲んだ。", "explanation": "ここは「のどが渇く」の意味。「眠い」は眠気を表すので、のどの渇きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36492, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眠くて", "is_correct": true, "explanation": "て形で、眠くて集中できなかったという理由を表し、文に合う。"}, {"text": "甘くて", "is_correct": false, "explanation": "甘いは味を表すので、本の内容が頭に入らない理由にならない。"}, {"text": "遠くて", "is_correct": false, "explanation": "遠いは距離を表すので、読書の理由として文が通らない。"}, {"text": "広くて", "is_correct": false, "explanation": "広いは空間を表すので、読書の理由として文が通らない。"}], "explanations": {"眠くて": "て形で、眠くて集中できなかったという理由を表し、文に合う。", "甘くて": "甘いは味を表すので、本の内容が頭に入らない理由にならない。", "遠くて": "遠いは距離を表すので、読書の理由として文が通らない。", "広くて": "広いは空間を表すので、読書の理由として文が通らない。"}, "sentence_index": 6, "correct_answer": "眠くて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "歯が眠くて、冷たいものが食べられない。", "explanation": "ここは「痛い」（痛みがある）の意味。「眠い」は眠気を表すので、歯の痛みには合わない。"}, {"text": "舌が眠くて、スープが飲めなかった。", "explanation": "ここは「熱い」（温度が高い）の意味。「眠い」は眠気を表すので、舌の熱さには合わない。"}, {"text": "肩が眠くて、腕が上がらない。", "explanation": "ここは「重い」（負担が大きい）の意味。「眠い」は眠気を表すので、肩の重さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36492, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は朝から眠いて、何もする気が起きない。", "corrected_sentence": "今日は朝から眠くて、何もする気が起きない。", "error_description": "「眠い」の連用形は「眠く」で、て形は「眠くて」。「眠いて」は形容詞の活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "眠く", "is_correct": true, "explanation": "「なってきた」に続く連用形で、正しい形。"}, {"text": "眠い", "is_correct": false, "explanation": "終止形なので、「だんだん眠いなってきた」のように「なってきた」には続かない。"}, {"text": "眠かった", "is_correct": false, "explanation": "過去形なので、「なってきた」には続かない。"}, {"text": "眠ければ", "is_correct": false, "explanation": "仮定形なので、「なってきた」には続かない。"}], "correct_form": "眠く", "base_form": "眠い", "form_label": "連用形", "sentence_index": 1, "explanations": {"眠く": "「なってきた」に続く連用形で、正しい形。", "眠い": "終止形なので、「だんだん眠いなってきた」のように「なってきた」には続かない。", "眠かった": "過去形なので、「なってきた」には続かない。", "眠ければ": "仮定形なので、「なってきた」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36492, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜更かしの後は、朝から眠かてしかたがない。", "corrected_sentence": "夜更かしの後は、朝から眠くてしかたがない。", "error_description": "「眠くて」の連用形は「眠く」。「眠かて」は過去形「眠かった」の語幹と混同した誤りで、正しくは「眠くて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "眠い", "is_correct": true, "explanation": "「と」の前に置く終止形で、条件を表す文に合う。"}, {"text": "眠く", "is_correct": false, "explanation": "連用形なので、「と」の前には続かない。"}, {"text": "眠くて", "is_correct": false, "explanation": "て形なので、「と」の前には続かない。"}, {"text": "眠ければ", "is_correct": false, "explanation": "仮定形なので、「と」と重ねると文が成り立たない。"}], "correct_form": "眠い", "base_form": "眠い", "form_label": "終止形", "sentence_index": 7, "explanations": {"眠い": "「と」の前に置く終止形で、条件を表す文に合う。", "眠く": "連用形なので、「と」の前には続かない。", "眠くて": "て形なので、「と」の前には続かない。", "眠ければ": "仮定形なので、「と」と重ねると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8493c9e0-460f-4068-ae29-8c8bfd448f37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
