INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36494, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あくびをすることです。", "primary_collocate": null, "pronunciation": "あくびをする", "ipa": "akɯbioɯɾɯ", "syllable_count": 6, "sentences": [{"text": "授業が長くて、思わずあくびをしてしまった。", "target_word": "あくびをしてしまった", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が長[なが]くて、思[おも]わずあくびをしてしまった。", "sentence_source": "generated"}, {"text": "夜ふかしをした朝は、電車の中であくびをします。", "target_word": "あくびをします", "complexity_tier": "T3", "furigana": "夜[よる]ふかしをした朝[あさ]は、電車[でんしゃ]の中[なか]であくびをします。", "sentence_source": "generated"}, {"text": "犬が日なたで大きなあくびをする。", "target_word": "あくびをする", "complexity_tier": "T3", "furigana": "犬[いぬ]が日[ひ]なたで大[おお]きなあくびをする。", "sentence_source": "generated"}, {"text": "眠いのに、人の前であくびをするのは失礼だと思って我慢した。", "target_word": "あくびをする", "complexity_tier": "T3", "furigana": "眠[ねむ]いのに、人[ひと]の前[まえ]であくびをするのは失礼[しつれい]だと思[おも]って我慢[がまん]した。", "sentence_source": "generated"}, {"text": "弟は退屈な映画を見ながら、何度もあくびをしていた。", "target_word": "あくびをしていた", "complexity_tier": "T3", "furigana": "弟[おとうと]は退屈[たいくつ]な映画[えいが]を見[み]ながら、何度[なんど]もあくびをしていた。", "sentence_source": "generated"}, {"text": "先生の前であくびをして、少し恥ずかしかった。", "target_word": "あくびをして", "complexity_tier": "T3", "furigana": "先生[せんせい]の前[まえ]であくびをして、少[すこ]し恥[は]ずかしかった。", "sentence_source": "generated"}, {"text": "猫は起きると、まずのびをしてあくびをする。", "target_word": "あくびをする", "complexity_tier": "T3", "furigana": "猫[ねこ]は起[お]きると、まずのびをしてあくびをする。", "sentence_source": "generated"}, {"text": "昼ごはんのあとは、眠くなってあくびをすることが多い。", "target_word": "あくびをする", "complexity_tier": "T3", "furigana": "昼[ひる]ごはんのあとは、眠[ねむ]くなってあくびをすることが多[おお]い。", "sentence_source": "generated"}, {"text": "会議が終わらなくて、みんな小さくあくびをしていた。", "target_word": "あくびをしていた", "complexity_tier": "T3", "furigana": "会議[かいぎ]が終[お]わらなくて、みんな小[ちい]さくあくびをしていた。", "sentence_source": "generated"}, {"text": "あくびをすると、涙が出てくることがある。", "target_word": "あくびをする", "complexity_tier": "T3", "furigana": "あくびをすると、涙[なみだ]が出[で]てくることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "あくびをする", "label": "終止形"}, {"form": "あくびをした", "label": "過去形"}, {"form": "あくびをして", "label": "て形"}, {"form": "あくびをしない", "label": "否定形"}, {"form": "あくびをします", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "眠い・退屈なときに口を大きく開けて息を吸う動作をする意味の「あくびをする」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b06b0e63-ab55-4198-b9e1-1c42010908cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36494, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "あくびをしてしまった", "is_correct": true, "explanation": "過去形。「思わず」の結果を述べる文末として正しい。"}, {"text": "あくびをしてしまうと", "is_correct": false, "explanation": "条件形「〜と」。後ろに続く文が必要で、文末には置けない。"}, {"text": "あくびをしてしまえば", "is_correct": false, "explanation": "仮定形「〜ば」。続きの文が必要で、文末にはならない。"}, {"text": "あくびをしてしまったら", "is_correct": false, "explanation": "仮定形「〜たら」。文末に置くと文が完結しない。"}], "explanations": {"あくびをしてしまった": "過去形。「思わず」の結果を述べる文末として正しい。", "あくびをしてしまうと": "条件形「〜と」。後ろに続く文が必要で、文末には置けない。", "あくびをしてしまえば": "仮定形「〜ば」。続きの文が必要で、文末にはならない。", "あくびをしてしまったら": "仮定形「〜たら」。文末に置くと文が完結しない。"}, "sentence_index": 0, "correct_answer": "あくびをしてしまった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ほこりを吸い込んで、大きなあくびが出た。", "explanation": "ここは〈くしゃみ〉の場面。ほこりで鼻がむずむずして出るのはくしゃみで、あくびとは違う。"}, {"text": "試合の前に、あくびでボールを止めた。", "explanation": "ここは〈キャッチ〉の場面。ボールを止めるのは手や足の動作で、あくびでは止められない。"}, {"text": "ドアの下にあくびがあって、冷たい風が入ってくる。", "explanation": "ここは〈すきま〉の意味。あくびは口を開けて息を吸う動作で、ドアのすきまを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36494, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "あくびをする", "is_correct": true, "explanation": "辞書形。「まずのびをして」に続く、猫の動作を述べる文末として正しい。"}, {"text": "あくびをすると", "is_correct": false, "explanation": "条件形「〜と」。文末には置けず、続きの文が必要になる。"}, {"text": "あくびをしたら", "is_correct": false, "explanation": "仮定形「〜たら」。文末では文が成り立たない。"}, {"text": "あくびをしたり", "is_correct": false, "explanation": "並列形「〜たり」。「〜たりする」と続けないと文末にならない。"}], "explanations": {"あくびをする": "辞書形。「まずのびをして」に続く、猫の動作を述べる文末として正しい。", "あくびをすると": "条件形「〜と」。文末には置けず、続きの文が必要になる。", "あくびをしたら": "仮定形「〜たら」。文末では文が成り立たない。", "あくびをしたり": "並列形「〜たり」。「〜たりする」と続けないと文末にならない。"}, "sentence_index": 6, "correct_answer": "あくびをする"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議で話す前に、あくびでマイクの音を大きくした。", "explanation": "ここは〈音量の調整〉の場面。マイクの音を変えるのは機器の操作で、あくびでは行えない。"}, {"text": "ゴールが決まると、スタジアムにあくびが上がった。", "explanation": "ここは〈歓声〉の話。歓声は声を上げるもので、あくびは口を開けて息を吸う動作なので「上がる」とは言わない。"}, {"text": "初対面の人と、しっかりあくびをした。", "explanation": "ここは〈握手〉の場面。手を握り合う動作は握手で、あくびは口の動作なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36494, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議が長くて、思わずあくびをしてしまったた。", "corrected_sentence": "会議が長くて、思わずあくびをしてしまった。", "error_description": "活用の誤り。「あくびをしてしまった」の末尾に余計な「た」が付いている。正しくは「あくびをしてしまった」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "あくびをします", "is_correct": true, "explanation": "丁寧形。電車の中であくびをする習慣を丁寧に述べる文末として正しい。"}, {"text": "あくびをして", "is_correct": false, "explanation": "て形。文末に置くと文が完結しない。"}, {"text": "あくびをしたら", "is_correct": false, "explanation": "仮定形「〜たら」。文末に置けず、文が完結しない。"}, {"text": "あくびをすれば", "is_correct": false, "explanation": "仮定形「〜ば」。文末に置けず、文が完結しない。"}], "correct_form": "あくびをします", "base_form": "あくびをする", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"あくびをします": "丁寧形。電車の中であくびをする習慣を丁寧に述べる文末として正しい。", "あくびをして": "て形。文末に置くと文が完結しない。", "あくびをしたら": "仮定形「〜たら」。文末に置けず、文が完結しない。", "あくびをすれば": "仮定形「〜ば」。文末に置けず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36494, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫は、寝る前にあくびをするた。", "corrected_sentence": "猫は、寝る前にあくびをする。", "error_description": "活用の誤り。辞書形「あくびをする」の後に余計な「た」が付いている。正しくは「あくびをする」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "あくびをする", "is_correct": true, "explanation": "辞書形。「〜ことが多い」の前は普通形で続くので正しい。"}, {"text": "あくびをしなくて", "is_correct": false, "explanation": "否定のて形。「〜こと」には続かず、文法的に成り立たない。"}, {"text": "あくびをしないで", "is_correct": false, "explanation": "否定のて形（〜ないで）。「〜こと」には続かない。"}, {"text": "あくびをしなければ", "is_correct": false, "explanation": "仮定形「〜ば」。「〜ことが多い」の前には置けない。"}], "correct_form": "あくびをする", "base_form": "あくびをする", "form_label": "辞書形", "sentence_index": 7, "explanations": {"あくびをする": "辞書形。「〜ことが多い」の前は普通形で続くので正しい。", "あくびをしなくて": "否定のて形。「〜こと」には続かず、文法的に成り立たない。", "あくびをしないで": "否定のて形（〜ないで）。「〜こと」には続かない。", "あくびをしなければ": "仮定形「〜ば」。「〜ことが多い」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
