INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36496, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "つまらないと感じることです。", "primary_collocate": null, "pronunciation": "たいくつ", "ipa": "taikɯtsɯ", "syllable_count": 4, "sentences": [{"text": "一人で家にいると、退屈でたまりません。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "一人[ひとり]で家[いえ]にいると、退屈[たいくつ]でたまりません。", "sentence_source": "generated"}, {"text": "雨の日は外に出られず、退屈な一日でした。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]に出[で]られず、退屈[たいくつ]な一日[いちにち]でした。", "sentence_source": "generated"}, {"text": "彼の話は長くて退屈だったので、みんな黙っていた。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は長[なが]くて退屈[たいくつ]だったので、みんな黙[だま]っていた。", "sentence_source": "generated"}, {"text": "退屈なときは、よく本を読みます。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "退屈[たいくつ]なときは、よく本[ほん]を読[よ]みます。", "sentence_source": "generated"}, {"text": "この映画は退屈で、途中で帰りたくなった。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "この映画[えいが]は退屈[たいくつ]で、途中[とちゅう]で帰[かえ]りたくなった。", "sentence_source": "generated"}, {"text": "授業が退屈で、窓の外ばかり見ていた。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が退屈[たいくつ]で、窓[まど]の外[そと]ばかり見[み]ていた。", "sentence_source": "generated"}, {"text": "毎日同じ仕事ばかりで、退屈してしまった。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "毎日[まいにち]同[おな]じ仕事[しごと]ばかりで、退屈[たいくつ]してしまった。", "sentence_source": "generated"}, {"text": "旅行中は退屈する暇がないほど忙しかった。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "旅行中[りょこうちゅう]は退屈[たいくつ]する暇[ひま]がないほど忙[いそが]しかった。", "sentence_source": "generated"}, {"text": "子どもは退屈すると、すぐに騒ぎ出す。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "子[こ]どもは退屈[たいくつ]すると、すぐに騒[さわ]ぎ出[だ]す。", "sentence_source": "generated"}, {"text": "会議が退屈だったが、我慢して最後まで聞いた。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "会議[かいぎ]が退屈[たいくつ]だったが、我慢[がまん]して最後[さいご]まで聞[き]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "退屈する", "label": "動詞形"}, {"form": "退屈な", "label": "連体形"}, {"form": "退屈で", "label": "連用形"}, {"form": "退屈だった", "label": "過去形"}], "register": "中立（日常の話し言葉・書き言葉）", "sense_fingerprint": "つまらなくて面白くないと感じる気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc97b34b-9f79-4981-aac7-2a1064bb0242') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36496, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退屈", "is_correct": true, "explanation": "正解。「退屈でたまりません」は、一人で家にいるつまらなさの強い気持ちを表す。"}, {"text": "相談", "is_correct": false, "explanation": "「相談でたまりません」は意味が通らない。相談は人と話し合うことで、気持ちの強さを表す語ではない。"}, {"text": "規則", "is_correct": false, "explanation": "「規則でたまりません」は不自然。規則は守るべき決まりで、このような気持ちの状態には使えない。"}, {"text": "計画", "is_correct": false, "explanation": "「計画でたまりません」は意味が通らない。計画は前もって立てる予定で、気持ちを表す語ではない。"}], "explanations": {"退屈": "正解。「退屈でたまりません」は、一人で家にいるつまらなさの強い気持ちを表す。", "相談": "「相談でたまりません」は意味が通らない。相談は人と話し合うことで、気持ちの強さを表す語ではない。", "規則": "「規則でたまりません」は不自然。規則は守るべき決まりで、このような気持ちの状態には使えない。", "計画": "「計画でたまりません」は意味が通らない。計画は前もって立てる予定で、気持ちを表す語ではない。"}, "sentence_index": 0, "correct_answer": "退屈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物を運んだあとで、退屈で腕が上がらない。", "explanation": "ここは〈疲れて〉の意味。腕が上がらないほどの体の疲れは退屈では表せず、〈疲れ〉を使う場面。"}, {"text": "夜の山道は退屈で、足がすくんだ。", "explanation": "ここは〈怖くて〉の意味。足がすくむほどの恐怖は退屈では表せず、〈怖い〉を使う場面。"}, {"text": "試合に負けて、退屈で唇をかんだ。", "explanation": "ここは〈悔しい〉の意味。唇をかむほどの悔しさは退屈では表せず、〈悔しい〉を使う場面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36496, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退屈", "is_correct": true, "explanation": "正解。「退屈してしまった」は、同じ仕事の繰り返しに飽きてつまらなく感じたことを表す。"}, {"text": "義務", "is_correct": false, "explanation": "「義務してしまった」は成り立たない。義務は「果たす」ものであり、この気持ちを表す語ではない。"}, {"text": "節度", "is_correct": false, "explanation": "「節度してしまった」は成り立たない。節度は過不足のない慎みで、ここには入らない。"}, {"text": "郵便", "is_correct": false, "explanation": "「郵便してしまった」は成り立たない。郵便は手紙や荷物を送る仕組みで、感情を表す語ではない。"}], "explanations": {"退屈": "正解。「退屈してしまった」は、同じ仕事の繰り返しに飽きてつまらなく感じたことを表す。", "義務": "「義務してしまった」は成り立たない。義務は「果たす」ものであり、この気持ちを表す語ではない。", "節度": "「節度してしまった」は成り立たない。節度は過不足のない慎みで、ここには入らない。", "郵便": "「郵便してしまった」は成り立たない。郵便は手紙や荷物を送る仕組みで、感情を表す語ではない。"}, "sentence_index": 6, "correct_answer": "退屈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "映画のラストシーンで、退屈が込み上げて涙が止まらなかった。", "explanation": "ここは〈感動〉の意味。込み上げて涙があふれる気持ちは退屈では表せず、感動を表す語を使う場面。"}, {"text": "発表の前は、退屈で手が震えた。", "explanation": "ここは〈緊張〉の意味。手が震えるほどの張りつめた気持ちは退屈では表せず、合わない。"}, {"text": "昔の写真を見て、退屈で胸がいっぱいになった。", "explanation": "ここは〈懐かしさ〉の意味。過去を思い出す温かい感情を退屈では表せず、胸がいっぱいになる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36496, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休日は予定がなくて、退屈を仕方がない。", "corrected_sentence": "休日は予定がなくて、退屈で仕方がない。", "error_description": "誤りは「退屈を仕方がない」の「を」。正しくは「退屈で仕方がない」で、「で」は状態の程度を表す。「を」は目的語を取るので、この形では使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36496, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨で外出できず、家で退屈ていた。", "corrected_sentence": "雨で外出できず、家で退屈していた。", "error_description": "誤りは「退屈ていた」。正しくは「退屈していた」で、「退屈」に動詞「する」の連用形「し」を補う必要がある。「ていた」だけでは動詞として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
