INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36497, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "興味がわかず、時間が長く感じられること。", "primary_collocate": null, "pronunciation": "たいくつ", "ipa": "taikɯtsɯ", "syllable_count": 4, "sentences": [{"text": "退屈な待ち時間が長くて、時計ばかり見ていた。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "退屈[たいくつ]な待[ま]ち時間[じかん]が長[なが]くて、時計[とけい]ばかり見[み]ていた。", "sentence_source": "generated"}, {"text": "病院のベッドで退屈な毎日を過ごした。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "病院[びょういん]のベッドで退屈[たいくつ]な毎日[まいにち]を過[す]ごした。", "sentence_source": "generated"}, {"text": "何もすることがなく、退屈で時間がなかなか過ぎない。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "何[なに]もすることがなく、退屈[たいくつ]で時間[じかん]がなかなか過[す]ぎない。", "sentence_source": "generated"}, {"text": "駅で電車を待つ間、退屈でスマホを何度も見た。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "駅[えき]で電車[でんしゃ]を待[ま]つ間[あいだ]、退屈[たいくつ]でスマホを何度[なんど]も見[み]た。", "sentence_source": "generated"}, {"text": "退屈な講義が続き、一時間が三時間のように感じた。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "退屈[たいくつ]な講義[こうぎ]が続[つづ]き、一時間[いちじかん]が三時間[さんじかん]のように感[かん]じた。", "sentence_source": "generated"}, {"text": "友だちが来るまで退屈して、窓の外をぼんやり見ていた。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "友[とも]だちが来[く]るまで退屈[たいくつ]して、窓[まど]の外[そと]をぼんやり見[み]ていた。", "sentence_source": "generated"}, {"text": "休みの日に予定がなく、一日じゅう退屈だった。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]に予定[よてい]がなく、一日[いちにち]じゅう退屈[たいくつ]だった。", "sentence_source": "generated"}, {"text": "退屈な時間を減らすために、散歩を始めた。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "退屈[たいくつ]な時間[じかん]を減[へ]らすために、散歩[さんぽ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "長い飛行機の旅は退屈なので、本を三冊持っていく。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "長[なが]い飛行機[ひこうき]の旅[たび]は退屈[たいくつ]なので、本[ほん]を三冊[さんさつ]持[も]っていく。", "sentence_source": "generated"}, {"text": "兄は退屈になると、いつもギターを弾き始める。", "target_word": "退屈", "complexity_tier": "T3", "furigana": "兄[あに]は退屈[たいくつ]になると、いつもギターを弾[ひ]き始[はじ]める。", "sentence_source": "generated"}], "morphological_forms": [{"form": "退屈する", "label": "動詞形"}, {"form": "退屈な", "label": "連体形"}, {"form": "退屈で", "label": "連用形"}, {"form": "退屈だ", "label": "終止形"}], "register": "中立（日常の話し言葉・書き言葉）", "sense_fingerprint": "何もすることがなく、時間が長く感じられる状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc97b34b-9f79-4981-aac7-2a1064bb0242') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36497, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退屈", "is_correct": true, "explanation": "正解。「退屈な待ち時間」は、興味がわかず時間が長く感じられる待ち時間を表す。"}, {"text": "相談", "is_correct": false, "explanation": "「相談な待ち時間」は成り立たない。相談は人と話し合うことで、待ち時間の様子を表さない。"}, {"text": "規則", "is_correct": false, "explanation": "「規則な待ち時間」は意味が通らない。規則は決まりを指し、時間の感じ方を表す語ではない。"}, {"text": "注文", "is_correct": false, "explanation": "「注文な待ち時間」は成り立たない。注文は品物を頼むことで、待ち時間の様子を表す語ではない。"}], "explanations": {"退屈": "正解。「退屈な待ち時間」は、興味がわかず時間が長く感じられる待ち時間を表す。", "相談": "「相談な待ち時間」は成り立たない。相談は人と話し合うことで、待ち時間の様子を表さない。", "規則": "「規則な待ち時間」は意味が通らない。規則は決まりを指し、時間の感じ方を表す語ではない。", "注文": "「注文な待ち時間」は成り立たない。注文は品物を頼むことで、待ち時間の様子を表す語ではない。"}, "sentence_index": 0, "correct_answer": "退屈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "合格の知らせを聞いて、退屈で飛び上がった。", "explanation": "ここは〈喜んで〉の意味。飛び上がるほどの喜びは退屈では表せず、合わない。"}, {"text": "人前で褒められ、退屈で顔を伏せた。", "explanation": "ここは〈照れ〉の意味。褒められた恥ずかしさは退屈では表せず、顔を伏せる反応とは合わない。"}, {"text": "電車に乗り遅れそうで、退屈して駅を走った。", "explanation": "ここは〈焦って〉の意味。退屈では急いで走る切迫した気持ちを表せず、合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36497, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退屈", "is_correct": true, "explanation": "正解。「一日じゅう退屈だった」は、予定がなく一日がつまらなく長かったことを表す。"}, {"text": "郵便", "is_correct": false, "explanation": "「一日じゅう郵便だった」は成り立たない。郵便は手紙や荷物を送る仕組みで、一日の様子を表さない。"}, {"text": "節度", "is_correct": false, "explanation": "「一日じゅう節度だった」は意味が通らない。節度は慎みの程度を表し、一日の感じ方には使えない。"}, {"text": "文房具", "is_correct": false, "explanation": "「一日じゅう文房具だった」は成り立たない。文房具は筆記用具などの道具で、時間の感じ方を表さない。"}], "explanations": {"退屈": "正解。「一日じゅう退屈だった」は、予定がなく一日がつまらなく長かったことを表す。", "郵便": "「一日じゅう郵便だった」は成り立たない。郵便は手紙や荷物を送る仕組みで、一日の様子を表さない。", "節度": "「一日じゅう節度だった」は意味が通らない。節度は慎みの程度を表し、一日の感じ方には使えない。", "文房具": "「一日じゅう文房具だった」は成り立たない。文房具は筆記用具などの道具で、時間の感じ方を表さない。"}, "sentence_index": 6, "correct_answer": "退屈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "理不尽な扱いに、退屈がこみ上げた。", "explanation": "ここは〈怒り〉の意味。退屈は怒りの感情を表さず、理不尽な扱いへの反応には合わない。"}, {"text": "彼の見事な演奏に、退屈して拍手した。", "explanation": "ここは〈感心して〉の意味。退屈では相手をほめる気持ちを表せず、見事な演奏に拍手する場面と合わない。"}, {"text": "突然の知らせに退屈して、言葉が出なかった。", "explanation": "ここは〈驚いて〉の意味。退屈は驚きの心の動きを表さず、突然の知らせに言葉を失う場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36497, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "待ち時間が退屈だく、ずっとスマホを見ていた。", "corrected_sentence": "待ち時間が退屈で、ずっとスマホを見ていた。", "error_description": "誤りは「退屈だく」。正しくは連用形の「退屈で」で、後ろの「ずっとスマホを見ていた」へつなぐ。「だく」という活用形は存在しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36497, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "退屈の長い時間を、本を読んで過ごした。", "corrected_sentence": "退屈な長い時間を、本を読んで過ごした。", "error_description": "誤りは「退屈の長い時間」。「退屈」は形容動詞なので、名詞を修飾するには「な」を使う。「の」では続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36498, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「欠伸をした」の「する」の目的語を表す。"}, {"text": "に", "is_correct": false, "explanation": "「大きな欠伸にした」は成り立たない。「に」は結果や相手を表し、「する」の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「大きな欠伸へした」は成り立たない。「へ」は方向を表す語で、動作の対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「大きな欠伸のをした」は成り立たない。「の」は名詞どうしをつなぐ語で、「する」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「欠伸をした」の「する」の目的語を表す。", "に": "「大きな欠伸にした」は成り立たない。「に」は結果や相手を表し、「する」の目的語にはならない。", "へ": "「大きな欠伸へした」は成り立たない。「へ」は方向を表す語で、動作の対象にはならない。", "の": "「大きな欠伸のをした」は成り立たない。「の」は名詞どうしをつなぐ語で、「する」の目的語にはならない。"}, "error_tags": {"に": "結果・相手", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
