INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36498, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ねむいときに、くちを大きくあけることです。", "primary_collocate": null, "pronunciation": "あくび", "ipa": "akɯbi", "syllable_count": 3, "sentences": [{"text": "夜ふかしをしたので、朝から欠伸が止まらない。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "夜[よる]ふかしをしたので、朝[あさ]から欠伸[あくび]が止[と]まらない。", "sentence_source": "generated"}, {"text": "眠いのか、弟は大きな欠伸をした。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "眠[ねむ]いのか、弟[おとうと]は大[おお]きな欠伸[あくび]をした。", "sentence_source": "generated"}, {"text": "先生の前で欠伸が出そうになり、あわてて口を押さえた。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "先生[せんせい]の前[まえ]で欠伸[あくび]が出[で]そうになり、あわてて口[くち]を押[お]さえた。", "sentence_source": "generated"}, {"text": "昼ごはんを食べたあとは、よく欠伸が出る。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "昼[ひる]ごはんを食[た]べたあとは、よく欠伸[あくび]が出[で]る。", "sentence_source": "generated"}, {"text": "欠伸をすると、目に涙がたまった。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "欠伸[あくび]をすると、目[め]に涙[なみだ]がたまった。", "sentence_source": "generated"}, {"text": "電車の中で、前の人が欠伸をしていた。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で、前[まえ]の人[ひと]が欠伸[あくび]をしていた。", "sentence_source": "generated"}, {"text": "眠いときは、自然に欠伸が出るものだ。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "眠[ねむ]いときは、自然[しぜん]に欠伸[あくび]が出[で]るものだ。", "sentence_source": "generated"}, {"text": "赤ちゃんが小さな欠伸をして、すぐに眠った。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが小[ちい]さな欠伸[あくび]をして、すぐに眠[ねむ]った。", "sentence_source": "generated"}, {"text": "授業中に欠伸をしたら、先生に見られてしまった。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "授業中[じゅぎょうちゅう]に欠伸[あくび]をしたら、先生[せんせい]に見[み]られてしまった。", "sentence_source": "generated"}, {"text": "眠くて欠伸ばかり出て、勉強が進まない。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "眠[ねむ]くて欠伸[あくび]ばかり出[で]て、勉強[べんきょう]が進[すす]まない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "欠伸", "label": "基本形"}, {"form": "欠伸が出る", "label": "慣用的な言い方"}], "register": "中立（日常の話し言葉・書き言葉）", "sense_fingerprint": "眠いときに口を大きく開ける動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc97b34b-9f79-4981-aac7-2a1064bb0242') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36498, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欠伸", "is_correct": true, "explanation": "正解。「朝から欠伸が止まらない」は、夜ふかしによる眠気で何度も口を開けることを表す。"}, {"text": "宿題", "is_correct": false, "explanation": "「朝から宿題が止まらない」は成り立たない。宿題は課された課題で、止まる対象にはならない。"}, {"text": "切手", "is_correct": false, "explanation": "「切手が止まらない」は意味が通らない。切手は郵便に使う小さな紙片で、止まらないものではない。"}, {"text": "電池", "is_correct": false, "explanation": "「電池が止まらない」は不自然。電池は電気を供給する部品で、止まらない状態は表さない。"}], "explanations": {"欠伸": "正解。「朝から欠伸が止まらない」は、夜ふかしによる眠気で何度も口を開けることを表す。", "宿題": "「朝から宿題が止まらない」は成り立たない。宿題は課された課題で、止まる対象にはならない。", "切手": "「切手が止まらない」は意味が通らない。切手は郵便に使う小さな紙片で、止まらないものではない。", "電池": "「電池が止まらない」は不自然。電池は電気を供給する部品で、止まらない状態は表さない。"}, "sentence_index": 0, "correct_answer": "欠伸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ほこりを吸って、欠伸が何度も出た。", "explanation": "ここは〈くしゃみ〉の意味。ほこりを吸った反応は欠伸ではなくくしゃみで出るので、眠気による欠伸とは合わない。"}, {"text": "驚いて、欠伸が止まらなくなった。", "explanation": "ここは〈しゃっくり〉の意味。驚いた反応で止まらなくなるのは欠伸ではなくしゃっくりなので、合わない。"}, {"text": "話の内容に納得して、欠伸を深くうなずいた。", "explanation": "ここは〈うなずき〉の意味。欠伸は口を開けて息を吸う動作で、頭を縦に動かす「うなずく」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36498, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欠伸", "is_correct": true, "explanation": "正解。「自然に欠伸が出るものだ」は、眠いときに生理的に出る動作を表す。"}, {"text": "規則", "is_correct": false, "explanation": "「自然に規則が出る」は不自然。規則は決められた取り決めで、自然に生じるものではない。"}, {"text": "節度", "is_correct": false, "explanation": "「自然に節度が出る」は不自然。節度は慎みの程度で、生理的な現象を表さない。"}, {"text": "義務", "is_correct": false, "explanation": "「自然に義務が出る」は不自然。義務は果たすべき務めで、生理的に出るものではない。"}], "explanations": {"欠伸": "正解。「自然に欠伸が出るものだ」は、眠いときに生理的に出る動作を表す。", "規則": "「自然に規則が出る」は不自然。規則は決められた取り決めで、自然に生じるものではない。", "節度": "「自然に節度が出る」は不自然。節度は慎みの程度で、生理的な現象を表さない。", "義務": "「自然に義務が出る」は不自然。義務は果たすべき務めで、生理的に出るものではない。"}, "sentence_index": 6, "correct_answer": "欠伸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友人の冗談に、欠伸がこみ上げて笑いが止まらなかった。", "explanation": "ここは〈笑い〉の意味。冗談に込み上げる笑いは欠伸では表せず、合わない。"}, {"text": "赤ちゃんが欠伸をたてて眠っている。", "explanation": "寝息は眠っている間に立てる音だが、欠伸は「たてる」ものではないので、寝息の場面には合わない。"}, {"text": "会場から大きな欠伸が上がった。", "explanation": "ここは〈歓声〉の意味。歓声は声を上げるものだが、欠伸は声ではないので「上がる」とは言えず、合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36498, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "授業中、先生の話がつまらなくて欠伸を出そうになった。", "corrected_sentence": "授業中、先生の話がつまらなくて欠伸が出そうになった。", "error_description": "誤りは「欠伸を出そう」の「を」。正しくは「欠伸が出そうになった」で、「が」は「出る」の主語を示す。「を」は他動詞の目的語で、「出る」には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36498, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議の途中で欠伸が出ようになり、こっそり口を押さえた。", "corrected_sentence": "会議の途中で欠伸が出そうになり、こっそり口を押さえた。", "error_description": "誤りは「出ようになり」の「よう」。正しくは「出そうになり」で、「そう」は今にも出そうな気配を表す。「よう」は意志の形で、「なる」とは続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
