INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36499, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「欠伸をする」の「する」の目的語を表す。"}, {"text": "に", "is_correct": false, "explanation": "「欠伸にするときは」は成り立たない。「に」は結果や相手を表し、「する」の目的語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「欠伸でするときは」は成り立たない。「で」は手段や場所を表し、「する」の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「欠伸へするときは」は成り立たない。「へ」は方向を表す語で、動作の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「欠伸をする」の「する」の目的語を表す。", "に": "「欠伸にするときは」は成り立たない。「に」は結果や相手を表し、「する」の目的語にはならない。", "で": "「欠伸でするときは」は成り立たない。「で」は手段や場所を表し、「する」の対象にはならない。", "へ": "「欠伸へするときは」は成り立たない。「へ」は方向を表す語で、動作の対象にはならない。"}, "error_tags": {"に": "結果・相手", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36499, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "眠いときや退屈なときに、無意識に口を大きく開けて息を吸い込む動作。", "primary_collocate": null, "pronunciation": "あくび", "ipa": "akɯbi", "syllable_count": 3, "sentences": [{"text": "退屈な会議で、思わず欠伸が出てしまった。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "退屈[たいくつ]な会議[かいぎ]で、思[おも]わず欠伸[あくび]が出[で]てしまった。", "sentence_source": "generated"}, {"text": "欠伸は人にうつると言われている。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "欠伸[あくび]は人[ひと]にうつると言[い]われている。", "sentence_source": "generated"}, {"text": "彼は欠伸を噛み殺して、真面目な顔で話を聞いた。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "彼[かれ]は欠伸[あくび]を噛[か]み殺[ころ]して、真面目[まじめ]な顔[かお]で話[はなし]を聞[き]いた。", "sentence_source": "generated"}, {"text": "犬が気持ちよさそうに欠伸をして、床に寝転んだ。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "犬[いぬ]が気持[きも]ちよさそうに欠伸[あくび]をして、床[ゆか]に寝転[ねころ]んだ。", "sentence_source": "generated"}, {"text": "つまらない映画で、あちこちで欠伸をする人が見えた。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "つまらない映画[えいが]で、あちこちで欠伸[あくび]をする人[ひと]が見[み]えた。", "sentence_source": "generated"}, {"text": "眠くなくても、退屈だと欠伸が出ることがある。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "眠[ねむ]くなくても、退屈[たいくつ]だと欠伸[あくび]が出[で]ることがある。", "sentence_source": "generated"}, {"text": "長い説明のあいだ、何度も欠伸を我慢した。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "長[なが]い説明[せつめい]のあいだ、何度[なんど]も欠伸[あくび]を我慢[がまん]した。", "sentence_source": "generated"}, {"text": "欠伸をするときは、手で口をかくすのがマナーだ。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "欠伸[あくび]をするときは、手[て]で口[くち]をかくすのがマナーだ。", "sentence_source": "generated"}, {"text": "猫が大きな欠伸をして、のびをした。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "猫[ねこ]が大[おお]きな欠伸[あくび]をして、のびをした。", "sentence_source": "generated"}, {"text": "欠伸のあとで、急に眠気が強くなった。", "target_word": "欠伸", "complexity_tier": "T3", "furigana": "欠伸[あくび]のあとで、急[きゅう]に眠気[ねむけ]が強[つよ]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "欠伸", "label": "基本形"}, {"form": "欠伸をする", "label": "慣用的な言い方"}], "register": "中立（日常の話し言葉・書き言葉）", "sense_fingerprint": "眠気や退屈で無意識に口を開けて息を吸う動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc97b34b-9f79-4981-aac7-2a1064bb0242') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36499, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欠伸", "is_correct": true, "explanation": "正解。「思わず欠伸が出てしまった」は、退屈な会議中に無意識に口が開いたことを表す。"}, {"text": "規則", "is_correct": false, "explanation": "「思わず規則が出てしまった」は成り立たない。規則は決まりで、思わず出るものではない。"}, {"text": "切手", "is_correct": false, "explanation": "「思わず切手が出てしまった」は不自然。切手は郵便に使う紙片で、体の反応を表さない。"}, {"text": "郵便", "is_correct": false, "explanation": "「思わず郵便が出てしまった」は意味が通らない。郵便は手紙や荷物を送る仕組みで、体の反応を表さない。"}], "explanations": {"欠伸": "正解。「思わず欠伸が出てしまった」は、退屈な会議中に無意識に口が開いたことを表す。", "規則": "「思わず規則が出てしまった」は成り立たない。規則は決まりで、思わず出るものではない。", "切手": "「思わず切手が出てしまった」は不自然。切手は郵便に使う紙片で、体の反応を表さない。", "郵便": "「思わず郵便が出てしまった」は意味が通らない。郵便は手紙や荷物を送る仕組みで、体の反応を表さない。"}, "sentence_index": 0, "correct_answer": "欠伸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花粉で鼻がむずむずして、欠伸が止まらなかった。", "explanation": "ここは〈くしゃみ〉の意味。花粉で鼻がむずむずしたときに出るのは欠伸ではなくくしゃみなので、合わない。"}, {"text": "誰にも聞こえない声で、欠伸をつぶやいた。", "explanation": "ここは〈つぶやき〉の意味。欠伸は言葉として口にするものではないので、「つぶやく」とは合わない。"}, {"text": "眠っている猫は、欠伸をたてて鳴いている。", "explanation": "欠伸は音を「たてる」ものではないので、鳴き声の場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36499, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欠伸", "is_correct": true, "explanation": "正解。「何度も欠伸を我慢した」は、長い説明の間に口を開きそうになるのを抑えたことを表す。"}, {"text": "電池", "is_correct": false, "explanation": "「電池を我慢した」は意味が通らない。電池は電気を供給する部品で、我慢する対象にはならない。"}, {"text": "文房具", "is_correct": false, "explanation": "「文房具を我慢した」は成り立たない。文房具は筆記用具などの道具で、我慢の対象にはならない。"}, {"text": "封筒", "is_correct": false, "explanation": "「封筒を我慢した」は意味が通らない。封筒は手紙を入れる袋で、我慢する対象ではない。"}], "explanations": {"欠伸": "正解。「何度も欠伸を我慢した」は、長い説明の間に口を開きそうになるのを抑えたことを表す。", "電池": "「電池を我慢した」は意味が通らない。電池は電気を供給する部品で、我慢する対象にはならない。", "文房具": "「文房具を我慢した」は成り立たない。文房具は筆記用具などの道具で、我慢の対象にはならない。", "封筒": "「封筒を我慢した」は意味が通らない。封筒は手紙を入れる袋で、我慢する対象ではない。"}, "sentence_index": 6, "correct_answer": "欠伸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "突然のけがに、思わず欠伸を上げた。", "explanation": "ここは〈叫び声〉の意味。欠伸は声を上げる動作ではなく、口を開いて息を吸うものなので「上げる」とは言えず、合わない。"}, {"text": "観客の欠伸が球場に響いた。", "explanation": "ここは〈歓声〉の意味。歓声は大きな声で球場に響くものだが、欠伸は喜びの声ではないので合わない。"}, {"text": "寝ている間に欠伸を言った。", "explanation": "ここは〈寝言〉の意味。寝言は寝ている間に口にする言葉だが、欠伸は言葉ではないので「言う」の目的語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36499, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "授業中、欠伸を止まらなくて困った。", "corrected_sentence": "授業中、欠伸が止まらなくて困った。", "error_description": "誤りは「欠伸を止まらなくて」の「を」。正しくは「欠伸が止まらなくて」で、「止まる」は自動詞なので「が」で主語を示す。「を」は目的語を表すので合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36499, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "講義の途中で、欠伸を噛み殺さった。", "corrected_sentence": "講義の途中で、欠伸を噛み殺した。", "error_description": "誤りは「噛み殺さった」。正しくは過去形の「噛み殺した」で、「殺す」の過去形は「殺した」である。「さった」は活用として誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36500, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「喉を見せる」で、喉が「見せる」の目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「見せて」は他動詞なので、目的語に「が」は使えない。"}, {"text": "と", "is_correct": false, "explanation": "「喉と見せて」では文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「喉へ見せて」では目的語を表せない。"}], "correct_answer": "を", "explanations": {"を": "「喉を見せる」で、喉が「見せる」の目的語になる。", "が": "「見せて」は他動詞なので、目的語に「が」は使えない。", "と": "「喉と見せて」では文として成り立たない。", "へ": "「喉へ見せて」では目的語を表せない。"}, "error_tags": {"が": "subject_object_confusion", "と": "wrong_relation", "へ": "direction"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36500, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「喉に何かがつまる」で、つまる場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "「つまる」は自動詞なので、「喉を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「喉と何かがつまったら」では文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「喉から何かがつまったら」では、つまる場所を表せず文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「喉に何かがつまる」で、つまる場所を表す。", "を": "「つまる」は自動詞なので、「喉を」は合わない。", "と": "「喉と何かがつまったら」では文として成り立たない。", "から": "「喉から何かがつまったら」では、つまる場所を表せず文として成り立たない。"}, "error_tags": {"を": "transitive_confusion", "と": "wrong_relation", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36500, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "のどは、くびのまえのほうにある、たべものやいきがとおるところです。", "primary_collocate": null, "pronunciation": "のど", "ipa": "nodo", "syllable_count": 2, "sentences": [{"text": "喉を見せて。", "target_word": "喉", "complexity_tier": "T1", "furigana": "喉[のど]を見[み]せて。", "sentence_source": "generated"}, {"text": "喉がかゆい。", "target_word": "喉", "complexity_tier": "T1", "furigana": "喉[のど]がかゆい。", "sentence_source": "generated"}, {"text": "喉の薬を買いました。", "target_word": "喉", "complexity_tier": "T2", "furigana": "喉[のど]の薬[くすり]を買[か]いました。", "sentence_source": "generated"}, {"text": "水を飲むと、喉が楽になります。", "target_word": "喉", "complexity_tier": "T2", "furigana": "水[みず]を飲[の]むと、喉[のど]が楽[らく]になります。", "sentence_source": "generated"}, {"text": "食べ物は口から喉を通って胃に行く。", "target_word": "喉", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]は口[くち]から喉[のど]を通[とお]って胃[い]に行[い]く。", "sentence_source": "generated"}, {"text": "空気は鼻と喉を通って肺に入る。", "target_word": "喉", "complexity_tier": "T3", "furigana": "空気[くうき]は鼻[はな]と喉[のど]を通[とお]って肺[はい]に入[はい]る。", "sentence_source": "generated"}, {"text": "話しすぎて、喉が痛くなった。", "target_word": "喉", "complexity_tier": "T3", "furigana": "話[はな]しすぎて、喉[のど]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "喉に何かがつまったら、すぐに背中をたたいてあげてください。", "target_word": "喉", "complexity_tier": "T4", "furigana": "喉[のど]に何[なに]かがつまったら、すぐに背中[せなか]をたたいてあげてください。", "sentence_source": "generated"}, {"text": "首の前にある喉は、声を出すときにも使われる。", "target_word": "喉", "complexity_tier": "T4", "furigana": "首[くび]の前[まえ]にある喉[のど]は、声[こえ]を出[だ]すときにも使[つか]われる。", "sentence_source": "generated"}, {"text": "冬は空気が乾燥するので、喉を守るためにマスクをつける人が多い。", "target_word": "喉", "complexity_tier": "T5", "furigana": "冬[ふゆ]は空気[くうき]が乾燥[かんそう]するので、喉[のど]を守[まも]るためにマスクをつける人[ひと]が多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喉元", "label": "派生"}, {"form": "喉笛", "label": "派生"}, {"form": "喉仏", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 首の前の食べ物と息の通り道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36500, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喉", "is_correct": true, "explanation": "見出し語そのものの「のど」です。"}, {"text": "窓", "is_correct": false, "explanation": "「まど」は「の」が「ま」に変わる一拍違いの別の語です。"}, {"text": "角", "is_correct": false, "explanation": "「かど」は「の」が「か」に変わる一拍違いの別の語です。"}, {"text": "糊", "is_correct": false, "explanation": "「のり」は「ど」が「り」に変わる一拍違いの別の語です。"}, {"text": "蚤", "is_correct": false, "explanation": "「のみ」は「ど」が「み」に変わる一拍違いの別の語です。"}], "explanations": {"喉": "見出し語そのものの「のど」です。", "窓": "「まど」は「の」が「ま」に変わる一拍違いの別の語です。", "角": "「かど」は「の」が「か」に変わる一拍違いの別の語です。", "糊": "「のり」は「ど」が「り」に変わる一拍違いの別の語です。", "蚤": "「のみ」は「ど」が「み」に変わる一拍違いの別の語です。"}, "sentence_index": null, "correct_answer": "喉"}, "level_3": {"options": [{"text": "喉", "is_correct": true, "explanation": "医者などが体の部分を見せてと言う場面で意味が合います。"}, {"text": "暑さ", "is_correct": false, "explanation": "形は合うが、暑さは見せるものではなく意味が合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "形は合うが、眠気を見せてとは言わず意味が合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが、空腹を見せてとは言わず意味が合わない。"}], "explanations": {"喉": "医者などが体の部分を見せてと言う場面で意味が合います。", "暑さ": "形は合うが、暑さは見せるものではなく意味が合わない。", "眠気": "形は合うが、眠気を見せてとは言わず意味が合わない。", "空腹": "形は合うが、空腹を見せてとは言わず意味が合わない。"}, "sentence_index": 0, "correct_answer": "喉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "喉に帽子をかぶって学校へ行った。", "explanation": "喉は首の前の部分で、帽子をかぶる場所ではない。"}, {"text": "喉を使って重い荷物をつかんだ。", "explanation": "喉は物をつかむ部分ではないので、使い方が合わない。"}, {"text": "喉の中でボールを蹴って遊んだ。", "explanation": "喉は体の中の細い通り道で、ボールを蹴る場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36500, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "喉", "is_correct": true, "explanation": "見出し語そのものの「のど」です。"}, {"text": "程", "is_correct": false, "explanation": "「ほど」は「の」が「ほ」に変わる一拍違いの別の語です。"}, {"text": "脳", "is_correct": false, "explanation": "「のう」は「ど」が「う」に変わる一拍違いの別の語です。"}, {"text": "伸び", "is_correct": false, "explanation": "「のび」は「ど」が「び」に変わる一拍違いの別の語です。"}, {"text": "トド", "is_correct": false, "explanation": "「とど」は「の」が「と」に変わる一拍違いの別の語です。"}], "explanations": {"喉": "見出し語そのものの「のど」です。", "程": "「ほど」は「の」が「ほ」に変わる一拍違いの別の語です。", "脳": "「のう」は「ど」が「う」に変わる一拍違いの別の語です。", "伸び": "「のび」は「ど」が「び」に変わる一拍違いの別の語です。", "トド": "「とど」は「の」が「と」に変わる一拍違いの別の語です。"}, "sentence_index": null, "correct_answer": "喉"}, "level_3": {"options": [{"text": "喉", "is_correct": true, "explanation": "話しすぎて痛くなるのは喉なので意味が合います。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、話しすぎて机が痛くなるとは言えず意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、話しすぎて靴が痛くなるとは言えず意味が合わない。"}, {"text": "窓", "is_correct": false, "explanation": "形は合うが、話しすぎて窓が痛くなるとは言えず意味が合わない。"}], "explanations": {"喉": "話しすぎて痛くなるのは喉なので意味が合います。", "机": "形は合うが、話しすぎて机が痛くなるとは言えず意味が合わない。", "靴": "形は合うが、話しすぎて靴が痛くなるとは言えず意味が合わない。", "窓": "形は合うが、話しすぎて窓が痛くなるとは言えず意味が合わない。"}, "sentence_index": 6, "correct_answer": "喉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "喉でごはんをかんで食べた。", "explanation": "食べ物をかむのは口と歯で、喉はかむ場所ではない。"}, {"text": "喉に靴下をはいて寝た。", "explanation": "靴下をはくのは足で、喉に使うのは合わない。"}, {"text": "喉の窓から外を見た。", "explanation": "喉は体の部分で、窓のように外を見る場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36500, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喉をかゆいので、薬を飲んだ。", "corrected_sentence": "喉がかゆいので、薬を飲んだ。", "error_description": "「かゆい」の主語は「喉が」で、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
