INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36501, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「喉を潤す」で、喉が「潤す」の目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「潤し」は他動詞なので、「喉が潤し」は文法的に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「喉へ潤し」では目的語を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「喉から潤し」では「潤す」の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「喉を潤す」で、喉が「潤す」の目的語になる。", "が": "「潤し」は他動詞なので、「喉が潤し」は文法的に合わない。", "へ": "「喉へ潤し」では目的語を表せない。", "から": "「喉から潤し」では「潤す」の対象にならない。"}, "error_tags": {"が": "subject_object_confusion", "へ": "direction", "から": "source"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
