INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36501, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べ物や飲み物が通る、口から胃への管の部分。また、空気の通り道でもある。", "primary_collocate": null, "pronunciation": "のど", "ipa": "nodo", "syllable_count": 2, "sentences": [{"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "喉", "complexity_tier": "T6", "furigana": "冷[つめ]たくて甘[あま]いレモネードは、暑[あつ]さに疲[つか]れた人々[ひとびと]の喉[のど]を潤[うるお]し、少年[しょうねん]の努力[どりょく]は小[ちい]さな売上[うりあげ]となって確実[かくじつ]に実[み]を結[むす]んでいった。", "sentence_source": "mined"}, {"text": "喉が痛い。", "target_word": "喉", "complexity_tier": "T1", "furigana": "喉[のど]が痛[いた]い。", "sentence_source": "generated"}, {"text": "喉が渇いた。", "target_word": "喉", "complexity_tier": "T1", "furigana": "喉[のど]が渇[かわ]いた。", "sentence_source": "generated"}, {"text": "喉が渇いたので、水を飲みます。", "target_word": "喉", "complexity_tier": "T2", "furigana": "喉[のど]が渇[かわ]いたので、水[みず]を飲[の]みます。", "sentence_source": "generated"}, {"text": "喉に魚の骨が刺さりました。", "target_word": "喉", "complexity_tier": "T2", "furigana": "喉[のど]に魚[さかな]の骨[ほね]が刺[ささ]りました。", "sentence_source": "generated"}, {"text": "風邪をひいて、喉が腫れている。", "target_word": "喉", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいて、喉[のど]が腫[は]れている。", "sentence_source": "generated"}, {"text": "冷たいお茶が喉を通る。", "target_word": "喉", "complexity_tier": "T3", "furigana": "冷[つめ]たいお茶[ちゃ]が喉[のど]を通[とお]る。", "sentence_source": "generated"}, {"text": "大きな声で歌いすぎて、喉を痛めてしまった。", "target_word": "喉", "complexity_tier": "T3", "furigana": "大[おお]きな声[こえ]で歌[うた]いすぎて、喉[のど]を痛[いた]めてしまった。", "sentence_source": "generated"}, {"text": "喉の調子が悪い時は、温かい飲み物を飲むといい。", "target_word": "喉", "complexity_tier": "T4", "furigana": "喉[のど]の調子[ちょうし]が悪[わる]い時[とき]は、温[あたた]かい飲[の]み物[もの]を飲[の]むといい。", "sentence_source": "generated"}, {"text": "医者は私の喉を診て、薬を出すから三日間飲むようにと言った。", "target_word": "喉", "complexity_tier": "T5", "furigana": "医者[いしゃ]は私[わたし]の喉[のど]を診[み]て、薬[くすり]を出[だ]すから三日間[みっかかん]飲[の]むようにと言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喉元", "label": "派生"}, {"form": "喉笛", "label": "派生"}, {"form": "喉仏", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 口から胃への管、空気の通り道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
