INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36502, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "開く", "is_correct": true, "explanation": "ひらく。聞かれた語そのもの。"}, {"text": "比較", "is_correct": false, "explanation": "ひかく。「ら」が「か」に変わる一音違い。"}, {"text": "気楽", "is_correct": false, "explanation": "きらく。「ひ」が「き」に変わる一音違い。"}, {"text": "卑俗", "is_correct": false, "explanation": "ひぞく。「ら」が「ぞ」に変わる一音違い。"}, {"text": "飛躍", "is_correct": false, "explanation": "ひやく。「ら」が「や」に変わる一音違い。"}], "explanations": {"開く": "ひらく。聞かれた語そのもの。", "比較": "ひかく。「ら」が「か」に変わる一音違い。", "気楽": "きらく。「ひ」が「き」に変わる一音違い。", "卑俗": "ひぞく。「ら」が「ぞ」に変わる一音違い。", "飛躍": "ひやく。「ら」が「や」に変わる一音違い。"}, "sentence_index": null, "correct_answer": "開く"}, "level_3": {"options": [{"text": "開いて", "is_correct": true, "explanation": "口を開いて笑う、という自然な動作。"}, {"text": "洗って", "is_correct": false, "explanation": "形は合うが意味が合わない。口を洗いながら笑うのは文脈に合わない。"}, {"text": "縫って", "is_correct": false, "explanation": "形は合うが意味が合わない。口を縫って笑うことはできない。"}, {"text": "数えて", "is_correct": false, "explanation": "形は合うが意味が合わない。口を数える動作は笑う文脈に合わない。"}], "explanations": {"開いて": "口を開いて笑う、という自然な動作。", "洗って": "形は合うが意味が合わない。口を洗いながら笑うのは文脈に合わない。", "縫って": "形は合うが意味が合わない。口を縫って笑うことはできない。", "数えて": "形は合うが意味が合わない。口を数える動作は笑う文脈に合わない。"}, "sentence_index": 0, "correct_answer": "開いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物がゆっくり開く。", "explanation": "荷物自体は戸のように開閉しない。「開く」の主語として不自然。"}, {"text": "重い石がゆっくり開く。", "explanation": "石は開閉するものではなく、「開く」は合わない。"}, {"text": "重い声がゆっくり開く。", "explanation": "声は「開く」対象ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
