INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36503, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "受身で、開いた人を示す。"}, {"text": "を", "is_correct": false, "explanation": "「だれかを開かれた」とは言えない。"}, {"text": "で", "is_correct": false, "explanation": "「だれかで開かれた」では開いた人を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「だれかが開かれた」では人が開かれたことになり、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "受身で、開いた人を示す。", "を": "「だれかを開かれた」とは言えない。", "で": "「だれかで開かれた」では開いた人を表せない。", "が": "「だれかが開かれた」では人が開かれたことになり、意味が通らない。"}, "error_tags": {"を": "object", "で": "means", "が": "subject"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閉じる", "is_correct": true, "explanation": "地図が開くの反対は、地図が閉じる。"}, {"text": "傾く", "is_correct": false, "explanation": "反対の意味ではない。"}, {"text": "揺れる", "is_correct": false, "explanation": "反対の意味ではない。"}, {"text": "笑う", "is_correct": false, "explanation": "反対の意味ではない。"}], "correct_answer": "閉じる", "explanations": {"閉じる": "地図が開くの反対は、地図が閉じる。", "傾く": "反対の意味ではない。", "揺れる": "反対の意味ではない。", "笑う": "反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36503, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "閉じていたものを、外側や内側へ動かして、間を作ること。", "primary_collocate": null, "pronunciation": "ひらく", "ipa": "çiɾaku", "syllable_count": 3, "sentences": [{"text": "結果として、建築は静的な物体ではなく、見る者によって絶えず意味が更新される開かれた場として再定義されるのです。", "target_word": "開かれた", "complexity_tier": "T6", "furigana": "結果[けっか]として、建築[けんちく]は静的[せいてき]な物体[ぶったい]ではなく、見[み]る者[もの]によって絶[た]えず意味[いみ]が更新[こうしん]される開[ひら]かれた場[ば]として再定義[さいていぎ]されるのです。", "sentence_source": "mined"}, {"text": "本を開くと、古い写真が出てきた。", "target_word": "開く", "complexity_tier": "T3", "furigana": "本[ほん]を開[ひら]くと、古[ふる]い写真[しゃしん]が出[で]てきた。", "sentence_source": "generated"}, {"text": "朝、花が開きます。", "target_word": "開きます", "complexity_tier": "T2", "furigana": "朝[あさ]、花[はな]が開[ひら]きます。", "sentence_source": "generated"}, {"text": "傘を開いて、雨の中を歩いた。", "target_word": "開いて", "complexity_tier": "T3", "furigana": "傘[かさ]を開[ひら]いて、雨[あめ]の中[なか]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "この扇子はかたくて開かない。", "target_word": "開かない", "complexity_tier": "T3", "furigana": "この扇子[せんす]はかたくて開[ひら]かない。", "sentence_source": "generated"}, {"text": "彼女は手のひらをそっと開いた。", "target_word": "開いた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は手[て]のひらをそっと開[ひら]いた。", "sentence_source": "generated"}, {"text": "机の上の本が開いている。", "target_word": "開いている", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]の本[ほん]が開[ひら]いている。", "sentence_source": "generated"}, {"text": "その手紙には、だれかに開かれた跡があった。", "target_word": "開かれた", "complexity_tier": "T4", "furigana": "その手紙[てがみ]には、だれかに開[ひら]かれた跡[あと]があった。", "sentence_source": "generated"}, {"text": "手紙を開く前に、深く息を吸った。", "target_word": "開く", "complexity_tier": "T4", "furigana": "手紙[てがみ]を開[ひら]く前[まえ]に、深[ふか]く息[いき]を吸[す]った。", "sentence_source": "generated"}, {"text": "風で、たたんだ地図が開いてしまった。", "target_word": "開いて", "complexity_tier": "T3", "furigana": "風[かぜ]で、たたんだ地図[ちず]が開[ひら]いてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "開かれる", "label": "活用"}, {"form": "開いて", "label": "活用"}, {"form": "開き", "label": "活用"}, {"form": "開かない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 閉じた物を動かして間を作る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36503, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "開く", "is_correct": true, "explanation": "ひらく。聞かれた語そのもの。"}, {"text": "比較", "is_correct": false, "explanation": "ひかく。「ら」が「か」に変わる一音違い。"}, {"text": "気楽", "is_correct": false, "explanation": "きらく。「ひ」が「き」に変わる一音違い。"}, {"text": "卑俗", "is_correct": false, "explanation": "ひぞく。「ら」が「ぞ」に変わる一音違い。"}, {"text": "飛躍", "is_correct": false, "explanation": "ひやく。「ら」が「や」に変わる一音違い。"}], "explanations": {"開く": "ひらく。聞かれた語そのもの。", "比較": "ひかく。「ら」が「か」に変わる一音違い。", "気楽": "きらく。「ひ」が「き」に変わる一音違い。", "卑俗": "ひぞく。「ら」が「ぞ」に変わる一音違い。", "飛躍": "ひやく。「ら」が「や」に変わる一音違い。"}, "sentence_index": null, "correct_answer": "開く"}, "level_3": {"options": [{"text": "開かれた", "is_correct": true, "explanation": "「開かれた場」で、誰にでも意味づけが開かれた場所という意味になり、文脈に合う。"}, {"text": "閉ざされた", "is_correct": false, "explanation": "形は合うが意味が合わない。意味が絶えず更新される場とは矛盾する。"}, {"text": "隔てられた", "is_correct": false, "explanation": "形は合うが意味が合わない。再定義される場の説明にならない。"}, {"text": "忘れられた", "is_correct": false, "explanation": "形は合うが意味が合わない。意味が更新され続ける場とは合わない。"}], "explanations": {"開かれた": "「開かれた場」で、誰にでも意味づけが開かれた場所という意味になり、文脈に合う。", "閉ざされた": "形は合うが意味が合わない。意味が絶えず更新される場とは矛盾する。", "隔てられた": "形は合うが意味が合わない。再定義される場の説明にならない。", "忘れられた": "形は合うが意味が合わない。意味が更新され続ける場とは合わない。"}, "sentence_index": 0, "correct_answer": "開かれた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電気を開いて、部屋を明るくした。", "explanation": "電気をつける意味で「開く」は使えない。「つける」が正しい。"}, {"text": "ご飯を開いて、おいしく食べた。", "explanation": "ご飯は閉じたものを広げる対象ではないので、「開く」は合わない。"}, {"text": "雨を開いて、外へ出かけた。", "explanation": "雨は「開く」対象にならない。傘なら開けるが、雨自体は開けない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36503, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "開く", "is_correct": true, "explanation": "ひらく。聞かれた語そのもの。"}, {"text": "秘策", "is_correct": false, "explanation": "ひさく。「ら」が「さ」に変わる一音違い。"}, {"text": "被爆", "is_correct": false, "explanation": "ひばく。「ら」が「ば」に変わる一音違い。"}, {"text": "被膜", "is_correct": false, "explanation": "ひまく。「ら」が「ま」に変わる一音違い。"}, {"text": "皮肉", "is_correct": false, "explanation": "ひにく。「ら」が「に」に変わる一音違い。"}], "explanations": {"開く": "ひらく。聞かれた語そのもの。", "秘策": "ひさく。「ら」が「さ」に変わる一音違い。", "被爆": "ひばく。「ら」が「ば」に変わる一音違い。", "被膜": "ひまく。「ら」が「ま」に変わる一音違い。", "皮肉": "ひにく。「ら」が「に」に変わる一音違い。"}, "sentence_index": null, "correct_answer": "開く"}, "level_3": {"options": [{"text": "開いている", "is_correct": true, "explanation": "本が広げられた状態を表す。"}, {"text": "眠っている", "is_correct": false, "explanation": "形は合うが意味が合わない。本は眠らない。"}, {"text": "泳いでいる", "is_correct": false, "explanation": "形は合うが意味が合わない。本は泳がない。"}, {"text": "歌っている", "is_correct": false, "explanation": "形は合うが意味が合わない。本は歌わない。"}], "explanations": {"開いている": "本が広げられた状態を表す。", "眠っている": "形は合うが意味が合わない。本は眠らない。", "泳いでいる": "形は合うが意味が合わない。本は泳がない。", "歌っている": "形は合うが意味が合わない。本は歌わない。"}, "sentence_index": 6, "correct_answer": "開いている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風で石が開いてしまった。", "explanation": "石は閉じたものではなく、「開く」の主語にならない。"}, {"text": "風でボールが開いてしまった。", "explanation": "ボールには開閉する部分がなく、「開く」は合わない。"}, {"text": "風で砂が開いてしまった。", "explanation": "砂は「開く」ものではない。「飛ぶ」などが自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36503, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は手紙に開いて、中を読んだ。", "corrected_sentence": "彼は手紙を開いて、中を読んだ。", "error_description": "「開く」の対象を示す助詞は「に」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "開く", "is_correct": true, "explanation": "「と」に続く終止形で、条件を表せる。"}, {"text": "開いて", "is_correct": false, "explanation": "て形に「と」は続かない。"}, {"text": "開き", "is_correct": false, "explanation": "連用形に「と」は続かない。"}, {"text": "開いた", "is_correct": false, "explanation": "「開いたと」では、ここの「本を開くと」の条件の意味にならない。"}], "correct_form": "開く", "base_form": "開く", "form_label": "終止形", "sentence_index": 1, "explanations": {"開く": "「と」に続く終止形で、条件を表せる。", "開いて": "て形に「と」は続かない。", "開き": "連用形に「と」は続かない。", "開いた": "「開いたと」では、ここの「本を開くと」の条件の意味にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36503, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "日記は妹を開かれてしまった。", "corrected_sentence": "日記は妹に開かれてしまった。", "error_description": "受身で開いた人を示すのは「を」ではなく「に」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "開かれた", "is_correct": true, "explanation": "「だれかに開かれた跡」という受身の連体形。"}, {"text": "開いて", "is_correct": false, "explanation": "て形は名詞「跡」に直接つながらない。"}, {"text": "開き", "is_correct": false, "explanation": "連用形は名詞「跡」に直接つながらない。"}, {"text": "開こう", "is_correct": false, "explanation": "意志形は名詞に続かない。"}], "correct_form": "開かれた", "base_form": "開く", "form_label": "受身の過去連体形", "sentence_index": 7, "explanations": {"開かれた": "「だれかに開かれた跡」という受身の連体形。", "開いて": "て形は名詞「跡」に直接つながらない。", "開き": "連用形は名詞「跡」に直接つながらない。", "開こう": "意志形は名詞に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36506, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「寝る」は寝る場所を「に」で示す。「芝生に寝て」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「寝る」は目的語を取らないので、「芝生を寝て」は不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、寝る場所を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、横になる場所には合わない。"}], "correct_answer": "に", "explanations": {"に": "「寝る」は寝る場所を「に」で示す。「芝生に寝て」の形になる。", "を": "「寝る」は目的語を取らないので、「芝生を寝て」は不自然になる。", "と": "「と」は並列や相手を示し、寝る場所を表せない。", "から": "「から」は起点を示すので、横になる場所には合わない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起きる", "is_correct": true, "explanation": "寝る（横になって休む）の対義語。体を起こす動作で、横になることと反対の関係にある。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の動作で、寝るとは対になる関係ではない。"}, {"text": "食べる", "is_correct": false, "explanation": "飲食の動作で、寝るとは対義の関係にない。"}, {"text": "読む", "is_correct": false, "explanation": "読書の動作で、横になる動作とは対義の関係にない。"}], "correct_answer": "起きる", "explanations": {"起きる": "寝る（横になって休む）の対義語。体を起こす動作で、横になることと反対の関係にある。", "歩く": "移動の動作で、寝るとは対になる関係ではない。", "食べる": "飲食の動作で、寝るとは対義の関係にない。", "読む": "読書の動作で、横になる動作とは対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36506, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「寝る」は寝る場所を「に」で示す。「席に寝て」の形になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「席が寝て」では場所を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示し、場所には使えない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、動詞「寝て」の前に置くと場所を示せない。"}], "correct_answer": "に", "explanations": {"に": "「寝る」は寝る場所を「に」で示す。「席に寝て」の形になる。", "が": "「が」は主語を示すので、「席が寝て」では場所を表せない。", "より": "「より」は比較の基準を示し、場所には使えない。", "の": "「の」は名詞をつなぐ助詞で、動詞「寝て」の前に置くと場所を示せない。"}, "error_tags": {"が": "主語", "より": "比較の基準", "の": "名詞つなぎ"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起きる", "is_correct": true, "explanation": "寝る（横になって休む）の対義語。体を起こす動作で、横になることと反対の関係にある。"}, {"text": "走る", "is_correct": false, "explanation": "運動の動作で、寝るとは対義の関係にない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "運動の動作で、寝るとは対義の関係にない。"}, {"text": "話す", "is_correct": false, "explanation": "会話の動作で、横になることとは対義の関係にない。"}], "correct_answer": "起きる", "explanations": {"起きる": "寝る（横になって休む）の対義語。体を起こす動作で、横になることと反対の関係にある。", "走る": "運動の動作で、寝るとは対義の関係にない。", "泳ぐ": "運動の動作で、寝るとは対義の関係にない。", "話す": "会話の動作で、横になることとは対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36506, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "からだをよこにして、めをとじて、やすむこと。", "primary_collocate": null, "pronunciation": "ねる", "ipa": "neɾɯ", "syllable_count": 2, "sentences": [{"text": "疲れたので、ソファに寝て少し目を閉じた。", "target_word": "寝て", "complexity_tier": "T2", "furigana": "疲(つか)れたので、ソファに寝(ね)て少(すこ)し目(め)を閉(と)じた。", "sentence_source": "generated"}, {"text": "公園の芝生に寝て、流れる雲をながめた。", "target_word": "寝て", "complexity_tier": "T3", "furigana": "公園(こうえん)の芝生(しばふ)に寝(ね)て、流(なが)れる雲(くも)をながめた。", "sentence_source": "generated"}, {"text": "風邪をひいたときは、無理をしないで布団に寝て休むのがいちばんだ。", "target_word": "寝て", "complexity_tier": "T3", "furigana": "風邪(かぜ)をひいたときは、無理(むり)をしないで布団(ふとん)に寝(ね)て休(やす)むのがいちばんだ。", "sentence_source": "generated"}, {"text": "電車の中で立ち続けた父は、家に着くと畳の上に寝て背中をのばした。", "target_word": "寝て", "complexity_tier": "T4", "furigana": "電車(でんしゃ)の中(なか)で立(た)ち続(つづ)けた父(ちち)は、家(いえ)に着(つ)くと畳(たたみ)の上(うえ)に寝(ね)て背中(せなか)をのばした。", "sentence_source": "generated"}, {"text": "腰が痛いので、かたい床に寝て腰を休めた。", "target_word": "寝て", "complexity_tier": "T3", "furigana": "腰(こし)が痛(いた)いので、かたい床(ゆか)に寝(ね)て腰(こし)を休(やす)めた。", "sentence_source": "generated"}, {"text": "病院のベッドに寝たまま、母は窓の外を見ていた。", "target_word": "寝た", "complexity_tier": "T3", "furigana": "病院(びょういん)のベッドに寝(ね)たまま、母(はは)は窓(まど)の外(そと)を見(み)ていた。", "sentence_source": "generated"}, {"text": "長い散歩のあと、木の下に寝て目を閉じると、すぐに気持ちが落ち着いた。", "target_word": "寝て", "complexity_tier": "T4", "furigana": "長(なが)い散歩(さんぽ)のあと、木(き)の下(した)に寝(ね)て目(め)を閉(と)じると、すぐに気持(きも)ちが落(お)ち着(つ)いた。", "sentence_source": "generated"}, {"text": "兄は車の後ろの席に寝て、体を休めながら目的地に向かった。", "target_word": "寝て", "complexity_tier": "T4", "furigana": "兄(あに)は車(くるま)の後(うし)ろの席(せき)に寝(ね)て、体(からだ)を休(やす)めながら目的地(もくてきち)に向(む)かった。", "sentence_source": "generated"}, {"text": "熱が高いので、今日は一日じゅう部屋で寝ていた。", "target_word": "寝ていた", "complexity_tier": "T3", "furigana": "熱(ねつ)が高(たか)いので、今日(きょう)は一日(いちにち)じゅう部屋(へや)で寝(ね)ていた。", "sentence_source": "generated"}, {"text": "子どもたちは砂浜に寝て、波の音を聞いていた。", "target_word": "寝て", "complexity_tier": "T3", "furigana": "子(こ)どもたちは砂浜(すなはま)に寝(ね)て、波(なみ)の音(おと)を聞(き)いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寝る", "label": "終止形"}, {"form": "寝た", "label": "た形"}, {"form": "寝て", "label": "て形"}, {"form": "寝ない", "label": "否定形"}, {"form": "寝れば", "label": "仮定形"}, {"form": "寝よう", "label": "意志形"}, {"form": "寝ろ", "label": "命令形"}], "register": "中立（普通体）", "sense_fingerprint": "体を横にして目を閉じ、その場で休む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36506, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寝て", "is_correct": true, "explanation": "て形で、「ソファに寝て少し目を閉じた」と続き、体を横にして休む意味になる。"}, {"text": "寝る", "is_correct": false, "explanation": "終止形は「ソファに寝る少し目を閉じた」と続かず、文が崩れる。"}, {"text": "寝た", "is_correct": false, "explanation": "た形は「ソファに寝た少し目を閉じた」と続かず、文がつながらない。"}, {"text": "寝ない", "is_correct": false, "explanation": "否定形は「寝ないで」の形でないと「少し目を閉じた」とつながらない。"}], "explanations": {"寝て": "て形で、「ソファに寝て少し目を閉じた」と続き、体を横にして休む意味になる。", "寝る": "終止形は「ソファに寝る少し目を閉じた」と続かず、文が崩れる。", "寝た": "た形は「ソファに寝た少し目を閉じた」と続かず、文がつながらない。", "寝ない": "否定形は「寝ないで」の形でないと「少し目を閉じた」とつながらない。"}, "sentence_index": 0, "correct_answer": "寝て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車がホームに寝て、ドアが開いた。", "explanation": "ここは〈止まる〉の意味。乗り物は横になって休まないので、寝るは人や動物にだけ使い、この定義（からだをよこにして休む）に合わない。"}, {"text": "ボールが寝て、ゴールに入った。", "explanation": "ここは〈転がる〉の意味。ボールは体を横にして休まないので、寝るは使わない。"}, {"text": "鍋の水が寝て、湯気が出た。", "explanation": "ここは〈沸く〉の意味。水が湯になる場面で、からだを横にして休む寝るは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36506, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寝て", "is_correct": true, "explanation": "て形で、「木の下に寝て目を閉じると」と続き、横になる動作を表す。"}, {"text": "寝ます", "is_correct": false, "explanation": "丁寧形は普通体の文の中で「目を閉じると」とつながらない。"}, {"text": "寝ました", "is_correct": false, "explanation": "丁寧な過去形は「目を閉じると」と続かず、文が崩れる。"}, {"text": "寝ません", "is_correct": false, "explanation": "丁寧な否定形は「目を閉じると」と続かず、文が成り立たない。"}], "explanations": {"寝て": "て形で、「木の下に寝て目を閉じると」と続き、横になる動作を表す。", "寝ます": "丁寧形は普通体の文の中で「目を閉じると」とつながらない。", "寝ました": "丁寧な過去形は「目を閉じると」と続かず、文が崩れる。", "寝ません": "丁寧な否定形は「目を閉じると」と続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "寝て"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓が寝て、風が入ってきた。", "explanation": "ここは〈開く〉の意味。窓は横になって休まないので、寝るは人や動物にだけ使う定義に合わない。"}, {"text": "地震で、古い塀が寝て道をふさいだ。", "explanation": "ここは〈倒れる〉の意味。塀は体を横にして休むものではないので、寝るは使わない。"}, {"text": "風で、カーテンが寝て、部屋が暗くなった。", "explanation": "ここは〈垂れ下がる〉の意味。カーテンは体を横にして休むものではないので、寝るは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36506, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は縁側を寝て、午後の風に当たった。", "corrected_sentence": "祖父は縁側に寝て、午後の風に当たった。", "error_description": "「寝る」は寝る場所を「に」で示す。「を」は目的語を示すので、場所には使えない（正しくは「に」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "寝て", "is_correct": true, "explanation": "て形で、「寝て、流れる雲をながめた」と続き、横になって見た様子を表す。"}, {"text": "寝る", "is_correct": false, "explanation": "終止形は読点の前で文が続かず、「流れる雲をながめた」とつながらない。"}, {"text": "寝ろ", "is_correct": false, "explanation": "命令形は「横になれ」の命令になり、過去の出来事を述べる文に合わない。"}, {"text": "寝よう", "is_correct": false, "explanation": "意志形は「寝よう」の提案になり、「ながめた」という過去の行動と合わない。"}], "correct_form": "寝て", "base_form": "寝る", "form_label": "て形", "sentence_index": 1, "explanations": {"寝て": "て形で、「寝て、流れる雲をながめた」と続き、横になって見た様子を表す。", "寝る": "終止形は読点の前で文が続かず、「流れる雲をながめた」とつながらない。", "寝ろ": "命令形は「横になれ」の命令になり、過去の出来事を述べる文に合わない。", "寝よう": "意志形は「寝よう」の提案になり、「ながめた」という過去の行動と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36506, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昼食のあと、ソファに寝る、少し休んだ。", "corrected_sentence": "昼食のあと、ソファに寝て、少し休んだ。", "error_description": "読点の前で続けるには「寝て」が必要。「寝る」（終止形）では文の流れがつながらない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "寝て", "is_correct": true, "explanation": "て形で、「寝て、体を休めながら向かった」と続き、動作の並列になる。"}, {"text": "寝ます", "is_correct": false, "explanation": "丁寧形は普通体の文の中で、後ろの「向かった」と続かない。"}, {"text": "寝ました", "is_correct": false, "explanation": "丁寧な過去形は「体を休めながら」と続かず、文の流れが崩れる。"}, {"text": "寝ろ", "is_correct": false, "explanation": "命令形は「寝ろ、」と命令で切れ、「兄は…向かった」の主語の動作として続かない。"}], "correct_form": "寝て", "base_form": "寝る", "form_label": "て形", "sentence_index": 7, "explanations": {"寝て": "て形で、「寝て、体を休めながら向かった」と続き、動作の並列になる。", "寝ます": "丁寧形は普通体の文の中で、後ろの「向かった」と続かない。", "寝ました": "丁寧な過去形は「体を休めながら」と続かず、文の流れが崩れる。", "寝ろ": "命令形は「寝ろ、」と命令で切れ、「兄は…向かった」の主語の動作として続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36507, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「に」は時刻を示す。「二時すぎに」の形で、寝た時刻を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、時刻には使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、時刻を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、時刻には使えない。"}], "correct_answer": "に", "explanations": {"に": "「に」は時刻を示す。「二時すぎに」の形で、寝た時刻を表す。", "を": "「を」は目的語を示すので、時刻には使えない。", "で": "「で」は場所や手段を示すので、時刻を表せない。", "へ": "「へ」は方向を示すので、時刻には使えない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起きる", "is_correct": true, "explanation": "寝る（眠るために休む）の対義語。目覚めて体を起こす動作で、眠ることと反対の関係にある。"}, {"text": "働く", "is_correct": false, "explanation": "仕事をする動作で、寝るとは対義の関係にない。"}, {"text": "食べる", "is_correct": false, "explanation": "飲食の動作で、寝るとは対義の関係にない。"}, {"text": "話す", "is_correct": false, "explanation": "会話の動作で、寝ることとは対義の関係にない。"}], "correct_answer": "起きる", "explanations": {"起きる": "寝る（眠るために休む）の対義語。目覚めて体を起こす動作で、眠ることと反対の関係にある。", "働く": "仕事をする動作で、寝るとは対義の関係にない。", "食べる": "飲食の動作で、寝るとは対義の関係にない。", "話す": "会話の動作で、寝ることとは対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36507, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「と」は条件を示す。「寝ると、朝まで気持ちよく眠れる」の形になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は逆接になり、「寝るが、朝まで眠れる」では意味がつながらない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は理由になり、窓をあけて眠る条件の意味とずれる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較になり、この文の意味に合わない。"}], "correct_answer": "と", "explanations": {"と": "「と」は条件を示す。「寝ると、朝まで気持ちよく眠れる」の形になる。", "が": "「が」は逆接になり、「寝るが、朝まで眠れる」では意味がつながらない。", "から": "「から」は理由になり、窓をあけて眠る条件の意味とずれる。", "より": "「より」は比較になり、この文の意味に合わない。"}, "error_tags": {"が": "逆接", "から": "理由", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起きる", "is_correct": true, "explanation": "寝る（眠るために休む）の対義語。目覚めて体を起こす動作で、眠ることと反対の関係にある。"}, {"text": "走る", "is_correct": false, "explanation": "運動の動作で、寝るとは対義の関係にない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "運動の動作で、寝るとは対義の関係にない。"}, {"text": "笑う", "is_correct": false, "explanation": "表情や感情の動作で、寝るとは対義の関係にない。"}], "correct_answer": "起きる", "explanations": {"起きる": "寝る（眠るために休む）の対義語。目覚めて体を起こす動作で、眠ることと反対の関係にある。", "走る": "運動の動作で、寝るとは対義の関係にない。", "泳ぐ": "運動の動作で、寝るとは対義の関係にない。", "笑う": "表情や感情の動作で、寝るとは対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36507, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "眠るために布団やベッドに入り、体を横にして休息すること。", "primary_collocate": null, "pronunciation": "ねる", "ipa": "neɾɯ", "syllable_count": 2, "sentences": [{"text": "明日は早いので、今夜は十時に寝る。", "target_word": "寝る", "complexity_tier": "T2", "furigana": "明日(あした)は早(はや)いので、今夜(こんや)は十時(じゅうじ)に寝(ね)る。", "sentence_source": "generated"}, {"text": "夜ふかしをしたので、昨日は二時すぎにやっと寝た。", "target_word": "寝た", "complexity_tier": "T3", "furigana": "夜(よる)ふかしをしたので、昨日(きのう)は二時(にじ)すぎにやっと寝(ね)た。", "sentence_source": "generated"}, {"text": "子どもは歯をみがいてから、自分のベッドで寝る。", "target_word": "寝る", "complexity_tier": "T2", "furigana": "子(こ)どもは歯(は)をみがいてから、自分(じぶん)のベッドで寝(ね)る。", "sentence_source": "generated"}, {"text": "寒い夜は、ふとんを二枚かけて寝ると暖かい。", "target_word": "寝る", "complexity_tier": "T3", "furigana": "寒(さむ)い夜(よる)は、ふとんを二枚(にまい)かけて寝(ね)ると暖(あたた)かい。", "sentence_source": "generated"}, {"text": "試験の前の日は、勉強をやめて早く寝たほうがいい。", "target_word": "寝た", "complexity_tier": "T3", "furigana": "試験(しけん)の前(まえ)の日(ひ)は、勉強(べんきょう)をやめて早(はや)く寝(ね)たほうがいい。", "sentence_source": "generated"}, {"text": "弟はゲームをしすぎて、夜になってもなかなか寝ない。", "target_word": "寝ない", "complexity_tier": "T3", "furigana": "弟(おとうと)はゲームをしすぎて、夜(よる)になってもなかなか寝(ね)ない。", "sentence_source": "generated"}, {"text": "風呂に入ったあと、母は読書をしてから寝る。", "target_word": "寝る", "complexity_tier": "T3", "furigana": "風呂(ふろ)に入(はい)ったあと、母(はは)は読書(どくしょ)をしてから寝(ね)る。", "sentence_source": "generated"}, {"text": "毎晩、窓を少しあけて寝ると、朝まで気持ちよく眠れる。", "target_word": "寝る", "complexity_tier": "T3", "furigana": "毎晩(まいばん)、窓(まど)を少(すこ)しあけて寝(ね)ると、朝(あさ)まで気持(きも)ちよく眠(ねむ)れる。", "sentence_source": "generated"}, {"text": "疲れていたので、夕飯も食べずに寝てしまった。", "target_word": "寝てしまった", "complexity_tier": "T3", "furigana": "疲(つか)れていたので、夕飯(ゆうはん)も食(た)べずに寝(ね)てしまった。", "sentence_source": "generated"}, {"text": "旅行の初日は、ホテルに着いてすぐ寝た。", "target_word": "寝た", "complexity_tier": "T2", "furigana": "旅行(りょこう)の初日(しょにち)は、ホテルに着(つ)いてすぐ寝(ね)た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寝る", "label": "終止形"}, {"form": "寝た", "label": "た形"}, {"form": "寝て", "label": "て形"}, {"form": "寝ない", "label": "否定形"}, {"form": "寝れば", "label": "仮定形"}, {"form": "寝よう", "label": "意志形"}, {"form": "寝ろ", "label": "命令形"}], "register": "中立（普通体）", "sense_fingerprint": "夜などに、眠るために布団やベッドに入って休息する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: みがい (Zipf 1.96)']::text[], '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36507, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寝る", "is_correct": true, "explanation": "終止形で、「今夜は十時に寝る。」と文を言い切る形になる。"}, {"text": "寝て", "is_correct": false, "explanation": "て形は文を途中で止める形で、「十時に寝て。」と文が終わらない。"}, {"text": "寝れば", "is_correct": false, "explanation": "仮定形は条件で止まり、「十時に寝れば。」と文が完結しない。"}, {"text": "寝なくて", "is_correct": false, "explanation": "否定のて形は文を途中で切るため、述語として文が完結しない。"}], "explanations": {"寝る": "終止形で、「今夜は十時に寝る。」と文を言い切る形になる。", "寝て": "て形は文を途中で止める形で、「十時に寝て。」と文が終わらない。", "寝れば": "仮定形は条件で止まり、「十時に寝れば。」と文が完結しない。", "寝なくて": "否定のて形は文を途中で切るため、述語として文が完結しない。"}, "sentence_index": 0, "correct_answer": "寝る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝坊しないように、アラームは六時に寝た。", "explanation": "ここは〈鳴る〉の意味。アラームは音を出す機器で、眠るという意味の寝るは使わない。"}, {"text": "強風で、看板が寝た。", "explanation": "ここは〈倒れる〉の意味。看板が横に倒れる場面で、眠る寝るとは意味が違う。"}, {"text": "玄関の靴が寝ていた。", "explanation": "ここは〈横倒しになる〉の意味。靴は眠らないので、人や動物にだけ使う寝るとは意味が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36507, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寝る", "is_correct": true, "explanation": "終止形で、「読書をしてから寝る。」と文を言い切る形になる。"}, {"text": "寝たり", "is_correct": false, "explanation": "たり形は「〜たり〜たり」と並べる形で、「寝たり。」と文が完結しない。"}, {"text": "寝ていて", "is_correct": false, "explanation": "て形は文を途中で止め、「してから寝ていて。」と文が完結しない。"}, {"text": "寝れなくて", "is_correct": false, "explanation": "て形は文を途中で切るため、述語として文が完結しない。"}], "explanations": {"寝る": "終止形で、「読書をしてから寝る。」と文を言い切る形になる。", "寝たり": "たり形は「〜たり〜たり」と並べる形で、「寝たり。」と文が完結しない。", "寝ていて": "て形は文を途中で止め、「してから寝ていて。」と文が完結しない。", "寝れなくて": "て形は文を途中で切るため、述語として文が完結しない。"}, "sentence_index": 6, "correct_answer": "寝る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の花が寝て、きれいだった。", "explanation": "ここは〈咲く〉の意味。花が開く様子で、眠るための寝るは合わない。"}, {"text": "古い時計が寝て、動かなくなった。", "explanation": "ここは〈壊れる〉の意味。機械が止まる場面で、寝るは使わない。"}, {"text": "洗濯物がよく寝た。", "explanation": "ここは〈乾く〉の意味。洗濯物が乾く場面で、眠る寝るは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36507, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は毎晩、布団を寝ている。", "corrected_sentence": "父は毎晩、布団で寝ている。", "error_description": "寝る場所は「で」で示す。「を」は目的語を示すので、「寝る」には使えない（正しくは「で」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "寝た", "is_correct": true, "explanation": "た形で、「やっと寝た」と過去の出来事を言い切る形になる。"}, {"text": "寝て", "is_correct": false, "explanation": "て形は文を途中で止め、「やっと寝て。」と文が完結しない。"}, {"text": "寝れば", "is_correct": false, "explanation": "仮定形は条件で止まり、文が完結しない。"}, {"text": "寝たら", "is_correct": false, "explanation": "たら形は条件節になり、過去の出来事を言い切れない。"}], "correct_form": "寝た", "base_form": "寝る", "form_label": "た形", "sentence_index": 1, "explanations": {"寝た": "た形で、「やっと寝た」と過去の出来事を言い切る形になる。", "寝て": "て形は文を途中で止め、「やっと寝て。」と文が完結しない。", "寝れば": "仮定形は条件で止まり、文が完結しない。", "寝たら": "たら形は条件節になり、過去の出来事を言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36507, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は、いつもより早く寝ったので、朝がすっきりしていた。", "corrected_sentence": "妹は、いつもより早く寝たので、朝がすっきりしていた。", "error_description": "「寝る」の過去形は「寝た」。「寝った」は誤りで、正しくは「寝た」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "寝る", "is_correct": true, "explanation": "終止形（連体形と同形）。「寝ると」の条件の形で、後ろの文につながる。"}, {"text": "寝ろ", "is_correct": false, "explanation": "命令形は「寝ろと」と引用の形になり、「朝まで眠れる」とつながらない。"}, {"text": "寝たくて", "is_correct": false, "explanation": "希望を表すて形は「寝たくてと」と続かず、文の条件にならない。"}, {"text": "寝させて", "is_correct": false, "explanation": "使役のて形は「寝させてと」と続かず、主語と合わない。"}], "correct_form": "寝る", "base_form": "寝る", "form_label": "終止形", "sentence_index": 7, "explanations": {"寝る": "終止形（連体形と同形）。「寝ると」の条件の形で、後ろの文につながる。", "寝ろ": "命令形は「寝ろと」と引用の形になり、「朝まで眠れる」とつながらない。", "寝たくて": "希望を表すて形は「寝たくてと」と続かず、文の条件にならない。", "寝させて": "使役のて形は「寝させてと」と続かず、主語と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36508, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「駅の前で」は場所を示す「で」で、友達を待つ場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "『駅の前を友達を待つ』では『を』が二つ続き、文として不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、待つ場所を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、待つ場所の指定にはならない。"}], "correct_answer": "で", "explanations": {"で": "「駅の前で」は場所を示す「で」で、友達を待つ場所を表す。", "を": "『駅の前を友達を待つ』では『を』が二つ続き、文として不自然になる。", "と": "「と」は並列や相手を示すので、待つ場所を表せない。", "より": "「より」は比較を示すので、待つ場所の指定にはならない。"}, "error_tags": {"を": "「を」は動作の対象を示すので、場所の「前」には続かない。", "と": "「と」は並列や相手を示すので、待つ場所を表せない。", "より": "「より」は比較を示すので、待つ場所の指定にはならない。"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "後ろ", "is_correct": true, "explanation": "「前」と対になる「後ろ」は、家の反対側を表すので対義語になる。"}, {"text": "上", "is_correct": false, "explanation": "上下の「上」で、「前」の対義語ではない。"}, {"text": "外", "is_correct": false, "explanation": "内と外の対になる語で、「前」の対義語ではない。"}, {"text": "中", "is_correct": false, "explanation": "内側を表す語で、「前」の対義語ではない。"}], "correct_answer": "後ろ", "explanations": {"後ろ": "「前」と対になる「後ろ」は、家の反対側を表すので対義語になる。", "上": "上下の「上」で、「前」の対義語ではない。", "外": "内と外の対になる語で、「前」の対義語ではない。", "中": "内側を表す語で、「前」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36508, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「出かける前に」は時点を示す「に」で、動作の前の時点を表す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、時点の「前」には付かない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、ここでは時点を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、時点を表す「前」には使えない。"}], "correct_answer": "に", "explanations": {"に": "「出かける前に」は時点を示す「に」で、動作の前の時点を表す。", "で": "「で」は場所や手段を示すので、時点の「前」には付かない。", "が": "「が」は主語を示すので、ここでは時点を表せない。", "へ": "「へ」は方向を示すので、時点を表す「前」には使えない。"}, "error_tags": {"で": "「で」は場所や手段を示すので、時点の「前」には付かない。", "が": "「が」は主語を示すので、時点を表す語の後には入らない。", "へ": "「へ」は方向を示すので、時点を表す「前」には使えない。"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "後ろ", "is_correct": true, "explanation": "「私の前」の反対側を表す「後ろ」で、対義語になる。"}, {"text": "下", "is_correct": false, "explanation": "上下の「下」で、「前」の対義語ではない。"}, {"text": "左", "is_correct": false, "explanation": "左右の一方を表す語で、「前」の対義語ではない。"}, {"text": "内", "is_correct": false, "explanation": "外側に対する内側を表す語で、「前」の対義語ではない。"}], "correct_answer": "後ろ", "explanations": {"後ろ": "「私の前」の反対側を表す「後ろ」で、対義語になる。", "下": "上下の「下」で、「前」の対義語ではない。", "左": "左右の一方を表す語で、「前」の対義語ではない。", "内": "外側に対する内側を表す語で、「前」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36508, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "時間や場所で、基準となるものより前（先・手前）の側を言う。", "primary_collocate": null, "pronunciation": "まえ", "ipa": "mae", "syllable_count": 2, "sentences": [{"text": "寝る前に、温かいお茶を飲みます。", "target_word": "前", "complexity_tier": "T3", "furigana": "寝[ね]る前[まえ]に、温[あたた]かいお茶[ちゃ]を飲[の]みます。", "sentence_source": "generated"}, {"text": "駅の前で友達を待っています。", "target_word": "前", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]で友達[ともだち]を待[ま]っています。", "sentence_source": "generated"}, {"text": "食事の前には、手をよく洗いましょう。", "target_word": "前", "complexity_tier": "T3", "furigana": "食事[しょくじ]の前[まえ]には、手[て]をよく洗[あら]いましょう。", "sentence_source": "generated"}, {"text": "家の前に小さな公園があって、子どもたちがよく遊んでいる。", "target_word": "前", "complexity_tier": "T3", "furigana": "家[いえ]の前[まえ]に小[ちい]さな公園[こうえん]があって、子[こ]どもたちがよく遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "三年前に、この町に引っ越してきました。", "target_word": "前", "complexity_tier": "T3", "furigana": "三年[さんねん]前[まえ]に、この町[まち]に引[ひ]っ越[こ]してきました。", "sentence_source": "generated"}, {"text": "試験の前の日は、早く寝たほうがいい。", "target_word": "前", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]の日[ひ]は、早[はや]く寝[ね]たほうがいい。", "sentence_source": "generated"}, {"text": "列の前のほうに座ると、先生の話がよく聞こえる。", "target_word": "前", "complexity_tier": "T3", "furigana": "列[れつ]の前[まえ]のほうに座[すわ]ると、先生[せんせい]の話[はなし]がよく聞[き]こえる。", "sentence_source": "generated"}, {"text": "出かける前に、窓が閉まっているか確認した。", "target_word": "前", "complexity_tier": "T3", "furigana": "出[で]かける前[まえ]に、窓[まど]が閉[し]まっているか確認[かくにん]した。", "sentence_source": "generated"}, {"text": "映画が始まる前に、トイレに行っておきます。", "target_word": "前", "complexity_tier": "T3", "furigana": "映画[えいが]が始[はじ]まる前[まえ]に、トイレに行[い]っておきます。", "sentence_source": "generated"}, {"text": "私の前に立っていた人が、急に振り返った。", "target_word": "前", "complexity_tier": "T3", "furigana": "私[わたし]の前[まえ]に立[た]っていた人[ひと]が、急[きゅう]に振[ふ]り返[かえ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "前", "label": "基本形"}, {"form": "前に", "label": "に格"}, {"form": "前の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "時間や場所で、ある基準より先・手前の側", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e5da86-1411-4fd5-9f5f-e54c321bb1e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
